#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <stdint.h>

static uint32_t read_u32(const uint8_t *b) {
    return (uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
}

static uint16_t read_u16(const uint8_t *b) {
    return (uint16_t)b[0] | ((uint16_t)b[1] << 8);
}

static int32_t read_i32(const uint8_t *b) {
    return (int32_t)read_u32(b);
}

static int popcount32(uint32_t v) {
    int c = 0;
    while (v) { c += v & 1; v >>= 1; }
    return c;
}

static int trailing_zeros32(uint32_t v) {
    if (v == 0) return 32;
    int c = 0;
    while (!(v & 1)) { c++; v >>= 1; }
    return c;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

typedef struct { int x, y; } Point;

typedef struct {
    int x, y;
    int minx, miny, maxx, maxy;
    int count;
} Component;

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    DIR *dir = opendir(argv[1]);
    if (!dir) return 1;

    char **names = NULL;
    int nfiles = 0, cap = 0;
    struct dirent *de;

    while ((de = readdir(dir)) != NULL) {
        const char *name = de->d_name;
        size_t len = strlen(name);
        if (len > 4 && strcmp(name + len - 4, ".bmp") == 0) {
            if (nfiles == cap) {
                cap = cap ? cap * 2 : 64;
                names = realloc(names, (size_t)cap * sizeof(char *));
            }
            names[nfiles++] = strdup(name);
        }
    }
    closedir(dir);

    qsort(names, (size_t)nfiles, sizeof(char *), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        printf("== %s\n", names[fi]);

        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", argv[1], names[fi]);
        FILE *f = fopen(path, "rb");
        if (!f) { free(names[fi]); continue; }
        fseek(f, 0, SEEK_END);
        long fsize = ftell(f);
        fseek(f, 0, SEEK_SET);
        uint8_t *data = malloc((size_t)fsize);
        if (fread(data, 1, (size_t)fsize, f) != (size_t)fsize) {
            fclose(f); free(data); free(names[fi]); continue;
        }
        fclose(f);

        if (fsize < 14 || data[0] != 'B' || data[1] != 'M') {
            free(data); free(names[fi]); continue;
        }

        uint32_t bfOffBits = read_u32(data + 10);

        if (fsize < 18) { free(data); free(names[fi]); continue; }
        uint32_t dibSize = read_u32(data + 14);
        if (dibSize < 40) { free(data); free(names[fi]); continue; }

        int32_t width = read_i32(data + 18);
        int32_t height = read_i32(data + 22);
        uint16_t bpp = read_u16(data + 28);
        uint32_t compression = read_u32(data + 30);
        uint32_t colorsUsed = read_u32(data + 46);

        int topdown = (height < 0);
        int h = topdown ? -height : height;
        int w = width;

        if (compression != 0 && compression != 3) {
            printf("error: unsupported compression %u\n", compression);
            free(data); free(names[fi]); continue;
        }

        uint32_t rmask = 0, gmask = 0, bmask = 0;
        if (bpp == 32 && compression == 3) {
            if (fsize < 66) { free(data); free(names[fi]); continue; }
            rmask = read_u32(data + 54);
            gmask = read_u32(data + 58);
            bmask = read_u32(data + 62);
        }

        const uint8_t *palette = NULL;
        if (bpp == 1 || bpp == 4 || bpp == 8) {
            uint32_t palEntries = colorsUsed ? colorsUsed : (1u << bpp);
            uint32_t palOffset = 14 + dibSize;
            if (palOffset + palEntries * 4 <= (uint32_t)fsize) {
                palette = data + palOffset;
            }
        }

        int rowBytes = ((w * (int)bpp + 31) / 32) * 4;

        uint8_t *ink = calloc((size_t)w * (size_t)h, 1);

        for (int y = 0; y < h; y++) {
            int storedY = topdown ? y : (h - 1 - y);
            const uint8_t *row = data + bfOffBits + (long)storedY * rowBytes;

            for (int x = 0; x < w; x++) {
                int R = 0, G = 0, B = 0;

                if (bpp == 1) {
                    int byteIdx = x / 8;
                    int bitIdx = 7 - (x % 8);
                    int idx = (row[byteIdx] >> bitIdx) & 1;
                    if (palette) {
                        B = palette[idx * 4 + 0];
                        G = palette[idx * 4 + 1];
                        R = palette[idx * 4 + 2];
                    }
                } else if (bpp == 4) {
                    int byteIdx = x / 2;
                    int shift = (x % 2 == 0) ? 4 : 0;
                    int idx = (row[byteIdx] >> shift) & 0xF;
                    if (palette) {
                        B = palette[idx * 4 + 0];
                        G = palette[idx * 4 + 1];
                        R = palette[idx * 4 + 2];
                    }
                } else if (bpp == 8) {
                    int idx = row[x];
                    if (palette) {
                        B = palette[idx * 4 + 0];
                        G = palette[idx * 4 + 1];
                        R = palette[idx * 4 + 2];
                    }
                } else if (bpp == 24) {
                    B = row[x * 3 + 0];
                    G = row[x * 3 + 1];
                    R = row[x * 3 + 2];
                } else if (bpp == 32) {
                    uint32_t pixel = read_u32(row + x * 4);
                    if (compression == 0) {
                        B = (int)(pixel & 0xFF);
                        G = (int)((pixel >> 8) & 0xFF);
                        R = (int)((pixel >> 16) & 0xFF);
                    } else {
                        int s, n, m, v;
                        s = trailing_zeros32(rmask);
                        n = popcount32(rmask);
                        m = (1 << n) - 1;
                        v = (int)((pixel & rmask) >> s);
                        R = (v * 255 + m / 2) / m;

                        s = trailing_zeros32(gmask);
                        n = popcount32(gmask);
                        m = (1 << n) - 1;
                        v = (int)((pixel & gmask) >> s);
                        G = (v * 255 + m / 2) / m;

                        s = trailing_zeros32(bmask);
                        n = popcount32(bmask);
                        m = (1 << n) - 1;
                        v = (int)((pixel & bmask) >> s);
                        B = (v * 255 + m / 2) / m;
                    }
                }

                int lum = (299 * R + 587 * G + 114 * B) / 1000;
                if (lum < 128) {
                    ink[y * w + x] = 1;
                }
            }
        }

        int inkCount = 0;
        for (int i = 0; i < w * h; i++) inkCount += ink[i];

        printf("size %dx%d bpp %d header %u %s ink %d\n",
               w, h, (int)bpp, dibSize,
               topdown ? "top-down" : "bottom-up", inkCount);

        uint8_t *visited = calloc((size_t)w * (size_t)h, 1);
        Component *comps = NULL;
        int ncomps = 0, compCap = 0;
        Point *queue = malloc((size_t)w * (size_t)h * sizeof(Point));

        const int dx[] = {-1, 0, 1, -1, 1, -1, 0, 1};
        const int dy[] = {-1, -1, -1, 0, 0, 1, 1, 1};

        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (!ink[y * w + x] || visited[y * w + x]) continue;

                if (ncomps == compCap) {
                    compCap = compCap ? compCap * 2 : 64;
                    comps = realloc(comps, (size_t)compCap * sizeof(Component));
                }

                Component *c = &comps[ncomps];
                c->x = x; c->y = y;
                c->minx = x; c->maxx = x;
                c->miny = y; c->maxy = y;
                c->count = 0;

                int qh = 0, qt = 0;
                queue[qt].x = x; queue[qt].y = y; qt++;
                visited[y * w + x] = 1;

                while (qh < qt) {
                    Point p = queue[qh++];
                    c->count++;
                    if (p.x < c->minx) c->minx = p.x;
                    if (p.x > c->maxx) c->maxx = p.x;
                    if (p.y < c->miny) c->miny = p.y;
                    if (p.y > c->maxy) c->maxy = p.y;

                    for (int d = 0; d < 8; d++) {
                        int nx = p.x + dx[d], ny = p.y + dy[d];
                        if (nx >= 0 && nx < w && ny >= 0 && ny < h &&
                            ink[ny * w + nx] && !visited[ny * w + nx]) {
                            visited[ny * w + nx] = 1;
                            queue[qt].x = nx; queue[qt].y = ny; qt++;
                        }
                    }
                }
                ncomps++;
            }
        }

        printf("components %d\n", ncomps);
        for (int i = 0; i < ncomps; i++) {
            printf("%d,%d bbox %d,%d-%d,%d pixels %d\n",
                   comps[i].x, comps[i].y,
                   comps[i].minx, comps[i].miny,
                   comps[i].maxx, comps[i].maxy,
                   comps[i].count);
        }

        free(queue);
        free(visited);
        free(comps);
        free(ink);
        free(data);
        free(names[fi]);
    }

    free(names);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

function readU16LE(buf: Buffer, off: number): number {
    return buf[off] | (buf[off + 1] << 8);
}

function readU32LE(buf: Buffer, off: number): number {
    return (buf[off] | (buf[off + 1] << 8) | (buf[off + 2] << 16) | (buf[off + 3] << 24)) >>> 0;
}

function readI32LE(buf: Buffer, off: number): number {
    return buf[off] | (buf[off + 1] << 8) | (buf[off + 2] << 16) | (buf[off + 3] << 24);
}

function popcount(n: number): number {
    let c = 0;
    while (n > 0) { c += n & 1; n >>>= 1; }
    return c;
}

function ctz(n: number): number {
    if (n === 0) return 32;
    let c = 0;
    while ((n & 1) === 0) { c++; n >>>= 1; }
    return c;
}

function extractChannel(pixel: number, mask: number): number {
    const s = ctz(mask);
    const n = popcount(mask);
    const m = (1 << n) - 1;
    const v = (pixel & mask) >>> s;
    return Math.floor((v * 255 + Math.floor(m / 2)) / m);
}

function isInk(r: number, g: number, b: number): boolean {
    return Math.floor((299 * r + 587 * g + 114 * b) / 1000) < 128;
}

interface Component {
    firstX: number;
    firstY: number;
    minX: number;
    minY: number;
    maxX: number;
    maxY: number;
    count: number;
}

function processFile(fname: string, data: Buffer): void {
    const bfOffBits = readU32LE(data, 10);

    // DIB header starts at offset 14
    const dibSize = readU32LE(data, 14);
    const width = readI32LE(data, 18);
    const rawHeight = readI32LE(data, 22);
    const bpp = readU16LE(data, 28);
    const compression = readU32LE(data, 32);
    const colorsUsed = readU32LE(data, 48);

    const height = Math.abs(rawHeight);
    const bottomUp = rawHeight > 0;

    if (compression !== 0 && compression !== 3) {
        console.log(`== ${fname}`);
        console.log(`error: unsupported compression ${compression}`);
        return;
    }

    // BI_BITFIELDS masks
    let redMask = 0, greenMask = 0, blueMask = 0;
    if (bpp === 32 && compression === 3) {
        // For both 40-byte and 108/124-byte headers, masks are at offset 14+40
        redMask = readU32LE(data, 14 + 40);
        greenMask = readU32LE(data, 14 + 44);
        blueMask = readU32LE(data, 14 + 48);
    }

    // Color table for indexed modes
    let palette: [number, number, number][] = [];
    if (bpp === 1 || bpp === 4 || bpp === 8) {
        const tableStart = 14 + dibSize;
        const numColors = colorsUsed > 0 ? colorsUsed : (1 << bpp);
        for (let i = 0; i < numColors; i++) {
            const off = tableStart + i * 4;
            const b = data[off];
            const g = data[off + 1];
            const r = data[off + 2];
            palette.push([r, g, b]);
        }
    }

    // Row stride (padded to 4 bytes)
    const bitsPerRow = width * bpp;
    const bytesPerRow = Math.ceil(bitsPerRow / 8);
    const stride = Math.ceil(bytesPerRow / 4) * 4;

    // Build ink grid
    const ink: boolean[][] = [];
    for (let y = 0; y < height; y++) {
        ink[y] = [];
        const storedRow = bottomUp ? (height - 1 - y) : y;
        const rowOffset = bfOffBits + storedRow * stride;

        for (let x = 0; x < width; x++) {
            let r: number, g: number, b: number;

            if (bpp === 1) {
                const byteIdx = x >> 3;
                const bitIdx = 7 - (x & 7);
                const idx = (data[rowOffset + byteIdx] >> bitIdx) & 1;
                const c = palette[idx] || [0, 0, 0];
                r = c[0]; g = c[1]; b = c[2];
            } else if (bpp === 4) {
                const byteIdx = x >> 1;
                const shift = (x & 1) === 0 ? 4 : 0;
                const idx = (data[rowOffset + byteIdx] >> shift) & 0xF;
                const c = palette[idx] || [0, 0, 0];
                r = c[0]; g = c[1]; b = c[2];
            } else if (bpp === 8) {
                const idx = data[rowOffset + x];
                const c = palette[idx] || [0, 0, 0];
                r = c[0]; g = c[1]; b = c[2];
            } else if (bpp === 24) {
                const off = rowOffset + x * 3;
                b = data[off];
                g = data[off + 1];
                r = data[off + 2];
            } else {
                // 32 bpp
                const off = rowOffset + x * 4;
                const pixel = readU32LE(data, off);
                if (compression === 3) {
                    r = extractChannel(pixel, redMask);
                    g = extractChannel(pixel, greenMask);
                    b = extractChannel(pixel, blueMask);
                } else {
                    b = data[off];
                    g = data[off + 1];
                    r = data[off + 2];
                }
            }

            ink[y][x] = isInk(r, g, b);
        }
    }

    // Count ink pixels
    let inkCount = 0;
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            if (ink[y][x]) inkCount++;
        }
    }

    // Find connected components (8-connectivity) using BFS
    const visited: boolean[][] = [];
    for (let y = 0; y < height; y++) {
        visited[y] = new Array(width).fill(false);
    }

    const components: Component[] = [];
    const dx = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dy = [-1, -1, -1, 0, 0, 1, 1, 1];

    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            if (ink[y][x] && !visited[y][x]) {
                const comp: Component = {
                    firstX: x, firstY: y,
                    minX: x, minY: y, maxX: x, maxY: y,
                    count: 0
                };
                const queue: [number, number][] = [[x, y]];
                visited[y][x] = true;
                let head = 0;

                while (head < queue.length) {
                    const [cx, cy] = queue[head++];
                    comp.count++;
                    if (cx < comp.minX) comp.minX = cx;
                    if (cx > comp.maxX) comp.maxX = cx;
                    if (cy < comp.minY) comp.minY = cy;
                    if (cy > comp.maxY) comp.maxY = cy;

                    for (let d = 0; d < 8; d++) {
                        const nx = cx + dx[d];
                        const ny = cy + dy[d];
                        if (nx >= 0 && nx < width && ny >= 0 && ny < height && ink[ny][nx] && !visited[ny][nx]) {
                            visited[ny][nx] = true;
                            queue.push([nx, ny]);
                        }
                    }
                }

                components.push(comp);
            }
        }
    }

    // Output
    const orientation = bottomUp ? "bottom-up" : "top-down";
    console.log(`== ${fname}`);
    console.log(`size ${width}x${height} bpp ${bpp} header ${dibSize} ${orientation} ink ${inkCount}`);
    console.log(`components ${components.length}`);
    for (const comp of components) {
        console.log(`${comp.firstX},${comp.firstY} bbox ${comp.minX},${comp.minY}-${comp.maxX},${comp.maxY} pixels ${comp.count}`);
    }
}

function main(): void {
    const dir = process.argv[2];
    const files = fs.readdirSync(dir)
        .filter(f => f.endsWith('.bmp'))
        .sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));

    for (const fname of files) {
        const data = fs.readFileSync(path.join(dir, fname));
        processFile(fname, data);
    }
}

main();

