import sys
import os
import struct
import socket
import random


def build_query(name, qtype_num, qid):
    header = struct.pack('!HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    qname = b''
    n = name
    if n.endswith('.'):
        n = n[:-1]
    if n:
        labels = n.split('.')
        for label in labels:
            qname += struct.pack('!B', len(label)) + label.encode('ascii')
    qname += b'\x00'
    qtype_class = struct.pack('!HH', qtype_num, 1)
    return header + qname + qtype_class


def parse_name(data, offset, visited=None):
    if visited is None:
        visited = set()
    labels = []
    while True:
        if offset >= len(data):
            break
        length = data[offset]
        if length & 0xC0 == 0xC0:
            if offset + 1 >= len(data):
                break
            pointer = struct.unpack('!H', data[offset:offset + 2])[0] & 0x3FFF
            if pointer in visited:
                break
            visited.add(pointer)
            sub_labels, _ = parse_name(data, pointer, visited)
            labels.extend(sub_labels)
            return labels, offset + 2
        elif length == 0:
            return labels, offset + 1
        else:
            offset += 1
            label = data[offset:offset + length]
            labels.append(label.decode('latin-1'))
            offset += length
    return labels, offset


def format_name(labels):
    if not labels:
        return '.'
    return '.'.join(l.lower() for l in labels)


def format_ipv4(data):
    return '.'.join(str(b) for b in data)


def format_ipv6(data):
    groups = []
    for i in range(8):
        groups.append(struct.unpack('!H', data[i * 2:i * 2 + 2])[0])

    best_start = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            run_len = j - i
            if run_len >= 2 and run_len > best_len:
                best_start = i
                best_len = run_len
            i = j
        else:
            i += 1

    parts = []
    i = 0
    while i < 8:
        if i == best_start:
            if i == 0:
                parts.append('')
            parts.append('')
            i += best_len
            if i >= 8:
                parts.append('')
            continue
        parts.append(format(groups[i], 'x'))
        i += 1

    return ':'.join(parts)


def format_txt_rdata(data):
    parts = []
    offset = 0
    while offset < len(data):
        length = data[offset]
        offset += 1
        string_bytes = data[offset:offset + length]
        offset += length
        s = '"'
        for b in string_bytes:
            if b == ord('"'):
                s += '\\"'
            elif b == ord('\\'):
                s += '\\\\'
            elif 0x20 <= b <= 0x7E:
                s += chr(b)
            else:
                s += '\\' + str(b).zfill(3)
        s += '"'
        parts.append(s)
    return ' '.join(parts)


RCODE_NAMES = {0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'}


def parse_response(data):
    if len(data) < 12:
        return None
    resp_id, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', data[:12])
    rcode = flags & 0x000F

    offset = 12
    for _ in range(qdcount):
        _, offset = parse_name(data, offset)
        offset += 4

    records = []
    for _ in range(ancount):
        owner_labels, offset = parse_name(data, offset)
        if offset + 10 > len(data):
            break
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', data[offset:offset + 10])
        offset += 10
        rdata_start = offset
        rdata = data[offset:offset + rdlength]
        offset += rdlength

        owner = format_name(owner_labels)

        if rtype == 1:
            type_name = 'A'
            data_str = format_ipv4(rdata)
        elif rtype == 28:
            type_name = 'AAAA'
            data_str = format_ipv6(rdata)
        elif rtype == 5:
            type_name = 'CNAME'
            target_labels, _ = parse_name(data, rdata_start)
            data_str = format_name(target_labels)
        elif rtype == 15:
            type_name = 'MX'
            preference = struct.unpack('!H', rdata[:2])[0]
            exchange_labels, _ = parse_name(data, rdata_start + 2)
            data_str = f"{preference} {format_name(exchange_labels)}"
        elif rtype == 16:
            type_name = 'TXT'
            data_str = format_txt_rdata(rdata)
        else:
            type_name = f'TYPE{rtype}'
            if rdlength == 0:
                data_str = '\\# 0'
            else:
                data_str = '\\# ' + str(rdlength) + ' ' + rdata.hex()

        records.append((owner, ttl, type_name, data_str))

    return rcode, records


def main():
    directory = sys.argv[1]
    port = int(sys.argv[2])

    queries_file = os.path.join(directory, 'queries.txt')
    with open(queries_file, 'r') as f:
        lines = f.readlines()

    TYPE_MAP = {'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5}

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = line.split(' ')
        name = parts[0]
        qtype_str = parts[1]
        qtype_num = TYPE_MAP[qtype_str]

        qid = random.randint(0, 65535)
        query = build_query(name, qtype_num, qid)

        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.sendto(query, ('127.0.0.1', port))

        while True:
            data, _ = sock.recvfrom(65535)
            if len(data) >= 12:
                resp_id = struct.unpack('!H', data[:2])[0]
                if resp_id == qid:
                    break
        sock.close()

        flags = struct.unpack('!H', data[2:4])[0]
        tc = (flags >> 9) & 1

        if tc:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect(('127.0.0.1', port))
            sock.sendall(struct.pack('!H', len(query)) + query)

            length_data = b''
            while len(length_data) < 2:
                chunk = sock.recv(2 - len(length_data))
                if not chunk:
                    break
                length_data += chunk

            msg_len = struct.unpack('!H', length_data)[0]

            msg_data = b''
            while len(msg_data) < msg_len:
                chunk = sock.recv(msg_len - len(msg_data))
                if not chunk:
                    break
                msg_data += chunk

            sock.close()
            data = msg_data

        result = parse_response(data)
        if result is None:
            continue

        rcode, records = result

        display_name = name.lower()
        if display_name.endswith('.') and display_name != '.':
            display_name = display_name[:-1]

        rcode_str = RCODE_NAMES.get(rcode, f'RCODE{rcode}')

        print(f"{display_name} {qtype_str} {rcode_str}")
        for owner, ttl, type_name, data_str in records:
            print(f"  {owner} {ttl} {type_name} {data_str}")


if __name__ == '__main__':
    main()

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        List<String[]> queries = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(Paths.get(dir, "queries.txt").toFile()))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;
                String[] parts = line.split(" ", 2);
                if (parts.length == 2) {
                    queries.add(new String[]{parts[0].trim(), parts[1].trim()});
                }
            }
        }

        for (String[] q : queries) {
            processQuery(q[0], q[1], port);
        }
    }

    static void processQuery(String name, String type, int port) throws Exception {
        int id = new Random().nextInt(65536);
        byte[] query = buildQuery(id, name, type);

        byte[] response = sendUdp(query, id, port);

        int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
        if ((flags & 0x0200) != 0) {
            response = sendTcp(query, id, port);
        }

        parseAndPrint(name, type, response);
    }

    static byte[] buildQuery(int id, String name, String type) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        bos.write((id >> 8) & 0xFF);
        bos.write(id & 0xFF);
        bos.write(0x01);
        bos.write(0x00);
        bos.write(0x00); bos.write(0x01);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);

        String qname = name;
        if (qname.endsWith(".")) {
            qname = qname.substring(0, qname.length() - 1);
        }
        if (!qname.isEmpty()) {
            String[] labels = qname.split("\\.");
            for (String label : labels) {
                byte[] lb = label.getBytes(StandardCharsets.US_ASCII);
                bos.write(lb.length);
                bos.writeBytes(lb);
            }
        }
        bos.write(0);

        int qtype = typeToCode(type);
        bos.write((qtype >> 8) & 0xFF);
        bos.write(qtype & 0xFF);
        bos.write(0x00);
        bos.write(0x01);

        return bos.toByteArray();
    }

    static int typeToCode(String type) {
        return switch (type.toUpperCase()) {
            case "A" -> 1;
            case "AAAA" -> 28;
            case "CNAME" -> 5;
            case "MX" -> 15;
            case "TXT" -> 16;
            default -> throw new IllegalArgumentException("Unknown type: " + type);
        };
    }

    static byte[] sendUdp(byte[] query, int id, int port) throws Exception {
        DatagramSocket socket = new DatagramSocket();
        socket.setSoTimeout(5000);
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        DatagramPacket send = new DatagramPacket(query, query.length, addr, port);
        socket.send(send);

        byte[] buf = new byte[65535];
        while (true) {
            DatagramPacket recv = new DatagramPacket(buf, buf.length);
            socket.receive(recv);
            byte[] data = Arrays.copyOf(recv.getData(), recv.getLength());
            if (data.length >= 12) {
                int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
                int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
                int qr = (flags >> 15) & 1;
                if (qr == 1 && respId == id) {
                    socket.close();
                    return data;
                }
            }
        }
    }

    static byte[] sendTcp(byte[] query, int id, int port) throws Exception {
        Socket socket = new Socket("127.0.0.1", port);
        socket.setSoTimeout(5000);

        DataOutputStream dos = new DataOutputStream(socket.getOutputStream());
        dos.writeShort(query.length);
        dos.write(query);
        dos.flush();

        DataInputStream dis = new DataInputStream(socket.getInputStream());
        int len = dis.readUnsignedShort();
        byte[] response = new byte[len];
        dis.readFully(response);

        socket.close();
        return response;
    }

    static void parseAndPrint(String name, String type, byte[] msg) {
        int flags = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
        int rcode = flags & 0x0F;
        int qdcount = ((msg[4] & 0xFF) << 8) | (msg[5] & 0xFF);
        int ancount = ((msg[6] & 0xFF) << 8) | (msg[7] & 0xFF);

        String rcodeStr = rcodeToString(rcode);

        String lowerName = name.toLowerCase();
        if (lowerName.endsWith(".")) lowerName = lowerName.substring(0, lowerName.length() - 1);
        System.out.println(lowerName + " " + type + " " + rcodeStr);

        int offset = 12;
        for (int i = 0; i < qdcount; i++) {
            offset = skipName(msg, offset);
            offset += 4;
        }

        for (int i = 0; i < ancount; i++) {
            String owner = readName(msg, offset);
            offset = skipName(msg, offset);

            int rtype = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
            long ttl = ((long)(msg[offset + 4] & 0xFF) << 24) | ((msg[offset + 5] & 0xFF) << 16)
                     | ((msg[offset + 6] & 0xFF) << 8) | (msg[offset + 7] & 0xFF);
            int rdlength = ((msg[offset + 8] & 0xFF) << 8) | (msg[offset + 9] & 0xFF);
            offset += 10;

            int rdataStart = offset;
            String rdata = parseRdata(msg, rdataStart, rdlength, rtype);
            offset += rdlength;

            String typeName = typeCodeToName(rtype);
            System.out.println("  " + owner + " " + ttl + " " + typeName + " " + rdata);
        }
    }

    static String rcodeToString(int rcode) {
        return switch (rcode) {
            case 0 -> "NOERROR";
            case 1 -> "FORMERR";
            case 2 -> "SERVFAIL";
            case 3 -> "NXDOMAIN";
            case 4 -> "NOTIMP";
            case 5 -> "REFUSED";
            default -> "RCODE" + rcode;
        };
    }

    static String typeCodeToName(int code) {
        return switch (code) {
            case 1 -> "A";
            case 5 -> "CNAME";
            case 15 -> "MX";
            case 16 -> "TXT";
            case 28 -> "AAAA";
            default -> "TYPE" + code;
        };
    }

    static int skipName(byte[] msg, int offset) {
        while (true) {
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                offset++;
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                offset += 2;
                break;
            }
            offset += 1 + len;
        }
        return offset;
    }

    static String readName(byte[] msg, int offset) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        int safety = 0;
        while (true) {
            if (++safety > 128) break;
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                int ptr = ((len & 0x3F) << 8) | (msg[offset + 1] & 0xFF);
                String rest = readName(msg, ptr);
                if (!rest.equals(".")) {
                    if (!first) sb.append('.');
                    sb.append(rest);
                }
                break;
            }
            if (!first) sb.append('.');
            sb.append(new String(msg, offset + 1, len, StandardCharsets.US_ASCII).toLowerCase());
            first = false;
            offset += 1 + len;
        }
        if (sb.length() == 0) return ".";
        return sb.toString();
    }

    static String parseRdata(byte[] msg, int offset, int rdlength, int rtype) {
        return switch (rtype) {
            case 1 -> parseA(msg, offset);
            case 28 -> parseAAAA(msg, offset);
            case 5 -> readName(msg, offset);
            case 15 -> parseMX(msg, offset);
            case 16 -> parseTXT(msg, offset, rdlength);
            default -> parseUnknown(msg, offset, rdlength);
        };
    }

    static String parseA(byte[] msg, int offset) {
        return (msg[offset] & 0xFF) + "." + (msg[offset + 1] & 0xFF) + "."
             + (msg[offset + 2] & 0xFF) + "." + (msg[offset + 3] & 0xFF);
    }

    static String parseAAAA(byte[] msg, int offset) {
        int[] groups = new int[8];
        for (int i = 0; i < 8; i++) {
            groups[i] = ((msg[offset + i * 2] & 0xFF) << 8) | (msg[offset + i * 2 + 1] & 0xFF);
        }

        int bestStart = -1, bestLen = 0;
        int curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (groups[i] == 0) {
                if (curStart == -1) { curStart = i; curLen = 1; }
                else curLen++;
            } else {
                if (curLen >= 2 && curLen > bestLen) {
                    bestStart = curStart; bestLen = curLen;
                }
                curStart = -1; curLen = 0;
            }
        }
        if (curLen >= 2 && curLen > bestLen) {
            bestStart = curStart; bestLen = curLen;
        }

        StringBuilder sb = new StringBuilder();
        if (bestStart == -1) {
            for (int i = 0; i < 8; i++) {
                if (i > 0) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
        } else {
            for (int i = 0; i < bestStart; i++) {
                if (i > 0) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
            sb.append("::");
            for (int i = bestStart + bestLen; i < 8; i++) {
                if (i > bestStart + bestLen) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
        }
        return sb.toString();
    }

    static String parseMX(byte[] msg, int offset) {
        int preference = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
        String exchange = readName(msg, offset + 2);
        return preference + " " + exchange;
    }

    static String parseTXT(byte[] msg, int offset, int rdlength) {
        StringBuilder sb = new StringBuilder();
        int end = offset + rdlength;
        int pos = offset;
        boolean first = true;
        while (pos < end) {
            int strLen = msg[pos] & 0xFF;
            pos++;
            if (!first) sb.append(' ');
            first = false;
            sb.append('"');
            for (int i = 0; i < strLen; i++) {
                int b = msg[pos + i] & 0xFF;
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b));
            }
            sb.append('"');
            pos += strLen;
        }
        return sb.toString();
    }

    static String parseUnknown(byte[] msg, int offset, int len) {
        StringBuilder sb = new StringBuilder();
        sb.append("\\# ").append(len);
        if (len > 0) {
            sb.append(' ');
            for (int i = 0; i < len; i++) {
                sb.append(String.format("%02x", msg[offset + i] & 0xFF));
            }
        }
        return sb.toString();
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as dgram from 'dgram';
import * as net from 'net';

const typeMap: Record<string, number> = {
  'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5
};

const rcodeNames: Record<number, string> = {
  0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'
};

function buildQuery(name: string, type: number): { buf: Buffer; id: number } {
  const id = Math.floor(Math.random() * 65536);
  const parts: number[] = [];

  parts.push((id >> 8) & 0xFF, id & 0xFF);
  parts.push(0x01, 0x00);
  parts.push(0x00, 0x01);
  parts.push(0x00, 0x00);
  parts.push(0x00, 0x00);
  parts.push(0x00, 0x00);

  const cleanName = name.replace(/\.$/, '');
  if (cleanName.length > 0) {
    const labels = cleanName.split('.');
    for (const label of labels) {
      parts.push(label.length);
      for (let i = 0; i < label.length; i++) {
        parts.push(label.charCodeAt(i) & 0xFF);
      }
    }
  }
  parts.push(0x00);

  parts.push((type >> 8) & 0xFF, type & 0xFF);
  parts.push(0x00, 0x01);

  return { buf: Buffer.from(parts), id };
}

function parseName(buf: Buffer, offset: number): { name: string; newOffset: number } {
  const labels: string[] = [];
  let currentOffset = offset;
  let jumped = false;
  let returnOffset = offset;

  while (currentOffset < buf.length) {
    const len = buf[currentOffset];
    if ((len & 0xC0) === 0xC0) {
      if (currentOffset + 1 >= buf.length) break;
      if (!jumped) {
        returnOffset = currentOffset + 2;
      }
      const ptr = ((len & 0x3F) << 8) | buf[currentOffset + 1];
      currentOffset = ptr;
      jumped = true;
    } else if (len === 0) {
      if (!jumped) {
        returnOffset = currentOffset + 1;
      }
      break;
    } else {
      const label = buf.slice(currentOffset + 1, currentOffset + 1 + len).toString('ascii');
      labels.push(label.toLowerCase());
      currentOffset += 1 + len;
      if (!jumped) {
        returnOffset = currentOffset;
      }
    }
  }

  const name = labels.length === 0 ? '.' : labels.join('.');
  return { name, newOffset: returnOffset };
}

function formatIPv6(buf: Buffer): string {
  const groups: number[] = [];
  for (let i = 0; i < 8; i++) {
    groups.push((buf[i * 2] << 8) | buf[i * 2 + 1]);
  }

  let bestStart = -1, bestLen = 0;
  let curStart = -1, curLen = 0;
  for (let i = 0; i < 8; i++) {
    if (groups[i] === 0) {
      if (curStart === -1) { curStart = i; curLen = 1; }
      else { curLen++; }
    } else {
      if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }
      curStart = -1; curLen = 0;
    }
  }
  if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }

  if (bestLen < 2) {
    return groups.map(g => g.toString(16)).join(':');
  }

  const before = groups.slice(0, bestStart).map(g => g.toString(16)).join(':');
  const after = groups.slice(bestStart + bestLen).map(g => g.toString(16)).join(':');

  if (bestStart === 0) {
    return '::' + after;
  } else if (bestStart + bestLen === 8) {
    return before + '::';
  } else {
    return before + '::' + after;
  }
}

function escapeTxtString(buf: Buffer): string {
  let result = '"';
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    if (b === 0x22) {
      result += '\\"';
    } else if (b === 0x5C) {
      result += '\\\\';
    } else if (b >= 0x20 && b <= 0x7E) {
      result += String.fromCharCode(b);
    } else {
      result += '\\' + b.toString(10).padStart(3, '0');
    }
  }
  result += '"';
  return result;
}

function sendUDP(query: Buffer, id: number, port: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = dgram.createSocket('udp4');

    const onData = (msg: Buffer) => {
      if (msg.length < 12) return;
      const msgId = (msg[0] << 8) | msg[1];
      const flags = (msg[2] << 8) | msg[3];
      const qr = (flags >> 15) & 1;
      if (qr === 1 && msgId === id) {
        socket.removeListener('message', onData);
        socket.close();
        resolve(msg);
      }
    };

    socket.on('message', onData);
    socket.on('error', (err) => { socket.close(); reject(err); });

    socket.send(query, port, '127.0.0.1', (err) => {
      if (err) { socket.close(); reject(err); }
    });
  });
}

function sendTCP(query: Buffer, id: number, port: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = net.connect(port, '127.0.0.1');
    let data = Buffer.alloc(0);
    let expectedLen = -1;

    socket.on('connect', () => {
      const lenBuf = Buffer.alloc(2);
      lenBuf.writeUInt16BE(query.length);
      socket.write(Buffer.concat([lenBuf, query]));
    });

    socket.on('data', (chunk) => {
      data = Buffer.concat([data, chunk]);
      if (expectedLen === -1 && data.length >= 2) {
        expectedLen = data.readUInt16BE(0);
      }
      if (expectedLen !== -1 && data.length >= 2 + expectedLen) {
        const msg = data.slice(2, 2 + expectedLen);
        socket.destroy();
        resolve(msg);
      }
    });

    socket.on('error', (err) => { socket.destroy(); reject(err); });
  });
}

function parseAndPrint(response: Buffer, queryName: string, queryType: string) {
  const flags = (response[2] << 8) | response[3];
  const rcode = flags & 0x0F;
  const qdcount = (response[4] << 8) | response[5];
  const ancount = (response[6] << 8) | response[7];

  const cleanName = queryName.replace(/\.$/, '').toLowerCase();
  const rcodeStr = rcodeNames[rcode] !== undefined ? rcodeNames[rcode] : `RCODE${rcode}`;
  console.log(`${cleanName} ${queryType} ${rcodeStr}`);

  let offset = 12;
  for (let i = 0; i < qdcount; i++) {
    while (offset < response.length) {
      const len = response[offset];
      if ((len & 0xC0) === 0xC0) {
        offset += 2;
        break;
      } else if (len === 0) {
        offset += 1;
        break;
      } else {
        offset += 1 + len;
      }
    }
    offset += 4;
  }

  for (let i = 0; i < ancount; i++) {
    const ownerResult = parseName(response, offset);
    const owner = ownerResult.name;
    offset = ownerResult.newOffset;

    const rtype = (response[offset] << 8) | response[offset + 1];
    offset += 2;
    offset += 2; // CLASS
    const ttl = response.readUInt32BE(offset);
    offset += 4;
    const rdlength = (response[offset] << 8) | response[offset + 1];
    offset += 2;

    const rdataStart = offset;
    const rdataEnd = offset + rdlength;

    let typeName: string;
    let dataStr: string;

    if (rtype === 1) {
      typeName = 'A';
      dataStr = `${response[rdataStart]}.${response[rdataStart + 1]}.${response[rdataStart + 2]}.${response[rdataStart + 3]}`;
    } else if (rtype === 28) {
      typeName = 'AAAA';
      dataStr = formatIPv6(response.slice(rdataStart, rdataEnd));
    } else if (rtype === 5) {
      typeName = 'CNAME';
      dataStr = parseName(response, rdataStart).name;
    } else if (rtype === 15) {
      typeName = 'MX';
      const pref = (response[rdataStart] << 8) | response[rdataStart + 1];
      const exchange = parseName(response, rdataStart + 2).name;
      dataStr = `${pref} ${exchange}`;
    } else if (rtype === 16) {
      typeName = 'TXT';
      const txtParts: string[] = [];
      let pos = rdataStart;
      while (pos < rdataEnd) {
        const strLen = response[pos];
        pos += 1;
        const strBuf = response.slice(pos, pos + strLen);
        pos += strLen;
        txtParts.push(escapeTxtString(strBuf));
      }
      dataStr = txtParts.join(' ');
    } else {
      typeName = `TYPE${rtype}`;
      if (rdlength === 0) {
        dataStr = '\\# 0';
      } else {
        dataStr = `\\# ${rdlength} ${response.slice(rdataStart, rdataEnd).toString('hex')}`;
      }
    }

    console.log(`  ${owner} ${ttl} ${typeName} ${dataStr}`);
    offset = rdataEnd;
  }
}

async function main() {
  const dir = process.argv[2];
  const port = parseInt(process.argv[3]);

  const content = fs.readFileSync(path.join(dir, 'queries.txt'), 'utf-8');
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === '') continue;

    const spaceIdx = trimmed.indexOf(' ');
    const name = trimmed.substring(0, spaceIdx);
    const typeStr = trimmed.substring(spaceIdx + 1).trim();
    const qtype = typeMap[typeStr.toUpperCase()];

    const { buf, id } = buildQuery(name, qtype);

    let response = await sendUDP(buf, id, port);

    const respFlags = (response[2] << 8) | response[3];
    const tc = (respFlags >> 9) & 1;

    if (tc) {
      response = await sendTCP(buf, id, port);
    }

    parseAndPrint(response, name, typeStr);
  }
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

import Foundation
import Darwin

func toBE16(_ v: UInt16) -> [UInt8] {
    return [UInt8(v >> 8), UInt8(v & 0xFF)]
}

func parseName(_ data: [UInt8], _ offset: Int) -> (name: String, nextOffset: Int) {
    var labels: [String] = []
    var pos = offset
    var nextOffset = offset
    var jumped = false
    var safety = 0

    while pos < data.count {
        safety += 1
        if safety > 128 { break }

        let len = Int(data[pos])
        if (len & 0xC0) == 0xC0 {
            if pos + 1 >= data.count { break }
            if !jumped {
                nextOffset = pos + 2
            }
            let ptr = ((len & 0x3F) << 8) | Int(data[pos + 1])
            pos = ptr
            jumped = true
        } else if len == 0 {
            if !jumped {
                nextOffset = pos + 1
            }
            break
        } else {
            if pos + 1 + len > data.count { break }
            let label = String(bytes: data[pos + 1 ..< pos + 1 + len], encoding: .ascii) ?? ""
            labels.append(label)
            pos += 1 + len
            if !jumped {
                nextOffset = pos
            }
        }
    }

    if labels.isEmpty {
        return (".", nextOffset)
    }
    return (labels.joined(separator: ".").lowercased(), nextOffset)
}

func buildQName(_ name: String) -> [UInt8] {
    var result: [UInt8] = []
    var n = name
    if n.hasSuffix(".") {
        n = String(n.dropLast())
    }
    if n.isEmpty {
        result.append(0)
        return result
    }
    let labels = n.components(separatedBy: ".")
    for label in labels {
        result.append(UInt8(label.count))
        result.append(contentsOf: Array(label.utf8))
    }
    result.append(0)
    return result
}

func typeNumber(_ typeStr: String) -> UInt16 {
    switch typeStr {
    case "A": return 1
    case "CNAME": return 5
    case "MX": return 15
    case "TXT": return 16
    case "AAAA": return 28
    default: return 0
    }
}

func typeName(_ type: UInt16) -> String {
    switch type {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(type)"
    }
}

func formatA(_ bytes: [UInt8]) -> String {
    return "\(bytes[0]).\(bytes[1]).\(bytes[2]).\(bytes[3])"
}

func formatAAAA(_ bytes: [UInt8]) -> String {
    var groups: [String] = []
    for i in 0..<8 {
        let hi = UInt16(bytes[i * 2]) << 8 | UInt16(bytes[i * 2 + 1])
        groups.append(String(format: "%x", hi))
    }

    var bestStart = -1
    var bestLen = 0
    var i = 0
    while i < 8 {
        if groups[i] == "0" {
            var j = i
            while j < 8 && groups[j] == "0" { j += 1 }
            let runLen = j - i
            if runLen >= 2 && runLen > bestLen {
                bestStart = i
                bestLen = runLen
            }
            i = j
        } else {
            i += 1
        }
    }

    if bestStart == -1 {
        return groups.joined(separator: ":")
    }

    var result = ""
    if bestStart > 0 {
        result = groups[0..<bestStart].joined(separator: ":")
    }
    result += "::"
    if bestStart + bestLen < 8 {
        result += groups[(bestStart + bestLen)...].joined(separator: ":")
    }
    return result
}

func escapeTXT(_ bytes: [UInt8]) -> String {
    var result = "\""
    for b in bytes {
        if b == 0x22 {
            result += "\\\""
        } else if b == 0x5C {
            result += "\\\\"
        } else if b >= 0x20 && b <= 0x7E {
            result += String(UnicodeScalar(b))
        } else {
            result += "\\\(String(format: "%03d", b))"
        }
    }
    result += "\""
    return result
}

func makeAddr(_ port: UInt16) -> sockaddr_in {
    var addr = sockaddr_in()
    addr.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr = in_addr(s_addr: inet_addr("127.0.0.1"))
    return addr
}

func udpExchange(_ query: [UInt8], _ id: UInt16, _ port: UInt16) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    if fd < 0 { return nil }
    defer { close(fd) }

    var addr = makeAddr(port)
    let sent = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            sendto(fd, query, query.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if sent < 0 { return nil }

    var buf = [UInt8](repeating: 0, count: 65535)
    while true {
        let n = recvfrom(fd, &buf, buf.count, 0, nil, nil)
        if n < 12 { continue }
        let respId = UInt16(buf[0]) << 8 | UInt16(buf[1])
        let flags = UInt16(buf[2]) << 8 | UInt16(buf[3])
        let qr = (flags >> 15) & 1
        if qr == 1 && respId == id {
            return Array(buf[0..<n])
        }
    }
}

func tcpExchange(_ query: [UInt8], _ port: UInt16) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0 { return nil }
    defer { close(fd) }

    var addr = makeAddr(port)
    let connected = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if connected < 0 { return nil }

    var toSend = toBE16(UInt16(query.count))
    toSend.append(contentsOf: query)
    let sent = send(fd, toSend, toSend.count, 0)
    if sent < 0 { return nil }

    var lenBuf = [UInt8](repeating: 0, count: 2)
    var totalRead = 0
    while totalRead < 2 {
        let n = read(fd, &lenBuf[totalRead], 2 - totalRead)
        if n <= 0 { return nil }
        totalRead += n
    }
    let msgLen = Int(UInt16(lenBuf[0]) << 8 | UInt16(lenBuf[1]))

    var msgBuf = [UInt8](repeating: 0, count: msgLen)
    totalRead = 0
    while totalRead < msgLen {
        let n = read(fd, &msgBuf[totalRead], msgLen - totalRead)
        if n <= 0 { return nil }
        totalRead += n
    }
    return msgBuf
}

func parseResponse(_ data: [UInt8]) -> (rcode: Int, records: [String]) {
    guard data.count >= 12 else { return (0, []) }

    let flags = UInt16(data[2]) << 8 | UInt16(data[3])
    let rcode = Int(flags & 0x000F)
    let qdcount = Int(UInt16(data[4]) << 8 | UInt16(data[5]))
    let ancount = Int(UInt16(data[6]) << 8 | UInt16(data[7]))

    var pos = 12

    for _ in 0..<qdcount {
        let (_, nextPos) = parseName(data, pos)
        pos = nextPos
        pos += 4
    }

    var records: [String] = []

    for _ in 0..<ancount {
        let (owner, nextPos) = parseName(data, pos)
        pos = nextPos

        if pos + 10 > data.count { break }
        let rtype = UInt16(data[pos]) << 8 | UInt16(data[pos + 1])
        let ttl = UInt32(data[pos + 4]) << 24 | UInt32(data[pos + 5]) << 16 | UInt32(data[pos + 6]) << 8 | UInt32(data[pos + 7])
        let rdlength = Int(UInt16(data[pos + 8]) << 8 | UInt16(data[pos + 9]))
        pos += 10

        let rdataStart = pos
        pos += rdlength

        let typeStr = typeName(rtype)
        var dataStr = ""

        switch rtype {
        case 1:
            if rdlength >= 4 {
                dataStr = formatA(Array(data[rdataStart..<rdataStart + 4]))
            }
        case 28:
            if rdlength >= 16 {
                dataStr = formatAAAA(Array(data[rdataStart..<rdataStart + 16]))
            }
        case 5:
            let (target, _) = parseName(data, rdataStart)
            dataStr = target
        case 15:
            if rdlength >= 3 {
                let pref = Int(UInt16(data[rdataStart]) << 8 | UInt16(data[rdataStart + 1]))
                let (exchange, _) = parseName(data, rdataStart + 2)
                dataStr = "\(pref) \(exchange)"
            }
        case 16:
            var txtPos = rdataStart
            let txtEnd = rdataStart + rdlength
            var strings: [String] = []
            while txtPos < txtEnd {
                let strLen = Int(data[txtPos])
                txtPos += 1
                if txtPos + strLen > txtEnd { break }
                let strBytes = Array(data[txtPos..<txtPos + strLen])
                txtPos += strLen
                strings.append(escapeTXT(strBytes))
            }
            dataStr = strings.joined(separator: " ")
        default:
            let rdata = Array(data[rdataStart..<rdataStart + rdlength])
            if rdata.isEmpty {
                dataStr = "\\# 0"
            } else {
                let hex = rdata.map { String(format: "%02x", $0) }.joined()
                dataStr = "\\# \(rdata.count) \(hex)"
            }
        }

        records.append("\(owner) \(ttl) \(typeStr) \(dataStr)")
    }

    return (rcode, records)
}

func resolveQuery(name: String, typeStr: String, port: UInt16) -> (rcode: Int, records: [String]) {
    let id = UInt16.random(in: 0...65535)

    var query: [UInt8] = []
    query.append(contentsOf: toBE16(id))
    query.append(contentsOf: toBE16(0x0100))
    query.append(contentsOf: toBE16(1))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: buildQName(name))
    query.append(contentsOf: toBE16(typeNumber(typeStr)))
    query.append(contentsOf: toBE16(1))

    guard let response = udpExchange(query, id, port) else {
        return (0, [])
    }

    if response.count >= 4 {
        let flags = UInt16(response[2]) << 8 | UInt16(response[3])
        let tc = (flags >> 9) & 1
        if tc == 1 {
            if let tcpResponse = tcpExchange(query, port) {
                return parseResponse(tcpResponse)
            }
        }
    }

    return parseResponse(response)
}

let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dir = args[1]
let port = UInt16(args[2])!

let queriesPath = dir + "/queries.txt"
let content = (try? String(contentsOfFile: queriesPath, encoding: .utf8)) ?? ""
let lines = content.components(separatedBy: "\n")

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    let parts = trimmed.split(separator: " ", omittingEmptySubsequences: true)
    guard parts.count >= 2 else { continue }
    let name = String(parts[0])
    let qtype = String(parts[1])

    let (rcode, records) = resolveQuery(name: name, typeStr: qtype, port: port)

    var lowerName = name.lowercased()
    if lowerName.hasSuffix(".") {
        lowerName = String(lowerName.dropLast())
    }
    if lowerName.isEmpty {
        lowerName = "."
    }

    let rcodeStr: String
    switch rcode {
    case 0: rcodeStr = "NOERROR"
    case 1: rcodeStr = "FORMERR"
    case 2: rcodeStr = "SERVFAIL"
    case 3: rcodeStr = "NXDOMAIN"
    case 4: rcodeStr = "NOTIMP"
    case 5: rcodeStr = "REFUSED"
    default: rcodeStr = "RCODE\(rcode)"
    }

    print("\(lowerName) \(qtype) \(rcodeStr)")
    for rec in records {
        print("  \(rec)")
    }
}

exit(0)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <stdint.h>

static uint16_t get_u16(const uint8_t *p) {
    return (uint16_t)((p[0] << 8) | p[1]);
}

static uint32_t get_u32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static void put_u16(uint8_t *p, uint16_t v) {
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)(v & 0xFF);
}

static const uint8_t *read_name(const uint8_t *msg, int msglen, const uint8_t *ptr,
                                 char *buf, int bufsize) {
    int pos = 0;
    int jumped = 0;
    const uint8_t *next = NULL;
    int guard = 0;

    while (1) {
        if (guard++ > 200) return NULL;
        if (ptr - msg >= msglen) return NULL;

        uint8_t len = *ptr;

        if ((len & 0xC0) == 0xC0) {
            if (ptr - msg + 1 >= msglen) return NULL;
            if (!jumped) {
                next = ptr + 2;
                jumped = 1;
            }
            int offset = ((len & 0x3F) << 8) | ptr[1];
            if (offset >= msglen) return NULL;
            ptr = msg + offset;
        } else if (len == 0) {
            if (!jumped) {
                next = ptr + 1;
            }
            break;
        } else {
            ptr++;
            if (ptr - msg + len > msglen) return NULL;
            if (pos > 0 && pos < bufsize - 1) {
                buf[pos++] = '.';
            }
            for (int i = 0; i < len && pos < bufsize - 1; i++) {
                buf[pos++] = (char)tolower(ptr[i]);
            }
            ptr += len;
        }
    }

    buf[pos] = '\0';
    if (pos == 0) {
        buf[0] = '.';
        buf[1] = '\0';
    }
    return next;
}

static void format_ipv6(const uint8_t *addr, char *buf, int bufsize) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (uint16_t)((addr[2*i] << 8) | addr[2*i+1]);

    int best_start = -1, best_len = 0;
    int i = 0;
    while (i < 8) {
        if (groups[i] == 0) {
            int j = i;
            while (j < 8 && groups[j] == 0) j++;
            int run = j - i;
            if (run >= 2 && run > best_len) {
                best_start = i;
                best_len = run;
            }
            i = j;
        } else {
            i++;
        }
    }

    int pos = 0;
    for (i = 0; i < 8; i++) {
        if (i == best_start) {
            buf[pos++] = ':';
            buf[pos++] = ':';
            i += best_len - 1;
            continue;
        }
        if (pos > 0 && buf[pos-1] != ':') {
            buf[pos++] = ':';
        }
        pos += snprintf(buf + pos, bufsize - pos, "%x", groups[i]);
    }
    buf[pos] = '\0';
}

static int read_exact(int fd, uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int r = (int)read(fd, buf + total, n - total);
        if (r <= 0) return -1;
        total += r;
    }
    return 0;
}

static int write_exact(int fd, const uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int w = (int)write(fd, buf + total, n - total);
        if (w <= 0) return -1;
        total += w;
    }
    return 0;
}

static int type_to_num(const char *t) {
    if (strcmp(t, "A") == 0) return 1;
    if (strcmp(t, "AAAA") == 0) return 28;
    if (strcmp(t, "MX") == 0) return 15;
    if (strcmp(t, "TXT") == 0) return 16;
    if (strcmp(t, "CNAME") == 0) return 5;
    return -1;
}

static const char *num_to_type(int t) {
    switch (t) {
        case 1: return "A";
        case 5: return "CNAME";
        case 15: return "MX";
        case 16: return "TXT";
        case 28: return "AAAA";
        default: return NULL;
    }
}

static const char *rcode_str(int rc) {
    switch (rc) {
        case 0: return "NOERROR";
        case 1: return "FORMERR";
        case 2: return "SERVFAIL";
        case 3: return "NXDOMAIN";
        case 4: return "NOTIMP";
        case 5: return "REFUSED";
        default: return NULL;
    }
}

static void print_txt_rdata(const uint8_t *rdata, int rdlen) {
    int pos = 0;
    int first = 1;
    while (pos < rdlen) {
        if (!first) putchar(' ');
        first = 0;
        int slen = rdata[pos++];
        if (pos + slen > rdlen) slen = rdlen - pos;
        putchar('"');
        for (int i = 0; i < slen; i++) {
            uint8_t c = rdata[pos++];
            if (c == '"') {
                putchar('\\'); putchar('"');
            } else if (c == '\\') {
                putchar('\\'); putchar('\\');
            } else if (c >= 0x20 && c <= 0x7E) {
                putchar(c);
            } else {
                printf("\\%03d", c);
            }
        }
        putchar('"');
    }
}

static void print_rdata(int type, const uint8_t *msg, int msglen,
                        const uint8_t *rdata, int rdlen) {
    if (type == 1) { /* A */
        if (rdlen >= 4)
            printf("%u.%u.%u.%u", rdata[0], rdata[1], rdata[2], rdata[3]);
    } else if (type == 28) { /* AAAA */
        if (rdlen >= 16) {
            char buf[64];
            format_ipv6(rdata, buf, sizeof(buf));
            printf("%s", buf);
        }
    } else if (type == 5) { /* CNAME */
        char name[1024];
        read_name(msg, msglen, rdata, name, sizeof(name));
        printf("%s", name);
    } else if (type == 15) { /* MX */
        if (rdlen >= 2) {
            int pref = get_u16(rdata);
            printf("%d ", pref);
            char name[1024];
            read_name(msg, msglen, rdata + 2, name, sizeof(name));
            printf("%s", name);
        }
    } else if (type == 16) { /* TXT */
        print_txt_rdata(rdata, rdlen);
    } else {
        printf("\\# %d", rdlen);
        if (rdlen > 0) {
            putchar(' ');
            for (int i = 0; i < rdlen; i++)
                printf("%02x", rdata[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) return 1;

    const char *dir = argv[1];
    int port = atoi(argv[2]);

    char path[4096];
    snprintf(path, sizeof(path), "%s/queries.txt", dir);

    FILE *f = fopen(path, "r");
    if (!f) return 1;

    srand((unsigned)time(NULL));

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        /* strip newline */
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r'))
            line[--len] = '\0';

        /* skip empty lines */
        int i = 0;
        while (i < len && isspace((unsigned char)line[i])) i++;
        if (i >= len) continue;

        /* parse name and type */
        char qname[1024], qtype_str[64];
        if (sscanf(line + i, "%1023s %63s", qname, qtype_str) < 2)
            continue;

        int qtype = type_to_num(qtype_str);
        if (qtype < 0) continue;

        /* build query */
        uint8_t query[2048];
        int qlen = 0;

        uint16_t qid = (uint16_t)(rand() & 0xFFFF);
        put_u16(query + 0, qid);
        put_u16(query + 2, 0x0100); /* flags */
        put_u16(query + 4, 1);      /* QDCOUNT */
        put_u16(query + 6, 0);      /* ANCOUNT */
        put_u16(query + 8, 0);      /* NSCOUNT */
        put_u16(query + 10, 0);     /* ARCOUNT */
        qlen = 12;

        /* encode QNAME: strip trailing dot, split by dots */
        char tmpname[1024];
        strncpy(tmpname, qname, sizeof(tmpname) - 1);
        tmpname[sizeof(tmpname)-1] = '\0';
        int tlen = (int)strlen(tmpname);
        if (tlen > 0 && tmpname[tlen-1] == '.')
            tmpname[--tlen] = '\0';

        if (tlen == 0) {
            query[qlen++] = 0; /* root */
        } else {
            char *p = tmpname;
            while (*p) {
                char *dot = strchr(p, '.');
                int lablen;
                if (dot) {
                    lablen = (int)(dot - p);
                } else {
                    lablen = (int)strlen(p);
                }
                if (lablen > 63) lablen = 63;
                query[qlen++] = (uint8_t)lablen;
                memcpy(query + qlen, p, lablen);
                qlen += lablen;
                if (dot) p = dot + 1; else p += lablen;
            }
            query[qlen++] = 0;
        }

        put_u16(query + qlen, (uint16_t)qtype); qlen += 2;
        put_u16(query + qlen, 1); qlen += 2; /* QCLASS = IN */

        /* send UDP and receive */
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons((uint16_t)port);
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);

        sendto(sock, query, qlen, 0, (struct sockaddr *)&addr, sizeof(addr));

        uint8_t resp[65536];
        int rlen = 0;
        while (1) {
            rlen = (int)recvfrom(sock, resp, sizeof(resp), 0, NULL, NULL);
            if (rlen < 12) continue;
            if (get_u16(resp) != qid) continue;
            if (!(resp[2] & 0x80)) continue; /* QR must be 1 */
            break;
        }
        close(sock);

        /* check TC */
        int tc = (resp[2] & 0x02) ? 1 : 0;

        if (tc) {
            /* TCP fallback */
            int tcp_sock = socket(AF_INET, SOCK_STREAM, 0);
            connect(tcp_sock, (struct sockaddr *)&addr, sizeof(addr));

            uint8_t tcpbuf[2048];
            put_u16(tcpbuf, (uint16_t)qlen);
            memcpy(tcpbuf + 2, query, qlen);
            write_exact(tcp_sock, tcpbuf, 2 + qlen);

            uint8_t tlen_buf[2];
            read_exact(tcp_sock, tlen_buf, 2);
            int tmsglen = get_u16(tlen_buf);
            if (tmsglen > (int)sizeof(resp)) tmsglen = (int)sizeof(resp);
            read_exact(tcp_sock, resp, tmsglen);
            rlen = tmsglen;
            close(tcp_sock);
        }

        /* parse response */
        if (rlen < 12) continue;

        int rcode = resp[3] & 0x0F;
        int qdcount = get_u16(resp + 4);
        int ancount = get_u16(resp + 6);

        /* print header line: lowercase name without trailing dot */
        char outname[1024];
        strncpy(outname, qname, sizeof(outname) - 1);
        outname[sizeof(outname)-1] = '\0';
        int onlen = (int)strlen(outname);
        if (onlen > 0 && outname[onlen-1] == '.')
            outname[--onlen] = '\0';
        for (int j = 0; j < onlen; j++)
            outname[j] = (char)tolower((unsigned char)outname[j]);
        if (onlen == 0) { outname[0] = '.'; outname[1] = '\0'; }

        printf("%s %s ", outname, qtype_str);
        const char *rs = rcode_str(rcode);
        if (rs) printf("%s\n", rs);
        else printf("RCODE%d\n", rcode);

        /* skip question section */
        const uint8_t *ptr = resp + 12;
        for (int q = 0; q < qdcount; q++) {
            char dummy[1024];
            ptr = read_name(resp, rlen, ptr, dummy, sizeof(dummy));
            if (!ptr) break;
            ptr += 4; /* QTYPE + QCLASS */
        }

        /* parse answer section */
        for (int a = 0; a < ancount && ptr; a++) {
            char owner[1024];
            ptr = read_name(resp, rlen, ptr, owner, sizeof(owner));
            if (!ptr) break;
            if (ptr - resp + 10 > rlen) break;

            int rtype = get_u16(ptr); ptr += 2;
            /* int rclass = */ ptr += 2; /* skip CLASS */
            uint32_t ttl = get_u32(ptr); ptr += 4;
            int rdlength = get_u16(ptr); ptr += 2;

            if (ptr - resp + rdlength > rlen) break;

            printf("  %s %u ", owner, ttl);
            const char *tn = num_to_type(rtype);
            if (tn) {
                printf("%s ", tn);
            } else {
                printf("TYPE%d ", rtype);
            }
            print_rdata(rtype, resp, rlen, ptr, rdlength);
            putchar('\n');

            ptr += rdlength;
        }
    }

    fclose(f);
    return 0;
}

import json
import sys
import os


def encode_pointer_token(token):
    return token.replace('~', '~0').replace('/', '~1')


def is_number(val):
    return isinstance(val, (int, float)) and not isinstance(val, bool)


def is_integer(val):
    if not is_number(val):
        return False
    if isinstance(val, int):
        return True
    if isinstance(val, float):
        return val == int(val)
    return False


def deep_equal(a, b):
    if isinstance(a, bool) and isinstance(b, bool):
        return a == b
    if isinstance(a, bool) or isinstance(b, bool):
        return False
    if is_number(a) and is_number(b):
        return float(a) == float(b)
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(deep_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(deep_equal(a[k], b[k]) for k in a)
    if a is None and b is None:
        return True
    return False


def matches_type(instance, type_name):
    if type_name == 'null':
        return instance is None
    if type_name == 'boolean':
        return isinstance(instance, bool)
    if type_name == 'number':
        return is_number(instance)
    if type_name == 'integer':
        return is_integer(instance)
    if type_name == 'string':
        return isinstance(instance, str)
    if type_name == 'array':
        return isinstance(instance, list)
    if type_name == 'object':
        return isinstance(instance, dict)
    return False


def validate(instance, schema, instance_loc, schema_loc, schema_root):
    errors = set()

    if isinstance(schema, bool):
        if schema is False:
            errors.add((instance_loc, schema_loc))
        return errors

    if not isinstance(schema, dict):
        return errors

    # type
    if 'type' in schema:
        type_val = schema['type']
        if isinstance(type_val, str):
            if not matches_type(instance, type_val):
                errors.add((instance_loc, schema_loc + '/type'))
        elif isinstance(type_val, list):
            if not any(matches_type(instance, t) for t in type_val):
                errors.add((instance_loc, schema_loc + '/type'))

    # enum
    if 'enum' in schema:
        if not any(deep_equal(instance, e) for e in schema['enum']):
            errors.add((instance_loc, schema_loc + '/enum'))

    # const
    if 'const' in schema:
        if not deep_equal(instance, schema['const']):
            errors.add((instance_loc, schema_loc + '/const'))

    # Number keywords
    if is_number(instance):
        if 'minimum' in schema:
            if float(instance) < float(schema['minimum']):
                errors.add((instance_loc, schema_loc + '/minimum'))
        if 'maximum' in schema:
            if float(instance) > float(schema['maximum']):
                errors.add((instance_loc, schema_loc + '/maximum'))
        if 'exclusiveMinimum' in schema:
            if float(instance) <= float(schema['exclusiveMinimum']):
                errors.add((instance_loc, schema_loc + '/exclusiveMinimum'))
        if 'exclusiveMaximum' in schema:
            if float(instance) >= float(schema['exclusiveMaximum']):
                errors.add((instance_loc, schema_loc + '/exclusiveMaximum'))

    # String keywords
    if isinstance(instance, str):
        if 'minLength' in schema:
            if len(instance) < schema['minLength']:
                errors.add((instance_loc, schema_loc + '/minLength'))
        if 'maxLength' in schema:
            if len(instance) > schema['maxLength']:
                errors.add((instance_loc, schema_loc + '/maxLength'))

    # Array keywords
    if isinstance(instance, list):
        if 'minItems' in schema:
            if len(instance) < schema['minItems']:
                errors.add((instance_loc, schema_loc + '/minItems'))
        if 'maxItems' in schema:
            if len(instance) > schema['maxItems']:
                errors.add((instance_loc, schema_loc + '/maxItems'))
        if 'uniqueItems' in schema and schema['uniqueItems'] is True:
            found_dup = False
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        found_dup = True
                        break
                if found_dup:
                    break
            if found_dup:
                errors.add((instance_loc, schema_loc + '/uniqueItems'))

        # prefixItems
        if 'prefixItems' in schema:
            prefix = schema['prefixItems']
            for i in range(min(len(instance), len(prefix))):
                child_loc = instance_loc + '/' + str(i)
                sub_loc = schema_loc + '/prefixItems/' + str(i)
                errors |= validate(instance[i], prefix[i], child_loc, sub_loc, schema_root)

        # items
        if 'items' in schema:
            start = len(schema.get('prefixItems', []))
            for i in range(start, len(instance)):
                child_loc = instance_loc + '/' + str(i)
                sub_loc = schema_loc + '/items'
                errors |= validate(instance[i], schema['items'], child_loc, sub_loc, schema_root)

    # Object keywords
    if isinstance(instance, dict):
        if 'minProperties' in schema:
            if len(instance) < schema['minProperties']:
                errors.add((instance_loc, schema_loc + '/minProperties'))
        if 'maxProperties' in schema:
            if len(instance) > schema['maxProperties']:
                errors.add((instance_loc, schema_loc + '/maxProperties'))

        if 'required' in schema:
            for j, name in enumerate(schema['required']):
                if name not in instance:
                    errors.add((instance_loc, schema_loc + '/required/' + str(j)))

        if 'properties' in schema:
            props = schema['properties']
            for name in instance:
                if name in props:
                    child_loc = instance_loc + '/' + encode_pointer_token(name)
                    sub_loc = schema_loc + '/properties/' + encode_pointer_token(name)
                    errors |= validate(instance[name], props[name], child_loc, sub_loc, schema_root)

        if 'additionalProperties' in schema:
            prop_names = set(schema['properties'].keys()) if 'properties' in schema else set()
            for name in instance:
                if name not in prop_names:
                    child_loc = instance_loc + '/' + encode_pointer_token(name)
                    sub_loc = schema_loc + '/additionalProperties'
                    errors |= validate(instance[name], schema['additionalProperties'], child_loc, sub_loc, schema_root)

    # Applicators
    if 'allOf' in schema:
        for i, sub in enumerate(schema['allOf']):
            sub_loc = schema_loc + '/allOf/' + str(i)
            errors |= validate(instance, sub, instance_loc, sub_loc, schema_root)

    if 'anyOf' in schema:
        any_accepted = False
        for i, sub in enumerate(schema['anyOf']):
            sub_loc = schema_loc + '/anyOf/' + str(i)
            sub_errors = validate(instance, sub, instance_loc, sub_loc, schema_root)
            if len(sub_errors) == 0:
                any_accepted = True
                break
        if not any_accepted:
            errors.add((instance_loc, schema_loc + '/anyOf'))

    if 'oneOf' in schema:
        count_accepted = 0
        for i, sub in enumerate(schema['oneOf']):
            sub_loc = schema_loc + '/oneOf/' + str(i)
            sub_errors = validate(instance, sub, instance_loc, sub_loc, schema_root)
            if len(sub_errors) == 0:
                count_accepted += 1
        if count_accepted != 1:
            errors.add((instance_loc, schema_loc + '/oneOf'))

    if 'not' in schema:
        sub_errors = validate(instance, schema['not'], instance_loc, schema_loc + '/not', schema_root)
        if len(sub_errors) == 0:
            errors.add((instance_loc, schema_loc + '/not'))

    if 'if' in schema:
        if_errors = validate(instance, schema['if'], instance_loc, schema_loc + '/if', schema_root)
        if len(if_errors) == 0:
            if 'then' in schema:
                errors |= validate(instance, schema['then'], instance_loc, schema_loc + '/then', schema_root)
        else:
            if 'else' in schema:
                errors |= validate(instance, schema['else'], instance_loc, schema_loc + '/else', schema_root)

    # $ref
    if '$ref' in schema:
        ref = schema['$ref']
        if ref == '#':
            resolved_schema = schema_root
            resolved_loc = '#'
        elif ref.startswith('#/$defs/'):
            token = ref[len('#/$defs/'):]
            name = token.replace('~1', '/').replace('~0', '~')
            resolved_schema = schema_root['$defs'][name]
            resolved_loc = '#/$defs/' + encode_pointer_token(name)
        else:
            resolved_schema = None
            resolved_loc = None
        if resolved_schema is not None:
            errors |= validate(instance, resolved_schema, instance_loc, resolved_loc, schema_root)

    return errors


def main():
    directory = sys.argv[1]

    with open(os.path.join(directory, 'schema.json'), 'r', encoding='utf-8') as f:
        schema = json.load(f)

    with open(os.path.join(directory, 'instances.json'), 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0

    for n, instance in enumerate(instances):
        errors = validate(instance, schema, '#', '#', schema)
        if len(errors) == 0:
            print(f"{n}: valid")
            valid_count += 1
        else:
            sorted_errors = sorted(errors, key=lambda e: (e[0], e[1]))
            print(f"{n}: invalid ({len(sorted_errors)})")
            for inst_loc, sch_loc in sorted_errors:
                print(f"  {inst_loc} {sch_loc}")
            invalid_count += 1

    print(f"valid={valid_count} invalid={invalid_count}")


