fn build_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut msg = Vec::new();

    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&0x0100u16.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());

    let trimmed = if name.ends_with('.') {
        &name[..name.len() - 1]
    } else {
        name
    };

    if !trimmed.is_empty() {
        for label in trimmed.split('.') {
            msg.push(label.len() as u8);
            msg.extend_from_slice(label.as_bytes());
        }
    }
    msg.push(0);

    msg.extend_from_slice(&qtype.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());

    msg
}

fn parse_name(msg: &[u8], offset: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = offset;
    let mut end_pos: Option<usize> = None;
    let mut jumped = false;
    let mut loop_count = 0;

    loop {
        loop_count += 1;
        if loop_count > 128 || pos >= msg.len() {
            break;
        }

        let len = msg[pos];

        if len & 0xC0 == 0xC0 {
            if !jumped {
                end_pos = Some(pos + 2);
                jumped = true;
            }
            if pos + 1 >= msg.len() {
                break;
            }
            let ptr = ((len as usize & 0x3F) << 8) | msg[pos + 1] as usize;
            pos = ptr;
        } else if len == 0 {
            if !jumped {
                end_pos = Some(pos + 1);
            }
            break;
        } else {
            let end = pos + 1 + len as usize;
            if end > msg.len() {
                break;
            }
            let label = String::from_utf8_lossy(&msg[pos + 1..end]).to_lowercase();
            labels.push(label);
            pos = end;
            if !jumped {
                end_pos = Some(pos);
            }
        }
    }

    let name = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    };

    (name, end_pos.unwrap_or(pos))
}

fn parse_response(msg: &[u8]) -> (u16, Vec<(String, u32, u16, usize, usize)>) {
    let rcode = (u16::from_be_bytes([msg[2], msg[3]])) & 0x0F;
    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let mut pos = 12;

    for _ in 0..qdcount {
        let (_, new_pos) = parse_name(msg, pos);
        pos = new_pos;
        pos += 4;
    }

    let mut records = Vec::new();
    for _ in 0..ancount {
        let (owner, new_pos) = parse_name(msg, pos);
        pos = new_pos;

        if pos + 10 > msg.len() {
            break;
        }
        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        pos += 2;
        pos += 2; // CLASS
        let ttl = u32::from_be_bytes([msg[pos], msg[pos + 1], msg[pos + 2], msg[pos + 3]]);
        pos += 4;
        let rdlength = u16::from_be_bytes([msg[pos], msg[pos + 1]]) as usize;
        pos += 2;
        let rdata_offset = pos;
        pos += rdlength;

        records.push((owner, ttl, rtype, rdata_offset, rdlength));
    }

    (rcode, records)
}

fn print_record(msg: &[u8], owner: &str, ttl: u32, rtype: u16, rdata_offset: usize, rdlength: usize) {
    if rdata_offset + rdlength > msg.len() {
        return;
    }
    let rdata = &msg[rdata_offset..rdata_offset + rdlength];

    match rtype {
        1 => {
