            if rdlength >= 2 {
                let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                let (exchange, _) = parse_name(msg, rdata_offset + 2);
                println!("  {} {} MX {} {}", owner, ttl, pref, exchange);
