            let data = format_generic(rdata);
            println!("  {} {} {} {}", owner, ttl, type_str, data);
        }
    }
}

fn format_ipv6(bytes: &[u8]) -> String {
    let mut groups = [0u16; 8];
    for i in 0..8 {
        groups[i] = u16::from_be_bytes([bytes[i * 2], bytes[i * 2 + 1]]);
    }

    let mut best_start = usize::MAX;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len >= 2 && len > best_len {
                best_start = start;
                best_len = len;
            }
        } else {
            i += 1;
        }
    }

    if best_len >= 2 {
        let before: Vec<String> = (0..best_start).map(|i| format!("{:x}", groups[i])).collect();
        let after: Vec<String> = ((best_start + best_len)..8)
            .map(|i| format!("{:x}", groups[i]))
            .collect();
        format!("{}::{}", before.join(":"), after.join(":"))
    } else {
        let parts: Vec<String> = (0..8).map(|i| format!("{:x}", groups[i])).collect();
        parts.join(":")
    }
}

fn format_txt(rdata: &[u8]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut pos = 0;
    while pos < rdata.len() {
        let len = rdata[pos] as usize;
        pos += 1;
        let end = std::cmp::min(pos + len, rdata.len());
        let s = &rdata[pos..end];
        let mut quoted = String::from("\"");
        for &b in s {
            if b == b'"' {
                quoted.push_str("\\\"");
            } else if b == b'\\' {
                quoted.push_str("\\\\");
            } else if b >= 0x20 && b <= 0x7E {
                quoted.push(b as char);
            } else {
                quoted.push_str(&format!("\\{:03}", b));
            }
        }
        quoted.push('"');
        parts.push(quoted);
        pos = end;
    }
    parts.join(" ")
}

fn format_generic(rdata: &[u8]) -> String {
    if rdata.is_empty() {
        "\\# 0".to_string()
    } else {
        let hex: String = rdata.iter().map(|b| format!("{:02x}", b)).collect();
        format!("\\# {} {}", rdata.len(), hex)
    }
}

fn normalize_name(name: &str) -> String {
    let lower = name.to_lowercase();
    let trimmed = if lower.ends_with('.') {
        &lower[..lower.len() - 1]
    } else {
        &lower
    };
    if trimmed.is_empty() {
        ".".to_string()
    } else {
        trimmed.to_string()
    }
}

fn type_str_to_num(s: &str) -> u16 {
    match s {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn rcode_to_str(rcode: u16) -> String {
    match rcode {
        0 => "NOERROR".to_string(),
        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        _ => format!("RCODE{}", rcode),
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ─── JSON Value Types ───────────────────────────────────────────────
    static abstract class JVal {
        enum Type { NULL, BOOLEAN, NUMBER, STRING, ARRAY, OBJECT }
        abstract Type type();
    }

    static final JVal JNULL = new JVal() { Type type() { return Type.NULL; } };

    static final class JBool extends JVal {
        final boolean v;
        JBool(boolean v) { this.v = v; }
        Type type() { return Type.BOOLEAN; }
    }

    static final class JNum extends JVal {
        final double v;
        JNum(double v) { this.v = v; }
        Type type() { return Type.NUMBER; }
        boolean isInt() { return v == Math.floor(v) && !Double.isInfinite(v); }
    }

    static final class JStr extends JVal {
        final String v;
        JStr(String v) { this.v = v; }
        Type type() { return Type.STRING; }
    }

    static final class JArr extends JVal {
        final List<JVal> el;
        JArr(List<JVal> el) { this.el = el; }
        Type type() { return Type.ARRAY; }
    }

    static final class JObj extends JVal {
        final LinkedHashMap<String, JVal> m;
        JObj(LinkedHashMap<String, JVal> m) { this.m = m; }
        Type type() { return Type.OBJECT; }
    }

    // ─── JSON Parser ────────────────────────────────────────────────────
    static final class Parser {
        final String s;
        int p;

        Parser(String s) { this.s = s; p = 0; }

        JVal parse() { skipWs(); JVal v = val(); skipWs(); return v; }

        void skipWs() {
            while (p < s.length()) {
                char c = s.charAt(p);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p++;
                else break;
            }
        }

        JVal val() {
            char c = s.charAt(p);
            if (c == '{') return obj();
            if (c == '[') return arr();
            if (c == '"') return str();
            if (c == 't') { p += 4; return new JBool(true); }
            if (c == 'f') { p += 5; return new JBool(false); }
            if (c == 'n') { p += 4; return JNULL; }
            return num();
        }

        JNum num() {
            int st = p;
            if (s.charAt(p) == '-') p++;
            while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++;
            if (p < s.length() && s.charAt(p) == '.') { p++; while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++; }
            if (p < s.length() && (s.charAt(p) == 'e' || s.charAt(p) == 'E')) {
                p++;
                if (p < s.length() && (s.charAt(p) == '+' || s.charAt(p) == '-')) p++;
                while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++;
            }
            return new JNum(Double.parseDouble(s.substring(st, p)));
        }

        JStr str() {
            p++; // skip "
            StringBuilder sb = new StringBuilder();
            while (p < s.length()) {
                char c = s.charAt(p);
                if (c == '"') { p++; break; }
                if (c == '\\') {
                    p++;
                    char e = s.charAt(p); p++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(s.substring(p, p + 4), 16); p += 4;
                            if (Character.isHighSurrogate((char) hi) && p + 1 < s.length()
                                    && s.charAt(p) == '\\' && s.charAt(p + 1) == 'u') {
                                p += 2;
                                int lo = Integer.parseInt(s.substring(p, p + 4), 16); p += 4;
                                sb.append((char) hi);
                                sb.append((char) lo);
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c); p++;
                }
            }
            return new JStr(sb.toString());
        }

        JArr arr() {
            p++; // [
            List<JVal> list = new ArrayList<>();
            skipWs();
            if (p < s.length() && s.charAt(p) == ']') { p++; return new JArr(list); }
            while (true) {
                skipWs(); list.add(val()); skipWs();
                if (s.charAt(p) == ',') p++; else break;
            }
            p++; // ]
            return new JArr(list);
        }

        JObj obj() {
            p++; // {
            LinkedHashMap<String, JVal> map = new LinkedHashMap<>();
            skipWs();
            if (p < s.length() && s.charAt(p) == '}') { p++; return new JObj(map); }
            while (true) {
                skipWs();
                JStr k = str();
                skipWs(); p++; // :
                skipWs();
                map.put(k.v, val());
                skipWs();
                if (s.charAt(p) == ',') p++; else break;
            }
            p++; // }
            return new JObj(map);
        }
    }

    // ─── Deep Equality ──────────────────────────────────────────────────
    static boolean deepEq(JVal a, JVal b) {
        if (a.type() != b.type()) return false;
        switch (a.type()) {
            case NULL: return true;
            case BOOLEAN: return ((JBool) a).v == ((JBool) b).v;
            case NUMBER: return ((JNum) a).v == ((JNum) b).v;
            case STRING: return ((JStr) a).v.equals(((JStr) b).v);
            case ARRAY: {
                List<JVal> la = ((JArr) a).el, lb = ((JArr) b).el;
                if (la.size() != lb.size()) return false;
                for (int i = 0; i < la.size(); i++) if (!deepEq(la.get(i), lb.get(i))) return false;
                return true;
            }
            case OBJECT: {
                LinkedHashMap<String, JVal> ma = ((JObj) a).m, mb = ((JObj) b).m;
                if (ma.size() != mb.size()) return false;
                for (Map.Entry<String, JVal> e : ma.entrySet()) {
                    JVal bv = mb.get(e.getKey());
                    if (bv == null || !deepEq(e.getValue(), bv)) return false;
                }
                return true;
            }
        }
        return false;
    }

    // ─── Error ──────────────────────────────────────────────────────────
    static final class Err {
        final String il, sl;
        Err(String il, String sl) { this.il = il; this.sl = sl; }
        @Override public boolean equals(Object o) {
            if (!(o instanceof Err)) return false;
            Err e = (Err) o; return il.equals(e.il) && sl.equals(e.sl);
        }
        @Override public int hashCode() { return Objects.hash(il, sl); }
    }

    static int cmpBytes(String a, String b) {
        byte[] ba = a.getBytes(StandardCharsets.UTF_8);
        byte[] bb = b.getBytes(StandardCharsets.UTF_8);
        int n = Math.min(ba.length, bb.length);
        for (int i = 0; i < n; i++) {
            int d = (ba[i] & 0xFF) - (bb[i] & 0xFF);
            if (d != 0) return d;
        }
        return ba.length - bb.length;
    }

    // ─── $ref Resolution ────────────────────────────────────────────────
    static JVal rootSchema;

    static String unescTok(String t) { return t.replace("~1", "/").replace("~0", "~"); }
    static String escTok(String s) { return s.replace("~", "~0").replace("/", "~1"); }

    static JVal resolveRef(String ref) {
        if (ref.equals("#")) return rootSchema;
        if (ref.startsWith("#/$defs/")) {
            String name = unescTok(ref.substring("#/$defs/".length()));
            if (rootSchema.type() == JVal.Type.OBJECT) {
                JVal defs = ((JObj) rootSchema).m.get("$defs");
                if (defs != null && defs.type() == JVal.Type.OBJECT)
                    return ((JObj) defs).m.get(name);
            }
        }
        return null;
    }

    static String refLoc(String ref) {
        if (ref.equals("#")) return "#";
        if (ref.startsWith("#/$defs/")) {
            String name = unescTok(ref.substring("#/$defs/".length()));
            return "#/$defs/" + escTok(name);
        }
        return ref;
    }

    // ─── Validation ─────────────────────────────────────────────────────
    static boolean accepts(JVal inst, JVal sch, String il, String sl) {
        Set<Err> errs = new HashSet<>();
        validate(inst, sch, il, sl, errs);
        return errs.isEmpty();
    }

    static void validate(JVal inst, JVal sch, String il, String sl, Set<Err> errs) {
        if (sch.type() == JVal.Type.BOOLEAN) {
            if (!((JBool) sch).v) errs.add(new Err(il, sl));
            return;
        }
        if (sch.type() != JVal.Type.OBJECT) return;
        JObj so = (JObj) sch;

        // type
        if (so.m.containsKey("type")) {
            if (!chkType(inst, so.m.get("type")))
                errs.add(new Err(il, sl + "/type"));
        }

        // enum
        if (so.m.containsKey("enum")) {
            JVal ev = so.m.get("enum");
            if (ev.type() == JVal.Type.ARRAY) {
                boolean ok = false;
                for (JVal e : ((JArr) ev).el) if (deepEq(inst, e)) { ok = true; break; }
                if (!ok) errs.add(new Err(il, sl + "/enum"));
            }
        }

        // const
        if (so.m.containsKey("const")) {
            if (!deepEq(inst, so.m.get("const")))
                errs.add(new Err(il, sl + "/const"));
        }

        // number keywords
        if (inst.type() == JVal.Type.NUMBER) {
            double nv = ((JNum) inst).v;
            if (so.m.containsKey("minimum")) {
                JVal v = so.m.get("minimum");
                if (v.type() == JVal.Type.NUMBER && nv < ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minimum"));
            }
            if (so.m.containsKey("maximum")) {
                JVal v = so.m.get("maximum");
                if (v.type() == JVal.Type.NUMBER && nv > ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maximum"));
            }
            if (so.m.containsKey("exclusiveMinimum")) {
                JVal v = so.m.get("exclusiveMinimum");
                if (v.type() == JVal.Type.NUMBER && nv <= ((JNum) v).v)
                    errs.add(new Err(il, sl + "/exclusiveMinimum"));
            }
            if (so.m.containsKey("exclusiveMaximum")) {
                JVal v = so.m.get("exclusiveMaximum");
                if (v.type() == JVal.Type.NUMBER && nv >= ((JNum) v).v)
                    errs.add(new Err(il, sl + "/exclusiveMaximum"));
            }
        }

        // string keywords
        if (inst.type() == JVal.Type.STRING) {
            String sv = ((JStr) inst).v;
            int len = sv.codePointCount(0, sv.length());
            if (so.m.containsKey("minLength")) {
                JVal v = so.m.get("minLength");
                if (v.type() == JVal.Type.NUMBER && len < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minLength"));
            }
            if (so.m.containsKey("maxLength")) {
                JVal v = so.m.get("maxLength");
                if (v.type() == JVal.Type.NUMBER && len > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxLength"));
            }
        }

        // array keywords
        if (inst.type() == JVal.Type.ARRAY) {
            List<JVal> el = ((JArr) inst).el;
            if (so.m.containsKey("minItems")) {
                JVal v = so.m.get("minItems");
                if (v.type() == JVal.Type.NUMBER && el.size() < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minItems"));
            }
            if (so.m.containsKey("maxItems")) {
                JVal v = so.m.get("maxItems");
                if (v.type() == JVal.Type.NUMBER && el.size() > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxItems"));
            }
            if (so.m.containsKey("uniqueItems")) {
                JVal v = so.m.get("uniqueItems");
                if (v.type() == JVal.Type.BOOLEAN && ((JBool) v).v) {
                    boolean uniq = true;
                    outer:
                    for (int i = 0; i < el.size(); i++)
                        for (int j = i + 1; j < el.size(); j++)
                            if (deepEq(el.get(i), el.get(j))) { uniq = false; break outer; }
                    if (!uniq) errs.add(new Err(il, sl + "/uniqueItems"));
                }
            }
            int pLen = 0;
            if (so.m.containsKey("prefixItems")) {
                JVal pi = so.m.get("prefixItems");
                if (pi.type() == JVal.Type.ARRAY) {
                    List<JVal> ps = ((JArr) pi).el;
                    pLen = ps.size();
                    for (int i = 0; i < Math.min(el.size(), ps.size()); i++)
                        validate(el.get(i), ps.get(i), il + "/" + i, sl + "/prefixItems/" + i, errs);
                }
            }
            if (so.m.containsKey("items")) {
                JVal is = so.m.get("items");
                for (int i = pLen; i < el.size(); i++)
                    validate(el.get(i), is, il + "/" + i, sl + "/items", errs);
            }
        }

        // object keywords
        if (inst.type() == JVal.Type.OBJECT) {
            LinkedHashMap<String, JVal> mem = ((JObj) inst).m;
            if (so.m.containsKey("minProperties")) {
                JVal v = so.m.get("minProperties");
                if (v.type() == JVal.Type.NUMBER && mem.size() < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minProperties"));
            }
            if (so.m.containsKey("maxProperties")) {
                JVal v = so.m.get("maxProperties");
                if (v.type() == JVal.Type.NUMBER && mem.size() > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxProperties"));
            }
            if (so.m.containsKey("required")) {
                JVal rq = so.m.get("required");
                if (rq.type() == JVal.Type.ARRAY) {
                    List<JVal> rl = ((JArr) rq).el;
                    for (int j = 0; j < rl.size(); j++) {
                        if (rl.get(j).type() == JVal.Type.STRING) {
                            if (!mem.containsKey(((JStr) rl.get(j)).v))
                                errs.add(new Err(il, sl + "/required/" + j));
                        }
                    }
                }
            }
            Set<String> pn = new HashSet<>();
            if (so.m.containsKey("properties")) {
                JVal pr = so.m.get("properties");
                if (pr.type() == JVal.Type.OBJECT) {
                    for (Map.Entry<String, JVal> e : ((JObj) pr).m.entrySet()) {
                        pn.add(e.getKey());
                        if (mem.containsKey(e.getKey()))
                            validate(mem.get(e.getKey()), e.getValue(),
                                    il + "/" + escTok(e.getKey()),
                                    sl + "/properties/" + escTok(e.getKey()), errs);
                    }
                }
            }
            if (so.m.containsKey("additionalProperties")) {
                JVal ap = so.m.get("additionalProperties");
                for (Map.Entry<String, JVal> e : mem.entrySet()) {
                    if (!pn.contains(e.getKey()))
                        validate(e.getValue(), ap,
                                il + "/" + escTok(e.getKey()),
                                sl + "/additionalProperties", errs);
                }
            }
        }

        // allOf
        if (so.m.containsKey("allOf")) {
            JVal ao = so.m.get("allOf");
            if (ao.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) ao).el;
                for (int i = 0; i < subs.size(); i++)
                    validate(inst, subs.get(i), il, sl + "/allOf/" + i, errs);
            }
        }

        // anyOf
        if (so.m.containsKey("anyOf")) {
            JVal ao = so.m.get("anyOf");
            if (ao.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) ao).el;
                boolean any = false;
                for (JVal sub : subs) {
                    if (accepts(inst, sub, il, sl + "/anyOf/0")) { any = true; break; }
                }
                if (!any) errs.add(new Err(il, sl + "/anyOf"));
            }
        }

        // oneOf
        if (so.m.containsKey("oneOf")) {
            JVal oo = so.m.get("oneOf");
            if (oo.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) oo).el;
                int cnt = 0;
                for (JVal sub : subs) {
                    if (accepts(inst, sub, il, sl + "/oneOf/0")) cnt++;
                }
                if (cnt != 1) errs.add(new Err(il, sl + "/oneOf"));
            }
        }

        // not
        if (so.m.containsKey("not")) {
            if (accepts(inst, so.m.get("not"), il, sl + "/not"))
                errs.add(new Err(il, sl + "/not"));
        }

        // if / then / else
        if (so.m.containsKey("if")) {
            boolean ifOk = accepts(inst, so.m.get("if"), il, sl + "/if");
            if (ifOk && so.m.containsKey("then"))
                validate(inst, so.m.get("then"), il, sl + "/then", errs);
            else if (!ifOk && so.m.containsKey("else"))
                validate(inst, so.m.get("else"), il, sl + "/else", errs);
        }

        // $ref
        if (so.m.containsKey("$ref")) {
            JVal rv = so.m.get("$ref");
            if (rv.type() == JVal.Type.STRING) {
                String ref = ((JStr) rv).v;
                JVal resolved = resolveRef(ref);
                if (resolved != null)
                    validate(inst, resolved, il, refLoc(ref), errs);
            }
        }
    }

    static boolean chkType(JVal inst, JVal tv) {
        if (tv.type() == JVal.Type.STRING) return matchT(inst, ((JStr) tv).v);
        if (tv.type() == JVal.Type.ARRAY) {
            for (JVal t : ((JArr) tv).el)
                if (t.type() == JVal.Type.STRING && matchT(inst, ((JStr) t).v)) return true;
            return false;
        }
        return true;
    }

    static boolean matchT(JVal inst, String tn) {
        switch (tn) {
            case "null":    return inst.type() == JVal.Type.NULL;
            case "boolean": return inst.type() == JVal.Type.BOOLEAN;
            case "number":  return inst.type() == JVal.Type.NUMBER;
            case "integer": return inst.type() == JVal.Type.NUMBER && ((JNum) inst).isInt();
            case "string":  return inst.type() == JVal.Type.STRING;
            case "array":   return inst.type() == JVal.Type.ARRAY;
            case "object":  return inst.type() == JVal.Type.OBJECT;
            default:        return true;
        }
    }

    // ─── Main ───────────────────────────────────────────────────────────
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schemaStr = new String(Files.readAllBytes(Paths.get(dir, "schema.json")), StandardCharsets.UTF_8);
        String instStr = new String(Files.readAllBytes(Paths.get(dir, "instances.json")), StandardCharsets.UTF_8);

        rootSchema = new Parser(schemaStr).parse();
        JVal instsVal = new Parser(instStr).parse();
        List<JVal> insts = ((JArr) instsVal).el;

        int vc = 0, ic = 0;
        for (int n = 0; n < insts.size(); n++) {
            Set<Err> errs = new HashSet<>();
            validate(insts.get(n), rootSchema, "#", "#", errs);
            if (errs.isEmpty()) {
                System.out.println(n + ": valid");
                vc++;
            } else {
                List<Err> sorted = new ArrayList<>(errs);
                sorted.sort((a, b) -> {
                    int c = cmpBytes(a.il, b.il);
                    return c != 0 ? c : cmpBytes(a.sl, b.sl);
                });
                System.out.println(n + ": invalid (" + sorted.size() + ")");
                for (Err e : sorted)
                    System.out.println("  " + e.il + " " + e.sl);
                ic++;
            }
        }
        System.out.println("valid=" + vc + " invalid=" + ic);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    neg: bool,
    digits: Vec<u32>,
}

impl BigInt {
    fn zero() -> Self { BigInt { neg: false, digits: vec![] } }
    fn is_zero(&self) -> bool { self.digits.is_empty() }
    fn is_odd(&self) -> bool { !self.digits.is_empty() && self.digits[0] % 2 == 1 }

    fn from_u64(v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let lo = (v % BASE) as u32;
        let hi = (v / BASE) as u32;
        let mut d = vec![lo];
        if hi > 0 { d.push(hi); }
        BigInt { neg: false, digits: d }
    }

    fn normalize(&mut self) {
        while self.digits.last() == Some(&0) { self.digits.pop(); }
        if self.digits.is_empty() { self.neg = false; }
    }

    fn abs(&self) -> Self { BigInt { neg: false, digits: self.digits.clone() } }

    fn cmp_abs(&self, o: &Self) -> i32 {
        if self.digits.len() != o.digits.len() {
            return if self.digits.len() > o.digits.len() { 1 } else { -1 };
        }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != o.digits[i] {
                return if self.digits[i] > o.digits[i] { 1 } else { -1 };
            }
        }
        0
    }

    fn cmp(&self, o: &Self) -> i32 {
        if self.neg != o.neg { return if self.neg { -1 } else { 1 }; }
        let c = self.cmp_abs(o);
        if self.neg { -c } else { c }
    }

    fn add_abs(&self, o: &Self) -> Self {
        let mut r = Vec::new();
        let mut c = 0u64;
        let n = self.digits.len().max(o.digits.len());
        for i in 0..n {
            let a = if i < self.digits.len() { self.digits[i] as u64 } else { 0 };
            let b = if i < o.digits.len() { o.digits[i] as u64 } else { 0 };
            let s = a + b + c;
            r.push((s % BASE) as u32);
            c = s / BASE;
        }
        if c > 0 { r.push(c as u32); }
        let mut res = BigInt { neg: self.neg, digits: r };
        res.normalize();
        res
    }

    fn sub_abs(&self, o: &Self) -> Self {
        let mut r = Vec::new();
        let mut b = 0i64;
        for i in 0..self.digits.len() {
            let a = self.digits[i] as i64;
            let d = if i < o.digits.len() { o.digits[i] as i64 } else { 0 };
            let mut diff = a - d - b;
            if diff < 0 { diff += BASE as i64; b = 1; } else { b = 0; }
            r.push(diff as u32);
        }
        let mut res = BigInt { neg: self.neg, digits: r };
        res.normalize();
        res
    }

    fn add(&self, o: &Self) -> Self {
        if self.neg == o.neg { self.add_abs(o) }
        else {
            let c = self.cmp_abs(o);
            if c >= 0 { self.sub_abs(o) } else { o.sub_abs(self) }
        }
    }

    fn sub(&self, o: &Self) -> Self {
        let mut no = o.clone();
        no.neg = !no.neg;
        if no.is_zero() { no.neg = false; }
        self.add(&no)
    }

    fn mul(&self, o: &Self) -> Self {
        if self.is_zero() || o.is_zero() { return Self::zero(); }
        let neg = self.neg != o.neg;
        let mut r = vec![0u64; self.digits.len() + o.digits.len()];
        for i in 0..self.digits.len() {
            let mut c = 0u64;
            for j in 0..o.digits.len() {
                let p = (self.digits[i] as u64) * (o.digits[j] as u64) + r[i + j] + c;
                r[i + j] = p % BASE;
                c = p / BASE;
            }
            let mut k = i + o.digits.len();
            while c > 0 {
                let s = r[k] + c;
                r[k] = s % BASE;
                c = s / BASE;
                k += 1;
            }
        }
        let d: Vec<u32> = r.iter().map(|&x| x as u32).collect();
        let mut res = BigInt { neg, digits: d };
        res.normalize();
        res
    }

    fn mul_small(&self, m: u32) -> Self {
        if m == 0 || self.is_zero() { return Self::zero(); }
        let mut r = Vec::new();
        let mut c = 0u64;
        for i in 0..self.digits.len() {
            let p = (self.digits[i] as u64) * (m as u64) + c;
            r.push((p % BASE) as u32);
            c = p / BASE;
        }
        while c > 0 { r.push((c % BASE) as u32); c /= BASE; }
        BigInt { neg: self.neg, digits: r }
    }

    fn divmod_abs(&self, div: &Self) -> (Self, Self) {
        if self.cmp_abs(div) < 0 { return (Self::zero(), self.abs()); }
        let mut q = vec![0u32; self.digits.len()];
        let mut rem = Self::zero();
        for i in (0..self.digits.len()).rev() {
            rem = rem.mul_small(BASE as u32);
            if self.digits[i] > 0 {
                rem = rem.add(&Self::from_u64(self.digits[i] as u64));
            }
            let mut lo: u32 = 0;
            let mut hi: u32 = (BASE - 1) as u32;
            while lo < hi {
                let mid = lo + (hi - lo + 1) / 2;
                let p = div.mul_small(mid);
                if p.cmp_abs(&rem) <= 0 { lo = mid; } else { hi = mid - 1; }
            }
            q[i] = lo;
            let p = div.mul_small(lo);
            rem = rem.sub_abs(&p);
        }
        let mut qq = BigInt { neg: false, digits: q };
        qq.normalize();
        (qq, rem)
    }

    fn to_usize(&self) -> usize {
        if self.is_zero() { return 0; }
        let mut val = 0usize;
        for i in (0..self.digits.len()).rev() {
            val = val * BASE as usize + self.digits[i] as usize;
        }
        val
    }

    fn to_string_plain(&self) -> String {
        if self.is_zero() { return "0".to_string(); }
        let mut s = String::new();
        if self.neg { s.push('-'); }
        let last = self.digits.last().unwrap();
        s.push_str(&last.to_string());
        for i in (0..self.digits.len() - 1).rev() {
            s.push_str(&format!("{:09}", self.digits[i]));
        }
        s
    }
}

fn round_half_even_div(value: &BigInt, divisor: &BigInt) -> BigInt {
    let neg = value.neg;
    let abs_val = value.abs();
    let (mut q, r) = abs_val.divmod_abs(divisor);
    let two_r = r.mul_small(2);
    let c = two_r.cmp_abs(divisor);
    if c > 0 {
        q = q.add(&BigInt::from_u64(1));
    } else if c == 0 {
        if q.is_odd() {
            q = q.add(&BigInt::from_u64(1));
        }
    }
    if neg && !q.is_zero() { q.neg = true; }
    q
}

fn pow10_u32(n: usize) -> u32 {
    let mut r = 1u32;
    for _ in 0..n { r *= 10; }
    r
}

fn pow10_bigint(n: usize) -> BigInt {
    let mut r = BigInt::from_u64(1);
    let ten = BigInt::from_u64(10);
    for _ in 0..n { r = r.mul(&ten); }
    r
}

#[derive(Clone, Debug)]
struct Decimal {
    value: BigInt,
    scale: usize,
}

fn parse_bigint_str(s: &str) -> BigInt {
    let mut r = BigInt::zero();
    for ch in s.chars() {
        let d = ch as u32 - '0' as u32;
        r = r.mul_small(10);
        if d > 0 { r = r.add(&BigInt::from_u64(d as u64)); }
    }
    r
}

fn parse_decimal(s: &str) -> Decimal {
    let (neg, s) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(pos) = s.find('.') {
        (&s[..pos], &s[pos + 1..])
    } else { (s, "") };
    let combined = format!("{}{}", int_part, frac_part);
    let scale = frac_part.len();
    let mut value = parse_bigint_str(&combined);
    if neg && !value.is_zero() { value.neg = true; }
    Decimal { value, scale }
}

fn round_to_minor(dec: &Decimal, minor: usize) -> BigInt {
    if dec.scale <= minor {
        let f = pow10_u32(minor - dec.scale);
        dec.value.mul_small(f)
    } else {
        let d = pow10_bigint(dec.scale - minor);
        round_half_even_div(&dec.value, &d)
    }
}

fn add_commas(s: &str) -> String {
    let mut r = String::new();
    let len = s.len();
    for (i, ch) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 { r.push(','); }
        r.push(ch);
    }
    r
}

fn format_money(value: &BigInt, minor: usize) -> String {
    if value.is_zero() {
        if minor == 0 { return "0".to_string(); }
        let mut s = "0.".to_string();
        for _ in 0..minor { s.push('0'); }
        return s;
    }
    let abs_val = value.abs();
    let digits_str = abs_val.to_string_plain();
    let neg_str = if value.neg { "-" } else { "" };
    if minor == 0 {
        return format!("{}{}", neg_str, add_commas(&digits_str));
    }
    let padded = if digits_str.len() <= minor {
        format!("{}{}", "0".repeat(minor - digits_str.len() + 1), digits_str)
    } else {
        digits_str.clone()
    };
    let int_part = &padded[..padded.len() - minor];
    let frac_part = &padded[padded.len() - minor..];
    format!("{}{},{}", neg_str, add_commas(int_part), frac_part)
}

fn neg_bigint(b: &BigInt) -> BigInt {
    if b.is_zero() { return BigInt::zero(); }
    let mut r = b.clone();
    r.neg = !r.neg;
    r
}

struct Account {
    currency: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/ledger.txt", dir);
    let content = fs::read_to_string(&path).unwrap();
    let lines: Vec<&str> = content.lines().collect();

    let mut currencies: HashMap<String, usize> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (i, line) in lines.iter().enumerate() {
        let line_num = i + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = fields[0];

        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: usize = fields[2].parse().unwrap();
                currencies.insert(code, minor);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                    continue;
                }
                let minor = currencies[&code];
                let limit = if fields.len() > 3 {
                    let lim_dec = parse_decimal(fields[3]);
                    let l = round_to_minor(&lim_dec, minor);
                    if l.neg { BigInt::zero() } else { l }
                } else {
                    BigInt::zero()
                };
                accounts.insert(name, Account { currency: code, balance: BigInt::zero(), limit });
            }
            "deposit" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let amt_dec = parse_decimal(fields[2]);
                let minor = currencies[&accounts[&name].currency];
                let amt = round_to_minor(&amt_dec, minor);
                if amt.cmp(&BigInt::zero()) <= 0 {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let new_bal = accounts[&name].balance.add(&amt);
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "withdraw" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let amt_dec = parse_decimal(fields[2]);
                let minor = currencies[&accounts[&name].currency];
                let amt = round_to_minor(&amt_dec, minor);
                if amt.cmp(&BigInt::zero()) <= 0 {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let new_bal = accounts[&name].balance.sub(&amt);
                let min_bal = neg_bigint(&accounts[&name].limit);
                if new_bal.cmp(&min_bal) < 0 {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "transfer" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to_name));
                    continue;
                }
                if accounts[&from_name].currency != accounts[&to_name].currency {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = currencies[&accounts[&from_name].currency];
                let amt_dec = parse_decimal(fields[3]);
                let amt = round_to_minor(&amt_dec, minor);
                if amt.cmp(&BigInt::zero()) <= 0 {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let new_bal = accounts[&from_name].balance.sub(&amt);
                let min_bal = neg_bigint(&accounts[&from_name].limit);
                if new_bal.cmp(&min_bal) < 0 {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                    continue;
                }
                let to_new = accounts[&to_name].balance.add(&amt);
                accounts.get_mut(&from_name).unwrap().balance = new_bal;
                accounts.get_mut(&to_name).unwrap().balance = to_new;
            }
            "convert" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to_name));
                    continue;
                }
                let from_minor = currencies[&accounts[&from_name].currency];
                let to_minor = currencies[&accounts[&to_name].currency];
                let amt_dec = parse_decimal(fields[3]);
                let rate_dec = parse_decimal(fields[4]);
                let amt = round_to_minor(&amt_dec, from_minor);
                if amt.cmp(&BigInt::zero()) <= 0 {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let new_bal = accounts[&from_name].balance.sub(&amt);
                let min_bal = neg_bigint(&accounts[&from_name].limit);
                if new_bal.cmp(&min_bal) < 0 {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                    continue;
                }
                let product = Decimal {
                    value: amt.mul(&rate_dec.value),
                    scale: from_minor + rate_dec.scale,
                };
                let received = round_to_minor(&product, to_minor);
                let to_new = accounts[&to_name].balance.add(&received);
                accounts.get_mut(&from_name).unwrap().balance = new_bal;
                accounts.get_mut(&to_name).unwrap().balance = to_new;
            }
            "interest" => {
                let name = fields[1].to_string();
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let rate_dec = parse_decimal(fields[2]);
                let minor = currencies[&accounts[&name].currency];
                let balance = accounts[&name].balance.clone();
                let product = Decimal {
                    value: balance.mul(&rate_dec.value),
                    scale: rate_dec.scale,
                };
                let interest = round_to_minor(&product, 0);
                let new_bal = accounts[&name].balance.add(&interest);
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "split" => {
                let from_name = fields[1].to_string();
                let mut targets: Vec<(String, BigInt)> = Vec::new();
                for i in 3..fields.len() {
                    let f = fields[i];
                    let colon_pos = f.rfind(':').unwrap();
                    let tname = f[..colon_pos].to_string();
                    let w = parse_bigint_str(&f[colon_pos + 1..]);
                    targets.push((tname, w));
                }
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                    continue;
                }
                let mut unknown_found = false;
                for (tname, _) in &targets {
                    if !accounts.contains_key(tname) {
                        rejections.push(format!("line {}: REJECT unknown account {}", line_num, tname));
                        unknown_found = true;
                        break;
                    }
                }
                if unknown_found { continue; }
                let from_cur = accounts[&from_name].currency.clone();
                if targets.iter().any(|(tname, _)| accounts[tname].currency != from_cur) {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = currencies[&from_cur];
                let amt_dec = parse_decimal(fields[2]);
                let amt = round_to_minor(&amt_dec, minor);
                if amt.cmp(&BigInt::zero()) <= 0 {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let new_bal = accounts[&from_name].balance.sub(&amt);
                let min_bal = neg_bigint(&accounts[&from_name].limit);
                if new_bal.cmp(&min_bal) < 0 {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                    continue;
                }
                let mut total_weight = BigInt::zero();
                for (_, w) in &targets {
                    total_weight = total_weight.add(w);
                }
                let mut bases: Vec<BigInt> = Vec::new();
                let mut rems: Vec<BigInt> = Vec::new();
                let mut sum_base = BigInt::zero();
                for (_, w) in &targets {
                    let prod = amt.mul(w);
                    let (q, r) = prod.divmod_abs(&total_weight);
                    bases.push(q.clone());
                    rems.push(r);
                    sum_base = sum_base.add(&q);
                }
                let leftover = amt.sub(&sum_base);
                let n = targets.len();
                let mut indices: Vec<usize> = (0..n).collect();
                indices.sort_by(|&a, &b| {
                    let c = rems[b].cmp_abs(&rems[a]);
                    if c != 0 { c } else { a.cmp(&b) }
                });
                let leftover_n = leftover.to_usize();
                for i in 0..leftover_n {
                    bases[indices[i]] = bases[indices[i]].add(&BigInt::from_u64(1));
                }
                accounts.get_mut(&from_name).unwrap().balance = new_bal;
                for (i, (tname, _)) in targets.iter().enumerate() {
                    let nb = accounts[tname].balance.add(&bases[i]);
                    accounts.get_mut(tname).unwrap().balance = nb;
                }
            }
            _ => {}
        }
    }

    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut account_names: Vec<&String> = accounts.keys().collect();
    account_names.sort();

    for name in &account_names {
        let acc = &accounts[*name];
        let minor = currencies[&acc.currency];
        println!("{} {} {}", name, acc.currency, format_money(&acc.balance, minor));
    }

    println!();

    let mut totals: HashMap<String, (BigInt, usize)> = HashMap::new();
    for acc in accounts.values() {
        let entry = totals.entry(acc.currency.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance);
        entry.1 += 1;
    }

    let mut codes: Vec<&String> = totals.keys().collect();
    codes.sort();

    for code in &codes {
        let (total, count) = &totals[*code];
        let minor = currencies[*code];
        println!("total {} {} ({} accounts)", code, format_money(total, minor), count);
    }
}

import sys
import json
import hmac
import hashlib
import base64
import os


def is_valid_base64url(s):
    if not s:
        return False
    valid_chars = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_')
    for c in s:
        if c not in valid_chars:
            return False
    if len(s) % 4 == 1:
        return False
    return True


def base64url_decode(s):
    padding = 4 - (len(s) % 4)
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)


def validate_token(token, keys, now, leeway, issuer, audience):
    # Rule 1: MALFORMED
    segments = token.split('.')
    if len(segments) != 3:
        return 'MALFORMED'

    for seg in segments:
        if seg == '':
            return 'MALFORMED'
        if not is_valid_base64url(seg):
            return 'MALFORMED'

    # Decode header and payload
    try:
        header_bytes = base64url_decode(segments[0])
        payload_bytes = base64url_decode(segments[1])
    except Exception:
        return 'MALFORMED'

    try:
        header = json.loads(header_bytes.decode('utf-8'))
        payload = json.loads(payload_bytes.decode('utf-8'))
    except Exception:
        return 'MALFORMED'

    if not isinstance(header, dict) or not isinstance(payload, dict):
        return 'MALFORMED'

    # Rule 2: UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
        return 'UNSUPPORTED_ALG'

    # Rule 3: UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys:
        return 'UNKNOWN_KEY'

    key = keys[kid]

    # Rule 4: ALG_MISMATCH
    if key['alg'] != alg:
        return 'ALG_MISMATCH'

    # Rule 5: BAD_SIGNATURE
    signing_input = (segments[0] + '.' + segments[1]).encode('ascii')
    secret = base64url_decode(key['k'])
    hash_func = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}[alg]
    expected_sig = hmac.new(secret, signing_input, hash_func).digest()

    try:
        actual_sig = base64url_decode(segments[2])
    except Exception:
        return 'BAD_SIGNATURE'

    if not hmac.compare_digest(expected_sig, actual_sig):
        return 'BAD_SIGNATURE'

    # Rule 6: EXPIRED
    if 'exp' in payload:
        exp = payload['exp']
        if now >= exp + leeway:
            return 'EXPIRED'

    # Rule 7: NOT_YET_VALID
    if 'nbf' in payload:
        nbf = payload['nbf']
        if now + leeway < nbf:
            return 'NOT_YET_VALID'

    # Rule 8: BAD_ISSUER
    iss = payload.get('iss')
    if not isinstance(iss, str) or iss != issuer:
        return 'BAD_ISSUER'

    # Rule 9: BAD_AUDIENCE
    aud = payload.get('aud')
    if aud is None:
        return 'BAD_AUDIENCE'
    if isinstance(aud, str):
        if aud != audience:
            return 'BAD_AUDIENCE'
    elif isinstance(aud, list):
        if audience not in aud:
            return 'BAD_AUDIENCE'
    else:
        return 'BAD_AUDIENCE'

    return 'VALID'


def main():
    dir_path = sys.argv[1]

    with open(os.path.join(dir_path, 'config.json'), 'r', encoding='utf-8') as f:
        config = json.load(f)

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = {k['kid']: k for k in config['keys']}

    with open(os.path.join(dir_path, 'tokens.txt'), 'r', encoding='utf-8') as f:
        lines = f.read().split('\n')

    valid_count = 0
    invalid_count = 0
    results = []

    token_num = 0
    for line in lines:
        stripped = line.strip(' \t')
        if stripped == '':
            continue
        token_num += 1

        result = validate_token(stripped, keys, now, leeway, issuer, audience)
        if result == 'VALID':
            valid_count += 1
        else:
            invalid_count += 1

        if result == 'VALID':
            segments = stripped.split('.')
            payload = json.loads(base64url_decode(segments[1]))
            sub = payload['sub']
            scope_str = payload.get('scope', '')
            if scope_str:
                scopes = sorted(set(s for s in scope_str.split(' ') if s))
                scope_str_out = ','.join(scopes)
            else:
                scope_str_out = ''
            results.append(f"{token_num}: VALID sub={sub} scope={scope_str_out}")
        else:
            results.append(f"{token_num}: {result}")

    for r in results:
        print(r)
    print()
    print(f"valid={valid_count} invalid={invalid_count}")


