def is_valid_id(val):
    if isinstance(val, str):
        return True
    if isinstance(val, int) and not isinstance(val, bool):
        return True
    return False


def count_words(text):
    separators = {' ', '\t', '\n', '\r'}
    count = 0
    in_word = False
    for ch in text:
        if ch in separators:
            in_word = False
        else:
            if not in_word:
                count += 1
                in_word = True
    return count


