fn sha512_generic(data: &[u8], h_init: [u64;8], out_len: usize) -> Vec<u8> {
    let mut h = h_init;
    let bit_len = (data.len() as u128) * 8;
    let mut padded = data.to_vec();
    padded.push(0x80);
    while padded.len() % 128 != 112 { padded.push(0); }
    padded.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in padded.chunks(128) {
        let mut w = [0u64;80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8*i],chunk[8*i+1],chunk[8*i+2],chunk[8*i+3],
                chunk[8*i+4],chunk[8*i+5],chunk[8*i+6],chunk[8*i+7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i-15].rotate_right(1)^w[i-15].rotate_right(8)^(w[i-15]>>7);
            let s1 = w[i-2].rotate_right(19)^w[i-2].rotate_right(61)^(w[i-2]>>6);
            w[i] = w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);
        }
        let (mut a,mut b,mut c,mut d,mut e,mut f,mut g,mut hh) =
            (h[0],h[1],h[2],h[3],h[4],h[5],h[6],h[7]);
        for i in 0..80 {
            let s1 = e.rotate_right(14)^e.rotate_right(18)^e.rotate_right(41);
            let ch = (e&f)^((!e)&g);
            let t1 = hh.wrapping_add(s1).wrapping_add(ch).wrapping_add(K512[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(28)^a.rotate_right(34)^a.rotate_right(39);
            let maj = (a&b)^(a&c)^(b&c);
            let t2 = s0.wrapping_add(maj);
            hh=g;g=f;f=e;e=d.wrapping_add(t1);
            d=c;c=b;b=a;a=t1.wrapping_add(t2);
        }
        h[0]=h[0].wrapping_add(a);h[1]=h[1].wrapping_add(b);
        h[2]=h[2].wrapping_add(c);h[3]=h[3].wrapping_add(d);
        h[4]=h[4].wrapping_add(e);h[5]=h[5].wrapping_add(f);
        h[6]=h[6].wrapping_add(g);h[7]=h[7].wrapping_add(hh);
    }
    let mut out = Vec::with_capacity(out_len);
    for i in 0..8 {
        let bytes = h[i].to_be_bytes();
        let n = std::cmp::min(8, out_len.saturating_sub(i*8));
        out.extend_from_slice(&bytes[..n]);
    }
    out
}

fn sha512(data: &[u8]) -> Vec<u8> {
    sha512_generic(data, [
        0x6a09e667f3bcc908,0xbb67ae8584caa73b,0x3c6ef372fe94f82b,0xa54ff53a5f1d36f1,
        0x510e527fade682d1,0x9b05688c2b3e6c1f,0x1f83d9abfb41bd6b,0x5be0cd19137e2179,
    ], 64)
}

fn sha384(data: &[u8]) -> Vec<u8> {
    sha512_generic(data, [
        0xcbbb9d5dc1059ed8,0x629a292a367cd507,0x9159015a3070dd17,0x152fecd8f70e5939,
        0x67332667ffc00b31,0x8eb44a8768581511,0xdb0c2e0d64f98fa7,0x47b5481dbefa4fa4,
    ], 48)
}

// ============ HMAC ============

fn hmac(alg: &str, key: &[u8], message: &[u8]) -> Vec<u8> {
    let (hash_fn, block_size): (fn(&[u8])->Vec<u8>, usize) = match alg {
        "HS256" => (sha256, 64),
        "HS384" => (sha384, 128),
        "HS512" => (sha512, 128),
        _ => unreachable!(),
    };
    let mut k = if key.len() > block_size { hash_fn(key) } else { key.to_vec() };
    k.resize(block_size, 0);
    let ipad: Vec<u8> = k.iter().map(|b| b ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|b| b ^ 0x5c).collect();
    let mut inner = ipad;
    inner.extend_from_slice(message);
    let inner_hash = hash_fn(&inner);
    let mut outer = opad;
    outer.extend_from_slice(&inner_hash);
    hash_fn(&outer)
}

