fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let config_str = fs::read_to_string(format!("{}/config.json", dir)).unwrap();
    let config = parse_json(config_str.as_bytes()).unwrap();
    let now = config.get("now").unwrap().as_f64().unwrap();
    let leeway = config.get("leeway").unwrap().as_f64().unwrap();
    let issuer = config.get("issuer").unwrap().as_str().unwrap().to_string();
    let audience = config.get("audience").unwrap().as_str().unwrap().to_string();
    let keys_arr = config.get("keys").unwrap().as_array().unwrap().to_vec();
    let tokens_str = fs::read_to_string(format!("{}/tokens.txt", dir)).unwrap();

    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;
    let mut line_num = 0usize;
    let mut out_lines: Vec<String> = Vec::new();

    for raw in tokens_str.split('\n') {
        let trimmed = raw.trim();
        if trimmed.is_empty() { continue; }
        line_num += 1;
        match verify_token(trimmed, now, leeway, &issuer, &audience, &keys_arr) {
            Ok((sub, scopes)) => {
                out_lines.push(format!("{}: VALID sub={} scope={}", line_num, sub, scopes));
                valid_count += 1;
            }
            Err(e) => {
                out_lines.push(format!("{}: {}", line_num, e));
                invalid_count += 1;
            }
        }
    }

    for l in &out_lines { println!("{}", l); }
    println!();
    println!("valid={} invalid={}", valid_count, invalid_count);
}

fn verify_token(
    token: &str,
    now: f64,
    leeway: f64,
    issuer: &str,
    audience: &str,
    keys: &[JsonValue],
) -> Result<(String, String), String> {
    // Rule 1: MALFORMED
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return Err("MALFORMED".into()); }
    for p in &parts { if p.is_empty() { return Err("MALFORMED".into()); } }
    let header_bytes = base64url_decode(parts[0]).ok_or("MALFORMED")?;
    let payload_bytes = base64url_decode(parts[1]).ok_or("MALFORMED")?;
    let sig_bytes = base64url_decode(parts[2]).ok_or("MALFORMED")?;
    let header = parse_json(&header_bytes).ok_or("MALFORMED")?;
    if !matches!(header, JsonValue::Object(_)) { return Err("MALFORMED".into()); }
    let payload = parse_json(&payload_bytes).ok_or("MALFORMED")?;
    if !matches!(payload, JsonValue::Object(_)) { return Err("MALFORMED".into()); }

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(JsonValue::String(s)) if s=="HS256"||s=="HS384"||s=="HS512" => s.clone(),
        _ => return Err("UNSUPPORTED_ALG".into()),
    };

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => return Err("UNKNOWN_KEY".into()),
    };
    let key_obj = keys.iter().find(|k| k.get("kid").and_then(|v|v.as_str())==Some(&kid));
    let key_obj = match key_obj { Some(k)=>k, None=>return Err("UNKNOWN_KEY".into()) };

    // Rule 4: ALG_MISMATCH
    if key_obj.get("alg").and_then(|v|v.as_str()).unwrap_or("") != alg {
        return Err("ALG_MISMATCH".into());
    }

    // Rule 5: BAD_SIGNATURE
    let k_b64 = key_obj.get("k").and_then(|v|v.as_str()).unwrap_or("");
    let secret = base64url_decode(k_b64).unwrap_or_default();
    let signing_input = format!("{}.{}", parts[0], parts[1]);
    let expected = hmac(&alg, &secret, signing_input.as_bytes());
    if sig_bytes != expected { return Err("BAD_SIGNATURE".into()); }

    // Rule 6: EXPIRED
    if let Some(exp_v) = payload.get("exp") {
        if let Some(exp) = exp_v.as_f64() {
            if now >= exp + leeway { return Err("EXPIRED".into()); }
        }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(nbf_v) = payload.get("nbf") {
        if let Some(nbf) = nbf_v.as_f64() {
            if now + leeway < nbf { return Err("NOT_YET_VALID".into()); }
        }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(JsonValue::String(s)) if s == issuer => {}
        _ => return Err("BAD_ISSUER".into()),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(JsonValue::String(s)) if s == audience => {}
        Some(JsonValue::Array(arr)) => {
            if !arr.iter().any(|v| v.as_str() == Some(audience)) {
                return Err("BAD_AUDIENCE".into());
            }
        }
        _ => return Err("BAD_AUDIENCE".into()),
    }

    // VALID
    let sub = payload.get("sub").and_then(|v|v.as_str()).unwrap_or("").to_string();
    let scope_raw = payload.get("scope").and_then(|v|v.as_str()).unwrap_or("");
    let mut scopes: Vec<&str> = scope_raw.split(' ').filter(|s| !s.is_empty()).collect();
    scopes.sort();
    scopes.dedup();
    Ok((sub, scopes.join(",")))
}

import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

public class Main {
    static boolean initialized = false;
    static Map<String, String> kvStore = new LinkedHashMap<>();

    static final String TOOLS_JSON = "[{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}},{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}},{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}},{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}},{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}]";

    // --- JSON Value types ---
    static abstract class JVal {
        abstract String toJson();
    }

    static class JNull extends JVal {
        String toJson() { return "null"; }
    }

    static class JBool extends JVal {
        boolean val;
        JBool(boolean v) { val = v; }
        String toJson() { return val ? "true" : "false"; }
    }

    static class JString extends JVal {
        String val;
        JString(String v) { val = v; }
        String toJson() { return escapeString(val); }
    }

    static class JNumber extends JVal {
        String raw;
        boolean isInteger;
        long intVal;
        double dblVal;
        JNumber(String raw, boolean isInt, long intVal, double dblVal) {
            this.raw = raw;
            this.isInteger = isInt;
            this.intVal = intVal;
            this.dblVal = dblVal;
        }
        String toJson() { return raw; }
    }

    static class JArray extends JVal {
        List<JVal> elements;
        JArray(List<JVal> e) { elements = e; }
        String toJson() {
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < elements.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(elements.get(i).toJson());
            }
            sb.append("]");
            return sb.toString();
        }
    }

    static class JObject extends JVal {
        LinkedHashMap<String, JVal> members;
        JObject(LinkedHashMap<String, JVal> m) { members = m; }
        String toJson() {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, JVal> e : members.entrySet()) {
                if (!first) sb.append(",");
                first = false;
                sb.append(escapeString(e.getKey()));
                sb.append(":");
                sb.append(e.getValue().toJson());
            }
            sb.append("}");
            return sb.toString();
        }
    }

    static String escapeString(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        sb.append('"');
        return sb.toString();
    }

    // --- JSON Parser ---
    static class Parser {
        String input;
        int pos;

        Parser(String s) { input = s; pos = 0; }

        JVal parse() {
            JVal v = parseValue();
            skipWs();
            if (pos != input.length()) throw new RuntimeException("trailing");
            return v;
        }

        void skipWs() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        JVal parseValue() {
            skipWs();
            if (pos >= input.length()) throw new RuntimeException("eof");
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') return parseLiteral("true", new JBool(true));
            if (c == 'f') return parseLiteral("false", new JBool(false));
            if (c == 'n') return parseLiteral("null", new JNull());
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("unexpected char: " + c);
        }

        JVal parseLiteral(String lit, JVal val) {
            if (!input.startsWith(lit, pos)) throw new RuntimeException("bad literal");
            pos += lit.length();
            return val;
        }

        JVal parseString() {
            if (input.charAt(pos) != '"') throw new RuntimeException("expected \"");
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; return new JString(sb.toString()); }
                if (c == '\\') {
                    pos++;
                    if (pos >= input.length()) throw new RuntimeException("bad escape");
                    char e = input.charAt(pos);
                    pos++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > input.length()) throw new RuntimeException("bad unicode escape");
                            String hex = input.substring(pos, pos + 4);
                            int cp = Integer.parseInt(hex, 16);
                            sb.append((char) cp);
                            pos += 4;
                            break;
                        default: throw new RuntimeException("bad escape char: " + e);
                    }
                } else if (c < 0x20) {
                    throw new RuntimeException("control char in string");
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            throw new RuntimeException("unterminated string");
        }

        JVal parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            if (pos >= input.length()) throw new RuntimeException("bad number");
            if (input.charAt(pos) == '0') {
                pos++;
            } else if (input.charAt(pos) >= '1' && input.charAt(pos) <= '9') {
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            } else {
                throw new RuntimeException("bad number");
            }
            boolean hasFrac = false;
            boolean hasExp = false;
            if (pos < input.length() && input.charAt(pos) == '.') {
                hasFrac = true;
                pos++;
                if (pos >= input.length() || input.charAt(pos) < '0' || input.charAt(pos) > '9')
                    throw new RuntimeException("bad fraction");
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                hasExp = true;
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                if (pos >= input.length() || input.charAt(pos) < '0' || input.charAt(pos) > '9')
                    throw new RuntimeException("bad exponent");
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            String raw = input.substring(start, pos);
            boolean isInt = !hasFrac && !hasExp;
            long intVal = 0;
            double dblVal = 0;
            if (isInt) {
                intVal = Long.parseLong(raw);
                dblVal = intVal;
            } else {
                dblVal = Double.parseDouble(raw);
            }
            return new JNumber(raw, isInt, intVal, dblVal);
        }

        JVal parseObject() {
            pos++; // consume '{'
            LinkedHashMap<String, JVal> map = new LinkedHashMap<>();
            skipWs();
            if (pos < input.length() && input.charAt(pos) == '}') { pos++; return new JObject(map); }
            while (true) {
                skipWs();
                if (pos >= input.length() || input.charAt(pos) != '"') throw new RuntimeException("expected key");
                JString key = (JString) parseString();
                skipWs();
                if (pos >= input.length() || input.charAt(pos) != ':') throw new RuntimeException("expected :");
                pos++;
                JVal val = parseValue();
                map.put(key.val, val);
                skipWs();
                if (pos >= input.length()) throw new RuntimeException("unterminated object");
                if (input.charAt(pos) == '}') { pos++; return new JObject(map); }
                if (input.charAt(pos) != ',') throw new RuntimeException("expected , or }");
                pos++;
            }
        }

        JVal parseArray() {
            pos++; // consume '['
            List<JVal> list = new ArrayList<>();
            skipWs();
            if (pos < input.length() && input.charAt(pos) == ']') { pos++; return new JArray(list); }
            while (true) {
                JVal val = parseValue();
                list.add(val);
                skipWs();
                if (pos >= input.length()) throw new RuntimeException("unterminated array");
                if (input.charAt(pos) == ']') { pos++; return new JArray(list); }
                if (input.charAt(pos) != ',') throw new RuntimeException("expected , or ]");
                pos++;
            }
        }
    }

    // --- Main ---
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            if (isBlank(line)) continue;
            String response = processLine(line);
            if (response != null) {
                output.append(response).append('\n');
            }
        }
        System.out.print(output.toString());
        System.out.flush();
        System.exit(0);
    }

    static boolean isBlank(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ' ' && c != '\t' && c != '\r') return false;
        }
        return true;
    }

    static String processLine(String line) {
        JVal parsed;
        try {
            Parser p = new Parser(line);
            parsed = p.parse();
        } catch (Exception e) {
            return "{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32700,\"message\":\"Parse error\"}}";
        }

        // Rule 2: not an object
        if (!(parsed instanceof JObject)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}";
        }

        JObject obj = (JObject) parsed;

        // Rule 3: response from client
        if (!obj.members.containsKey("method") &&
            (obj.members.containsKey("result") || obj.members.containsKey("error"))) {
            return null;
        }

        // Rule 4: invalid request checks
        JVal jsonrpcVal = obj.members.get("jsonrpc");
        boolean jsonrpcOk = (jsonrpcVal instanceof JString) && ((JString) jsonrpcVal).val.equals("2.0");

        JVal methodVal = obj.members.get("method");
        boolean methodOk = (methodVal instanceof JString);

        boolean idOk = true;
        if (obj.members.containsKey("id")) {
            idOk = isValidId(obj.members.get("id"));
        }

        if (!jsonrpcOk || !methodOk || !idOk) {
            String idJson = getEchoId(obj);
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}";
        }

        // Rule 5: notification
        if (!obj.members.containsKey("id")) {
            return null;
        }

        // Rule 6: request
        String method = ((JString) methodVal).val;
        String idJson = obj.members.get("id").toJson();

        // 6a
        if (!method.equals("initialize") && !method.equals("ping") &&
            !method.equals("tools/list") && !method.equals("tools/call")) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32601,\"message\":\"Method not found\"}}";
        }

        // 6b
        if (obj.members.containsKey("params") && !(obj.members.get("params") instanceof JObject)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}";
        }

        // 6c
        if (!initialized && !method.equals("initialize") && !method.equals("ping")) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32002,\"message\":\"Server not initialized\"}}";
        }

        // 6d dispatch
        switch (method) {
            case "initialize": return handleInitialize(idJson, obj);
            case "ping": return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":{}}";
            case "tools/list": return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":{\"tools\":" + TOOLS_JSON + "}}";
            case "tools/call": return handleToolsCall(idJson, obj);
            default: return null;
        }
    }

    static boolean isValidId(JVal v) {
        if (v instanceof JString) return true;
        if (v instanceof JNumber && ((JNumber) v).isInteger) return true;
        return false;
    }

    static String getEchoId(JObject obj) {
        if (obj.members.containsKey("id")) {
            JVal idVal = obj.members.get("id");
            if (isValidId(idVal)) return idVal.toJson();
        }
        return "null";
    }

    static String handleInitialize(String idJson, JObject obj) {
        if (initialized) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32600,\"message\":\"Already initialized\"}}";
        }
        JVal paramsVal = obj.members.get("params");
        if (paramsVal == null || !(paramsVal instanceof JObject)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}";
        }
        JObject params = (JObject) paramsVal;
        JVal pv = params.members.get("protocolVersion");
        if (pv == null || !(pv instanceof JString)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}";
        }
        String clientVersion = ((JString) pv).val;
        String version;
        if (clientVersion.equals("2025-06-18") || clientVersion.equals("2025-03-26") || clientVersion.equals("2024-11-05")) {
            version = clientVersion;
        } else {
            version = "2025-06-18";
        }
        initialized = true;
        String result = "{\"protocolVersion\":" + escapeString(version) +
                ",\"capabilities\":{\"tools\":{\"listChanged\":false}}," +
                "\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}";
        return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":" + result + "}";
    }

    static String handleToolsCall(String idJson, JObject obj) {
        JVal paramsVal = obj.members.get("params");
        if (paramsVal == null || !(paramsVal instanceof JObject)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}";
        }
        JObject params = (JObject) paramsVal;
        JVal nameVal = params.members.get("name");
        if (nameVal == null || !(nameVal instanceof JString)) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}";
        }
        String toolName = ((JString) nameVal).val;

        if (!toolName.equals("kv_set") && !toolName.equals("kv_get") &&
            !toolName.equals("kv_list") && !toolName.equals("sum") && !toolName.equals("text_stats")) {
            return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"error\":{\"code\":-32602,\"message\":\"Unknown tool: " + escapeString(toolName).substring(1, escapeString(toolName).length()-1) + "\"}}";
        }

        // Get arguments
        JObject argsObj;
        if (params.members.containsKey("arguments")) {
            JVal argsVal = params.members.get("arguments");
            if (!(argsVal instanceof JObject)) {
                return toolFailure(idJson, "arguments must be an object");
            }
            argsObj = (JObject) argsVal;
        } else {
            argsObj = new JObject(new LinkedHashMap<>());
        }

        // Validate arguments
        String validationError = validateArguments(toolName, argsObj);
        if (validationError != null) {
            return toolFailure(idJson, validationError);
        }

        // Execute tool
        return executeTool(idJson, toolName, argsObj);
    }

    static String toolFailure(String idJson, String message) {
        return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":{\"content\":[{\"type\":\"text\",\"text\":" + escapeString(message) + "}],\"isError\":true}}";
    }

    static String toolSuccess(String idJson, String text) {
        return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":{\"content\":[{\"type\":\"text\",\"text\":" + escapeString(text) + "}],\"isError\":false}}";
    }

    static String toolSuccessStructured(String idJson, String structuredJson) {
        return "{\"jsonrpc\":\"2.0\",\"id\":" + idJson + ",\"result\":{\"content\":[{\"type\":\"text\",\"text\":" + escapeString(structuredJson) + "}],\"structuredContent\":" + structuredJson + ",\"isError\":false}}";
    }

    // --- Tool schemas for validation ---
    static class PropDef {
        String name;
        String type; // "string" or "array_int"
        boolean required;
        int minLength;
        int minItems;
        PropDef(String name, String type, boolean required, int minLength, int minItems) {
            this.name = name; this.type = type; this.required = required;
            this.minLength = minLength; this.minItems = minItems;
        }
    }

    static Map<String, List<PropDef>> toolSchemas = new HashMap<>();
    static {
        toolSchemas.put("kv_set", Arrays.asList(
            new PropDef("key", "string", true, 1, 0),
            new PropDef("value", "string", true, 0, 0)
        ));
        toolSchemas.put("kv_get", Arrays.asList(
            new PropDef("key", "string", true, 1, 0)
        ));
        toolSchemas.put("kv_list", Arrays.asList(
            new PropDef("prefix", "string", false, 0, 0)
        ));
        toolSchemas.put("sum", Arrays.asList(
            new PropDef("numbers", "array_int", true, 0, 1)
        ));
        toolSchemas.put("text_stats", Arrays.asList(
            new PropDef("text", "string", true, 0, 0)
        ));
    }

    static String validateArguments(String toolName, JObject args) {
        List<PropDef> props = toolSchemas.get(toolName);
        Set<String> knownNames = new HashSet<>();
        for (PropDef p : props) knownNames.add(p.name);

        // Check unknown arguments
        List<String> unknown = new ArrayList<>();
        for (String key : args.members.keySet()) {
            if (!knownNames.contains(key)) unknown.add(key);
        }
        if (!unknown.isEmpty()) {
            unknown.sort(Main::compareByCodePoint);
            return "unknown argument: " + unknown.get(0);
        }

        // Check each property in order
        for (PropDef p : props) {
            if (!args.members.containsKey(p.name)) {
                if (p.required) return "missing required argument: " + p.name;
                continue;
            }
            JVal val = args.members.get(p.name);
            if (p.type.equals("string")) {
                if (!(val instanceof JString)) return "argument " + p.name + " must be a string";
                if (p.minLength > 0 && ((JString) val).val.length() < p.minLength)
                    return "argument " + p.name + " must not be empty";
            } else if (p.type.equals("array_int")) {
                if (!(val instanceof JArray)) return "argument " + p.name + " must be an array of integers";
                JArray arr = (JArray) val;
                for (JVal elem : arr.elements) {
                    if (!(elem instanceof JNumber) || !((JNumber) elem).isInteger)
                        return "argument " + p.name + " must be an array of integers";
                }
                if (p.minItems > 0 && arr.elements.size() < p.minItems)
                    return "argument " + p.name + " must not be empty";
            }
        }
        return null;
    }

    static String executeTool(String idJson, String toolName, JObject args) {
        switch (toolName) {
            case "kv_set": {
                String key = ((JString) args.members.get("key")).val;
                String value = ((JString) args.members.get("value")).val;
                boolean existed = kvStore.containsKey(key);
                kvStore.put(key, value);
                String text = existed ? "updated " + key : "created " + key;
                return toolSuccess(idJson, text);
            }
            case "kv_get": {
                String key = ((JString) args.members.get("key")).val;
                if (!kvStore.containsKey(key)) {
                    return toolFailure(idJson, "key not found: " + key);
                }
                return toolSuccess(idJson, kvStore.get(key));
            }
            case "kv_list": {
                String prefix = "";
                if (args.members.containsKey("prefix")) {
                    prefix = ((JString) args.members.get("prefix")).val;
                }
                List<String> keys = new ArrayList<>();
                for (String k : kvStore.keySet()) {
                    if (k.startsWith(prefix)) keys.add(k);
                }
                keys.sort(Main::compareByCodePoint);
                StringBuilder sb = new StringBuilder();
                sb.append("{\"keys\":[");
                for (int i = 0; i < keys.size(); i++) {
                    if (i > 0) sb.append(",");
                    sb.append(escapeString(keys.get(i)));
                }
                sb.append("],\"count\":").append(keys.size()).append("}");
                return toolSuccessStructured(idJson, sb.toString());
            }
            case "sum": {
                JArray arr = (JArray) args.members.get("numbers");
                long sum = 0;
                for (JVal elem : arr.elements) {
                    sum += ((JNumber) elem).intVal;
                }
                String structured = "{\"sum\":" + sum + ",\"count\":" + arr.elements.size() + "}";
                return toolSuccessStructured(idJson, structured);
            }
            case "text_stats": {
                String text = ((JString) args.members.get("text")).val;
                int words = countWords(text);
                int codepoints = text.codePointCount(0, text.length());
                int utf8Bytes = text.getBytes(StandardCharsets.UTF_8).length;
                String structured = "{\"words\":" + words + ",\"codepoints\":" + codepoints + ",\"utf8_bytes\":" + utf8Bytes + "}";
                return toolSuccessStructured(idJson, structured);
            }
            default:
                return null;
        }
    }

    static int countWords(String text) {
        int count = 0;
        boolean inWord = false;
        for (int i = 0; i < text.length(); ) {
            int cp = text.codePointAt(i);
            if (cp == 0x20 || cp == 0x09 || cp == 0x0A || cp == 0x0D) {
                inWord = false;
            } else {
                if (!inWord) {
                    count++;
                    inWord = true;
                }
            }
            i += Character.charCount(cp);
        }
        return count;
    }

    static int compareByCodePoint(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }
}

import Foundation

// MARK: - JSON Value
enum JSONValue {
    case null
    case bool(Bool)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser
struct JSONParser {
    let input: [UInt8]
    var pos: Int = 0

    init(_ s: String) {
        input = Array(s.utf8)
    }

    mutating func parse() -> JSONValue? {
        skipWS()
        guard let val = parseValue() else { return nil }
        skipWS()
        if pos != input.count { return nil }
        return val
    }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { pos += 1 } else { break }
        }
    }

    mutating func parseValue() -> JSONValue? {
        guard pos < input.count else { return nil }
        let c = input[pos]
        if c == UInt8(ascii: "{") { return parseObject() }
        if c == UInt8(ascii: "[") { return parseArray() }
        if c == UInt8(ascii: "\"") { return parseString() }
        if c == UInt8(ascii: "t") { return matchLit("true") ? .bool(true) : nil }
        if c == UInt8(ascii: "f") { return matchLit("false") ? .bool(false) : nil }
        if c == UInt8(ascii: "n") { return matchLit("null") ? .null : nil }
        if c == UInt8(ascii: "-") || (c >= UInt8(ascii: "0") && c <= UInt8(ascii: "9")) { return parseNumber() }
        return nil
    }

    mutating func matchLit(_ s: String) -> Bool {
        let bytes = Array(s.utf8)
        if pos + bytes.count > input.count { return false }
        for i in 0..<bytes.count { if input[pos+i] != bytes[i] { return false } }
        pos += bytes.count
        return true
    }

    mutating func parseNumber() -> JSONValue? {
        let start = pos
        var isFloat = false
        if pos < input.count && input[pos] == UInt8(ascii: "-") { pos += 1 }
        if pos >= input.count { return nil }
        if input[pos] == UInt8(ascii: "0") {
            pos += 1
        } else if input[pos] >= UInt8(ascii: "1") && input[pos] <= UInt8(ascii: "9") {
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        } else { return nil }
        if pos < input.count && input[pos] == UInt8(ascii: ".") {
            isFloat = true; pos += 1
            if pos >= input.count || input[pos] < UInt8(ascii: "0") || input[pos] > UInt8(ascii: "9") { return nil }
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        if pos < input.count && (input[pos] == UInt8(ascii: "e") || input[pos] == UInt8(ascii: "E")) {
            isFloat = true; pos += 1
            if pos < input.count && (input[pos] == UInt8(ascii: "+") || input[pos] == UInt8(ascii: "-")) { pos += 1 }
            if pos >= input.count || input[pos] < UInt8(ascii: "0") || input[pos] > UInt8(ascii: "9") { return nil }
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        let numStr = String(bytes: input[start..<pos], encoding: .utf8)!
        if isFloat {
            return .double(Double(numStr)!)
        } else {
            if let i = Int64(numStr) { return .int(i) }
            return .double(Double(numStr)!)
        }
    }

    mutating func parseString() -> JSONValue? {
        guard let s = parseRawString() else { return nil }
        return .string(s)
    }

    mutating func parseRawString() -> String? {
        guard pos < input.count && input[pos] == UInt8(ascii: "\"") else { return nil }
        pos += 1
        var bytes: [UInt8] = []
        while pos < input.count {
            let c = input[pos]
            if c == UInt8(ascii: "\"") { pos += 1; return String(bytes: bytes, encoding: .utf8) }
            if c == UInt8(ascii: "\\") {
                pos += 1
                if pos >= input.count { return nil }
                let e = input[pos]
                if e == UInt8(ascii: "\"") { bytes.append(0x22); pos += 1 }
                else if e == UInt8(ascii: "\\") { bytes.append(0x5C); pos += 1 }
                else if e == UInt8(ascii: "/") { bytes.append(0x2F); pos += 1 }
                else if e == UInt8(ascii: "b") { bytes.append(0x08); pos += 1 }
                else if e == UInt8(ascii: "f") { bytes.append(0x0C); pos += 1 }
                else if e == UInt8(ascii: "n") { bytes.append(0x0A); pos += 1 }
                else if e == UInt8(ascii: "r") { bytes.append(0x0D); pos += 1 }
                else if e == UInt8(ascii: "t") { bytes.append(0x09); pos += 1 }
                else if e == UInt8(ascii: "u") {
                    pos += 1
                    guard let cp = parseHex4() else { return nil }
                    if cp >= 0xD800 && cp <= 0xDBFF {
                        if pos+1 >= input.count || input[pos] != UInt8(ascii: "\\") || input[pos+1] != UInt8(ascii: "u") { return nil }
                        pos += 2
                        guard let cp2 = parseHex4() else { return nil }
                        if cp2 < 0xDC00 || cp2 > 0xDFFF { return nil }
                        let combined = 0x10000 + (Int(cp - 0xD800) << 10) + Int(cp2 - 0xDC00)
                        guard let sc = Unicode.Scalar(combined) else { return nil }
                        bytes.append(contentsOf: Array(String(sc).utf8))
                    } else if cp >= 0xDC00 && cp <= 0xDFFF {
                        return nil
                    } else {
                        guard let sc = Unicode.Scalar(cp) else { return nil }
                        bytes.append(contentsOf: Array(String(sc).utf8))
                    }
                } else { return nil }
            } else {
                bytes.append(c); pos += 1
            }
        }
        return nil
    }

    mutating func parseHex4() -> UInt32? {
        guard pos + 4 <= input.count else { return nil }
        var val: UInt32 = 0
        for i in 0..<4 {
            let c = input[pos+i]; val <<= 4
            if c >= UInt8(ascii: "0") && c <= UInt8(ascii: "9") { val |= UInt32(c - UInt8(ascii: "0")) }
            else if c >= UInt8(ascii: "a") && c <= UInt8(ascii: "f") { val |= UInt32(c - UInt8(ascii: "a") + 10) }
            else if c >= UInt8(ascii: "A") && c <= UInt8(ascii: "F") { val |= UInt32(c - UInt8(ascii: "A") + 10) }
            else { return nil }
        }
        pos += 4
        return val
    }

    mutating func parseArray() -> JSONValue? {
        pos += 1; var arr: [JSONValue] = []
        skipWS()
        if pos < input.count && input[pos] == UInt8(ascii: "]") { pos += 1; return .array(arr) }
        while true {
            guard let v = parseValue() else { return nil }
            arr.append(v); skipWS()
            if pos >= input.count { return nil }
            if input[pos] == UInt8(ascii: ",") { pos += 1; skipWS() }
            else if input[pos] == UInt8(ascii: "]") { pos += 1; return .array(arr) }
            else { return nil }
        }
    }

    mutating func parseObject() -> JSONValue? {
        pos += 1; var obj: [(String, JSONValue)] = []
        skipWS()
        if pos < input.count && input[pos] == UInt8(ascii: "}") { pos += 1; return .object(obj) }
        while true {
            skipWS()
            guard let key = parseRawString() else { return nil }
            skipWS()
            if pos >= input.count || input[pos] != UInt8(ascii: ":") { return nil }
            pos += 1; skipWS()
            guard let v = parseValue() else { return nil }
            obj.append((key, v)); skipWS()
            if pos >= input.count { return nil }
            if input[pos] == UInt8(ascii: ",") { pos += 1 }
            else if input[pos] == UInt8(ascii: "}") { pos += 1; return .object(obj) }
            else { return nil }
        }
    }
}

// MARK: - JSON Serializer
func escStr(_ s: String) -> String {
    var r = "\""
    for sc in s.unicodeScalars {
        switch sc {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        case "\u{0008}": r += "\\b"
        case "\u{000C}": r += "\\f"
        default:
            if sc.value < 0x20 { r += String(format: "\\u%04x", sc.value) }
            else { r.unicodeScalars.append(sc) }
        }
    }
    r += "\""
    return r
}

func ser(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool(let b): return b ? "true" : "false"
    case .int(let i): return String(i)
    case .double(let d):
        if d == d.rounded() && abs(d) < 1e15 { return String(Int64(d)) }
        return String(d)
    case .string(let s): return escStr(s)
    case .array(let a): return "[" + a.map{ser($0)}.joined(separator: ",") + "]"
    case .object(let pairs):
        return "{" + pairs.map{ escStr($0.0) + ":" + ser($0.1) }.joined(separator: ",") + "}"
    }
}

// MARK: - Helpers
func getObj(_ v: JSONValue, _ key: String) -> JSONValue? {
    if case .object(let pairs) = v {
        for (k, val) in pairs { if k == key { return val } }
    }
    return nil
}

func hasKey(_ v: JSONValue, _ key: String) -> Bool {
    if case .object(let pairs) = v {
        for (k, _) in pairs { if k == key { return true } }
    }
    return false
}

func isValidId(_ v: JSONValue?) -> Bool {
    guard let v = v else { return false }
    switch v {
    case .string: return true
    case .int: return true
    default: return false
    }
}

// MARK: - Tool Definitions
struct ToolProp {
    let name: String
    let type: String // "string" or "array_int"
    let required: Bool
    let minLength: Int?
    let minItems: Int?
}

struct ToolDef {
    let name: String
    let props: [ToolProp]
    let hasOutputSchema: Bool
}

