        ("description", .string("List the stored keys that start with a prefix, sorted by Unicode code point.")),
        ("inputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("prefix", .object([("type", .string("string"))]))
            ])),
            ("additionalProperties", .bool(false))
        ])),
