      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

function compareByCodePoint(a: string, b: string): number {
  const ac = Array.from(a);
  const bc = Array.from(b);
  const len = Math.min(ac.length, bc.length);
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)!;
    const cb = bc[i].codePointAt(0)!;
    if (ca < cb) return -1;
    if (ca > cb) return 1;
  }
  return ac.length - bc.length;
}

function isIdRawInteger(raw: string): boolean {
  let depth = 0;
  let inString = false;
  let escaped = false;
  let result = true;
  let i = 0;

  while (i < raw.length) {
    const ch = raw[i];

    if (inString) {
      if (escaped) { escaped = false; i++; continue; }
      if (ch === '\\') { escaped = true; i++; continue; }
      if (ch === '"') { inString = false; }
      i++;
      continue;
    }

    if (ch === '"') {
      if (depth === 1 && raw.startsWith('"id"', i)) {
        let j = i + 4;
        while (j < raw.length && (raw[j] === ' ' || raw[j] === '\t' || raw[j] === '\r' || raw[j] === '\n')) j++;
        if (j < raw.length && raw[j] === ':') {
          j++;
          while (j < raw.length && (raw[j] === ' ' || raw[j] === '\t' || raw[j] === '\r' || raw[j] === '\n')) j++;
          if (j < raw.length && (raw[j] === '-' || (raw[j] >= '0' && raw[j] <= '9'))) {
            let start = j;
            while (j < raw.length && (raw[j] === '-' || raw[j] === '+' || raw[j] === '.' || raw[j] === 'e' || raw[j] === 'E' || (raw[j] >= '0' && raw[j] <= '9'))) j++;
            const numStr = raw.substring(start, j);
            result = !(numStr.includes('.') || /[eE]/.test(numStr));
          }
        }
      }
      inString = true;
      i++;
      continue;
    }

    if (ch === '{' || ch === '[') depth++;
    else if (ch === '}' || ch === ']') depth--;
    i++;
  }
  return result;
}

function isValidId(msg: any, raw: string): boolean {
  if (!('id' in msg)) return true;
  const id = msg.id;
  if (typeof id === 'string') return true;
  if (typeof id === 'number') {
    if (!Number.isInteger(id)) return false;
    return isIdRawInteger(raw);
  }
  return false;
}

function getResponseId(msg: any, raw: string): any {
  if (!('id' in msg)) return null;
  const id = msg.id;
  if (typeof id === 'string') return id;
  if (typeof id === 'number' && Number.isInteger(id) && isIdRawInteger(raw)) return id;
  return null;
}

function makeError(id: any, code: number, message: string): string {
  return JSON.stringify({ jsonrpc: "2.0", id, error: { code, message } });
}

function makeResult(id: any, result: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result });
}

function toolSuccess(id: any, text: string): string {
  return makeResult(id, { content: [{ type: "text", text }], isError: false });
}

function toolSuccessStructured(id: any, S: any): string {
  return makeResult(id, {
    content: [{ type: "text", text: JSON.stringify(S) }],
    structuredContent: S,
    isError: false
  });
}

function toolFailure(id: any, message: string): string {
  return makeResult(id, { content: [{ type: "text", text: message }], isError: true });
}

function handleToolsCall(id: any, params: any): string {
  if (!params || typeof params !== 'object' || Array.isArray(params)) {
    return makeError(id, -32602, "Invalid params");
  }
  if (!('name' in params) || typeof params.name !== 'string') {
    return makeError(id, -32602, "Invalid params");
  }
  const toolName = params.name;
  const tool = TOOLS.find(t => t.name === toolName);
  if (!tool) {
    return makeError(id, -32602, `Unknown tool: ${toolName}`);
  }

  let args: any = {};
  if ('arguments' in params) {
    args = params.arguments;
    if (args === null || typeof args !== 'object' || Array.isArray(args)) {
      return toolFailure(id, "arguments must be an object");
    }
  }

  const schemaProps = Object.keys(tool.inputSchema.properties);
  const argKeys = Object.keys(args);
  const unknownKeys = argKeys.filter(k => !schemaProps.includes(k));
  if (unknownKeys.length > 0) {
    unknownKeys.sort(compareByCodePoint);
    return toolFailure(id, `unknown argument: ${unknownKeys[0]}`);
  }

  for (const propName of schemaProps) {
    const propDef = (tool.inputSchema.properties as any)[propName];
    const required: string[] = (tool.inputSchema as any).required || [];
    const isRequired = required.includes(propName);
    const isPresent = propName in args;

    if (!isPresent) {
      if (isRequired) {
        return toolFailure(id, `missing required argument: ${propName}`);
      }
      continue;
    }

    const val = args[propName];

    if (propDef.type === 'string') {
      if (typeof val !== 'string') {
        return toolFailure(id, `argument ${propName} must be a string`);
      }
      if (propDef.minLength !== undefined && val.length < propDef.minLength) {
        return toolFailure(id, `argument ${propName} must not be empty`);
      }
    } else if (propDef.type === 'array') {
      if (!Array.isArray(val)) {
        return toolFailure(id, `argument ${propName} must be an array of integers`);
      }
      for (const item of val) {
        if (typeof item !== 'number' || !Number.isInteger(item)) {
          return toolFailure(id, `argument ${propName} must be an array of integers`);
        }
      }
      if (propDef.minItems !== undefined && val.length < propDef.minItems) {
        return toolFailure(id, `argument ${propName} must not be empty`);
      }
    }
  }

  return executeTool(id, tool, args);
}

function executeTool(id: any, tool: any, args: any): string {
  switch (tool.name) {
    case 'kv_set': {
      const key = args.key as string;
      const value = args.value as string;
      const existed = store.has(key);
      store.set(key, value);
      const text = existed ? `updated ${key}` : `created ${key}`;
      return toolSuccess(id, text);
    }
    case 'kv_get': {
      const key = args.key as string;
      if (!store.has(key)) {
        return toolFailure(id, `key not found: ${key}`);
      }
      return toolSuccess(id, store.get(key)!);
    }
    case 'kv_list': {
      const prefix: string = ('prefix' in args) ? (args.prefix as string) : '';
      const keys: string[] = [];
      for (const k of store.keys()) {
        if (k.startsWith(prefix)) keys.push(k);
      }
      keys.sort(compareByCodePoint);
      const S = { keys, count: keys.length };
      return toolSuccessStructured(id, S);
    }
    case 'sum': {
      const numbers = args.numbers as number[];
      const total = numbers.reduce((a, b) => a + b, 0);
      const S = { sum: total, count: numbers.length };
      return toolSuccessStructured(id, S);
    }
    case 'text_stats': {
      const text = args.text as string;
      const words = text.split(/[\t\n\r ]+/).filter(s => s.length > 0).length;
      const codepoints = Array.from(text).length;
      const utf8Bytes = new TextEncoder().encode(text).length;
      const S = { words, codepoints, utf8_bytes: utf8Bytes };
      return toolSuccessStructured(id, S);
    }
    default:
      return toolFailure(id, "unknown tool");
  }
}

function processLine(line: string): string | null {
  if (line.trim() === '') return null;

  let msg: any;
  try {
    msg = JSON.parse(line);
  } catch {
    return makeError(null, -32700, "Parse error");
  }

  if (msg === null || typeof msg !== 'object' || Array.isArray(msg)) {
    return makeError(null, -32600, "Invalid Request");
  }

  if (!('method' in msg) && ('result' in msg || 'error' in msg)) {
    return null;
  }

  if (msg.jsonrpc !== "2.0" || !('method' in msg) || typeof msg.method !== 'string' || !isValidId(msg, line)) {
    const id = getResponseId(msg, line);
    return makeError(id, -32600, "Invalid Request");
  }

  if (!('id' in msg)) {
    return null;
  }

  const id = getResponseId(msg, line);
  const method: string = msg.method;

  if (!['initialize', 'ping', 'tools/list', 'tools/call'].includes(method)) {
    return makeError(id, -32601, "Method not found");
  }

  if ('params' in msg) {
    const p = msg.params;
    if (p === null || typeof p !== 'object' || Array.isArray(p)) {
      return makeError(id, -32602, "Invalid params");
    }
  }

  if (!initialized && method !== 'initialize' && method !== 'ping') {
    return makeError(id, -32002, "Server not initialized");
  }

  const params = 'params' in msg ? msg.params : undefined;

  if (method === 'initialize') {
    return handleInitialize(id, params);
  } else if (method === 'ping') {
    return makeResult(id, {});
  } else if (method === 'tools/list') {
    return makeResult(id, { tools: TOOLS });
  } else if (method === 'tools/call') {
    return handleToolsCall(id, params);
  }

  return null;
}

function handleInitialize(id: any, params: any): string {
  if (initialized) {
    return makeError(id, -32600, "Already initialized");
  }
  if (params === undefined || params === null || typeof params !== 'object' || Array.isArray(params)) {
    return makeError(id, -32602, "Invalid params");
  }
  if (!('protocolVersion' in params) || typeof params.protocolVersion !== 'string') {
    return makeError(id, -32602, "Invalid params");
  }

  const supported = ["2025-06-18", "2025-03-26", "2024-11-05"];
  const version = supported.includes(params.protocolVersion) ? params.protocolVersion : "2025-06-18";
  initialized = true;

  return makeResult(id, {
    protocolVersion: version,
    capabilities: { tools: { listChanged: false } },
    serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
  });
}

rl.on('line', (line) => {
  const response = processLine(line);
  if (response !== null) {
    process.stdout.write(response + '\n');
  }
});

rl.on('close', () => {
  process.exitCode = 0;
});

import * as fs from 'fs';
import * as path from 'path';

function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) {
        crc = (crc >>> 1) ^ 0xEDB88320;
      } else {
        crc = crc >>> 1;
      }
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function splitLines(content: string): string[] {
  if (content === '') return [];
  const parts = content.split('\n');
  const lines: string[] = [];
  for (let i = 0; i < parts.length - 1; i++) {
    lines.push(parts[i] + '\n');
  }
  if (parts[parts.length - 1] !== '') {
    lines.push(parts[parts.length - 1]);
  }
  return lines;
}

interface Hunk {
  a: number;
  b: number;
  c: number;
  d: number;
  oldLines: string[];
  newLines: string[];
  malformed: boolean;
}

interface Section {
  filePath: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
}

function parseDiff(diffContent: string): Section[] {
  const lines = diffContent.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const sections: Section[] = [];
  let i = 0;

  while (i < lines.length) {
    if (!lines[i].startsWith('diff --git ')) {
      i++;
      continue;
    }

    const match = lines[i].match(/^diff --git a\/(.+) b\/(.+)$/);
    if (!match) {
      i++;
      continue;
    }
    const filePath = match[1];
    i++;

    let kind: 'create' | 'delete' | 'modify' = 'modify';

    while (i < lines.length) {
      const hline = lines[i];
      if (hline.startsWith('diff --git ') || hline.startsWith('@@ ')) break;
      if (hline.startsWith('new file mode ')) {
        kind = 'create';
        i++;
      } else if (hline.startsWith('deleted file mode ')) {
        kind = 'delete';
        i++;
      } else if (
        hline.startsWith('index ') ||
        hline.startsWith('--- ') ||
        hline.startsWith('+++ ')
      ) {
        i++;
      } else {
        break;
      }
    }

    const hunks: Hunk[] = [];
    while (i < lines.length) {
      if (!lines[i].startsWith('@@ ')) break;

      const hunkMatch = lines[i].match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
      if (!hunkMatch) {
        i++;
        continue;
      }

      const a = parseInt(hunkMatch[1]);
      const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2]) : 1;
      const c = parseInt(hunkMatch[3]);
      const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4]) : 1;
      i++;

      const oldLines: string[] = [];
      const newLines: string[] = [];
      let lastMarker = '';

      while (i < lines.length) {
        const bline = lines[i];
        if (bline.startsWith('@@ ') || bline.startsWith('diff --git ')) break;

        if (bline.startsWith('\\')) {
          if (lastMarker === ' ') {
            if (oldLines.length > 0)
              oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
            if (newLines.length > 0)
              newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
          } else if (lastMarker === '-') {
            if (oldLines.length > 0)
              oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
          } else if (lastMarker === '+') {
            if (newLines.length > 0)
              newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
          }
          i++;
          continue;
        }

        const marker = bline[0];
        const content = bline.substring(1);

        if (marker === ' ') {
          oldLines.push(content + '\n');
          newLines.push(content + '\n');
        } else if (marker === '-') {
          oldLines.push(content + '\n');
        } else if (marker === '+') {
          newLines.push(content + '\n');
        }

        lastMarker = marker;
        i++;
      }

      const malformed = oldLines.length !== b || newLines.length !== d;
      hunks.push({ a, b, c, d, oldLines, newLines, malformed });
    }

    sections.push({ filePath, kind, hunks });
  }

  return sections;
}

function main() {
  const dir = process.argv[2];
  const diffPath = path.join(dir, 'changes.diff');
  const treeDir = path.join(dir, 'tree');

  const diffContent = fs.readFileSync(diffPath, 'latin1');
  const sections = parseDiff(diffContent);

  sections.sort((a, b) => {
    if (a.filePath < b.filePath) return -1;
    if (a.filePath > b.filePath) return 1;
    return 0;
  });

  const output: string[] = [];

  for (const section of sections) {
    const { filePath, kind, hunks } = section;

    output.push(`${filePath}: ${kind}`);

    const fullPath = path.join(treeDir, filePath);
    let fileExists = false;
    let content: string = '';

    try {
      content = fs.readFileSync(fullPath, 'latin1');
      fileExists = true;
    } catch {
      fileExists = false;
    }

    if (kind === 'create') {
      if (fileExists) {
        output.push('  error: already exists');
        continue;
      }
      content = '';
    } else {
      if (!fileExists) {
        output.push('  error: not found');
        continue;
      }
    }

    let lines = splitLines(content);
    let delta = 0;
    let allApplied = true;

    for (let hi = 0; hi < hunks.length; hi++) {
      const hunk = hunks[hi];
      const hunkNum = hi + 1;

      if (hunk.malformed) {
        output.push(`  hunk ${hunkNum}: malformed`);
        allApplied = false;
        continue;
      }

      const P = hunk.a + delta;

      if (hunk.b === 0) {
        if (P >= 0 && P <= lines.length) {
          lines = [...lines.slice(0, P), ...hunk.newLines, ...lines.slice(P)];
          output.push(`  hunk ${hunkNum}: applied at ${P} (offset 0)`);
          delta += hunk.d;
        } else {
          output.push(`  hunk ${hunkNum}: rejected`);
          allApplied = false;
        }
      } else {
        const b = hunk.b;
        const maxP = lines.length - b + 1;

        let found = false;
        let foundP = -1;

        if (maxP >= 1) {
          for (let k = 0; ; k++) {
            const candidates: number[] = [];
            if (k === 0) {
              candidates.push(P);
            } else {
              candidates.push(P - k);
              candidates.push(P + k);
            }

            for (const p of candidates) {
              if (p >= 1 && p <= maxP) {
                let matches = true;
                for (let j = 0; j < b; j++) {
                  if (lines[p - 1 + j] !== hunk.oldLines[j]) {
                    matches = false;
                    break;
                  }
                }
                if (matches) {
                  found = true;
                  foundP = p;
                  break;
                }
              }
            }

            if (found) break;
            if (P - k < 1 && P + k > maxP) break;
          }
        }

        if (found) {
          const offset = foundP - P;
          lines = [
            ...lines.slice(0, foundP - 1),
            ...hunk.newLines,
            ...lines.slice(foundP - 1 + b),
          ];
          const offsetStr = offset > 0 ? `+${offset}` : `${offset}`;
          output.push(`  hunk ${hunkNum}: applied at ${foundP} (offset ${offsetStr})`);
          delta += hunk.d - hunk.b;
        } else {
          output.push(`  hunk ${hunkNum}: rejected`);
          allApplied = false;
        }
      }
    }

    if (kind === 'delete' && allApplied && lines.length === 0) {
      output.push('  result: deleted');
    } else {
      const finalContent = lines.join('');
      const buf = Buffer.from(finalContent, 'latin1');
      const crc = crc32(buf);
      output.push(
        `  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`
      );
    }
  }

  if (output.length > 0) {
    console.log(output.join('\n'));
  }
}

main();

import sys
import os
import zlib


def main():
    base_dir = sys.argv[1]

    with open(os.path.join(base_dir, 'changes.diff'), 'rb') as f:
        diff_data = f.read()

    sections = parse_diff(diff_data)
    sections.sort(key=lambda s: s['path'])

    output_blocks = []
    for section in sections:
        block = process_section(section, base_dir)
        output_blocks.append(block)

    if output_blocks:
        sys.stdout.write('\n'.join(output_blocks) + '\n')


def parse_diff(data):
    lines = split_diff_lines(data)
    sections = []
    i = 0
    while i < len(lines):
        if lines[i].startswith(b'diff --git a/'):
            section, i = parse_section(lines, i)
            sections.append(section)
        else:
            i += 1
    return sections


def split_diff_lines(data):
    if not data:
        return []
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    return lines


def parse_section(lines, i):
    header = lines[i]
    parts = header.split(b' ')
    path = parts[2][2:]  # Remove "a/"
    i += 1

    kind = 'modify'

    while i < len(lines) and not lines[i].startswith(b'@@ ') and not lines[i].startswith(b'diff --git '):
        if lines[i].startswith(b'new file mode '):
            kind = 'create'
        elif lines[i].startswith(b'deleted file mode '):
            kind = 'delete'
        i += 1

    hunks = []
    while i < len(lines) and lines[i].startswith(b'@@ '):
        hunk, i = parse_hunk(lines, i)
        hunks.append(hunk)

    return {'path': path, 'kind': kind, 'hunks': hunks}, i


def parse_hunk(lines, i):
    header = lines[i]
    i += 1

    a, b, c, d = parse_hunk_header(header)

    body = []
    while i < len(lines) and not lines[i].startswith(b'@@ ') and not lines[i].startswith(b'diff --git '):
        body.append(lines[i])
        i += 1

    old_lines, new_lines = parse_hunk_body(body)

    malformed = (len(old_lines) != b) or (len(new_lines) != d)

    return {'a': a, 'b': b, 'c': c, 'd': d, 'old': old_lines, 'new': new_lines, 'malformed': malformed}, i


def parse_hunk_header(line):
    rest = line[3:]  # Remove "@@ "
    idx = rest.find(b' @@')
    range_part = rest[:idx]
    parts = range_part.split(b' ')

    old_part = parts[0][1:]  # Remove "-"
    if b',' in old_part:
        a_str, b_str = old_part.split(b',')
        a = int(a_str)
        b_val = int(b_str)
    else:
        a = int(old_part)
        b_val = 1

    new_part = parts[1][1:]  # Remove "+"
    if b',' in new_part:
        c_str, d_str = new_part.split(b',')
        c = int(c_str)
        d_val = int(d_str)
    else:
        c = int(new_part)
        d_val = 1

    return a, b_val, c, d_val


def parse_hunk_body(body_lines):
    old_lines = []
    new_lines = []
    last_type = None

    for line in body_lines:
        if line.startswith(b'\\'):
            if last_type == 'context':
                old_lines[-1] = (old_lines[-1][0], False)
                new_lines[-1] = (new_lines[-1][0], False)
            elif last_type == 'old':
                old_lines[-1] = (old_lines[-1][0], False)
            elif last_type == 'new':
                new_lines[-1] = (new_lines[-1][0], False)
        elif line.startswith(b' '):
            content = line[1:]
            old_lines.append((content, True))
            new_lines.append((content, True))
            last_type = 'context'
        elif line.startswith(b'-'):
            content = line[1:]
            old_lines.append((content, True))
            last_type = 'old'
        elif line.startswith(b'+'):
            content = line[1:]
            new_lines.append((content, True))
            last_type = 'new'

    return old_lines, new_lines


def bytes_to_lines(data):
    if not data:
        return []
    lines = []
    while data:
        idx = data.find(b'\n')
        if idx == -1:
            lines.append((data, False))
            break
        else:
            lines.append((data[:idx], True))
            data = data[idx + 1:]
    return lines


def lines_to_bytes(lines):
    result = b''
    for content, has_nl in lines:
        result += content
        if has_nl:
            result += b'\n'
    return result


def find_match(content_lines, old_lines, P):
    b = len(old_lines)
    n = len(content_lines)
    if b == 0:
        return None

    max_k = max(P - 1, n - b + 1 - P)
    if max_k < 0:
        return None

    for k in range(0, max_k + 1):
        p = P - k
        if p >= 1 and p + b - 1 <= n:
            if content_lines[p - 1:p - 1 + b] == old_lines:
                return p
        if k > 0:
            p = P + k
            if p >= 1 and p + b - 1 <= n:
                if content_lines[p - 1:p - 1 + b] == old_lines:
                    return p

    return None


def apply_hunks(content_lines, hunks):
    results = []
    delta = 0

    for i, hunk in enumerate(hunks):
        hunk_num = i + 1

        if hunk['malformed']:
            results.append((hunk_num, 'malformed', None, None))
            continue

        b = hunk['b']
        d = hunk['d']
        a = hunk['a']
        P = a + delta

        if b == 0:
            if 0 <= P <= len(content_lines):
                content_lines = content_lines[:P] + hunk['new'] + content_lines[P:]
                results.append((hunk_num, 'applied', P, 0))
                delta += d - b
            else:
                results.append((hunk_num, 'rejected', None, None))
        else:
            match_pos = find_match(content_lines, hunk['old'], P)
            if match_pos is not None:
                start = match_pos - 1
                end = start + b
                content_lines = content_lines[:start] + hunk['new'] + content_lines[end:]
                offset = match_pos - P
                results.append((hunk_num, 'applied', match_pos, offset))
                delta += d - b
            else:
                results.append((hunk_num, 'rejected', None, None))

    return content_lines, results


def process_section(section, base_dir):
    path = section['path']
    kind = section['kind']
    hunks = section['hunks']

    path_str = os.fsdecode(path)
    tree_dir = os.path.join(base_dir, 'tree')
    file_path = os.path.join(tree_dir, path_str)
    file_exists = os.path.isfile(file_path)

    if kind == 'create':
        if file_exists:
            return f"{path_str}: {kind}\n  error: already exists"
        content_lines = []
    else:  # modify or delete
        if not file_exists:
            return f"{path_str}: {kind}\n  error: not found"
        with open(file_path, 'rb') as f:
            data = f.read()
        content_lines = bytes_to_lines(data)

    content_lines, hunk_results = apply_hunks(content_lines, hunks)

    deleted = False
    if kind == 'delete':
        all_applied = all(status == 'applied' for _, status, _, _ in hunk_results)
        if all_applied and len(content_lines) == 0:
            deleted = True

    return format_output(path_str, kind, hunk_results, content_lines, deleted)


def format_output(path_str, kind, hunk_results, content_lines, deleted):
    lines = []
    lines.append(f"{path_str}: {kind}")

    for hunk_num, status, pos, offset in hunk_results:
        if status == 'malformed':
            lines.append(f"  hunk {hunk_num}: malformed")
        elif status == 'rejected':
            lines.append(f"  hunk {hunk_num}: rejected")
        elif status == 'applied':
            if offset == 0:
                offset_str = "0"
            elif offset > 0:
                offset_str = f"+{offset}"
            else:
                offset_str = str(offset)
            lines.append(f"  hunk {hunk_num}: applied at {pos} (offset {offset_str})")

    if deleted:
        lines.append("  result: deleted")
    else:
        n = len(content_lines)
        data = lines_to_bytes(content_lines)
        crc = zlib.crc32(data) & 0xFFFFFFFF
        lines.append(f"  result: {n} lines, crc32 {crc:08x}")

    return '\n'.join(lines)


if __name__ == '__main__':
    main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* CRC32 (zlib/PNG) */
static uint32_t crc32_tab[256];
static void crc32_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++)
            c = (c & 1) ? (c >> 1) ^ 0xEDB88320u : (c >> 1);
        crc32_tab[i] = c;
    }
}
static uint32_t crc32_calc(const uint8_t *buf, size_t len) {
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < len; i++)
        crc = crc32_tab[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFFu;
}

/* Line: pointer + length (includes trailing \n if present) */
typedef struct { const char *data; size_t len; } Line;

/* Content: dynamic array of lines */
typedef struct {
    Line *lines;
    size_t count, cap;
} Content;

static void content_init(Content *c) { c->lines = NULL; c->count = 0; c->cap = 0; }

static void content_ensure(Content *c, size_t need) {
    if (need > c->cap) {
        c->cap = need < 16 ? 16 : need * 2;
        c->lines = realloc(c->lines, c->cap * sizeof(Line));
    }
}

static void content_push(Content *c, const char *d, size_t l) {
    content_ensure(c, c->count + 1);
    c->lines[c->count].data = d;
    c->lines[c->count].len = l;
    c->count++;
}

static void content_from_bytes(Content *c, const char *buf, size_t len) {
    content_init(c);
    if (len == 0) return;
    size_t s = 0;
    for (size_t i = 0; i < len; i++) {
        if (buf[i] == '\n') {
            content_push(c, buf + s, i - s + 1);
            s = i + 1;
        }
    }
    if (s < len) content_push(c, buf + s, len - s);
}

static int line_eq(Line a, Line b) {
    return a.len == b.len && (a.len == 0 || memcmp(a.data, b.data, a.len) == 0);
}

static int content_match_at(Content *c, size_t pos0, Line *old, size_t b) {
    for (size_t i = 0; i < b; i++)
        if (!line_eq(c->lines[pos0 + i], old[i])) return 0;
    return 1;
}

static void content_replace_range(Content *c, size_t pos0, size_t old_cnt,
                                  Line *nl, size_t new_cnt) {
    size_t tail = c->count - pos0 - old_cnt;
    content_ensure(c, pos0 + new_cnt + tail);
    memmove(c->lines + pos0 + new_cnt, c->lines + pos0 + old_cnt, tail * sizeof(Line));
    memcpy(c->lines + pos0, nl, new_cnt * sizeof(Line));
    c->count = pos0 + new_cnt + tail;
}

static void content_insert_at(Content *c, size_t pos0, Line *nl, size_t new_cnt) {
    size_t tail = c->count - pos0;
    content_ensure(c, pos0 + new_cnt + tail);
    memmove(c->lines + pos0 + new_cnt, c->lines + pos0, tail * sizeof(Line));
    memcpy(c->lines + pos0, nl, new_cnt * sizeof(Line));
    c->count = pos0 + new_cnt + tail;
}

/* Hunk */
typedef struct {
    int a, b, c, d;
    Line *old_lines; size_t old_count;
    Line *new_lines; size_t new_count;
    int malformed;
} Hunk;

/* Section */
enum { KIND_MODIFY, KIND_CREATE, KIND_DELETE };
typedef struct {
    char *path;
    int kind;
    Hunk *hunks; size_t hunk_count, hunk_cap;
} Section;

static void section_add_hunk(Section *s) {
    if (s->hunk_count >= s->hunk_cap) {
        s->hunk_cap = s->hunk_cap ? s->hunk_cap * 2 : 4;
        s->hunks = realloc(s->hunks, s->hunk_cap * sizeof(Hunk));
    }
    memset(&s->hunks[s->hunk_count], 0, sizeof(Hunk));
    s->hunk_count++;
}

/* Read entire file into memory; returns NULL if file doesn't exist */
static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    size_t n = fread(buf, 1, (size_t)sz, f);
    fclose(f);
    buf[n] = '\0';
    *out_len = n;
    return buf;
}

/* Raw diff line (includes trailing \n) */
typedef struct { const char *start; size_t len; } RawLine;

static RawLine *split_lines(const char *buf, size_t len, size_t *out_count) {
    size_t cap = 256, count = 0;
    RawLine *lines = (RawLine *)malloc(cap * sizeof(RawLine));
    size_t s = 0;
    for (size_t i = 0; i < len; i++) {
        if (buf[i] == '\n') {
            if (count >= cap) { cap *= 2; lines = realloc(lines, cap * sizeof(RawLine)); }
            lines[count].start = buf + s;
            lines[count].len = i - s + 1;
            count++;
            s = i + 1;
        }
    }
    if (s < len) {
        if (count >= cap) { cap *= 2; lines = realloc(lines, cap * sizeof(RawLine)); }
        lines[count].start = buf + s;
        lines[count].len = len - s;
        count++;
    }
    *out_count = count;
    return lines;
}

static int starts_with(const char *s, size_t len, const char *prefix) {
    size_t plen = strlen(prefix);
    return len >= plen && memcmp(s, prefix, plen) == 0;
}

static int parse_int(const char *s, size_t len, size_t *pos, int *out) {
    int val = 0;
    size_t start = *pos;
    while (*pos < len && s[*pos] >= '0' && s[*pos] <= '9') {
        val = val * 10 + (s[*pos] - '0');
        (*pos)++;
    }
    if (*pos == start) return 0;
    *out = val;
    return 1;
}

static void print_offset(int off) {
    if (off == 0) printf("0");
    else if (off > 0) printf("+%d", off);
    else printf("%d", off);
}

int main(int argc, char *argv[]) {
    (void)argc;
    crc32_init();
    const char *dir = argv[1];

    /* Read changes.diff */
    char diff_path[8192];
    snprintf(diff_path, sizeof(diff_path), "%s/changes.diff", dir);
    size_t diff_len;
    char *diff_buf = read_file(diff_path, &diff_len);
    if (!diff_buf) { fprintf(stderr, "cannot read changes.diff\n"); return 1; }

    size_t nlines;
    RawLine *dl = split_lines(diff_buf, diff_len, &nlines);

    /* Parse sections */
    Section *sections = NULL;
    size_t nsections = 0, sec_cap = 0;

    size_t i = 0;
    while (i < nlines) {
        if (!starts_with(dl[i].start, dl[i].len, "diff --git a/")) { i++; continue; }

        /* Extract path from "diff --git a/<path> b/<path>\n" */
        const char *s = dl[i].start;
        size_t slen = dl[i].len;
        size_t pos = 13; /* strlen("diff --git a/") */
        /* Find " b/" */
        size_t bpos = pos;
        while (bpos < slen) {
            if (s[bpos] == ' ' && bpos + 2 < slen && s[bpos+1] == 'b' && s[bpos+2] == '/')
                break;
            bpos++;
        }
        size_t path_len = bpos - pos;
        char *path = (char *)malloc(path_len + 1);
        memcpy(path, s + pos, path_len);
        path[path_len] = '\0';

        if (nsections >= sec_cap) {
            sec_cap = sec_cap ? sec_cap * 2 : 16;
            sections = realloc(sections, sec_cap * sizeof(Section));
        }
        Section *sec = &sections[nsections++];
        memset(sec, 0, sizeof(Section));
        sec->path = path;
        sec->kind = KIND_MODIFY;
        i++;

        /* Parse header lines */
        while (i < nlines) {
            if (starts_with(dl[i].start, dl[i].len, "new file mode")) { sec->kind = KIND_CREATE; i++; continue; }
            if (starts_with(dl[i].start, dl[i].len, "deleted file mode")) { sec->kind = KIND_DELETE; i++; continue; }
            if (starts_with(dl[i].start, dl[i].len, "index ")) { i++; continue; }
            if (starts_with(dl[i].start, dl[i].len, "--- ")) { i++; continue; }
            if (starts_with(dl[i].start, dl[i].len, "+++ ")) { i++; continue; }
            if (starts_with(dl[i].start, dl[i].len, "@@ ")) break;
            if (starts_with(dl[i].start, dl[i].len, "diff --git ")) break;
            i++;
        }

        /* Parse hunks */
        while (i < nlines && starts_with(dl[i].start, dl[i].len, "@@ ")) {
            section_add_hunk(sec);
            Hunk *h = &sec->hunks[sec->hunk_count - 1];

            const char *hs = dl[i].start;
            size_t hl = dl[i].len;
            size_t hp = 3; /* skip "@@ " */

            /* Parse -a[,b] */
            if (hp < hl && hs[hp] == '-') hp++;
            parse_int(hs, hl, &hp, &h->a);
            if (hp < hl && hs[hp] == ',') { hp++; parse_int(hs, hl, &hp, &h->b); }
            else h->b = 1;

            /* Parse +c[,d] */
            while (hp < hl && hs[hp] == ' ') hp++;
            if (hp < hl && hs[hp] == '+') hp++;
            parse_int(hs, hl, &hp, &h->c);
            if (hp < hl && hs[hp] == ',') { hp++; parse_int(hs, hl, &hp, &h->d); }
            else h->d = 1;

            i++; /* move past @@ line to body */

            /* Find body extent */
            size_t body_start = i;
            size_t body_end = i;
            while (body_end < nlines) {
                if (starts_with(dl[body_end].start, dl[body_end].len, "@@ ")) break;
                if (starts_with(dl[body_end].start, dl[body_end].len, "diff --git ")) break;
                body_end++;
            }

            /* Parse body lines */
            size_t max_lines = body_end - body_start + 1;
            Line *old_arr = (Line *)malloc(max_lines * sizeof(Line));
            Line *new_arr = (Line *)malloc(max_lines * sizeof(Line));
            size_t oc = 0, nc = 0;
            char last_marker = 0;

            for (size_t j = body_start; j < body_end; j++) {
                const char *bl = dl[j].start;
                size_t blen = dl[j].len;
                if (blen == 0) continue;
                char marker = bl[0];

                if (marker == '\\') {
                    /* No newline at end of file: strip \n from last added line(s) */
                    if (last_marker == ' ' || last_marker == '-') {
                        if (oc > 0) old_arr[oc - 1].len--;
                    }
                    if (last_marker == ' ' || last_marker == '+') {
                        if (nc > 0) new_arr[nc - 1].len--;
                    }
                    continue;
                }

                const char *content = bl + 1;
                size_t clen = blen - 1; /* content includes trailing \n */

                if (marker == ' ') {
                    old_arr[oc].data = content; old_arr[oc].len = clen; oc++;
                    new_arr[nc].data = content; new_arr[nc].len = clen; nc++;
                } else if (marker == '-') {
                    old_arr[oc].data = content; old_arr[oc].len = clen; oc++;
                } else if (marker == '+') {
                    new_arr[nc].data = content; new_arr[nc].len = clen; nc++;
                }
                last_marker = marker;
            }

            h->old_lines = old_arr;
            h->old_count = oc;
            h->new_lines = new_arr;
            h->new_count = nc;

            if ((int)oc != h->b || (int)nc != h->d)
                h->malformed = 1;

            i = body_end;
        }
    }

    /* Sort sections by path (bytewise) */
    for (size_t a = 1; a < nsections; a++) {
        Section tmp = sections[a];
        size_t b = a;
        while (b > 0 && strcmp(sections[b - 1].path, tmp.path) > 0) {
            sections[b] = sections[b - 1];
            b--;
        }
        sections[b] = tmp;
    }

    /* Process each section */
    for (size_t si = 0; si < nsections; si++) {
        Section *sec = &sections[si];

        const char *kind_str = sec->kind == KIND_CREATE ? "create" :
                               sec->kind == KIND_DELETE ? "delete" : "modify";
        printf("%s: %s\n", sec->path, kind_str);

        /* Build file path */
        char fpath[16384];
        snprintf(fpath, sizeof(fpath), "%s/tree/%s", dir, sec->path);

        size_t file_len = 0;
        char *file_buf = read_file(fpath, &file_len);

        /* Check error conditions */
        if (sec->kind == KIND_CREATE) {
            if (file_buf) {
                printf("  error: already exists\n");
                free(file_buf);
                continue;
            }
        } else {
            if (!file_buf) {
                printf("  error: not found\n");
                continue;
            }
        }

        /* Initialize content */
        Content content;
        if (sec->kind == KIND_CREATE) {
            content_init(&content);
        } else {
            content_from_bytes(&content, file_buf, file_len);
        }

        /* Apply hunks */
        int delta = 0;
        int all_applied = 1;

        for (size_t hi = 0; hi < sec->hunk_count; hi++) {
            Hunk *h = &sec->hunks[hi];

            if (h->malformed) {
                printf("  hunk %zu: malformed\n", hi + 1);
                all_applied = 0;
                continue;
            }

            int P = h->a + delta;

            if (h->b == 0) {
                /* Insertion */
                if (P >= 0 && (size_t)P <= content.count) {
                    content_insert_at(&content, (size_t)P, h->new_lines, h->new_count);
                    printf("  hunk %zu: applied at %d (offset 0)\n", hi + 1, P);
                    delta += h->d - h->b;
                } else {
                    printf("  hunk %zu: rejected\n", hi + 1);
                    all_applied = 0;
                }
            } else {
                /* Search for match */
                int max_pos = (int)content.count - h->b + 1;
                int found_pos = -1;

                if (max_pos >= 1) {
                    for (int k = 0; ; k++) {
                        int p1 = P - k;
                        int p2 = P + k;

                        /* Termination: both sides exhausted */
                        if (p1 < 1 && p2 > max_pos) break;

                        /* Try p1 (left) */
                        if (p1 >= 1 && p1 <= max_pos) {
                            if (content_match_at(&content, (size_t)(p1 - 1), h->old_lines, (size_t)h->b)) {
                                found_pos = p1;
                                break;
                            }
                        }
                        /* Try p2 (right), skip if k==0 to avoid duplicate */
                        if (k > 0 && p2 >= 1 && p2 <= max_pos) {
                            if (content_match_at(&content, (size_t)(p2 - 1), h->old_lines, (size_t)h->b)) {
                                found_pos = p2;
                                break;
                            }
                        }
                    }
                }

                if (found_pos >= 0) {
                    content_replace_range(&content, (size_t)(found_pos - 1),
                                         (size_t)h->b, h->new_lines, (size_t)h->d);
                    int offset = found_pos - P;
                    printf("  hunk %zu: applied at %d (offset ", hi + 1, found_pos);
                    print_offset(offset);
                    printf(")\n");
                    delta += h->d - h->b;
                } else {
                    printf("  hunk %zu: rejected\n", hi + 1);
                    all_applied = 0;
                }
            }
        }

        /* Output result */
        if (sec->kind == KIND_DELETE && all_applied && content.count == 0) {
            printf("  result: deleted\n");
        } else {
            size_t total_len = 0;
            for (size_t li = 0; li < content.count; li++)
                total_len += content.lines[li].len;
            uint8_t *buf = (uint8_t *)malloc(total_len + 1);
            size_t off = 0;
            for (size_t li = 0; li < content.count; li++) {
                memcpy(buf + off, content.lines[li].data, content.lines[li].len);
                off += content.lines[li].len;
            }
            uint32_t crc = crc32_calc(buf, total_len);
            printf("  result: %zu lines, crc32 %08x\n", content.count, crc);
            free(buf);
        }

        free(content.lines);
        free(file_buf);
    }

    return 0;
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.CRC32;

public class Main {

    static class Hunk {
        int a, b, c, d;
        List<byte[]> oldLines = new ArrayList<>();
        List<byte[]> newLines = new ArrayList<>();
        boolean malformed;
        int nextIndex;
    }

    static class Section {
        String path;
        String kind;
        List<Hunk> hunks = new ArrayList<>();
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        byte[] diffBytes = Files.readAllBytes(Paths.get(dir, "changes.diff"));
        List<Section> sections = parseDiff(diffBytes);

        sections.sort((s1, s2) -> {
            byte[] b1 = s1.path.getBytes(StandardCharsets.UTF_8);
            byte[] b2 = s2.path.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(b1.length, b2.length);
            for (int i = 0; i < len; i++) {
                int cmp = (b1[i] & 0xFF) - (b2[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return Integer.compare(b1.length, b2.length);
        });

        StringBuilder output = new StringBuilder();
        for (Section sec : sections) {
            output.append(applySection(sec, dir));
        }
        System.out.print(output);
    }

    static List<byte[]> splitLines(byte[] data) {
        List<byte[]> lines = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                lines.add(Arrays.copyOfRange(data, start, i));
                start = i + 1;
            }
        }
        if (start < data.length) {
            lines.add(Arrays.copyOfRange(data, start, data.length));
        }
        return lines;
    }

    static boolean startsWith(byte[] arr, String prefix) {
        byte[] pb = prefix.getBytes(StandardCharsets.UTF_8);
        if (arr.length < pb.length) return false;
        for (int i = 0; i < pb.length; i++) {
            if (arr[i] != pb[i]) return false;
        }
        return true;
    }

    static String toStr(byte[] b) {
        return new String(b, StandardCharsets.UTF_8);
    }

    static List<Section> parseDiff(byte[] diff) {
        List<byte[]> lines = splitLines(diff);
        List<Section> sections = new ArrayList<>();
        int i = 0;
        while (i < lines.size()) {
            if (startsWith(lines.get(i), "diff --git a/")) {
                String rest = toStr(lines.get(i)).substring("diff --git a/".length());
                int spaceIdx = rest.indexOf(' ');
                String path = rest.substring(0, spaceIdx);

                Section sec = new Section();
                sec.path = path;
                sec.kind = "modify";

                i++;
                while (i < lines.size()) {
                    byte[] l = lines.get(i);
                    if (startsWith(l, "@@ ")) break;
                    if (startsWith(l, "diff --git ")) break;
                    if (startsWith(l, "new file mode ")) sec.kind = "create";
                    else if (startsWith(l, "deleted file mode ")) sec.kind = "delete";
                    i++;
                }

                while (i < lines.size()) {
                    byte[] l = lines.get(i);
                    if (startsWith(l, "@@ ")) {
                        Hunk hunk = parseHunk(lines, i);
                        sec.hunks.add(hunk);
                        i = hunk.nextIndex;
                    } else if (startsWith(l, "diff --git ")) {
                        break;
                    } else {
                        i++;
                    }
                }

                sections.add(sec);
            } else {
                i++;
            }
        }
        return sections;
    }

    static Hunk parseHunk(List<byte[]> lines, int startIdx) {
        Hunk hunk = new Hunk();
        String header = toStr(lines.get(startIdx));
        String rest = header.substring(3);
        int closeAt = rest.indexOf("@@");
        String rangePart = rest.substring(0, closeAt).trim();
        String[] parts = rangePart.split("\\s+");

        String oldRange = parts[0].substring(1);
        String[] op = oldRange.split(",");
        hunk.a = Integer.parseInt(op[0]);
        hunk.b = op.length > 1 ? Integer.parseInt(op[1]) : 1;

        String newRange = parts[1].substring(1);
        String[] np = newRange.split(",");
        hunk.c = Integer.parseInt(np[0]);
        hunk.d = np.length > 1 ? Integer.parseInt(np[1]) : 1;

        List<byte[]> bodyLines = new ArrayList<>();
        int i = startIdx + 1;
        while (i < lines.size()) {
            byte[] l = lines.get(i);
            if (startsWith(l, "@@ ") || startsWith(l, "diff --git ")) break;
            bodyLines.add(l);
            i++;
        }
        hunk.nextIndex = i;

        int j = 0;
        while (j < bodyLines.size()) {
            byte[] bl = bodyLines.get(j);
            if (bl.length == 0) { j++; continue; }
            byte marker = bl[0];
            if (marker == '\\') { j++; continue; }

            byte[] content = Arrays.copyOfRange(bl, 1, bl.length);
            boolean noNl = false;
            if (j + 1 < bodyLines.size() && bodyLines.get(j + 1).length > 0
                    && bodyLines.get(j + 1)[0] == '\\') {
                noNl = true;
                j++;
            }

            byte[] lineBytes;
            if (noNl) {
                lineBytes = content;
            } else {
                lineBytes = new byte[content.length + 1];
                System.arraycopy(content, 0, lineBytes, 0, content.length);
                lineBytes[content.length] = '\n';
            }

            if (marker == ' ') {
                hunk.oldLines.add(lineBytes);
                hunk.newLines.add(lineBytes);
            } else if (marker == '-') {
                hunk.oldLines.add(lineBytes);
            } else if (marker == '+') {
                hunk.newLines.add(lineBytes);
            }
            j++;
        }

        hunk.malformed = (hunk.oldLines.size() != hunk.b) || (hunk.newLines.size() != hunk.d);
        return hunk;
    }

    static List<byte[]> readFileLines(String dir, String path) throws Exception {
        Path fp = Paths.get(dir, "tree", path);
        if (!Files.exists(fp)) return null;
        byte[] data = Files.readAllBytes(fp);
        List<byte[]> lines = new ArrayList<>();
        if (data.length == 0) return lines;
        int start = 0;
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                lines.add(Arrays.copyOfRange(data, start, i + 1));
                start = i + 1;
            }
        }
        if (start < data.length) {
            lines.add(Arrays.copyOfRange(data, start, data.length));
        }
        return lines;
    }

    static String applySection(Section sec, String dir) throws Exception {
        StringBuilder sb = new StringBuilder();
        sb.append(sec.path).append(": ").append(sec.kind).append("\n");

        List<byte[]> content;

        if (sec.kind.equals("create")) {
            if (Files.exists(Paths.get(dir, "tree", sec.path))) {
                sb.append("  error: already exists\n");
                return sb.toString();
            }
            content = new ArrayList<>();
        } else {
            content = readFileLines(dir, sec.path);
            if (content == null) {
                sb.append("  error: not found\n");
                return sb.toString();
            }
        }

        int delta = 0;
        boolean allApplied = true;

        for (int h = 0; h < sec.hunks.size(); h++) {
            Hunk hunk = sec.hunks.get(h);
            int hn = h + 1;

            if (hunk.malformed) {
                sb.append("  hunk ").append(hn).append(": malformed\n");
                allApplied = false;
                continue;
            }

            int P = hunk.a + delta;

            if (hunk.b == 0) {
                if (P < 0 || P > content.size()) {
                    sb.append("  hunk ").append(hn).append(": rejected\n");
                    allApplied = false;
                } else {
                    content.addAll(P, hunk.newLines);
                    sb.append("  hunk ").append(hn).append(": applied at ").append(P)
                      .append(" (offset 0)\n");
                    delta += hunk.d - hunk.b;
                }
            } else {
                int lineCount = content.size();
                int b = hunk.b;
                boolean found = false;
                int matchPos = -1;

                for (int k = 0; ; k++) {
                    int p1 = P - k;
                    int p2 = P + k;

                    boolean v1 = (p1 >= 1 && p1 + b - 1 <= lineCount);
                    boolean v2 = (p2 >= 1 && p2 + b - 1 <= lineCount);

                    if (k == 0) {
                        if (v1 && matches(content, p1, hunk.oldLines)) {
                            found = true;
                            matchPos = p1;
                            break;
                        }
                    } else {
                        if (v1 && matches(content, p1, hunk.oldLines)) {
                            found = true;
                            matchPos = p1;
                            break;
                        }
                        if (v2 && matches(content, p2, hunk.oldLines)) {
                            found = true;
                            matchPos = p2;
                            break;
                        }
                    }

                    if (p1 < 1 && p2 + b - 1 > lineCount) break;
                }

                if (!found) {
                    sb.append("  hunk ").append(hn).append(": rejected\n");
                    allApplied = false;
                } else {
                    int si = matchPos - 1;
                    for (int x = 0; x < b; x++) content.remove(si);
                    content.addAll(si, hunk.newLines);
                    int offset = matchPos - P;
                    String os = offset > 0 ? "+" + offset : String.valueOf(offset);
                    sb.append("  hunk ").append(hn).append(": applied at ").append(matchPos)
                      .append(" (offset ").append(os).append(")\n");
                    delta += hunk.d - hunk.b;
                }
            }
        }

        if (sec.kind.equals("delete") && allApplied && content.isEmpty()) {
            sb.append("  result: deleted\n");
        } else {
            int totalLen = 0;
            for (byte[] line : content) totalLen += line.length;
            byte[] bytes = new byte[totalLen];
            int pos = 0;
            for (byte[] line : content) {
                System.arraycopy(line, 0, bytes, pos, line.length);
                pos += line.length;
            }
            CRC32 crc = new CRC32();
            crc.update(bytes);
            sb.append("  result: ").append(content.size()).append(" lines, crc32 ")
              .append(String.format("%08x", crc.getValue())).append("\n");
        }

        return sb.toString();
    }

    static boolean matches(List<byte[]> content, int pos, List<byte[]> oldLines) {
        int si = pos - 1;
        for (int i = 0; i < oldLines.size(); i++) {
            if (!Arrays.equals(content.get(si + i), oldLines.get(i))) return false;
        }
        return true;
    }
}

import Foundation

// CRC32 (zlib/PNG: reflected polynomial 0xEDB88320, init and final XOR 0xFFFFFFFF)
func crc32(_ data: [UInt8]) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var crc = UInt32(i)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
        table[i] = crc
    }
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        let index = Int((crc ^ UInt32(byte)) & 0xFF)
        crc = (crc >> 8) ^ table[index]
    }
    return crc ^ 0xFFFFFFFF
}

func splitLines(_ content: [UInt8]) -> [[UInt8]] {
    if content.isEmpty { return [] }
    var lines: [[UInt8]] = []
    var start = 0
    for i in 0..<content.count {
        if content[i] == 0x0A {
            lines.append(Array(content[start...i]))
            start = i + 1
        }
    }
    if start < content.count {
        lines.append(Array(content[start..<content.count]))
    }
    return lines
}

func joinLines(_ lines: [[UInt8]]) -> [UInt8] {
    var result: [UInt8] = []
    for line in lines {
        result.append(contentsOf: line)
    }
    return result
}

struct Hunk {
    let a: Int
    let b: Int
    let c: Int
    let d: Int
    let oldLines: [[UInt8]]
    let newLines: [[UInt8]]
    let malformed: Bool
}

struct Section {
    let path: String
    let pathBytes: [UInt8]
    let kind: String
    let hunks: [Hunk]
}

func parseHunkHeader(_ line: String) -> (a: Int, b: Int, c: Int, d: Int)? {
    guard line.hasPrefix("@@ ") else { return nil }
    let rest = String(line.dropFirst(3))
    guard let closeRange = rest.range(of: " @@") else { return nil }
    let spec = String(rest[rest.startIndex..<closeRange.lowerBound])
    let parts = spec.split(separator: " ", maxSplits: 1)
    guard parts.count == 2 else { return nil }
    let oldPart = String(parts[0])
    let newPart = String(parts[1])
    guard oldPart.hasPrefix("-") && newPart.hasPrefix("+") else { return nil }
    let oldStr = String(oldPart.dropFirst())
    let newStr = String(newPart.dropFirst())
    let oldComponents = oldStr.split(separator: ",")
    let newComponents = newStr.split(separator: ",")
    guard let a = Int(oldComponents[0]), let c = Int(newComponents[0]) else { return nil }
    let b = oldComponents.count > 1 ? (Int(oldComponents[1]) ?? 1) : 1
    let d = newComponents.count > 1 ? (Int(newComponents[1]) ?? 1) : 1
    return (a, b, c, d)
}

func parseDiff(_ diffContent: [UInt8]) -> [Section] {
    let diffLines = splitLines(diffContent)
    var sections: [Section] = []
    var i = 0

    while i < diffLines.count {
        let lineStr = String(decoding: diffLines[i], as: UTF8.self)
        guard lineStr.hasPrefix("diff --git a/") else {
            i += 1
            continue
        }
        let afterPrefix = String(lineStr.dropFirst("diff --git a/".count))
        guard let spaceIdx = afterPrefix.firstIndex(of: " ") else {
            i += 1
            continue
        }
        let path = String(afterPrefix[afterPrefix.startIndex..<spaceIdx])
        i += 1
        var kind = "modify"

        // Parse header lines
        while i < diffLines.count {
            let hline = String(decoding: diffLines[i], as: UTF8.self)
            if hline.hasPrefix("new file mode ") {
                kind = "create"
                i += 1
            } else if hline.hasPrefix("deleted file mode ") {
                kind = "delete"
                i += 1
            } else if hline.hasPrefix("index ") {
                i += 1
            } else if hline.hasPrefix("--- ") {
                i += 1
                if i < diffLines.count {
                    let nextLine = String(decoding: diffLines[i], as: UTF8.self)
                    if nextLine.hasPrefix("+++ ") {
                        i += 1
                    }
                }
                break
            } else if hline.hasPrefix("@@ ") {
                break
            } else if hline.hasPrefix("diff --git ") {
                break
            } else {
                i += 1
            }
        }

        // Parse hunks
        var hunks: [Hunk] = []
        while i < diffLines.count {
            let hline = String(decoding: diffLines[i], as: UTF8.self)
            if hline.hasPrefix("diff --git ") { break }
            if !hline.hasPrefix("@@ ") {
                i += 1
                continue
            }
            guard let header = parseHunkHeader(hline) else {
                i += 1
                continue
            }
            i += 1

            // Collect body lines
            var bodyLines: [(marker: UInt8, content: [UInt8])] = []
            while i < diffLines.count {
                let bline = diffLines[i]
                if bline.isEmpty { break }
                let firstByte = bline[0]
                if firstByte == 0x40 && bline.count >= 3 && bline[1] == 0x40 && bline[2] == 0x20 {
                    break
                }
                if firstByte == 0x64 && bline.count >= 11 {
                    let prefix: [UInt8] = [0x64,0x69,0x66,0x66,0x20,0x2D,0x2D,0x67,0x69,0x74,0x20]
                    if Array(bline[0..<11]) == prefix { break }
                }
                let marker = firstByte
                let content = Array(bline.dropFirst())
                bodyLines.append((marker, content))
                i += 1
            }

            // Build old and new lines from body
            var oldLines: [[UInt8]] = []
            var newLines: [[UInt8]] = []
            var j = 0
            while j < bodyLines.count {
                let (marker, content) = bodyLines[j]
                if marker == 0x5C { // '\'
                    j += 1
                    continue
                }
                let hasNewline: Bool
                if j + 1 < bodyLines.count && bodyLines[j + 1].marker == 0x5C {
                    hasNewline = false
                    j += 2
                } else {
                    hasNewline = true
                    j += 1
                }
                var lineBytes = content
                if hasNewline {
                    lineBytes.append(0x0A)
                }
                switch marker {
                case 0x20: // ' '
                    oldLines.append(lineBytes)
                    newLines.append(lineBytes)
                case 0x2D: // '-'
                    oldLines.append(lineBytes)
                case 0x2B: // '+'
                    newLines.append(lineBytes)
                default:
                    break
                }
            }

            let malformed = (oldLines.count != header.b) || (newLines.count != header.d)
            hunks.append(Hunk(a: header.a, b: header.b, c: header.c, d: header.d,
                             oldLines: oldLines, newLines: newLines, malformed: malformed))
        }

        sections.append(Section(path: path, pathBytes: Array(path.utf8), kind: kind, hunks: hunks))
    }
    return sections
}

func formatOffset(_ offset: Int) -> String {
    if offset > 0 { return "+\(offset)" }
    if offset < 0 { return "\(offset)" }
    return "0"
}

func linesMatch(_ content: [[UInt8]], _ pos: Int, _ oldLines: [[UInt8]]) -> Bool {
    let startIdx = pos - 1
    for i in 0..<oldLines.count {
        if content[startIdx + i] != oldLines[i] { return false }
    }
    return true
}

func applyHunks(content: inout [[UInt8]], hunks: [Hunk]) -> (results: [String], allApplied: Bool) {
    var delta = 0
    var hunkResults: [String] = []
    var allApplied = true

    for (idx, hunk) in hunks.enumerated() {
        let hunkNum = idx + 1
        if hunk.malformed {
            hunkResults.append("  hunk \(hunkNum): malformed")
            allApplied = false
            continue
        }
        let P = hunk.a + delta
        if hunk.b == 0 {
            if P >= 0 && P <= content.count {
                content.insert(contentsOf: hunk.newLines, at: P)
                hunkResults.append("  hunk \(hunkNum): applied at \(P) (offset 0)")
                delta += hunk.d - hunk.b
            } else {
                hunkResults.append("  hunk \(hunkNum): rejected")
                allApplied = false
            }
        } else {
            let lo = 1
            let hi = content.count - hunk.b + 1
            var found = false
            var foundPos = 0
            if lo <= hi {
                var k = 0
                while true {
                    var anyValid = false
                    let p1 = P - k
                    if p1 >= lo && p1 <= hi {
                        if linesMatch(content, p1, hunk.oldLines) {
                            found = true
                            foundPos = p1
                            break
                        }
                        anyValid = true
                    }
                    if k > 0 {
                        let p2 = P + k
                        if p2 >= lo && p2 <= hi {
                            if linesMatch(content, p2, hunk.oldLines) {
                                found = true
                                foundPos = p2
                                break
                            }
                            anyValid = true
                        }
                    }
                    if !anyValid { break }
                    k += 1
                }
            }
            if found {
                let startIdx = foundPos - 1
                content.removeSubrange(startIdx..<(startIdx + hunk.b))
                content.insert(contentsOf: hunk.newLines, at: startIdx)
                let offset = foundPos - P
                hunkResults.append("  hunk \(hunkNum): applied at \(foundPos) (offset \(formatOffset(offset)))")
                delta += hunk.d - hunk.b
            } else {
                hunkResults.append("  hunk \(hunkNum): rejected")
                allApplied = false
            }
        }
    }
    return (hunkResults, allApplied)
}

