use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256usize {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i] = c;
    }
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFF_FFFF
}

fn split_lines(content: &[u8]) -> Vec<Vec<u8>> {
    if content.is_empty() {
        return vec![];
    }
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..content.len() {
        if content[i] == b'\n' {
            lines.push(content[start..=i].to_vec());
            start = i + 1;
        }
    }
    if start < content.len() {
        lines.push(content[start..].to_vec());
    }
    lines
}

fn join_lines(lines: &[Vec<u8>]) -> Vec<u8> {
    let mut result = Vec::new();
    for line in lines {
        result.extend_from_slice(line);
    }
    result
}

fn split_diff_lines(data: &[u8]) -> Vec<&[u8]> {
    let mut result = Vec::new();
    let mut start = 0;
    for i in 0..data.len() {
        if data[i] == b'\n' {
            result.push(&data[start..i]);
            start = i + 1;
        }
    }
    if start < data.len() {
        result.push(&data[start..]);
    }
    result
}

fn starts_with(line: &[u8], prefix: &[u8]) -> bool {
    line.len() >= prefix.len() && &line[..prefix.len()] == prefix
}

fn find_subslice(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > haystack.len() {
        return None;
    }
    for i in 0..=haystack.len() - needle.len() {
        if &haystack[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

fn parse_i64(s: &[u8]) -> i64 {
    let mut negative = false;
    let mut start = 0;
    if !s.is_empty() && s[0] == b'-' {
        negative = true;
        start = 1;
    }
    let mut val: i64 = 0;
    for i in start..s.len() {
        val = val * 10 + (s[i] - b'0') as i64;
    }
    if negative { -val } else { val }
}

fn parse_usize(s: &[u8]) -> usize {
    let mut val: usize = 0;
    for i in 0..s.len() {
        val = val * 10 + (s[i] - b'0') as usize;
    }
    val
}

fn parse_range(s: &[u8]) -> (i64, usize) {
    if let Some(comma_pos) = s.iter().position(|&c| c == b',') {
        let num = parse_i64(&s[..comma_pos]);
        let count = parse_usize(&s[comma_pos + 1..]);
        (num, count)
    } else {
        (parse_i64(s), 1)
    }
}

fn parse_hunk_header(line: &[u8]) -> (i64, usize, usize, usize) {
    let rest = &line[3..]; // skip "@@ "
    let space_pos = rest.iter().position(|&c| c == b' ').unwrap();
    let old_str = &rest[1..space_pos]; // skip '-'
    let new_part = &rest[space_pos + 1..];
    let at_pos = find_subslice(new_part, b" @@").unwrap();
    let new_str = &new_part[1..at_pos]; // skip '+'
    let (a, b) = parse_range(old_str);
    let (c, d) = parse_range(new_str);
    (a, b, c, d)
}

struct Hunk {
    a: i64,
    b: usize,
    d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
    malformed: bool,
}

struct Section {
    path: Vec<u8>,
    kind: String,
    hunks: Vec<Hunk>,
}

fn parse_diff(data: &[u8]) -> Vec<Section> {
    let lines = split_diff_lines(data);
    let mut sections = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        if !starts_with(lines[i], b"diff --git a/") {
            i += 1;
            continue;
        }

        let line = lines[i];
        let after_prefix = &line[b"diff --git a/".len()..];
        let sep = find_subslice(after_prefix, b" b/").unwrap();
        let path = after_prefix[..sep].to_vec();
        i += 1;

        let mut kind = "modify".to_string();

        while i < lines.len()
            && !starts_with(lines[i], b"diff --git ")
            && !starts_with(lines[i], b"@@ ")
        {
            if starts_with(lines[i], b"new file mode ") {
                kind = "create".to_string();
            } else if starts_with(lines[i], b"deleted file mode ") {
                kind = "delete".to_string();
            }
            i += 1;
        }

        let mut hunks = Vec::new();
        while i < lines.len() && starts_with(lines[i], b"@@ ") {
            let header = lines[i];
            i += 1;

            let (a, b, _c, d) = parse_hunk_header(header);

            let mut body: Vec<(u8, Vec<u8>)> = Vec::new();
            while i < lines.len() {
                let bl = lines[i];
                if starts_with(bl, b"@@ ") || starts_with(bl, b"diff --git ") {
                    break;
                }
                if bl.is_empty() {
                    i += 1;
                    continue;
                }
                let marker = bl[0];
                let content = bl[1..].to_vec();
                body.push((marker, content));
                i += 1;
            }

            // Handle \ No newline at end of file
            let mut filtered: Vec<(u8, Vec<u8>, bool)> = Vec::new();
            for j in 0..body.len() {
                if body[j].0 == b'\\' {
                    if !filtered.is_empty() {
                        filtered.last_mut().unwrap().2 = false;
                    }
                } else {
                    filtered.push((body[j].0, body[j].1.clone(), true));
                }
            }

            let mut old_lines = Vec::new();
            let mut new_lines = Vec::new();

            for (marker, content, nl) in &filtered {
                let mut line_bytes = content.clone();
                if *nl {
                    line_bytes.push(b'\n');
                }
                match *marker {
                    b' ' => {
                        old_lines.push(line_bytes.clone());
                        new_lines.push(line_bytes);
                    }
                    b'-' => {
                        old_lines.push(line_bytes);
                    }
                    b'+' => {
                        new_lines.push(line_bytes);
                    }
                    _ => {}
                }
            }

            let malformed = old_lines.len() != b || new_lines.len() != d;
            hunks.push(Hunk { a, b, d, old_lines, new_lines, malformed });
        }

        sections.push(Section { path, kind, hunks });
    }

    sections
}

fn matches_at(lines: &[Vec<u8>], p: usize, old_lines: &[Vec<u8>]) -> bool {
    let start = p - 1;
    if start + old_lines.len() > lines.len() {
        return false;
    }
    for i in 0..old_lines.len() {
        if lines[start + i] != old_lines[i] {
            return false;
        }
    }
    true
}

fn apply_section(section: &Section, dir: &str) -> String {
    let path_str = String::from_utf8_lossy(&section.path).to_string();
    let file_path = format!("{}/tree/{}", dir, path_str);
    let file_exists = Path::new(&file_path).exists();

    match section.kind.as_str() {
        "create" => {
            if file_exists {
                return format!("{}: create\n  error: already exists\n", path_str);
            }
        }
        "delete" | "modify" => {
            if !file_exists {
                return format!("{}: {}\n  error: not found\n", path_str, section.kind);
            }
        }
        _ => unreachable!(),
    }

    let content = if file_exists {
        fs::read(&file_path).unwrap()
    } else {
        vec![]
    };

    let mut lines = split_lines(&content);
    let mut delta: i64 = 0;
    let mut hunk_results: Vec<String> = Vec::new();

    for (idx, hunk) in section.hunks.iter().enumerate() {
        let hunk_num = idx + 1;

        if hunk.malformed {
            hunk_results.push(format!("  hunk {}: malformed\n", hunk_num));
            continue;
        }

        let p_expected = hunk.a + delta;

        if hunk.b == 0 {
            let p = p_expected;
            if p < 0 || p > lines.len() as i64 {
                hunk_results.push(format!("  hunk {}: rejected\n", hunk_num));
            } else {
                let insert_pos = p as usize;
                for (i, new_line) in hunk.new_lines.iter().enumerate() {
                    lines.insert(insert_pos + i, new_line.clone());
                }
                hunk_results.push(format!("  hunk {}: applied at {} (offset 0)\n", hunk_num, p));
                delta += hunk.d as i64;
            }
        } else {
            let b = hunk.b;
            let max_p = lines.len() as i64 - b as i64 + 1;

            let mut found_p: Option<usize> = None;
            let mut offset: i64 = 0;

            loop {
                let p1 = p_expected - offset;
                if p1 >= 1 && p1 <= max_p {
                    if matches_at(&lines, p1 as usize, &hunk.old_lines) {
                        found_p = Some(p1 as usize);
                        break;
                    }
                }

                if offset > 0 {
                    let p2 = p_expected + offset;
                    if p2 >= 1 && p2 <= max_p {
                        if matches_at(&lines, p2 as usize, &hunk.old_lines) {
                            found_p = Some(p2 as usize);
                            break;
                        }
                    }
                }

                if p_expected - offset < 1 && p_expected + offset > max_p {
                    break;
                }

                offset += 1;
            }

            if let Some(p) = found_p {
                let start = p - 1;
                let end = start + b;
                let new_lines = hunk.new_lines.clone();
                lines.splice(start..end, new_lines);

                let actual_offset = p as i64 - p_expected;
                let offset_str = if actual_offset > 0 {
                    format!("+{}", actual_offset)
                } else {
                    format!("{}", actual_offset)
                };
                hunk_results.push(format!(
                    "  hunk {}: applied at {} (offset {})\n",
                    hunk_num, p, offset_str
                ));
                delta += hunk.d as i64 - b as i64;
            } else {
                hunk_results.push(format!("  hunk {}: rejected\n", hunk_num));
            }
        }
    }

    let mut output = format!("{}: {}\n", path_str, section.kind);
    for hr in &hunk_results {
        output.push_str(hr);
    }

    if section.kind == "delete" {
        let all_applied = hunk_results.iter().all(|hr| hr.contains("applied"));
        if all_applied && lines.is_empty() {
            output.push_str("  result: deleted\n");
        } else {
            let content_bytes = join_lines(&lines);
            let crc = crc32(&content_bytes);
            output.push_str(&format!("  result: {} lines, crc32 {:08x}\n", lines.len(), crc));
        }
    } else {
        let content_bytes = join_lines(&lines);
        let crc = crc32(&content_bytes);
        output.push_str(&format!("  result: {} lines, crc32 {:08x}\n", lines.len(), crc));
    }

    output
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];

    let diff_data = fs::read(format!("{}/changes.diff", dir)).unwrap();
    let sections = parse_diff(&diff_data);

    let mut results: BTreeMap<Vec<u8>, String> = BTreeMap::new();

    for section in &sections {
        let output = apply_section(section, dir);
        results.insert(section.path.clone(), output);
    }

    let mut out = String::new();
    for (_, block) in &results {
        out.push_str(block);
    }
    print!("{}", out);
}

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256usize {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i] = c;
    }
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFF_FFFF
}

fn split_lines(content: &[u8]) -> Vec<Vec<u8>> {
    if content.is_empty() {
        return vec![];
    }
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..content.len() {
        if content[i] == b'\n' {
            lines.push(content[start..=i].to_vec());
            start = i + 1;
        }
    }
    if start < content.len() {
        lines.push(content[start..].to_vec());
    }
    lines
}

fn join_lines(lines: &[Vec<u8>]) -> Vec<u8> {
    let mut result = Vec::new();
    for line in lines {
        result.extend_from_slice(line);
    }
    result
}

fn split_diff_lines(data: &[u8]) -> Vec<&[u8]> {
    let mut result = Vec::new();
    let mut start = 0;
    for i in 0..data.len() {
        if data[i] == b'\n' {
            result.push(&data[start..i]);
            start = i + 1;
        }
    }
    if start < data.len() {
        result.push(&data[start..]);
    }
    result
}

fn starts_with(line: &[u8], prefix: &[u8]) -> bool {
    line.len() >= prefix.len() && &line[..prefix.len()] == prefix
}

fn find_subslice(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > haystack.len() {
        return None;
    }
    for i in 0..=haystack.len() - needle.len() {
        if &haystack[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

fn parse_i64(s: &[u8]) -> i64 {
    let mut negative = false;
    let mut start = 0;
    if !s.is_empty() && s[0] == b'-' {
        negative = true;
        start = 1;
    }
    let mut val: i64 = 0;
    for i in start..s.len() {
        val = val * 10 + (s[i] - b'0') as i64;
    }
    if negative { -val } else { val }
}

fn parse_usize(s: &[u8]) -> usize {
    let mut val: usize = 0;
    for i in 0..s.len() {
        val = val * 10 + (s[i] - b'0') as usize;
    }
    val
}

fn parse_range(s: &[u8]) -> (i64, usize) {
    if let Some(comma_pos) = s.iter().position(|&c| c == b',') {
        let num = parse_i64(&s[..comma_pos]);
        let count = parse_usize(&s[comma_pos + 1..]);
        (num, count)
    } else {
        (parse_i64(s), 1)
    }
}

fn parse_hunk_header(line: &[u8]) -> (i64, usize, i64, usize) {
    let rest = &line[3..]; // skip "@@ "
    let space_pos = rest.iter().position(|&c| c == b' ').unwrap();
    let old_str = &rest[1..space_pos]; // skip '-'
    let new_part = &rest[space_pos + 1..];
    let at_pos = find_subslice(new_part, b" @@").unwrap();
    let new_str = &new_part[1..at_pos]; // skip '+'
    let (a, b) = parse_range(old_str);
    let (c, d) = parse_range(new_str);
    (a, b, c, d)
}

struct Hunk {
    a: i64,
    b: usize,
    d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
    malformed: bool,
}

struct Section {
    path: Vec<u8>,
    kind: String,
    hunks: Vec<Hunk>,
}

fn parse_diff(data: &[u8]) -> Vec<Section> {
    let lines = split_diff_lines(data);
    let mut sections = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        if !starts_with(lines[i], b"diff --git a/") {
            i += 1;
            continue;
        }

        let line = lines[i];
        let after_prefix = &line[b"diff --git a/".len()..];
        let sep = find_subslice(after_prefix, b" b/").unwrap();
        let path = after_prefix[..sep].to_vec();
        i += 1;

        let mut kind = "modify".to_string();

        while i < lines.len()
            && !starts_with(lines[i], b"diff --git ")
            && !starts_with(lines[i], b"@@ ")
        {
            if starts_with(lines[i], b"new file mode ") {
                kind = "create".to_string();
            } else if starts_with(lines[i], b"deleted file mode ") {
                kind = "delete".to_string();
            }
            i += 1;
        }

        let mut hunks = Vec::new();
        while i < lines.len() && starts_with(lines[i], b"@@ ") {
            let header = lines[i];
            i += 1;

            let (a, b, _c, d) = parse_hunk_header(header);

            let mut body: Vec<(u8, Vec<u8>)> = Vec::new();
            while i < lines.len() {
                let bl = lines[i];
                if starts_with(bl, b"@@ ") || starts_with(bl, b"diff --git ") {
                    break;
                }
                if bl.is_empty() {
                    i += 1;
                    continue;
                }
                let marker = bl[0];
                let content = bl[1..].to_vec();
                body.push((marker, content));
                i += 1;
            }

            // Handle \ No newline at end of file
            let mut filtered: Vec<(u8, Vec<u8>, bool)> = Vec::new();
            for j in 0..body.len() {
                if body[j].0 == b'\\' {
                    if !filtered.is_empty() {
                        filtered.last_mut().unwrap().2 = false;
                    }
                } else {
                    filtered.push((body[j].0, body[j].1.clone(), true));
                }
            }

            let mut old_lines = Vec::new();
            let mut new_lines = Vec::new();

            for (marker, content, nl) in &filtered {
                let mut line_bytes = content.clone();
                if *nl {
                    line_bytes.push(b'\n');
                }
                match *marker {
                    b' ' => {
                        old_lines.push(line_bytes.clone());
                        new_lines.push(line_bytes);
                    }
                    b'-' => {
                        old_lines.push(line_bytes);
                    }
                    b'+' => {
                        new_lines.push(line_bytes);
                    }
                    _ => {}
                }
            }

            let malformed = old_lines.len() != b || new_lines.len() != d;
            hunks.push(Hunk { a, b, d, old_lines, new_lines, malformed });
        }

        sections.push(Section { path, kind, hunks });
    }

    sections
}

fn matches_at(lines: &[Vec<u8>], p: usize, old_lines: &[Vec<u8>]) -> bool {
    let start = p - 1;
    if start + old_lines.len() > lines.len() {
        return false;
    }
