/* ============ VALUE TYPES ============ */

typedef struct Value Value;
typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;
typedef struct Node Node;

typedef enum { VT_INT, VT_BOOL, VT_STRING, VT_LIST, VT_FUNC, VT_NIL } VType;

struct Value {
    VType type;
    union {
        int64_t ival;
        bool bval;
        struct { char *data; int len; } s;
        List *list;
        Func *func;
    };
};

struct List {
    Value *items;
    int len, cap;
};

struct Func {
    bool is_builtin;
    char **params;
    int nparams;
    Node **body;
    int nbody;
    Scope *captured;
    char *bname;
    int bid;
};

struct Scope {
    Scope *parent;
    struct { char *name; Value val; } *vars;
    int nvars, cap;
    bool captured;
};

/* ============ AST ============ */

typedef enum {
    ST_LET, ST_FN_DECL, ST_IF, ST_WHILE, ST_FOR, ST_RETURN, ST_BREAK, ST_CONTINUE,
    ST_ASSIGN, ST_IDX_ASSIGN, ST_EXPR_STMT,
    EX_INT, EX_STR, EX_BOOL, EX_NIL, EX_IDENT, EX_BIN, EX_UNARY, EX_CALL, EX_INDEX, EX_LIST_LIT, EX_LAMBDA
} NodeType;

enum { OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_MOD, OP_EQ, OP_NE, OP_LT, OP_LE, OP_GT, OP_GE, OP_AND, OP_OR };
enum { UN_NEG, UN_NOT };

struct Node {
    NodeType type;
    int line;
    char *name;
    int64_t ival;
    char *sval;
    int slen;
    bool bval;
    int op;
    Node *a, *b, *c;
    Node **nodes;
    int nnodes;
    char **params;
    int nparams;
    Node *else_if;
};

/* ============ GLOBALS ============ */

#define CF_NORMAL 0
#define CF_BREAK 1
#define CF_CONTINUE 2
#define CF_RETURN 3

static int control_flow;
static Value return_value;

/* ============ HELPERS ============ */

static void *xmalloc(size_t n) { void *p = malloc(n); if (!p) { fprintf(stderr, "OOM\n"); exit(1); } return p; }
static void *xrealloc(void *p, size_t n) { void *r = realloc(p, n); if (!r) { fprintf(stderr, "OOM\n"); exit(1); } return r; }

static Value mk_int(int64_t v) { Value x; x.type = VT_INT; x.ival = v; return x; }
static Value mk_bool(bool v) { Value x; x.type = VT_BOOL; x.bval = v; return x; }
static Value mk_nil(void) { Value x; x.type = VT_NIL; return x; }
static Value mk_str(const char *s, int len) {
    Value x; x.type = VT_STRING; x.s.data = (char*)xmalloc(len + 1);
    memcpy(x.s.data, s, len); x.s.data[len] = 0; x.s.len = len; return x;
}
static Value mk_list(List *l) { Value x; x.type = VT_LIST; x.list = l; return x; }
static Value mk_func(Func *f) { Value x; x.type = VT_FUNC; x.func = f; return x; }

static List *new_list(void) { List *l = xmalloc(sizeof(List)); l->items = NULL; l->len = 0; l->cap = 0; return l; }

static void list_push(List *l, Value v) {
    if (l->len >= l->cap) { l->cap = l->cap ? l->cap * 2 : 4; l->items = xrealloc(l->items, l->cap * sizeof(Value)); }
    l->items[l->len++] = v;
}

static bool is_truthy(Value v) {
    switch (v.type) {
        case VT_BOOL: return v.bval;
        case VT_INT: return v.ival != 0;
        case VT_STRING: return v.s.len != 0;
        case VT_LIST: return v.list->len != 0;
        case VT_FUNC: return true;
        case VT_NIL: return false;
    }
    return false;
}

/* ============ LEXER ============ */

typedef enum {
    TOK_INT, TOK_STR, TOK_IDENT,
    TOK_PLUS, TOK_MINUS, TOK_STAR, TOK_SLASH, TOK_PERCENT,
    TOK_EQ, TOK_NE, TOK_LT, TOK_LE, TOK_GT, TOK_GE,
    TOK_ASSIGN, TOK_LPAREN, TOK_RPAREN, TOK_LBRACKET, TOK_RBRACKET, TOK_LBRACE, TOK_RBRACE,
    TOK_COMMA, TOK_SEMI,
    TOK_LET, TOK_FN, TOK_IF, TOK_ELSE, TOK_WHILE, TOK_FOR, TOK_IN,
    TOK_RETURN, TOK_BREAK, TOK_CONTINUE, TOK_AND, TOK_OR, TOK_NOT,
    TOK_TRUE, TOK_FALSE, TOK_NIL, TOK_EOF
} TokenType;

typedef struct {
    TokenType type;
    int line;
    int64_t ival;
    char *sval;
    int slen;
} Token;

static Token *tokens;
static int ntokens, tokpos;

static int is_ident_start(char c) { return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_'; }
static int is_ident_char(char c) { return is_ident_start(c) || (c >= '0' && c <= '9'); }

static const char *keywords[] = {"let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil",NULL};
static const TokenType kw_types[] = {TOK_LET,TOK_FN,TOK_IF,TOK_ELSE,TOK_WHILE,TOK_FOR,TOK_IN,TOK_RETURN,TOK_BREAK,TOK_CONTINUE,TOK_AND,TOK_OR,TOK_NOT,TOK_TRUE,TOK_FALSE,TOK_NIL};

static TokenType kw_lookup(const char *s, int len) {
    for (int i = 0; keywords[i]; i++) {
        if ((int)strlen(keywords[i]) == len && memcmp(keywords[i], s, len) == 0) return kw_types[i];
    }
    return TOK_IDENT;
}

static void tokenize(const char *src, int srclen) {
    int cap = 1024, n = 0, line = 1;
    tokens = xmalloc(cap * sizeof(Token));
    int i = 0;
    while (i < srclen) {
        char c = src[i];
        if (c == '\n') { line++; i++; continue; }
        if (c == ' ' || c == '\t' || c == '\r') { i++; continue; }
        if (c == '#') { while (i < srclen && src[i] != '\n') i++; continue; }

        if (n >= cap) { cap *= 2; tokens = xrealloc(tokens, cap * sizeof(Token)); }
        Token *t = &tokens[n];
        t->line = line;
        t->sval = NULL; t->slen = 0; t->ival = 0;

        if (c >= '0' && c <= '9') {
            t->type = TOK_INT;
            int64_t val = 0;
            while (i < srclen && src[i] >= '0' && src[i] <= '9') { val = val * 10 + (src[i] - '0'); i++; }
            t->ival = val; n++; continue;
        }
        if (c == '"') {
            t->type = TOK_STR; i++;
            int scap = 64, slen = 0; char *sbuf = xmalloc(scap);
            while (i < srclen && src[i] != '"') {
                if (src[i] == '\\') {
                    i++;
                    char e = src[i];
                    char out;
                    if (e == 'n') out = '\n';
                    else if (e == 't') out = '\t';
                    else if (e == '"') out = '"';
                    else if (e == '\\') out = '\\';
                    else out = e;
                    if (slen >= scap) { scap *= 2; sbuf = xrealloc(sbuf, scap); }
                    sbuf[slen++] = out; i++;
                } else {
                    if (slen >= scap) { scap *= 2; sbuf = xrealloc(sbuf, scap); }
                    sbuf[slen++] = src[i++];
                }
            }
            if (i < srclen) i++; // skip closing "
            t->sval = sbuf; t->slen = slen; n++; continue;
        }
        if (is_ident_start(c)) {
            int start = i;
            while (i < srclen && is_ident_char(src[i])) i++;
            int len = i - start;
            TokenType kw = kw_lookup(src + start, len);
            if (kw != TOK_IDENT) { t->type = kw; }
            else {
                t->type = TOK_IDENT;
                t->sval = xmalloc(len + 1);
                memcpy(t->sval, src + start, len);
                t->sval[len] = 0; t->slen = len;
            }
            n++; continue;
        }
        /* Operators */
        if (c == '=' && i+1 < srclen && src[i+1] == '=') { t->type = TOK_EQ; i += 2; n++; continue; }
        if (c == '!' && i+1 < srclen && src[i+1] == '=') { t->type = TOK_NE; i += 2; n++; continue; }
        if (c == '<' && i+1 < srclen && src[i+1] == '=') { t->type = TOK_LE; i += 2; n++; continue; }
        if (c == '>' && i+1 < srclen && src[i+1] == '=') { t->type = TOK_GE; i += 2; n++; continue; }
        if (c == '<') { t->type = TOK_LT; i++; n++; continue; }
        if (c == '>') { t->type = TOK_GT; i++; n++; continue; }
        if (c == '=') { t->type = TOK_ASSIGN; i++; n++; continue; }
        if (c == '+') { t->type = TOK_PLUS; i++; n++; continue; }
        if (c == '-') { t->type = TOK_MINUS; i++; n++; continue; }
        if (c == '*') { t->type = TOK_STAR; i++; n++; continue; }
        if (c == '/') { t->type = TOK_SLASH; i++; n++; continue; }
        if (c == '%') { t->type = TOK_PERCENT; i++; n++; continue; }
        if (c == '(') { t->type = TOK_LPAREN; i++; n++; continue; }
        if (c == ')') { t->type = TOK_RPAREN; i++; n++; continue; }
        if (c == '[') { t->type = TOK_LBRACKET; i++; n++; continue; }
        if (c == ']') { t->type = TOK_RBRACKET; i++; n++; continue; }
        if (c == '{') { t->type = TOK_LBRACE; i++; n++; continue; }
        if (c == '}') { t->type = TOK_RBRACE; i++; n++; continue; }
        if (c == ',') { t->type = TOK_COMMA; i++; n++; continue; }
        if (c == ';') { t->type = TOK_SEMI; i++; n++; continue; }
        i++; /* skip unknown */
    }
    if (n >= cap) { cap++; tokens = xrealloc(tokens, cap * sizeof(Token)); }
    tokens[n].type = TOK_EOF; tokens[n].line = line; tokens[n].sval = NULL;
    ntokens = n; tokpos = 0;
}

/* ============ PARSER ============ */

static Token *peek(void) { return &tokens[tokpos]; }
static Token *advance(void) { return &tokens[tokpos++]; }
static bool match(TokenType t) { if (peek()->type == t) { tokpos++; return true; } return false; }
static void expect(TokenType t) { if (!match(t)) { fprintf(stderr, "syntax error at line %d\n", peek()->line); exit(1); } }

static Node *new_node(NodeType t) {
    Node *n = xmalloc(sizeof(Node));
    memset(n, 0, sizeof(Node));
    n->type = t;
    n->line = peek()->line;
    return n;
}

static Node *parse_expr(void);
static Node **parse_block(int *out_n);

static Node **parse_block(int *out_n) {
    expect(TOK_LBRACE);
    int cap = 8, n = 0;
    Node **stmts = xmalloc(cap * sizeof(Node*));
    while (peek()->type != TOK_RBRACE && peek()->type != TOK_EOF) {
        if (n >= cap) { cap *= 2; stmts = xrealloc(stmts, cap * sizeof(Node*)); }
        stmts[n++] = parse_stmt();
    }
    expect(TOK_RBRACE);
    *out_n = n;
    return stmts;
}

static Node *parse_params(char ***out_params, int *out_nparams) {
    if (peek()->type == TOK_RPAREN) { *out_params = NULL; *out_nparams = 0; return NULL; }
    int cap = 4, n = 0;
    char **params = xmalloc(cap * sizeof(char*));
    for (;;) {
        Token *t = advance();
        if (n >= cap) { cap *= 2; params = xrealloc(params, cap * sizeof(char*)); }
        params[n++] = t->sval;
        if (!match(TOK_COMMA)) break;
    }
    *out_params = params; *out_nparams = n;
    return NULL;
}

static Node *parse_primary(void) {
    Token *t = peek();
    if (t->type == TOK_INT) { advance(); Node *n = new_node(EX_INT); n->line = t->line; n->ival = t->ival; return n; }
    if (t->type == TOK_STR) { advance(); Node *n = new_node(EX_STR); n->line = t->line; n->sval = t->sval; n->slen = t->slen; return n; }
    if (t->type == TOK_TRUE) { advance(); Node *n = new_node(EX_BOOL); n->line = t->line; n->bval = true; return n; }
    if (t->type == TOK_FALSE) { advance(); Node *n = new_node(EX_BOOL); n->line = t->line; n->bval = false; return n; }
    if (t->type == TOK_NIL) { advance(); Node *n = new_node(EX_NIL); n->line = t->line; return n; }
    if (t->type == TOK_IDENT) { advance(); Node *n = new_node(EX_IDENT); n->line = t->line; n->name = t->sval; return n; }
    if (t->type == TOK_LPAREN) { advance(); Node *e = parse_expr(); expect(TOK_RPAREN); return e; }
    if (t->type == TOK_LBRACKET) {
        advance();
        int cap = 4, n = 0;
        Node **elems = xmalloc(cap * sizeof(Node*));
        if (peek()->type != TOK_RBRACKET) {
            for (;;) {
                if (n >= cap) { cap *= 2; elems = xrealloc(elems, cap * sizeof(Node*)); }
                elems[n++] = parse_expr();
                if (!match(TOK_COMMA)) break;
            }
        }
        expect(TOK_RBRACKET);
        Node *nd = new_node(EX_LIST_LIT); nd->line = t->line; nd->nodes = elems; nd->nnodes = n;
        return nd;
    }
    if (t->type == TOK_FN) {
        advance(); expect(TOK_LPAREN);
        char **params; int nparams;
        parse_params(&params, &nparams);
        expect(TOK_RPAREN);
        int nbody;
        Node **body = parse_block(&nbody);
        Node *nd = new_node(EX_LAMBDA); nd->line = t->line; nd->params = params; nd->nparams = nparams; nd->nodes = body; nd->nnodes = nbody;
        return nd;
    }
    fprintf(stderr, "unexpected token at line %d\n", t->line); exit(1);
    return NULL;
}

static Node *parse_postfix(void) {
    Node *n = parse_primary();
    for (;;) {
        if (peek()->type == TOK_LPAREN) {
            int line = peek()->line;
            advance();
            int cap = 4, na = 0;
            Node **args = xmalloc(cap * sizeof(Node*));
            if (peek()->type != TOK_RPAREN) {
                for (;;) {
                    if (na >= cap) { cap *= 2; args = xrealloc(args, cap * sizeof(Node*)); }
                    args[na++] = parse_expr();
                    if (!match(TOK_COMMA)) break;
                }
            }
            expect(TOK_RPAREN);
            Node *c = new_node(EX_CALL); c->line = line; c->a = n; c->nodes = args; c->nnodes = na;
            n = c;
        } else if (peek()->type == TOK_LBRACKET) {
            int line = peek()->line;
            advance();
            Node *idx = parse_expr();
            expect(TOK_RBRACKET);
            Node *ix = new_node(EX_INDEX); ix->line = line; ix->a = n; ix->b = idx;
            n = ix;
        } else break;
    }
    return n;
}

static Node *parse_unary(void) {
    if (peek()->type == TOK_MINUS) {
        int line = peek()->line;
        advance();
        Node *n = new_node(EX_UNARY); n->line = line; n->op = UN_NEG; n->a = parse_unary();
        return n;
    }
    return parse_postfix();
}

static Node *parse_mul(void) {
    Node *n = parse_unary();
    while (peek()->type == TOK_STAR || peek()->type == TOK_SLASH || peek()->type == TOK_PERCENT) {
        int line = peek()->line;
        int op;
        if (peek()->type == TOK_STAR) op = OP_MUL;
        else if (peek()->type == TOK_SLASH) op = OP_DIV;
        else op = OP_MOD;
        advance();
        Node *r = parse_unary();
        Node *b = new_node(EX_BIN); b->line = line; b->op = op; b->a = n; b->b = r;
        n = b;
    }
    return n;
}

static Node *parse_add(void) {
    Node *n = parse_mul();
    while (peek()->type == TOK_PLUS || peek()->type == TOK_MINUS) {
        int line = peek()->line;
        int op = (peek()->type == TOK_PLUS) ? OP_ADD : OP_SUB;
        advance();
        Node *r = parse_mul();
        Node *b = new_node(EX_BIN); b->line = line; b->op = op; b->a = n; b->b = r;
        n = b;
    }
    return n;
}

static Node *parse_comparison(void) {
    Node *n = parse_add();
    while (peek()->type == TOK_EQ || peek()->type == TOK_NE || peek()->type == TOK_LT ||
           peek()->type == TOK_LE || peek()->type == TOK_GT || peek()->type == TOK_GE) {
        int line = peek()->line;
        int op;
        switch (peek()->type) {
            case TOK_EQ: op = OP_EQ; break; case TOK_NE: op = OP_NE; break;
            case TOK_LT: op = OP_LT; break; case TOK_LE: op = OP_LE; break;
            case TOK_GT: op = OP_GT; break; default: op = OP_GE; break;
        }
        advance();
        Node *r = parse_add();
        Node *b = new_node(EX_BIN); b->line = line; b->op = op; b->a = n; b->b = r;
        n = b;
    }
    return n;
}

static Node *parse_not(void) {
    if (peek()->type == TOK_NOT) {
        int line = peek()->line;
        advance();
        Node *n = new_node(EX_UNARY); n->line = line; n->op = UN_NOT; n->a = parse_not();
        return n;
    }
    return parse_comparison();
}

static Node *parse_and(void) {
    Node *n = parse_not();
    while (peek()->type == TOK_AND) {
        int line = peek()->line;
        advance();
        Node *r = parse_not();
        Node *b = new_node(EX_BIN); b->line = line; b->op = OP_AND; b->a = n; b->b = r;
        n = b;
    }
    return n;
}

static Node *parse_or(void) {
    Node *n = parse_and();
    while (peek()->type == TOK_OR) {
        int line = peek()->line;
        advance();
        Node *r = parse_and();
        Node *b = new_node(EX_BIN); b->line = line; b->op = OP_OR; b->a = n; b->b = r;
        n = b;
    }
    return n;
}

static Node *parse_expr(void) { return parse_or(); }

static Node *parse_ifstmt(void) {
    int line = peek()->line;
    advance(); // if
    Node *cond = parse_expr();
    int nthen;
    Node **then_body = parse_block(&nthen);
    Node *n = new_node(ST_IF); n->line = line; n->a = cond; n->nodes = then_body; n->nnodes = nthen;
    n->else_if = NULL; n->b = NULL; n->nc = 0;
    if (peek()->type == TOK_ELSE) {
        advance();
        if (peek()->type == TOK_IF) {
            n->else_if = parse_ifstmt();
        } else {
            int nelse;
            n->b = (Node*)parse_block(&nelse); // hack: store in b
            n->c = (Node*)(intptr_t)nelse; // hack: store count in c... no, let me use a different approach
        }
    }
    return n;
}

