// MARK: - Values

final class TernList {
    var elements: [Value]
    init(_ elems: [Value] = []) { elements = elems }
}

final class TernFunction {
    let params: [String]
    let body: [Stmt]
    let capturedScope: Scope
    let isBuiltin: Bool
    let builtinName: String
    let builtinArity: Int  // -1 for variadic
    let builtinFn: (([Value]) throws -> Value)?

    init(params: [String], body: [Stmt], capturedScope: Scope) {
        self.params = params
        self.body = body
        self.capturedScope = capturedScope
        self.isBuiltin = false
        self.builtinName = ""
        self.builtinArity = -1
        self.builtinFn = nil
    }

    init(builtinName: String, arity: Int, fn: @escaping ([Value]) throws -> Value) {
        self.params = []
        self.body = []
        self.capturedScope = Scope(parent: nil)
        self.isBuiltin = true
        self.builtinName = builtinName
        self.builtinArity = arity
        self.builtinFn = fn
    }
}

enum Value {
    case int(Int64)
    case bool(Bool)
    case string(String)
    case list(TernList)
    case function(TernFunction)
    case nilVal
}

final class Scope {
    let parent: Scope?
    var vars: [String: Value]
    init(parent: Scope?) { self.parent = parent; self.vars = [:] }

    func lookup(_ name: String) -> Value? {
        if let v = vars[name] { return v }
        return parent?.lookup(name)
    }

    func set(_ name: String, _ value: Value) -> Bool {
        if vars[name] != nil { vars[name] = value; return true }
        return parent?.set(name, value) ?? false
    }

    func define(_ name: String, _ value: Value) {
        vars[name] = value
    }
}

// MARK: - Errors

struct TernError: Error {
    let line: Int
    let message: String
}

enum ControlFlow: Error {
    case breakSignal
    case continueSignal
    case returnSignal(Value)
}

// MARK: - Interpreter

func typeName(_ v: Value) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .string: return "string"
    case .list: return "list"
    case .function: return "function"
    case .nilVal: return "nil"
    }
}

func isTruthy(_ v: Value) -> Bool {
    switch v {
    case .int(let n): return n != 0
    case .bool(let b): return b
    case .string(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .function: return true
    case .nilVal: return false
    }
}

func displayValue(_ v: Value, quoted: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let n): return String(n)
    case .bool(let b): return b ? "true" : "false"
    case .string(let s):
        if quoted {
            var r = "\""
            for c in s {
                switch c {
                case "\\": r += "\\\\"
                case "\"": r += "\\\""
                case "\n": r += "\\n"
                case "\t": r += "\\t"
                default: r.append(c)
                }
            }
            r += "\""
            return r
        } else {
            return s
        }
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if seen.contains(oid) { return "[...]" }
        seen.insert(oid)
        var r = "["
        for (i, elem) in l.elements.enumerated() {
            if i > 0 { r += ", " }
            r += displayValue(elem, quoted: true, seen: &seen)
        }
        r += "]"
        seen.remove(oid)
        return r
    case .function: return "<fn>"
    case .nilVal: return "nil"
    }
}

func valuesEqual(_ a: Value, _ b: Value) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nilVal, .nilVal): return true
    case (.list(let x), .list(let y)):
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valuesEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    case (.function(let x), .function(let y)): return x === y
    default: return false
    }
}

func safeAdd(_ a: Int64, _ b: Int64, line: Int) throws -> Int64 {
    let (r, ov) = a.addingReportingOverflow(b)
    if ov { throw TernError(line: line, message: "integer overflow") }
    return r
}

func safeSub(_ a: Int64, _ b: Int64, line: Int) throws -> Int64 {
    let (r, ov) = a.subtractingReportingOverflow(b)
    if ov { throw TernError(line: line, message: "integer overflow") }
    return r
}

func safeMul(_ a: Int64, _ b: Int64, line: Int) throws -> Int64 {
    let (r, ov) = a.multipliedReportingOverflow(by: b)
    if ov { throw TernError(line: line, message: "integer overflow") }
    return r
}

func safeDiv(_ a: Int64, _ b: Int64, line: Int) throws -> Int64 {
    if b == 0 { throw TernError(line: line, message: "division by zero") }
    if a == Int64.min && b == -1 { throw TernError(line: line, message: "integer overflow") }
    return a / b
}

func safeMod(_ a: Int64, _ b: Int64, line: Int) throws -> Int64 {
    if b == 0 { throw TernError(line: line, message: "division by zero") }
    if b == -1 { return 0 }
    let q = a / b
    return a - q * b
}

func safeNeg(_ a: Int64, line: Int) throws -> Int64 {
    if a == Int64.min { throw TernError(line: line, message: "integer overflow") }
    return -a
}

final class Interpreter {
    let globalScope: Scope
    let builtinScope: Scope
    var output: String = ""

    init() {
        builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        setupBuiltins()
    }

    func setupBuiltins() {
        let interp = self

        builtinScope.define("print", .function(TernFunction(builtinName: "print", arity: -1) { args in
            var parts: [String] = []
            for a in args {
                var seen = Set<ObjectIdentifier>()
                parts.append(displayValue(a, quoted: false, seen: &seen))
            }
            interp.output += parts.joined(separator: " ") + "\n"
            return .nilVal
        }))

        builtinScope.define("str", .function(TernFunction(builtinName: "str", arity: 1) { args in
            var seen = Set<ObjectIdentifier>()
            return .string(displayValue(args[0], quoted: false, seen: &seen))
        }))

        builtinScope.define("type", .function(TernFunction(builtinName: "type", arity: 1) { args in
            return .string(typeName(args[0]))
        }))

        builtinScope.define("len", .function(TernFunction(builtinName: "len", arity: 1) { args in
            switch args[0] {
            case .string(let s): return .int(Int64(s.count))
            case .list(let l): return .int(Int64(l.elements.count))
            default: throw TernError(line: 0, message: "bad argument to len")
            }
        }))

        builtinScope.define("push", .function(TernFunction(builtinName: "push", arity: 2) { args in
            switch args[0] {
            case .list(let l): l.elements.append(args[1]); return .nilVal
            default: throw TernError(line: 0, message: "bad argument to push")
            }
        }))

        builtinScope.define("pop", .function(TernFunction(builtinName: "pop", arity: 1) { args in
            switch args[0] {
            case .list(let l):
                if l.elements.isEmpty { throw TernError(line: 0, message: "bad argument to pop") }
                return l.elements.removeLast()
            default: throw TernError(line: 0, message: "bad argument to pop")
            }
        }))

        builtinScope.define("range", .function(TernFunction(builtinName: "range", arity: 2) { args in
            guard case .int(let a) = args[0], case .int(let b) = args[1] else {
                throw TernError(line: 0, message: "bad argument to range")
            }
            if b <= a { return .list(TernList()) }
            var elems: [Value] = []
            elems.reserveCapacity(Int(b - a))
            var i = a
            while i < b { elems.append(.int(i)); i += 1 }
            return .list(TernList(elems))
        }))

        builtinScope.define("slice", .function(TernFunction(builtinName: "slice", arity: 3) { args in
            guard case .int(let a) = args[1], case .int(let b) = args[2] else {
                throw TernError(line: 0, message: "bad argument to slice")
            }
            switch args[0] {
            case .string(let s):
                let chars = Array(s)
                let ai = Int(a), bi = Int(b)
                if ai < 0 || bi > chars.count || ai > bi { throw TernError(line: 0, message: "bad argument to slice") }
                return .string(String(chars[ai..<bi]))
            case .list(let l):
                let ai = Int(a), bi = Int(b)
                if ai < 0 || bi > l.elements.count || ai > bi { throw TernError(line: 0, message: "bad argument to slice") }
                return .list(TernList(Array(l.elements[ai..<bi])))
            default: throw TernError(line: 0, message: "bad argument to slice")
            }
        }))
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execStmts(stmts, scope: globalScope)
        } catch let e as TernError {
            // output already has everything printed so far
            FileHandle.standardOutput.write(output.data(using: .utf8)!)
            output = ""
            FileHandle.standardOutput.write("error at line \(e.line): \(e.message)\n".data(using: .utf8)!)
        } catch {
            // shouldn't happen
            FileHandle.standardOutput.write(output.data(using: .utf8)!)
        }
        FileHandle.standardOutput.write(output.data(using: .utf8)!)
    }

    func execStmts(_ stmts: [Stmt], scope: Scope) throws {
        for s in stmts {
            try execStmt(s, scope: scope)
        }
    }

    func execStmt(_ stmt: Stmt, scope: Scope) throws {
        switch stmt {
        case .letStmt(let name, let val, _):
            let v = try evalExpr(val, scope: scope)
            scope.define(name, v)

        case .fnDecl(let name, let params, let body, _):
            let fn = TernFunction(params: params, body: body, capturedScope: scope)
            scope.define(name, .function(fn))

        case .ifStmt(let cond, let thenBlock, let elseBlock, _):
            let cv = try evalExpr(cond, scope: scope)
            if isTruthy(cv) {
                let s = Scope(parent: scope)
                try execStmts(thenBlock, scope: s)
            } else if let eb = elseBlock {
                let s = Scope(parent: scope)
                try execStmts(eb, scope: s)
            }

        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try evalExpr(cond, scope: scope)
                if !isTruthy(cv) { break }
                let s = Scope(parent: scope)
                do {
                    try execStmts(body, scope: s)
                } catch ControlFlow.breakSignal { break }
                catch ControlFlow.continueSignal { continue }
            }

        case .forStmt(let varName, let iterExpr, let body, let line):
            let iterVal = try evalExpr(iterExpr, scope: scope)
            guard case .list(let lst) = iterVal else {
                throw TernError(line: line, message: "cannot iterate \(typeName(iterVal))")
            }
            var i = 0
            while i < lst.elements.count {
                let s = Scope(parent: scope)
                s.define(varName, lst.elements[i])
                do {
                    try execStmts(body, scope: s)
                } catch ControlFlow.breakSignal { break }
                catch ControlFlow.continueSignal { i += 1; continue }
                i += 1
            }

        case .returnStmt(let valExpr, _):
            let v: Value
            if let ve = valExpr { v = try evalExpr(ve, scope: scope) }
            else { v = .nilVal }
            throw ControlFlow.returnSignal(v)

        case .breakStmt:
            throw ControlFlow.breakSignal

        case .continueStmt:
            throw ControlFlow.continueSignal

        case .assignStmt(let name, let valExpr, let line):
            let v = try evalExpr(valExpr, scope: scope)
            if !scope.set(name, v) {
                throw TernError(line: line, message: "undefined variable \(name)")
            }

        case .indexAssign(let objExpr, let idxExpr, let valExpr, let line):
            let obj = try evalExpr(objExpr, scope: scope)
            let idx = try evalExpr(idxExpr, scope: scope)
            let v = try evalExpr(valExpr, scope: scope)
            guard case .list(let lst) = obj else {
                throw TernError(line: line, message: "cannot assign into \(typeName(obj))")
            }
            guard case .int(let i) = idx else {
                throw TernError(line: line, message: "cannot index list with \(typeName(idx))")
            }
            let ii = Int(i)
            if ii < 0 || ii >= lst.elements.count {
                throw TernError(line: line, message: "index \(i) out of range for length \(lst.elements.count)")
            }
            lst.elements[ii] = v

        case .exprStmt(let expr, _):
            _ = try evalExpr(expr, scope: scope)
        }
    }

    func evalExpr(_ expr: Expr, scope: Scope) throws -> Value {
        switch expr {
        case .intLit(let v, _): return .int(v)
        case .strLit(let v, _): return .string(v)
        case .boolLit(let v, _): return .bool(v)
        case .nilLit: return .nilVal

        case .ident(let name, let line):
            if let v = scope.lookup(name) { return v }
            throw TernError(line: line, message: "undefined variable \(name)")

        case .binOp(let op, let left, let right, let line):
            switch op {
            case .or:
                let lv = try evalExpr(left, scope: scope)
                if isTruthy(lv) { return lv }
                return try evalExpr(right, scope: scope)
            case .and:
                let lv = try evalExpr(left, scope: scope)
                if !isTruthy(lv) { return lv }
                return try evalExpr(right, scope: scope)
            case .not:
                // not is handled in unOp, but just in case
                let lv = try evalExpr(left, scope: scope)
                return .bool(!isTruthy(lv))
            default:
                let lv = try evalExpr(left, scope: scope)
                let rv = try evalExpr(right, scope: scope)
                return try evalBinOp(op, lv, rv, line: line)
            }

        case .unOp(let op, let operand, let line):
            let v = try evalExpr(operand, scope: scope)
            switch op {
            case .neg:
                guard case .int(let n) = v else {
                    throw TernError(line: line, message: "cannot apply - to \(typeName(v))")
                }
                return .int(try safeNeg(n, line: line))
            case .not:
                return .bool(!isTruthy(v))
            }

        case .call(let calleeExpr, let argExprs, let line):
            let callee = try evalExpr(calleeExpr, scope: scope)
            var args: [Value] = []
            args.reserveCapacity(argExprs.count)
            for ae in argExprs {
                args.append(try evalExpr(ae, scope: scope))
            }
            guard case .function(let fn) = callee else {
                throw TernError(line: line, message: "cannot call \(typeName(callee))")
            }
            if fn.isBuiltin {
                if fn.builtinArity >= 0 && args.count != fn.builtinArity {
                    throw TernError(line: line, message: "expected \(fn.builtinArity) arguments, got \(args.count)")
                }
                do {
                    return try fn.builtinFn!(args)
                } catch let e as TernError {
                    throw TernError(line: line, message: e.message)
                }
            } else {
                if args.count != fn.params.count {
                    throw TernError(line: line, message: "expected \(fn.params.count) arguments, got \(args.count)")
                }
                let callScope = Scope(parent: fn.capturedScope)
                for (i, p) in fn.params.enumerated() {
                    callScope.define(p, args[i])
                }
                do {
                    try execStmts(fn.body, scope: callScope)
                } catch ControlFlow.returnSignal(let v) {
                    return v
                }
                return .nilVal
            }

        case .index(let objExpr, let idxExpr, let line):
            let obj = try evalExpr(objExpr, scope: scope)
            let idx = try evalExpr(idxExpr, scope: scope)
            switch obj {
            case .list(let lst):
                guard case .int(let i) = idx else {
                    throw TernError(line: line, message: "cannot index list with \(typeName(idx))")
                }
                let ii = Int(i)
                if ii < 0 || ii >= lst.elements.count {
                    throw TernError(line: line, message: "index \(i) out of range for length \(lst.elements.count)")
                }
                return lst.elements[ii]
            case .string(let s):
                guard case .int(let i) = idx else {
                    throw TernError(line: line, message: "cannot index string with \(typeName(idx))")
                }
                let chars = Array(s)
                let ii = Int(i)
                if ii < 0 || ii >= chars.count {
                    throw TernError(line: line, message: "index \(i) out of range for length \(chars.count)")
                }
                return .string(String(chars[ii]))
            default:
                throw TernError(line: line, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
            }

        case .listLit(let elems, _):
            var vals: [Value] = []
            vals.reserveCapacity(elems.count)
            for e in elems {
                vals.append(try evalExpr(e, scope: scope))
            }
            return .list(TernList(vals))

        case .fnExpr(let params, let body, _):
            return .function(TernFunction(params: params, body: body, capturedScope: scope))
        }
    }

    func evalBinOp(_ op: BinOp, _ lv: Value, _ rv: Value, line: Int) throws -> Value {
        switch op {
        case .add:
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .int(try safeAdd(a, b, line: line))
            case (.string(let a), .string(let b)): return .string(a + b)
            case (.list(let a), .list(let b)): return .list(TernList(a.elements + b.elements))
            default: throw TernError(line: line, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
            }
        case .sub:
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError(line: line, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
            }
            return .int(try safeSub(a, b, line: line))
        case .mul:
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError(line: line, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
            }
            return .int(try safeMul(a, b, line: line))
        case .div:
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError(line: line, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
            }
            return .int(try safeDiv(a, b, line: line))
        case .mod:
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError(line: line, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
            }
            return .int(try safeMod(a, b, line: line))
        case .eq:
            return .bool(valuesEqual(lv, rv))
        case .neq:
            return .bool(!valuesEqual(lv, rv))
        case .lt:
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a < b)
            case (.string(let a), .string(let b)): return .bool(a < b)
            default: throw TernError(line: line, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
            }
        case .le:
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a <= b)
            case (.string(let a), .string(let b)): return .bool(a <= b)
            default: throw TernError(line: line, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
            }
        case .gt:
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a > b)
            case (.string(let a), .string(let b)): return .bool(a > b)
            default: throw TernError(line: line, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
            }
        case .ge:
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a >= b)
            case (.string(let a), .string(let b)): return .bool(a >= b)
            default: throw TernError(line: line, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
            }
        case .or, .and:
            // Should not reach here
            fatalError("or/and handled separately")
        }
    }
}

// MARK: - Main

let args = CommandLine.arguments
if args.count < 2 {
    fatalError("Usage: \(args[0]) <directory>")
}
let dir = args[1]
let filePath = dir + "/program.tern"
let content = try! String(contentsOfFile: filePath, encoding: .ascii)
let tokens = tokenize(content)
let parser = Parser(tokens)
let program = parser.parseProgram()
let interp = Interpreter()
interp.run(program)

import * as fs from 'fs';
import * as path from 'path';

// ===== LEXER =====

interface Token {
  type: string;
  value: any;
  line: number;
}

const KEYWORDS = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);

function lex(source: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;
  let line = 1;
  while (pos < source.length) {
    if (source[pos] === '\n') { line++; pos++; continue; }
    if (source[pos] === ' ' || source[pos] === '\t' || source[pos] === '\r') { pos++; continue; }
    if (source[pos] === '#') { while (pos < source.length && source[pos] !== '\n') pos++; continue; }
    if (source[pos] >= '0' && source[pos] <= '9') {
      let num = '';
      while (pos < source.length && source[pos] >= '0' && source[pos] <= '9') num += source[pos++];
      tokens.push({ type: 'INT', value: BigInt(num), line });
      continue;
    }
    if (source[pos] === '"') {
      pos++;
      let s = '';
      while (pos < source.length && source[pos] !== '"') {
        if (source[pos] === '\\') {
          pos++;
          if (source[pos] === 'n') s += '\n';
          else if (source[pos] === 't') s += '\t';
          else if (source[pos] === '"') s += '"';
          else if (source[pos] === '\\') s += '\\';
          else s += source[pos];
          pos++;
        } else s += source[pos++];
      }
      pos++;
      tokens.push({ type: 'STRING', value: s, line });
      continue;
    }
    if (/[A-Za-z_]/.test(source[pos])) {
      let id = '';
      while (pos < source.length && /[A-Za-z0-9_]/.test(source[pos])) id += source[pos++];
      if (KEYWORDS.has(id)) tokens.push({ type: id.toUpperCase(), value: id, line });
      else tokens.push({ type: 'IDENT', value: id, line });
      continue;
    }
    if (pos + 1 < source.length) {
      const two = source[pos] + source[pos + 1];
      if (two === '==' || two === '!=' || two === '<=' || two === '>=') {
        tokens.push({ type: two, value: two, line });
        pos += 2;
        continue;
      }
    }
    const ch = source[pos];
    if ('+-*/%()[]{},;<>='.includes(ch)) {
      tokens.push({ type: ch, value: ch, line });
      pos++;
      continue;
    }
    pos++;
  }
  return tokens;
}

// ===== AST =====

type Expr =
  | { kind: 'IntLit'; value: bigint; line: number }
  | { kind: 'StringLit'; value: string; line: number }
  | { kind: 'BoolLit'; value: boolean; line: number }
  | { kind: 'NilLit'; line: number }
  | { kind: 'Ident'; name: string; line: number }
  | { kind: 'BinaryOp'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'UnaryMinus'; operand: Expr; line: number }
  | { kind: 'Not'; operand: Expr; line: number }
  | { kind: 'And'; left: Expr; right: Expr; line: number }
  | { kind: 'Or'; left: Expr; right: Expr; line: number }
  | { kind: 'Call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'Index'; obj: Expr; index: Expr; line: number }
  | { kind: 'ListLit'; elements: Expr[]; line: number }
  | { kind: 'FnExpr'; params: string[]; body: Stmt[]; line: number };

type Stmt =
  | { kind: 'LetStmt'; name: string; value: Expr; line: number }
  | { kind: 'FnStmt'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'IfStmt'; cond: Expr; thenBody: Stmt[]; elseBody: Stmt[] | IfStmt | null; line: number }
  | { kind: 'WhileStmt'; cond: Expr; body: Stmt[]; line: number }
  | { kind: 'ForStmt'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'ReturnStmt'; value: Expr | null; line: number }
  | { kind: 'BreakStmt'; line: number }
  | { kind: 'ContinueStmt'; line: number }
  | { kind: 'AssignStmt'; name: string; value: Expr; line: number }
  | { kind: 'IndexAssignStmt'; obj: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'ExprStmt'; expr: Expr; line: number };

// ===== PARSER =====

class Parser {
  tokens: Token[];
  pos: number;
  constructor(tokens: Token[]) { this.tokens = tokens; this.pos = 0; }
  peek(): Token | null { return this.pos < this.tokens.length ? this.tokens[this.pos] : null; }
  peekAt(n: number): Token | null { return this.pos + n < this.tokens.length ? this.tokens[this.pos + n] : null; }
  advance(): Token { return this.tokens[this.pos++]; }
  expect(type: string): Token {
    const t = this.advance();
    if (!t || t.type !== type) throw new Error(`Expected ${type} got ${t?.type} at line ${t?.line}`);
    return t;
  }
  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek()) stmts.push(this.parseStmt());
    return stmts;
  }
  parseBlock(): Stmt[] {
    this.expect('{');
    const stmts: Stmt[] = [];
    while (this.peek() && this.peek()!.type !== '}') stmts.push(this.parseStmt());
    this.expect('}');
    return stmts;
  }
  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek() && this.peek()!.type === 'IDENT') {
      params.push(this.advance().value);
      while (this.peek() && this.peek()!.type === ',') { this.advance(); params.push(this.expect('IDENT').value); }
    }
    return params;
  }
  parseStmt(): Stmt {
    const tok = this.peek()!;
    switch (tok.type) {
      case 'LET': return this.parseLetStmt();
      case 'FN':
        if (this.peekAt(1) && this.peekAt(1)!.type === 'IDENT') return this.parseFnStmt();
        return this.parseExprOrAssignStmt();
      case 'IF': return this.parseIfStmt();
      case 'WHILE': return this.parseWhileStmt();
      case 'FOR': return this.parseForStmt();
      case 'RETURN': return this.parseReturnStmt();
      case 'BREAK': { this.advance(); this.expect(';'); return { kind: 'BreakStmt', line: tok.line }; }
      case 'CONTINUE': { this.advance(); this.expect(';'); return { kind: 'ContinueStmt', line: tok.line }; }
      default: return this.parseExprOrAssignStmt();
    }
  }
  parseLetStmt(): Stmt {
    const tok = this.advance();
    const name = this.expect('IDENT').value;
    this.expect('=');
    const value = this.parseExpr();
    this.expect(';');
    return { kind: 'LetStmt', name, value, line: tok.line };
  }
  parseFnStmt(): Stmt {
    const tok = this.advance();
    const name = this.expect('IDENT').value;
    this.expect('(');
    const params = this.parseParams();
    this.expect(')');
    const body = this.parseBlock();
    return { kind: 'FnStmt', name, params, body, line: tok.line };
  }
  parseIfStmt(): IfStmt {
    const tok = this.advance();
    const cond = this.parseExpr();
    const thenBody = this.parseBlock();
    let elseBody: Stmt[] | IfStmt | null = null;
    if (this.peek() && this.peek()!.type === 'ELSE') {
      this.advance();
      if (this.peek() && this.peek()!.type === 'IF') elseBody = this.parseIfStmt();
      else elseBody = this.parseBlock();
    }
    return { kind: 'IfStmt', cond, thenBody, elseBody, line: tok.line };
  }
  parseWhileStmt(): Stmt {
    const tok = this.advance();
    const cond = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'WhileStmt', cond, body, line: tok.line };
  }
  parseForStmt(): Stmt {
    const tok = this.advance();
    const varName = this.expect('IDENT').value;
    this.expect('IN');
    const iterable = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'ForStmt', varName, iterable, body, line: tok.line };
  }
  parseReturnStmt(): Stmt {
    const tok = this.advance();
    if (this.peek() && this.peek()!.type === ';') { this.advance(); return { kind: 'ReturnStmt', value: null, line: tok.line }; }
    const value = this.parseExpr();
    this.expect(';');
    return { kind: 'ReturnStmt', value, line: tok.line };
  }
  parseExprOrAssignStmt(): Stmt {
    const expr = this.parseExpr();
    const tok = this.peek()!;
    if (tok.type === '=') {
      this.advance();
      const value = this.parseExpr();
      this.expect(';');
      if (expr.kind === 'Ident') return { kind: 'AssignStmt', name: expr.name, value, line: expr.line };
      if (expr.kind === 'Index') return { kind: 'IndexAssignStmt', obj: expr.obj, index: expr.index, value, line: expr.line };
      throw new Error('Invalid assignment target');
    }
    this.expect(';');
    return { kind: 'ExprStmt', expr, line: expr.line };
  }
  parseExpr(): Expr { return this.parseOr(); }
  parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek() && this.peek()!.type === 'OR') {
      this.advance();
      const right = this.parseAnd();
      left = { kind: 'Or', left, right, line: left.line };
    }
    return left;
  }
  parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek() && this.peek()!.type === 'AND') {
      this.advance();
      const right = this.parseNot();
      left = { kind: 'And', left, right, line: left.line };
    }
    return left;
  }
  parseNot(): Expr {
    if (this.peek() && this.peek()!.type === 'NOT') {
      const tok = this.advance();
      const operand = this.parseNot();
      return { kind: 'Not', operand, line: tok.line };
    }
    return this.parseComparison();
  }
  parseComparison(): Expr {
    let left = this.parseAddSub();
    while (this.peek() && ['==', '!=', '<', '<=', '>', '>='].includes(this.peek()!.type)) {
      const op = this.advance();
      const right = this.parseAddSub();
      left = { kind: 'BinaryOp', op: op.value, left, right, line: op.line };
    }
    return left;
  }
  parseAddSub(): Expr {
    let left = this.parseMulDiv();
    while (this.peek() && (this.peek()!.type === '+' || this.peek()!.type === '-')) {
      const op = this.advance();
      const right = this.parseMulDiv();
      left = { kind: 'BinaryOp', op: op.value, left, right, line: op.line };
    }
    return left;
  }
  parseMulDiv(): Expr {
    let left = this.parseUnaryMinus();
    while (this.peek() && (this.peek()!.type === '*' || this.peek()!.type === '/' || this.peek()!.type === '%')) {
      const op = this.advance();
      const right = this.parseUnaryMinus();
      left = { kind: 'BinaryOp', op: op.value, left, right, line: op.line };
    }
    return left;
  }
  parseUnaryMinus(): Expr {
    if (this.peek() && this.peek()!.type === '-') {
      const tok = this.advance();
      const operand = this.parseUnaryMinus();
      return { kind: 'UnaryMinus', operand, line: tok.line };
    }
    return this.parsePostfix();
  }
  parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.peek() && this.peek()!.type === '(') {
        const tok = this.advance();
        const args: Expr[] = [];
        if (this.peek() && this.peek()!.type !== ')') {
          args.push(this.parseExpr());
          while (this.peek() && this.peek()!.type === ',') { this.advance(); args.push(this.parseExpr()); }
        }
        this.expect(')');
        expr = { kind: 'Call', callee: expr, args, line: tok.line };
      } else if (this.peek() && this.peek()!.type === '[') {
        const tok = this.advance();
        const index = this.parseExpr();
        this.expect(']');
        expr = { kind: 'Index', obj: expr, index, line: tok.line };
      } else break;
    }
    return expr;
  }
  parsePrimary(): Expr {
    const tok = this.peek()!;
    if (tok.type === 'INT') { this.advance(); return { kind: 'IntLit', value: tok.value, line: tok.line }; }
    if (tok.type === 'STRING') { this.advance(); return { kind: 'StringLit', value: tok.value, line: tok.line }; }
    if (tok.type === 'TRUE') { this.advance(); return { kind: 'BoolLit', value: true, line: tok.line }; }
    if (tok.type === 'FALSE') { this.advance(); return { kind: 'BoolLit', value: false, line: tok.line }; }
    if (tok.type === 'NIL') { this.advance(); return { kind: 'NilLit', line: tok.line }; }
    if (tok.type === 'IDENT') { this.advance(); return { kind: 'Ident', name: tok.value, line: tok.line }; }
    if (tok.type === '(') { this.advance(); const e = this.parseExpr(); this.expect(')'); return e; }
    if (tok.type === '[') {
      this.advance();
      const elements: Expr[] = [];
      if (this.peek() && this.peek()!.type !== ']') {
        elements.push(this.parseExpr());
        while (this.peek() && this.peek()!.type === ',') { this.advance(); elements.push(this.parseExpr()); }
      }
      this.expect(']');
      return { kind: 'ListLit', elements, line: tok.line };
    }
    if (tok.type === 'FN') {
      this.advance();
      this.expect('(');
      const params = this.parseParams();
      this.expect(')');
      const body = this.parseBlock();
      return { kind: 'FnExpr', params, body, line: tok.line };
    }
    throw new Error(`Unexpected token ${tok.type} at line ${tok.line}`);
  }
}

// ===== INTERPRETER =====

const INT_MIN = -(2n ** 63n);
const INT_MAX = 2n ** 63n - 1n;

interface UserFunction {
  kind: 'user';
  params: string[];
  body: Stmt[];
  closure: Scope;
}
interface BuiltinFunction {
  kind: 'builtin';
  name: string;
  arity: number | null;
  fn: (args: Value[], line: number) => Value;
}
type FunctionValue = UserFunction | BuiltinFunction;
type Value = bigint | boolean | string | Value[] | FunctionValue | null;

class Scope {
  parent: Scope | null;
  vars: Map<string, Value>;
  constructor(parent: Scope | null) { this.parent = parent; this.vars = new Map(); }
  lookup(name: string): { value: Value } | null {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) return { value: s.vars.get(name)! }; s = s.parent; }
    return null;
  }
  declare(name: string, value: Value) { this.vars.set(name, value); }
  assign(name: string, value: Value): boolean {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) { s.vars.set(name, value); return true; } s = s.parent; }
    return false;
  }
}

class TernError {
  line: number;
  message: string;
  constructor(line: number, message: string) { this.line = line; this.message = message; }
}
class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { value: Value; constructor(v: Value) { this.value = v; } }

function typeName(v: Value): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'string') return 'string';
  if (Array.isArray(v)) return 'list';
  return 'function';
}

function isTruthy(v: Value): boolean {
  if (v === null) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'string') return v !== '';
  if (Array.isArray(v)) return v.length > 0;
  return true; // functions are truthy
}

function escapeStr(s: string): string {
  let r = '';
  for (const ch of s) {
    if (ch === '\\') r += '\\\\';
    else if (ch === '"') r += '\\"';
    else if (ch === '\n') r += '\\n';
    else if (ch === '\t') r += '\\t';
    else r += ch;
  }
  return r;
}

function display(v: Value, inList: boolean, seen: Set<Value[]>): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'string') return inList ? '"' + escapeStr(v) + '"' : v;
  if (Array.isArray(v)) {
    if (seen.has(v)) return '[...]';
    seen.add(v);
    const parts: string[] = [];
    for (const el of v) parts.push(display(el, true, seen));
    seen.delete(v);
    return '[' + parts.join(', ') + ']';
  }
  return '<fn>';
}

function valuesEqual(a: Value, b: Value): boolean {
  if (a === null && b === null) return true;
  if (a === null || b === null) return false;
  if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
  if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
  if (typeof a === 'string' && typeof b === 'string') return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!valuesEqual(a[i], b[i])) return false;
    return true;
  }
  if (typeof a === 'object' && typeof b === 'object') return a === b;
  return false;
}

function checkInt(v: bigint, line: number): bigint {
  if (v < INT_MIN || v > INT_MAX) throw new TernError(line, 'integer overflow');
  return v;
}

class Interpreter {
  output: string[] = [];

  run(program: Stmt[]) {
    const builtinsScope = new Scope(null);
    this.registerBuiltins(builtinsScope);
    const globalScope = new Scope(builtinsScope);
    this.execBlock(program, globalScope);
  }

  registerBuiltins(scope: Scope) {
    scope.declare('print', {
      kind: 'builtin', name: 'print', arity: null,
      fn: (args, line) => {
        const parts: string[] = [];
        for (const a of args) parts.push(display(a, false, new Set()));
        this.output.push(parts.join(' ') + '\n');
        return null;
      }
    } as BuiltinFunction);
    scope.declare('str', {
      kind: 'builtin', name: 'str', arity: 1,
      fn: (args, line) => display(args[0], false, new Set())
    } as BuiltinFunction);
    scope.declare('type', {
      kind: 'builtin', name: 'type', arity: 1,
      fn: (args, line) => typeName(args[0])
    } as BuiltinFunction);
    scope.declare('len', {
      kind: 'builtin', name: 'len', arity: 1,
      fn: (args, line) => {
        const v = args[0];
        if (typeof v === 'string') return BigInt(v.length);
        if (Array.isArray(v)) return BigInt(v.length);
        throw new TernError(line, 'bad argument to len');
      }
    } as BuiltinFunction);
    scope.declare('push', {
      kind: 'builtin', name: 'push', arity: 2,
      fn: (args, line) => {
        if (!Array.isArray(args[0])) throw new TernError(line, 'bad argument to push');
        (args[0] as Value[]).push(args[1]);
        return null;
      }
    } as BuiltinFunction);
    scope.declare('pop', {
      kind: 'builtin', name: 'pop', arity: 1,
      fn: (args, line) => {
        if (!Array.isArray(args[0]) || (args[0] as Value[]).length === 0) throw new TernError(line, 'bad argument to pop');
        return (args[0] as Value[]).pop()!;
      }
    } as BuiltinFunction);
    scope.declare('range', {
      kind: 'builtin', name: 'range', arity: 2,
      fn: (args, line) => {
        if (typeof args[0] !== 'bigint' || typeof args[1] !== 'bigint') throw new TernError(line, 'bad argument to range');
        const a = args[0] as bigint, b = args[1] as bigint;
        const result: Value[] = [];
        for (let i = a; i < b; i++) result.push(i);
        return result;
      }
    } as BuiltinFunction);
    scope.declare('slice', {
      kind: 'builtin', name: 'slice', arity: 3,
      fn: (args, line) => {
        const [x, a, b] = args;
        if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new TernError(line, 'bad argument to slice');
        if (typeof x === 'string') {
          const ai = Number(a), bi = Number(b);
          if (ai < 0 || bi > x.length || ai > bi) throw new TernError(line, 'bad argument to slice');
          return x.slice(ai, bi);
        }
        if (Array.isArray(x)) {
          const ai = Number(a), bi = Number(b);
          if (ai < 0 || bi > x.length || ai > bi) throw new TernError(line, 'bad argument to slice');
          return (x as Value[]).slice(ai, bi);
        }
        throw new TernError(line, 'bad argument to slice');
      }
    } as BuiltinFunction);
  }

  execBlock(stmts: Stmt[], scope: Scope) {
    for (const s of stmts) this.execStmt(s, scope);
  }

  execStmt(s: Stmt, scope: Scope) {
    switch (s.kind) {
      case 'LetStmt': {
        const val = this.eval(s.value, scope);
        scope.declare(s.name, val);
        break;
      }
      case 'FnStmt': {
        const fn: UserFunction = { kind: 'user', params: s.params, body: s.body, closure: scope };
        scope.declare(s.name, fn);
        break;
      }
      case 'IfStmt': {
        const cond = this.eval(s.cond, scope);
        if (isTruthy(cond)) {
          this.execBlock(s.thenBody, new Scope(scope));
        } else if (s.elseBody !== null) {
          if (Array.isArray(s.elseBody)) {
            this.execBlock(s.elseBody, new Scope(scope));
          } else {
            this.execStmt(s.elseBody, scope);
          }
        }
        break;
      }
      case 'WhileStmt': {
        while (true) {
          const cond = this.eval(s.cond, scope);
          if (!isTruthy(cond)) break;
          try {
            this.execBlock(s.body, new Scope(scope));
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) continue;
            throw e;
          }
        }
        break;
      }
      case 'ForStmt': {
        const iterable = this.eval(s.iterable, scope);
        if (!Array.isArray(iterable)) throw new TernError(s.line, `cannot iterate ${typeName(iterable)}`);
        const list = iterable as Value[];
        let i = 0;
        while (i < list.length) {
          const iterScope = new Scope(scope);
          iterScope.declare(s.varName, list[i]);
          try {
            this.execBlock(s.body, iterScope);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { i++; continue; }
            throw e;
          }
          i++;
        }
        break;
      }
      case 'ReturnStmt': {
        const val = s.value ? this.eval(s.value, scope) : null;
        throw new ReturnSignal(val);
      }
      case 'BreakStmt': throw new BreakSignal();
      case 'ContinueStmt': throw new ContinueSignal();
      case 'AssignStmt': {
        const val = this.eval(s.value, scope);
        if (!scope.assign(s.name, val)) throw new TernError(s.line, `undefined variable ${s.name}`);
        break;
      }
      case 'IndexAssignStmt': {
        const obj = this.eval(s.obj, scope);
        const idx = this.eval(s.index, scope);
        const val = this.eval(s.value, scope);
        if (!Array.isArray(obj)) throw new TernError(s.line, `cannot assign into ${typeName(obj)}`);
        if (typeof idx !== 'bigint') throw new TernError(s.line, `cannot index list with ${typeName(idx)}`);
        const i = Number(idx);
        const list = obj as Value[];
        if (i < 0 || i >= list.length) throw new TernError(s.line, `index ${idx} out of range for length ${list.length}`);
        list[i] = val;
        break;
      }
      case 'ExprStmt': {
        this.eval(s.expr, scope);
        break;
      }
    }
  }

  eval(e: Expr, scope: Scope): Value {
    switch (e.kind) {
      case 'IntLit': return e.value;
      case 'StringLit': return e.value;
      case 'BoolLit': return e.value;
      case 'NilLit': return null;
      case 'Ident': {
        const found = scope.lookup(e.name);
        if (!found) throw new TernError(e.line, `undefined variable ${e.name}`);
        return found.value;
      }
      case 'BinaryOp': return this.evalBinary(e, scope);
      case 'UnaryMinus': {
        const v = this.eval(e.operand, scope);
        if (typeof v !== 'bigint') throw new TernError(e.line, `cannot apply - to ${typeName(v)}`);
        return checkInt(-v, e.line);
      }
      case 'Not': {
        const v = this.eval(e.operand, scope);
        return !isTruthy(v);
      }
      case 'And': {
        const l = this.eval(e.left, scope);
        if (!isTruthy(l)) return l;
        return this.eval(e.right, scope);
      }
      case 'Or': {
        const l = this.eval(e.left, scope);
        if (isTruthy(l)) return l;
        return this.eval(e.right, scope);
      }
      case 'Call': return this.evalCall(e, scope);
      case 'Index': return this.evalIndex(e, scope);
      case 'ListLit': {
        const elems: Value[] = [];
        for (const el of e.elements) elems.push(this.eval(el, scope));
        return elems;
      }
      case 'FnExpr': {
        return { kind: 'user', params: e.params, body: e.body, closure: scope } as UserFunction;
      }
    }
  }

  evalBinary(e: Extract<Expr, { kind: 'BinaryOp' }>, scope: Scope): Value {
    const left = this.eval(e.left, scope);
    const right = this.eval(e.right, scope);
    const op = e.op;
    if (op === '==' ) return valuesEqual(left, right);
    if (op === '!=') return !valuesEqual(left, right);
    if (op === '<' || op === '<=' || op === '>' || op === '>=') {
      if (typeof left === 'bigint' && typeof right === 'bigint') {
        if (op === '<') return left < right;
        if (op === '<=') return left <= right;
        if (op === '>') return left > right;
        return left >= right;
      }
      if (typeof left === 'string' && typeof right === 'string') {
        if (op === '<') return left < right;
        if (op === '<=') return left <= right;
        if (op === '>') return left > right;
        return left >= right;
      }
      throw new TernError(e.line, `cannot apply ${op} to ${typeName(left)} and ${typeName(right)}`);
    }
    if (op === '+') {
      if (typeof left === 'bigint' && typeof right === 'bigint') return checkInt(left + right, e.line);
      if (typeof left === 'string' && typeof right === 'string') return left + right;
      if (Array.isArray(left) && Array.isArray(right)) return [...(left as Value[]), ...(right as Value[])];
      throw new TernError(e.line, `cannot apply + to ${typeName(left)} and ${typeName(right)}`);
    }
    if (op === '-' || op === '*' || op === '/' || op === '%') {
      if (typeof left !== 'bigint' || typeof right !== 'bigint') {
        throw new TernError(e.line, `cannot apply ${op} to ${typeName(left)} and ${typeName(right)}`);
      }
      if (op === '-') return checkInt(left - right, e.line);
      if (op === '*') return checkInt(left * right, e.line);
      if (right === 0n) throw new TernError(e.line, 'division by zero');
      if (op === '/') {
        const r = left / right;
        return checkInt(r, e.line);
      }
      // %
      const r = left % right;
      return checkInt(r, e.line);
    }
    throw new TernError(e.line, `cannot apply ${op} to ${typeName(left)} and ${typeName(right)}`);
  }

  evalCall(e: Extract<Expr, { kind: 'Call' }>, scope: Scope): Value {
    const callee = this.eval(e.callee, scope);
    const args: Value[] = [];
    for (const a of e.args) args.push(this.eval(a, scope));
    if (typeof callee !== 'object' || callee === null || !('kind' in callee)) {
      throw new TernError(e.line, `cannot call ${typeName(callee)}`);
    }
    const fn = callee as FunctionValue;
    if (fn.kind === 'builtin') {
      if (fn.arity !== null && args.length !== fn.arity) {
        throw new TernError(e.line, `expected ${fn.arity} arguments, got ${args.length}`);
      }
      return fn.fn(args, e.line);
    }
    // user function
    if (args.length !== fn.params.length) {
      throw new TernError(e.line, `expected ${fn.params.length} arguments, got ${args.length}`);
    }
    const callScope = new Scope(fn.closure);
    for (let i = 0; i < fn.params.length; i++) {
      callScope.declare(fn.params[i], args[i]);
    }
    try {
      this.execBlock(fn.body, callScope);
    } catch (r) {
      if (r instanceof ReturnSignal) return r.value;
      throw r;
    }
    return null;
  }

  evalIndex(e: Extract<Expr, { kind: 'Index' }>, scope: Scope): Value {
    const obj = this.eval(e.obj, scope);
    const idx = this.eval(e.index, scope);
    if (Array.isArray(obj)) {
      if (typeof idx !== 'bigint') throw new TernError(e.line, `cannot index ${typeName(obj)} with ${typeName(idx)}`);
      const i = Number(idx);
      if (i < 0 || i >= (obj as Value[]).length) throw new TernError(e.line, `index ${idx} out of range for length ${(obj as Value[]).length}`);
      return (obj as Value[])[i];
    }
    if (typeof obj === 'string') {
      if (typeof idx !== 'bigint') throw new TernError(e.line, `cannot index ${typeName(obj)} with ${typeName(idx)}`);
      const i = Number(idx);
      if (i < 0 || i >= obj.length) throw new TernError(e.line, `index ${idx} out of range for length ${obj.length}`);
      return obj[i];
    }
    throw new TernError(e.line, `cannot index ${typeName(obj)} with ${typeName(idx)}`);
  }
}

// ===== MAIN =====

const dir = process.argv[2];
if (!dir) { process.exit(1); }
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = lex(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();
const interp = new Interpreter();

try {
  interp.run(program);
} catch (e) {
  if (e instanceof TernError) {
    interp.output.push(`error at line ${e.line}: ${e.message}\n`);
  } else {
    throw e;
  }
}

process.stdout.write(interp.output.join(''));
process.exit(0);

use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;
use std::io::Write;

// ===== Token =====
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Int(i64), Str(String), Ident(String),
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Neq, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace,
    Comma, Semicolon, EOF,
}

#[derive(Clone)]
struct Token { kind: Tok, line: usize }

// ===== Lexer =====
fn lex(src: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let bytes = src.as_bytes();
    let mut i = 0usize;
    let mut line = 1usize;
    while i < bytes.len() {
        if bytes[i] == b'\n' { line += 1; i += 1; continue; }
        if bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\r' { i += 1; continue; }
        if bytes[i] == b'#' { while i < bytes.len() && bytes[i] != b'\n' { i += 1; } continue; }
        let sl = line;
        if bytes[i].is_ascii_digit() {
            let mut val: i64 = 0;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                val = val * 10 + (bytes[i] - b'0') as i64; i += 1;
            }
            tokens.push(Token { kind: Tok::Int(val), line: sl }); continue;
        }
        if bytes[i] == b'"' {
            i += 1; let mut s = String::new();
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' { i += 1; match bytes[i] {
                    b'n' => s.push('\n'), b't' => s.push('\t'),
                    b'"' => s.push('"'), b'\\' => s.push('\\'),
                    _ => s.push(bytes[i] as char),
                }} else { s.push(bytes[i] as char); }
                i += 1;
            }
            i += 1;
            tokens.push(Token { kind: Tok::Str(s), line: sl }); continue;
        }
        if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            let st = i;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') { i += 1; }
            let w = &src[st..i];
            let kind = match w {
                "let"=>Tok::Let,"fn"=>Tok::Fn,"if"=>Tok::If,"else"=>Tok::Else,
                "while"=>Tok::While,"for"=>Tok::For,"in"=>Tok::In,"return"=>Tok::Return,
                "break"=>Tok::Break,"continue"=>Tok::Continue,"and"=>Tok::And,"or"=>Tok::Or,
                "not"=>Tok::Not,"true"=>Tok::True,"false"=>Tok::False,"nil"=>Tok::Nil,
                _ => Tok::Ident(w.to_string()),
            };
            tokens.push(Token { kind, line: sl }); continue;
        }
        let kind = match bytes[i] {
            b'=' if i+1<bytes.len()&&bytes[i+1]==b'=' => { i+=1; Tok::Eq }
            b'!' if i+1<bytes.len()&&bytes[i+1]==b'=' => { i+=1; Tok::Neq }
            b'<' if i+1<bytes.len()&&bytes[i+1]==b'=' => { i+=1; Tok::Le }
            b'>' if i+1<bytes.len()&&bytes[i+1]==b'=' => { i+=1; Tok::Ge }
            b'<' => Tok::Lt, b'>' => Tok::Gt, b'=' => Tok::Assign,
            b'+' => Tok::Plus, b'-' => Tok::Minus, b'*' => Tok::Star,
            b'/' => Tok::Slash, b'%' => Tok::Percent,
            b'(' => Tok::LParen, b')' => Tok::RParen,
            b'[' => Tok::LBracket, b']' => Tok::RBracket,
            b'{' => Tok::LBrace, b'}' => Tok::RBrace,
            b',' => Tok::Comma, b';' => Tok::Semicolon,
            _ => unreachable!(),
        };
        i += 1;
        tokens.push(Token { kind, line: sl });
    }
    tokens.push(Token { kind: Tok::EOF, line });
    tokens
}

// ===== AST =====
#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64), StrLit(String), BoolLit(bool), NilLit,
    Ident(String, usize),
    UnaryNot(Box<Expr>), UnaryNeg(Box<Expr>, usize),
    BinOp(String, Box<Expr>, Box<Expr>, usize),
    And(Box<Expr>, Box<Expr>), Or(Box<Expr>, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>),
    FnLit(Vec<String>, Vec<Stmt>),
}

#[derive(Debug, Clone)]
enum Stmt {
    Let(String, Expr),
    FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<ElsePart>),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>, usize),
    Return(Option<Expr>),
    Break, Continue,
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr),
}

#[derive(Debug, Clone)]
enum ElsePart { Block(Vec<Stmt>), If(Box<Stmt>) }

// ===== Parser =====
struct Parser { tokens: Vec<Token>, pos: usize }

impl Parser {
    fn new(tokens: Vec<Token>) -> Self { Parser { tokens, pos: 0 } }
    fn peek(&self) -> &Tok { &self.tokens[self.pos].kind }
    fn peek_line(&self) -> usize { self.tokens[self.pos].line }
    fn peek2(&self) -> &Tok { if self.pos+1 < self.tokens.len() { &self.tokens[self.pos+1].kind } else { &Tok::EOF } }
    fn advance(&mut self) -> &Token { let t = &self.tokens[self.pos]; self.pos += 1; t }
    fn expect(&mut self, k: &Tok) { assert_eq!(&self.tokens[self.pos].kind, k, "expected {:?} got {:?}", k, self.tokens[self.pos].kind); self.pos += 1; }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while *self.peek() != Tok::EOF { stmts.push(self.parse_stmt()); }
        stmts
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(&Tok::LBrace);
        let mut stmts = Vec::new();
        while *self.peek() != Tok::RBrace { stmts.push(self.parse_stmt()); }
        self.expect(&Tok::RBrace);
        stmts
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut params = Vec::new();
        if *self.peek() != Tok::RParen {
            loop {
                if let Tok::Ident(s) = self.peek().clone() { params.push(s); self.pos += 1; } else { break; }
                if *self.peek() == Tok::Comma { self.pos += 1; } else { break; }
            }
        }
        params
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().clone() {
            Tok::Let => { self.pos+=1; let name = if let Tok::Ident(s)=self.peek().clone(){s}else{unreachable!()}; self.pos+=1; self.expect(&Tok::Assign); let e = self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::Let(name, e) }
            Tok::Fn if *self.peek2() == &Tok::Ident(String::new()) || matches!(self.peek2(), Tok::Ident(_)) => {
                self.pos+=1; let name = if let Tok::Ident(s)=self.peek().clone(){s}else{unreachable!()}; self.pos+=1;
                self.expect(&Tok::LParen); let params = self.parse_params(); self.expect(&Tok::RParen);
                let body = self.parse_block(); Stmt::FnDecl(name, params, body)
            }
            Tok::If => self.parse_if(),
            Tok::While => { self.pos+=1; let c = self.parse_expr(); let b = self.parse_block(); Stmt::While(c, b) }
            Tok::For => { let fl = self.peek_line(); self.pos+=1; let var = if let Tok::Ident(s)=self.peek().clone(){s}else{unreachable!()}; self.pos+=1; self.expect(&Tok::In); let e = self.parse_expr(); let b = self.parse_block(); Stmt::For(var, e, b, fl) }
            Tok::Return => { self.pos+=1; if *self.peek()==Tok::Semicolon { self.pos+=1; Stmt::Return(None) } else { let e=self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::Return(Some(e)) } }
            Tok::Break => { self.pos+=1; self.expect(&Tok::Semicolon); Stmt::Break }
            Tok::Continue => { self.pos+=1; self.expect(&Tok::Semicolon); Stmt::Continue }
            _ => {
                let e = self.parse_expr();
                if *self.peek() == Tok::Assign {
                    self.pos += 1;
                    match e {
                        Expr::Ident(name, ln) => { let v = self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::Assign(name, v, ln) }
                        Expr::Index(obj, idx, ln) => { let v = self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::IndexAssign(obj, idx, v, ln) }
                        _ => unreachable!(),
                    }
                } else {
                    self.expect(&Tok::Semicolon);
                    Stmt::ExprStmt(e)
                }
            }
        }
    }

    fn parse_if(&mut self) -> Stmt {
        self.pos+=1; let c = self.parse_expr(); let b = self.parse_block();
        let els = if *self.peek() == Tok::Else {
            self.pos+=1;
            if *self.peek() == Tok::If { Some(ElsePart::If(Box::new(self.parse_if()))) }
            else { Some(ElsePart::Block(self.parse_block())) }
        } else { None };
        Stmt::If(c, b, els)
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }
    fn parse_or(&mut self) -> Expr {
        let mut l = self.parse_and();
        while *self.peek() == Tok::Or { self.pos+=1; let r=self.parse_and(); l=Expr::Or(Box::new(l),Box::new(r)); }
        l
    }
    fn parse_and(&mut self) -> Expr {
        let mut l = self.parse_not();
        while *self.peek() == Tok::And { self.pos+=1; let r=self.parse_not(); l=Expr::And(Box::new(l),Box::new(r)); }
        l
    }
    fn parse_not(&mut self) -> Expr {
        if *self.peek() == Tok::Not { self.pos+=1; return Expr::UnaryNot(Box::new(self.parse_not())); }
        self.parse_cmp()
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut l = self.parse_add();
        loop {
            let op = match self.peek() {
                Tok::Eq => "==", Tok::Neq => "!=", Tok::Lt => "<",
                Tok::Le => "<=", Tok::Gt => ">", Tok::Ge => ">=", _ => break,
            };
            let ln = self.peek_line(); self.pos+=1;
            let r = self.parse_add();
            l = Expr::BinOp(op.to_string(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_add(&mut self) -> Expr {
        let mut l = self.parse_mul();
        loop {
            let op = match self.peek() { Tok::Plus=>"+", Tok::Minus=>"-", _=>break };
            let ln = self.peek_line(); self.pos+=1;
            let r = self.parse_mul();
            l = Expr::BinOp(op.to_string(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_mul(&mut self) -> Expr {
        let mut l = self.parse_unary();
        loop {
            let op = match self.peek() { Tok::Star=>"*", Tok::Slash=>"/", Tok::Percent=>"%", _=>break };
            let ln = self.peek_line(); self.pos+=1;
            let r = self.parse_unary();
            l = Expr::BinOp(op.to_string(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_unary(&mut self) -> Expr {
        if *self.peek() == Tok::Minus { let ln=self.peek_line(); self.pos+=1; return Expr::UnaryNeg(Box::new(self.parse_unary()), ln); }
        self.parse_postfix()
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek() {
                Tok::LParen => { let ln=self.peek_line(); self.pos+=1; let args = self.parse_args(); self.expect(&Tok::RParen); e = Expr::Call(Box::new(e), args, ln); }
                Tok::LBracket => { let ln=self.peek_line(); self.pos+=1; let idx=self.parse_expr(); self.expect(&Tok::RBracket); e = Expr::Index(Box::new(e), Box::new(idx), ln); }
                _ => break,
            }
        }
        e
    }
    fn parse_args(&mut self) -> Vec<Expr> {
        let mut args = Vec::new();
        if *self.peek() != Tok::RParen {
            loop { args.push(self.parse_expr()); if *self.peek()==Tok::Comma { self.pos+=1; } else { break; } }
        }
        args
    }
    fn parse_primary(&mut self) -> Expr {
        match self.peek().clone() {
            Tok::Int(n) => { self.pos+=1; Expr::IntLit(n) }
            Tok::Str(s) => { self.pos+=1; Expr::StrLit(s) }
            Tok::True => { self.pos+=1; Expr::BoolLit(true) }
            Tok::False => { self.pos+=1; Expr::BoolLit(false) }
            Tok::Nil => { self.pos+=1; Expr::NilLit }
            Tok::Ident(s) => { let ln=self.peek_line(); self.pos+=1; Expr::Ident(s, ln) }
            Tok::LParen => { self.pos+=1; let e=self.parse_expr(); self.expect(&Tok::RParen); e }
            Tok::LBracket => { self.pos+=1; let items=self.parse_args(); self.expect(&Tok::RBracket); Expr::ListLit(items) }
            Tok::Fn => { self.pos+=1; self.expect(&Tok::LParen); let params=self.parse_params(); self.expect(&Tok::RParen); let body=self.parse_block(); Expr::FnLit(params, body) }
            _ => unreachable!(),
        }
    }
}

// ===== Value =====
#[derive(Clone)]
enum Value {
    Int(i64), Bool(bool), Str(String),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Rc<FnData>),
    Nil,
}

#[derive(Clone)]
enum FnData {
    User { params: Vec<String>, body: Rc<Vec<Stmt>>, captured: Rc<RefCell<Scope>> },
    Builtin(String),
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    fn new(parent: Option<Rc<RefCell<Scope>>>) -> Self { Scope { vars: HashMap::new(), parent } }
    fn lookup(&self, name: &str) -> Option<&Value> {
        if let Some(v) = self.vars.get(name) { return Some(v); }
        if let Some(ref p) = self.parent { return p.borrow().lookup(name); }
        None
    }
    fn assign(&mut self, name: &str, val: Value) -> bool {
        if self.vars.contains_key(name) { self.vars.insert(name.to_string(), val); return true; }
        if let Some(ref p) = self.parent { return p.borrow_mut().assign(name, val); }
        false
    }
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int", Value::Bool(_) => "bool", Value::Str(_) => "string",
        Value::List(_) => "list", Value::Function(_) => "function", Value::Nil => "nil",
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::Nil => false,
        Value::List(l) => !l.borrow().is_empty(),
        Value::Function(_) => true,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::List(x), Value::List(y)) => {
            let xb = x.borrow(); let yb = y.borrow();
            if xb.len() != yb.len() { return false; }
            for (a,b) in xb.iter().zip(yb.iter()) { if !values_equal(a,b) { return false; } }
            true
        }
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

fn display(v: &Value, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(b) => if *b {"true".to_string()} else {"false".to_string()},
        Value::Str(s) => s.clone(),
        Value::Nil => "nil".to_string(),
        Value::Function(_) => "<fn>".to_string(),
        Value::List(items) => {
            let ptr = Rc::as_ptr(items) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let inner: Vec<String> = items.borrow().iter().map(|item| inner_display(item, seen)).collect();
            seen.pop();
            format!("[{}]", inner.join(", "))
        }
    }
}

fn inner_display(v: &Value, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Str(s) => format!("\"{}\"", escape_str(s)),
        _ => display(v, seen),
    }
}

// ===== Error =====
struct RuntimeError { line: usize, msg: String }

// ===== Interpreter =====
struct Interp {
    global: Rc<RefCell<Scope>>,
}

enum CF { Normal, Break, Continue, Return(Value) }

impl Interp {
    fn new() -> Self {
        let global = Rc::new(RefCell::new(Scope::new(None)));
        let interp = Interp { global };
        interp.register_builtins();
        interp
    }

    fn register_builtins(&self) {
        let names = ["print","str","type","len","push","pop","range","slice"];
        for name in &names {
            let f = Value::Function(Rc::new(FnData::Builtin(name.to_string())));
            self.global.borrow_mut().vars.insert(name.to_string(), f);
        }
    }

    fn run(&mut self, stmts: &[Stmt]) -> Result<(), RuntimeError> {
        let scope = self.global.clone();
        self.run_block(stmts, &scope)?;
        Ok(())
    }

    fn run_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<CF, RuntimeError> {
        for s in stmts {
            let cf = self.run_stmt(s, scope)?;
            match cf {
                CF::Normal => continue,
                _ => return Ok(cf),
            }
        }
        Ok(CF::Normal)
    }

    fn run_stmt(&mut self, stmt: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<CF, RuntimeError> {
        match stmt {
            Stmt::Let(name, expr) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), v);
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body) => {
                let f = Value::Function(Rc::new(FnData::User {
                    params: params.clone(), body: Rc::new(body.clone()), captured: scope.clone(),
                }));
                scope.borrow_mut().vars.insert(name.clone(), f);
                Ok(CF::Normal)
            }
            Stmt::If(cond, then_b, els) => {
                let cv = self.eval(cond, scope)?;
                if is_truthy(&cv) {
                    let bs = Rc::new(RefCell::new(Scope::new(Some(scope.clone()))));
                    self.run_block(then_b, &bs)
                } else {
                    match els {
                        Some(ElsePart::Block(b)) => {
                            let bs = Rc::new(RefCell::new(Scope::new(Some(scope.clone()))));
                            self.run_block(b, &bs)
                        }
                        Some(ElsePart::If(s)) => self.run_stmt(s, scope),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let cv = self.eval(cond, scope)?;
                    if !is_truthy(&cv) { break; }
                    let bs = Rc::new(RefCell::new(Scope::new(Some(scope.clone()))));
                    match self.run_block(body, &bs)? {
                        CF::Break => break,
                        CF::Continue => continue,
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => {}
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, expr, body, line) => {
                let lv = self.eval(expr, scope)?;
                let list = match lv {
                    Value::List(l) => l,
                    other => return Err(RuntimeError { line: *line, msg: format!("cannot iterate {}", type_name(&other)) }),
                };
                let mut i: usize = 0;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let is = Rc::new(RefCell::new(Scope::new(Some(scope.clone()))));
                    is.borrow_mut().vars.insert(var.clone(), elem);
                    match self.run_block(body, &is)? {
                        CF::Break => break,
                        CF::Continue => { i += 1; }
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => { i += 1; }
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::Return(expr) => {
                let v = match expr { Some(e) => self.eval(e, scope)?, None => Value::Nil };
                Ok(CF::Return(v))
            }
            Stmt::Break => Ok(CF::Break),
            Stmt::Continue => Ok(CF::Continue),
            Stmt::Assign(name, expr, line) => {
                let v = self.eval(expr, scope)?;
                if !scope.borrow_mut().assign(name, v) {
                    return Err(RuntimeError { line: *line, msg: format!("undefined variable {}", name) });
                }
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(obj, idx, val, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                let vv = self.eval(val, scope)?;
                match &ov {
                    Value::List(list) => {
                        let i = match &iv {
                            Value::Int(i) => *i,
                            other => return Err(RuntimeError { line: *line, msg: format!("cannot index list with {}", type_name(other)) }),
                        };
                        let len = list.borrow().len() as i64;
                        if i < 0 || i >= len {
                            return Err(RuntimeError { line: *line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        list.borrow_mut()[i as usize] = vv;
                    }
                    other => return Err(RuntimeError { line: *line, msg: format!("cannot assign into {}", type_name(other)) }),
                }
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(expr) => { self.eval(expr, scope)?; Ok(CF::Normal) }
        }
    }

    fn eval(&mut self, expr: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value, RuntimeError> {
        match expr {
            Expr::IntLit(n) => Ok(Value::Int(*n)),
            Expr::StrLit(s) => Ok(Value::Str(s.clone())),
            Expr::BoolLit(b) => Ok(Value::Bool(*b)),
            Expr::NilLit => Ok(Value::Nil),
            Expr::Ident(name, line) => {
                scope.borrow().lookup(name).cloned().ok_or_else(|| RuntimeError { line: *line, msg: format!("undefined variable {}", name) })
            }
            Expr::UnaryNot(operand) => {
                let v = self.eval(operand, scope)?;
                Ok(Value::Bool(!is_truthy(&v)))
            }
            Expr::UnaryNeg(operand, line) => {
                let v = self.eval(operand, scope)?;
                match v {
                    Value::Int(n) => {
                        if n == i64::MIN { return Err(RuntimeError{line:*line, msg:"integer overflow".to_string()}); }
                        Ok(Value::Int(-n))
                    }
                    other => Err(RuntimeError { line: *line, msg: format!("cannot apply - to {}", type_name(&other)) }),
                }
            }
            Expr::BinOp(op, l, r, line) => {
                let lv = self.eval(l, scope)?;
                let rv = self.eval(r, scope)?;
                self.binop(op, lv, rv, *line)
            }
            Expr::And(l, r) => {
                let lv = self.eval(l, scope)?;
                if !is_truthy(&lv) { Ok(lv) } else { self.eval(r, scope) }
            }
            Expr::Or(l, r) => {
                let lv = self.eval(l, scope)?;
                if is_truthy(&lv) { Ok(lv) } else { self.eval(r, scope) }
            }
            Expr::Call(callee, args, line) => {
                let cv = self.eval(callee, scope)?;
                let mut argv = Vec::with_capacity(args.len());
                for a in args { argv.push(self.eval(a, scope)?); }
                self.call(cv, argv, *line)
            }
            Expr::Index(obj, idx, line) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                match (&ov, &iv) {
                    (Value::List(list), Value::Int(i)) => {
                        let len = list.borrow().len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(RuntimeError { line: *line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(list.borrow()[*i as usize].clone())
                    }
                    (Value::Str(s), Value::Int(i)) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len {
                            return Err(RuntimeError { line: *line, msg: format!("index {} out of range for length {}", i, len) });
                        }
                        Ok(Value::Str(s[*i as usize..*i as usize+1].to_string()))
                    }
                    _ => Err(RuntimeError { line: *line, msg: format!("cannot index {} with {}", type_name(&ov), type_name(&iv)) }),
                }
            }
            Expr::ListLit(items) => {
                let mut v = Vec::with_capacity(items.len());
                for it in items { v.push(self.eval(it, scope)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body) => {
                Ok(Value::Function(Rc::new(FnData::User {
                    params: params.clone(), body: Rc::new(body.clone()), captured: scope.clone(),
                })))
            }
        }
    }

    fn binop(&mut self, op: &str, lv: Value, rv: Value, line: usize) -> Result<Value, RuntimeError> {
        match op {
            "==" => return Ok(Value::Bool(values_equal(&lv, &rv))),
            "!=" => return Ok(Value::Bool(!values_equal(&lv, &rv))),
            _ => {}
        }
        match op {
            "+" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => { a.checked_add(*b).map(Value::Int).ok_or(RuntimeError{line,msg:"integer overflow".to_string()}) }
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                    (Value::List(a), Value::List(b)) => {
                        let mut v = a.borrow().clone();
                        v.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply + to {} and {}", type_name(&lv), type_name(&rv))}),
                }
            }
            "-" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => { a.checked_sub(*b).map(Value::Int).ok_or(RuntimeError{line,msg:"integer overflow".to_string()}) }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply - to {} and {}", type_name(&lv), type_name(&rv))}),
                }
            }
            "*" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => { a.checked_mul(*b).map(Value::Int).ok_or(RuntimeError{line,msg:"integer overflow".to_string()}) }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply * to {} and {}", type_name(&lv), type_name(&rv))}),
                }
            }
            "/" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line,msg:"division by zero".to_string()}); }
                        a.checked_div(*b).map(Value::Int).ok_or(RuntimeError{line,msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply / to {} and {}", type_name(&lv), type_name(&rv))}),
                }
            }
            "%" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line,msg:"division by zero".to_string()}); }
                        if *b == -1 { return Ok(Value::Int(0)); }
                        a.checked_rem(*b).map(Value::Int).ok_or(RuntimeError{line,msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply % to {} and {}", type_name(&lv), type_name(&rv))}),
                }
            }
            "<" | "<=" | ">" | ">=" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => {
                        let r = match op { "<"=>a<*b, "<=" =>a<=*b, ">"=>a>*b, _=>a>=*b };
                        Ok(Value::Bool(r))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let r = match op { "<"=>a<b, "<=" =>a<=b, ">"=>a>b, _=>a>=b };
                        Ok(Value::Bool(r))
                    }
                    _ => Err(RuntimeError{line, msg:format!("cannot apply {} to {} and {}", op, type_name(&lv), type_name(&rv))}),
                }
            }
            _ => unreachable!(),
        }
    }

    fn call(&mut self, func: Value, args: Vec<Value>, line: usize) -> Result<Value, RuntimeError> {
        match &func {
            Value::Function(f) => {
                match &**f {
                    FnData::User { params, body, captured } => {
                        if params.len() != args.len() {
                            return Err(RuntimeError{line, msg:format!("expected {} arguments, got {}", params.len(), args.len())});
                        }
                        let fs = Rc::new(RefCell::new(Scope::new(Some(captured.clone()))));
                        for (p, a) in params.iter().zip(args.into_iter()) {
                            fs.borrow_mut().vars.insert(p.clone(), a);
                        }
                        match self.run_block(&body, &fs)? {
                            CF::Return(v) => Ok(v),
                            _ => Ok(Value::Nil),
                        }
                    }
                    FnData::Builtin(name) => {
                        self.call_builtin(name, args, line)
                    }
                }
            }
            other => Err(RuntimeError{line, msg:format!("cannot call {}", type_name(other))}),
        }
    }

    fn call_builtin(&mut self, name: &str, args: Vec<Value>, line: usize) -> Result<Value, RuntimeError> {
        match name {
            "print" => {
                let parts: Vec<String> = args.iter().map(|v| { let mut s = Vec::new(); display(v, &mut s) }).collect();
                println!("{}", parts.join(" "));
                Ok(Value::Nil)
            }
            "str" => {
                if args.len() != 1 { return Err(RuntimeError{line, msg:format!("expected 1 arguments, got {}", args.len())}); }
                let mut s = Vec::new();
                Ok(Value::Str(display(&args[0], &mut s)))
            }
            "type" => {
                if args.len() != 1 { return Err(RuntimeError{line, msg:format!("expected 1 arguments, got {}", args.len())}); }
                Ok(Value::Str(type_name(&args[0]).to_string()))
            }
            "len" => {
                if args.len() != 1 { return Err(RuntimeError{line, msg:format!("expected 1 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(RuntimeError{line, msg:"bad argument to len".to_string()}),
                }
            }
            "push" => {
                if args.len() != 2 { return Err(RuntimeError{line, msg:format!("expected 2 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(RuntimeError{line, msg:"bad argument to push".to_string()}),
                }
            }
            "pop" => {
                if args.len() != 1 { return Err(RuntimeError{line, msg:format!("expected 1 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::List(l) => {
                        let mut lb = l.borrow_mut();
                        if lb.is_empty() { return Err(RuntimeError{line, msg:"bad argument to pop".to_string()}); }
                        Ok(lb.pop().unwrap())
                    }
                    _ => Err(RuntimeError{line, msg:"bad argument to pop".to_string()}),
                }
            }
            "range" => {
                if args.len() != 2 { return Err(RuntimeError{line, msg:format!("expected 2 arguments, got {}", args.len())}); }
                let (a, b) = match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return Err(RuntimeError{line, msg:"bad argument to range".to_string()}),
                };
                if b <= a { return Ok(Value::List(Rc::new(RefCell::new(vec![])))); }
                let mut v = Vec::with_capacity((b - a) as usize);
                let mut cur = a;
                while cur < b { v.push(Value::Int(cur)); cur += 1; }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            "slice" => {
                if args.len() != 3 { return Err(RuntimeError{line, msg:format!("expected 3 arguments, got {}", args.len())}); }
                let (a, b) = match (&args[1], &args[2]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return Err(RuntimeError{line, msg:"bad argument to slice".to_string()}),
                };
                match &args[0] {
                    Value::Str(s) => {
                        let len = s.len() as i64;
                        if a < 0 || b < a || b > len { return Err(RuntimeError{line, msg:"bad argument to slice".to_string()}); }
                        Ok(Value::Str(s[a as usize..b as usize].to_string()))
                    }
                    Value::List(l) => {
                        let len = l.borrow().len() as i64;
                        if a < 0 || b < a || b > len { return Err(RuntimeError{line, msg:"bad argument to slice".to_string()}); }
                        Ok(Value::List(Rc::new(RefCell::new(l.borrow()[a as usize..b as usize].to_vec()))))
                    }
                    _ => Err(RuntimeError{line, msg:"bad argument to slice".to_string()}),
                }
            }
            _ => unreachable!(),
        }
    }
}

fn main() {
    let dir = std::env::args().nth(1).unwrap();
    let path = format!("{}/program.tern", dir);
    let source = std::fs::read_to_string(&path).unwrap();
    let tokens = lex(&source);
    let mut parser = Parser::new(tokens);
    let ast = parser.parse_program();
    let mut interp = Interp::new();
    match interp.run(&ast) {
        Ok(_) => {}
        Err(e) => {
            let _ = std::io::stdout().flush();
            println!("error at line {}: {}", e.line, e.msg);
        }
    }
    let _ = std::io::stdout().flush();
}

import Foundation

func crc32(_ data: [UInt8]) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) }
            else { c = c >> 1 }
        }
        table[i] = c
    }
    var crc: UInt32 = 0xFFFFFFFF
    for b in data {
        crc = table[Int((crc ^ UInt32(b)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func toBE32(_ value: Int) -> [UInt8] {
    let v = UInt32(truncatingIfNeeded: value)
    return [UInt8((v >> 24) & 0xFF), UInt8((v >> 16) & 0xFF), UInt8((v >> 8) & 0xFF), UInt8(v & 0xFF)]
}

func makeChunk(_ type: String, _ data: [UInt8]) -> [UInt8] {
    var chunk: [UInt8] = []
    chunk.append(contentsOf: toBE32(data.count))
    let typeBytes = Array(type.utf8)
    chunk.append(contentsOf: typeBytes)
    chunk.append(contentsOf: data)
    let crcData = typeBytes + data
    let crc = crc32(crcData)
    chunk.append(contentsOf: toBE32(Int(crc)))
    return chunk
}

func writePNG(_ canvas: [(Int, Int, Int)], width: Int, height: Int, path: String) {
    var pngData: [UInt8] = []

    // PNG signature
    pngData.append(contentsOf: [137, 80, 78, 71, 13, 10, 26, 10])

    // IHDR
    var ihdrData: [UInt8] = []
    ihdrData.append(contentsOf: toBE32(width))
    ihdrData.append(contentsOf: toBE32(height))
    ihdrData.append(8)   // bit depth
    ihdrData.append(2)   // color type: RGB
    ihdrData.append(0)   // compression
    ihdrData.append(0)   // filter
    ihdrData.append(0)   // interlace
    pngData.append(contentsOf: makeChunk("IHDR", ihdrData))

    // Build raw image data with filter bytes
    var rawData: [UInt8] = []
    rawData.reserveCapacity(height * (1 + width * 3))
    for y in 0..<height {
        rawData.append(0) // filter: None
        for x in 0..<width {
            let (r, g, b) = canvas[y * width + x]
            rawData.append(UInt8(r))
            rawData.append(UInt8(g))
            rawData.append(UInt8(b))
        }
    }

    // zlib stream with stored DEFLATE blocks
    var zlibData: [UInt8] = []
    zlibData.append(0x78) // CMF
    zlibData.append(0x01) // FLG

    let maxBlock = 65535
    var offset = 0
    while offset < rawData.count {
        let blockSize = min(maxBlock, rawData.count - offset)
        let isLast = (offset + blockSize >= rawData.count)

        zlibData.append(isLast ? 0x01 : 0x00)
        zlibData.append(UInt8(blockSize & 0xFF))
        zlibData.append(UInt8((blockSize >> 8) & 0xFF))
        let nlen = ~UInt16(blockSize)
        zlibData.append(UInt8(nlen & 0xFF))
        zlibData.append(UInt8((nlen >> 8) & 0xFF))
        zlibData.append(contentsOf: rawData[offset..<(offset + blockSize)])
        offset += blockSize
    }

    // Handle empty data edge case (shouldn't happen given constraints)
    if rawData.count == 0 {
        zlibData.append(0x01) // last stored block
        zlibData.append(0x00)
        zlibData.append(0x00)
        zlibData.append(0xFF)
        zlibData.append(0xFF)
    }

    let adler = adler32(rawData)
    zlibData.append(contentsOf: toBE32(Int(adler)))

    pngData.append(contentsOf: makeChunk("IDAT", zlibData))

    // IEND
    pngData.append(contentsOf: makeChunk("IEND", []))

    let url = URL(fileURLWithPath: path)
    try! Data(pngData).write(to: url)
}

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { fatalError("Usage: main <directory>") }
    let dir = args[1]

    let scenePath = (dir as NSString).appendingPathComponent("scene.json")
    guard let data = FileManager.default.contents(atPath: scenePath) else {
        fatalError("Cannot read \(scenePath)")
    }

    guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
        fatalError("Cannot parse JSON")
    }

    let width = json["width"] as! Int
    let height = json["height"] as! Int
    let bg = json["background"] as! [Int]

    var canvas = [(Int, Int, Int)](repeating: (bg[0], bg[1], bg[2]), count: width * height)

    let shapes = json["shapes"] as! [[String: Any]]

    var shapeCounts: [Int] = []

    for shape in shapes {
        let type = shape["type"] as! String
        let color = shape["color"] as! [Int]
        let sR = color[0], sG = color[1], sB = color[2], alpha = color[3]

        var count = 0

        switch type {
        case "rect":
            let rx = shape["x"] as! Int
            let ry = shape["y"] as! Int
            let w = shape["w"] as! Int
            let h = shape["h"] as! Int
            let xLo = max(0, rx)
            let xHi = min(width, rx + w)
            let yLo = max(0, ry)
            let yHi = min(height, ry + h)
            if xLo < xHi && yLo < yHi {
                count = (xHi - xLo) * (yHi - yLo)
                if alpha > 0 {
                    let invA = 255 - alpha
                    for y in yLo..<yHi {
                        let rowBase = y * width
                        for x in xLo..<xHi {
                            let idx = rowBase + x
                            let (dR, dG, dB) = canvas[idx]
                            canvas[idx] = (
                                (sR * alpha + dR * invA + 127) / 255,
                                (sG * alpha + dG * invA + 127) / 255,
                                (sB * alpha + dB * invA + 127) / 255
                            )
                        }
                    }
                }
            }

        case "circle":
            let cx = shape["cx"] as! Int
            let cy = shape["cy"] as! Int
            let r = shape["r"] as! Int
            let r64 = Int64(r)
            let r2 = r64 * r64
            let xLo = max(0, cx - r)
            let xHi = min(width - 1, cx + r)
            let yLo = max(0, cy - r)
            let yHi = min(height - 1, cy + r)
            if xLo <= xHi && yLo <= yHi {
                if alpha > 0 {
                    let invA = 255 - alpha
                    for y in yLo...yHi {
                        let dy = Int64(y - cy)
                        let dy2 = dy * dy
                        let rowBase = y * width
                        for x in xLo...xHi {
                            let dx = Int64(x - cx)
                            if dx * dx + dy2 <= r2 {
                                count += 1
                                let idx = rowBase + x
                                let (dR, dG, dB) = canvas[idx]
                                canvas[idx] = (
                                    (sR * alpha + dR * invA + 127) / 255,
                                    (sG * alpha + dG * invA + 127) / 255,
                                    (sB * alpha + dB * invA + 127) / 255
                                )
                            }
                        }
                    }
                } else {
                    for y in yLo...yHi {
                        let dy = Int64(y - cy)
                        let dy2 = dy * dy
                        for x in xLo...xHi {
                            let dx = Int64(x - cx)
                            if dx * dx + dy2 <= r2 {
                                count += 1
                            }
                        }
                    }
                }
            }

        case "triangle":
            let pts = shape["points"] as! [[Int]]
            let p0x = pts[0][0], p0y = pts[0][1]
            let p1x = pts[1][0], p1y = pts[1][1]
            let p2x = pts[2][0], p2y = pts[2][1]
            let e0dx = Int64(p1x - p0x), e0dy = Int64(p1y - p0y)
            let e1dx = Int64(p2x - p1x), e1dy = Int64(p2y - p1y)
            let e2dx = Int64(p0x - p2x), e2dy = Int64(p0y - p2y)

            let minX = min(p0x, min(p1x, p2x))
            let maxX = max(p0x, max(p1x, p2x))
            let minY = min(p0y, min(p1y, p2y))
            let maxY = max(p0y, max(p1y, p2y))
            let xLo = max(0, minX)
            let xHi = min(width - 1, maxX)
            let yLo = max(0, minY)
            let yHi = min(height - 1, maxY)

            if xLo <= xHi && yLo <= yHi {
                if alpha > 0 {
                    let invA = 255 - alpha
                    for y in yLo...yHi {
                        let rowBase = y * width
                        for x in xLo...xHi {
                            let x64 = Int64(x), y64 = Int64(y)
                            let e0 = e0dx * (y64 - Int64(p0y)) - e0dy * (x64 - Int64(p0x))
                            let e1 = e1dx * (y64 - Int64(p1y)) - e1dy * (x64 - Int64(p1x))
                            let e2 = e2dx * (y64 - Int64(p2y)) - e2dy * (x64 - Int64(p2x))
                            if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                                count += 1
                                let idx = rowBase + x
                                let (dR, dG, dB) = canvas[idx]
                                canvas[idx] = (
                                    (sR * alpha + dR * invA + 127) / 255,
                                    (sG * alpha + dG * invA + 127) / 255,
                                    (sB * alpha + dB * invA + 127) / 255
                                )
                            }
                        }
                    }
                } else {
                    for y in yLo...yHi {
                        for x in xLo...xHi {
                            let x64 = Int64(x), y64 = Int64(y)
                            let e0 = e0dx * (y64 - Int64(p0y)) - e0dy * (x64 - Int64(p0x))
                            let e1 = e1dx * (y64 - Int64(p1y)) - e1dy * (x64 - Int64(p1x))
                            let e2 = e2dx * (y64 - Int64(p2y)) - e2dy * (x64 - Int64(p2x))
                            if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                                count += 1
                            }
                        }
                    }
                }
            }

        case "line":
            let x1 = shape["x1"] as! Int
            let y1 = shape["y1"] as! Int
            let x2 = shape["x2"] as! Int
            let y2 = shape["y2"] as! Int
            let r = shape["r"] as! Int
            let dx = Int64(x2 - x1)
            let dy = Int64(y2 - y1)
            let L = dx * dx + dy * dy
            let r64 = Int64(r)
            let r2 = r64 * r64

            let minX = min(x1, x2) - r
            let maxX = max(x1, x2) + r
            let minY = min(y1, y2) - r
            let maxY = max(y1, y2) + r
            let xLo = max(0, minX)
            let xHi = min(width - 1, maxX)
            let yLo = max(0, minY)
            let yHi = min(height - 1, maxY)

            if xLo <= xHi && yLo <= yHi {
                let r2L = r2 * L
                if alpha > 0 {
                    let invA = 255 - alpha
                    for y in yLo...yHi {
                        let rowBase = y * width
                        for x in xLo...xHi {
                            let x64 = Int64(x), y64 = Int64(y)
                            let t = (x64 - Int64(x1)) * dx + (y64 - Int64(y1)) * dy
                            var covered = false
                            if t <= 0 {
                                let ddx = x64 - Int64(x1)
                                let ddy = y64 - Int64(y1)
                                covered = (ddx * ddx + ddy * ddy <= r2)
                            } else if t >= L {
                                let ddx = x64 - Int64(x2)
                                let ddy = y64 - Int64(y2)
                                covered = (ddx * ddx + ddy * ddy <= r2)
                            } else {
                                let c = (x64 - Int64(x1)) * dy - (y64 - Int64(y1)) * dx
                                covered = (c * c <= r2L)
                            }
                            if covered {
                                count += 1
                                let idx = rowBase + x
                                let (dR, dG, dB) = canvas[idx]
                                canvas[idx] = (
                                    (sR * alpha + dR * invA + 127) / 255,
                                    (sG * alpha + dG * invA + 127) / 255,
                                    (sB * alpha + dB * invA + 127) / 255
                                )
                            }
                        }
                    }
                } else {
                    for y in yLo...yHi {
                        for x in xLo...xHi {
                            let x64 = Int64(x), y64 = Int64(y)
                            let t = (x64 - Int64(x1)) * dx + (y64 - Int64(y1)) * dy
                            var covered = false
                            if t <= 0 {
                                let ddx = x64 - Int64(x1)
                                let ddy = y64 - Int64(y1)
                                covered = (ddx * ddx + ddy * ddy <= r2)
                            } else if t >= L {
                                let ddx = x64 - Int64(x2)
                                let ddy = y64 - Int64(y2)
                                covered = (ddx * ddx + ddy * ddy <= r2)
                            } else {
                                let c = (x64 - Int64(x1)) * dy - (y64 - Int64(y1)) * dx
                                covered = (c * c <= r2L)
                            }
                            if covered {
                                count += 1
                            }
                        }
                    }
                }
            }

        default:
            break
        }

        shapeCounts.append(count)
    }

    // Write PNG
    writePNG(canvas, width: width, height: height, path: "out.png")

    // Print summary
    for (i, count) in shapeCounts.enumerated() {
        let t = shapes[i]["type"] as! String
        print("\(i + 1) \(t) \(count)")
    }

    // Count distinct colors
    var colorSet = Set<Int>()
    for (r, g, b) in canvas {
        colorSet.insert(r * 65536 + g * 256 + b)
    }
    print("colors \(colorSet.count)")
}

