int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    char cpath[1024];
    snprintf(cpath,sizeof(cpath),"%s/client.json",argv[1]);
    FILE*f=fopen(cpath,"rb");
    if(!f){fprintf(stderr,"cannot open %s\n",cpath);return 1;}
    Buf fj;buf_init(&fj);
    {char t[4096];size_t n;while((n=fread(t,1,4096,f))>0)buf_append(&fj,t,n);}
    fclose(f);

    char client_id[512],client_secret[512],scope[512];
    size_t pos=j_find_key(fj.d,0,"client_id");
    j_parse_string(fj.d,&pos,client_id,sizeof(client_id));
    pos=j_find_key(fj.d,0,"client_secret");
    j_parse_string(fj.d,&pos,client_secret,sizeof(client_secret));
    pos=j_find_key(fj.d,0,"scope");
    j_parse_string(fj.d,&pos,scope,sizeof(scope));
    pos=j_find_key(fj.d,0,"page_size");
    int page_size=atoi(fj.d+pos);

    Url url;parse_url(argv[2],&url);

    /* Step 1: get token */
    char*enc_id=form_urlencode(client_id);
    char*enc_sec=form_urlencode(client_secret);
    Buf cred;buf_init(&cred);
    buf_puts(&cred,enc_id);buf_puts(&cred,":");buf_puts(&cred,enc_sec);
    char*b64=base64_encode((unsigned char*)cred.d,cred.len);
    char*enc_scope=form_urlencode(scope);

    Buf tok_body;buf_init(&tok_body);
    buf_puts(&tok_body,"grant_type=client_credentials&scope=");
    buf_puts(&tok_body,enc_scope);

    Buf tok_hdrs;buf_init(&tok_hdrs);
    buf_puts(&tok_hdrs,"Content-Type: application/x-www-form-urlencoded\r\n");
    buf_puts(&tok_hdrs,"Authorization: Basic ");buf_puts(&tok_hdrs,b64);buf_puts(&tok_hdrs,"\r\n");

    char tok_path[600];
    snprintf(tok_path,sizeof(tok_path),"%s/oauth/token",url.path);

    Resp resp;
    do_request(&url,"POST",tok_path,tok_hdrs.d,tok_body.d,&resp);
    if(resp.status!=200){
        printf("ERROR %d %s\n",resp.status,resp.body);
        return 0;
    }
    pos=j_find_key(resp.body,0,"access_token");
    char access_token[4096];
    j_parse_string(resp.body,&pos,access_token,sizeof(access_token));
    free(resp.headers);free(resp.body);

    /* Step 2: fetch orders */
    int pages=0,retries=0,reauth=0;
    int total_orders=0;
    int token_used_ok=0;

    char cursor[4096]="";
    int first_page=1;

    while(1){
        char ord_path[8192];
        if(first_page)
            snprintf(ord_path,sizeof(ord_path),"%s/orders?limit=%d",url.path,page_size);
        else{
            char*ec=pct_encode(cursor);
            snprintf(ord_path,sizeof(ord_path),"%s/orders?limit=%d&cursor=%s",url.path,page_size,ec);
            free(ec);
        }

        Buf ord_hdrs;buf_init(&ord_hdrs);
        buf_puts(&ord_hdrs,"Authorization: Bearer ");buf_puts(&ord_hdrs,access_token);buf_puts(&ord_hdrs,"\r\n");

        Resp r;
        do_request(&url,"GET",ord_path,ord_hdrs.d,NULL,&r);
        free(ord_hdrs.d);

        if(r.status==429){
            retries++;
            const char*ra=ci_strstr(r.headers,"Retry-After:");
            int wait=ra?atoi(ra+12):1;
            free(r.headers);free(r.body);
            sleep(wait);
            continue;
        }
        if(r.status==503){
            retries++;
            free(r.headers);free(r.body);
            sleep(1);
            continue;
        }
        if(r.status==401){
            if(!token_used_ok){
                printf("ERROR %d %s\n",r.status,r.body);
                free(r.headers);free(r.body);
                return 0;
            }
            free(r.headers);free(r.body);
            /* re-auth */
            Resp tr;
            do_request(&url,"POST",tok_path,tok_hdrs.d,tok_body.d,&tr);
            if(tr.status!=200){
                printf("ERROR %d %s\n",tr.status,tr.body);
                free(tr.headers);free(tr.body);
                return 0;
            }
            pos=j_find_key(tr.body,0,"access_token");
            j_parse_string(tr.body,&pos,access_token,sizeof(access_token));
            free(tr.headers);free(tr.body);
            reauth++;
            token_used_ok=0;
            continue;
        }
        if(r.status!=200){
            printf("ERROR %d %s\n",r.status,r.body);
            free(r.headers);free(r.body);
            return 0;
        }

        /* 200 response */
        pages++;
        token_used_ok=1;

        /* Parse data array */
        size_t dpos=j_find_key(r.body,0,"data");
        if(dpos!=SIZE_MAX&&r.body[dpos]=='['){
            size_t p=dpos+1;
            j_skip_ws(r.body,&p);
            if(r.body[p]!=']'){
                while(1){
                    j_skip_ws(r.body,&p);
                    /* p points to start of order object */
                    size_t os=p;
                    /* find the end of this object */
                    j_skip_value(r.body,&p);
                    /* parse fields from os to p */
                    /* status */
                    size_t sp2=j_find_key(r.body,os,"status");
                    char status[256]="";
                    if(sp2!=SIZE_MAX)j_parse_string(r.body,&sp2,status,sizeof(status));

                    /* amount */
                    size_t ap=j_find_key(r.body,os,"amount");
                    char amount[128]="0";
                    if(ap!=SIZE_MAX)j_parse_string(r.body,&ap,amount,sizeof(amount));

                    /* currency */
                    size_t cp=j_find_key(r.body,os,"currency");
                    char currency[256]="";
                    if(cp!=SIZE_MAX)j_parse_string(r.body,&cp,currency,sizeof(currency));

                    /* customer.name */
                    size_t custp=j_find_key(r.body,os,"customer");
                    char cname[4096]="";
                    if(custp!=SIZE_MAX&&r.body[custp]=='{'){
                        size_t np=j_find_key(r.body,custp,"name");
                        if(np!=SIZE_MAX)j_parse_string(r.body,&np,cname,sizeof(cname));
                    }

                    total_orders++;
                    add_status(status);
                    if(strcmp(status,"cancelled")!=0){
                        long long cents=parse_amount(amount);
                        add_total(cname,currency,cents);
                    }

                    /* check for more elements */
                    j_skip_ws(r.body,&p);
                    if(r.body[p]==','){p++;continue;}
                    if(r.body[p]==']')break;
                    break;
                }
            }
        }

        /* next_cursor */
        size_t ncp=j_find_key(r.body,0,"next_cursor");
        if(ncp==SIZE_MAX||r.body[ncp]=='n'){
            free(r.headers);free(r.body);
            break;
        }
        j_parse_string(r.body,&ncp,cursor,sizeof(cursor));
        free(r.headers);free(r.body);
        first_page=0;
    }

    /* Output */
    qsort(ctots,n_ctot,sizeof(CTot),cmp_ctot);
    qsort(scounts,n_scount,sizeof(SCount),cmp_sc);

    for(int i=0;i<n_ctot;i++){
        char amt[64];
        fmt_amount(ctots[i].cents,amt,sizeof(amt));
        printf("total %s %s %s\n",ctots[i].currency,amt,ctots[i].name);
    }
    for(int i=0;i<n_scount;i++){
        printf("status %s %d\n",scounts[i].status,scounts[i].count);
    }
    printf("orders %d pages %d retries %d reauth %d\n",total_orders,pages,retries,reauth);
    return 0;
}

use std::io::{Read, Write, BufReader};
use std::net::TcpStream;
use std::collections::HashMap;
use std::thread::sleep;
use std::time::Duration;
use std::env;
use std::fs;

// ==================== JSON Parser ====================

#[derive(Clone)]
enum JsonValue {
    Object(Vec<(String, JsonValue)>),
    Array(Vec<JsonValue>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

struct JP<'a> { d: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(d: &'a [u8]) -> Self { JP { d, p: 0 } }
    fn ws(&mut self) { while self.p < self.d.len() && matches!(self.d[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn pk(&self) -> Option<u8> { if self.p < self.d.len() { Some(self.d[self.p]) } else { None } }

    fn parse(&mut self) -> JsonValue {
        self.ws();
        match self.pk() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => JsonValue::Str(self.string()),
            Some(b't') => { self.p += 4; JsonValue::Bool(true) }
            Some(b'f') => { self.p += 5; JsonValue::Bool(false) }
            Some(b'n') => { self.p += 4; JsonValue::Null }
            _ => self.num(),
        }
    }

    fn obj(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut f = Vec::new();
        if self.pk() == Some(b'}') { self.p += 1; return JsonValue::Object(f); }
        loop {
            self.ws(); let k = self.string(); self.ws(); self.p += 1; self.ws();
            let v = self.parse(); f.push((k, v)); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Object(f)
    }

    fn arr(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut a = Vec::new();
        if self.pk() == Some(b']') { self.p += 1; return JsonValue::Array(a); }
        loop {
            self.ws(); a.push(self.parse()); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Array(a)
    }

    fn string(&mut self) -> String {
        self.p += 1;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = self.d[self.p];
            if c == b'"' { self.p += 1; break; }
            if c == b'\\' {
                self.p += 1;
                let c2 = self.d[self.p];
                match c2 {
                    b'"' => { buf.push(b'"'); self.p += 1; }
                    b'\\' => { buf.push(b'\\'); self.p += 1; }
                    b'/' => { buf.push(b'/'); self.p += 1; }
                    b'b' => { buf.push(8); self.p += 1; }
                    b'f' => { buf.push(12); self.p += 1; }
                    b'n' => { buf.push(b'\n'); self.p += 1; }
                    b'r' => { buf.push(b'\r'); self.p += 1; }
                    b't' => { buf.push(b'\t'); self.p += 1; }
                    b'u' => {
                        self.p += 1;
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            utf8(&mut buf, code);
                        } else {
                            utf8(&mut buf, cp);
                        }
                    }
                    _ => { buf.push(c2); self.p += 1; }
                }
            } else { buf.push(c); self.p += 1; }
        }
        String::from_utf8(buf).unwrap()
    }

    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.d[self.p];
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => 0,
            };
            self.p += 1;
        }
        v
    }

    fn num(&mut self) -> JsonValue {
        let s = self.p;
        if self.d[self.p] == b'-' { self.p += 1; }
        while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.d.len() && self.d[self.p] == b'.' {
            self.p += 1;
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        if self.p < self.d.len() && (self.d[self.p] == b'e' || self.d[self.p] == b'E') {
            self.p += 1;
            if self.d[self.p] == b'+' || self.d[self.p] == b'-' { self.p += 1; }
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        JsonValue::Num(std::str::from_utf8(&self.d[s..self.p]).unwrap().parse::<f64>().unwrap())
    }
}

fn utf8(buf: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 { buf.push(cp as u8); }
    else if cp < 0x800 { buf.push(0xC0|(cp>>6) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else if cp < 0x10000 { buf.push(0xE0|(cp>>12) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else { buf.push(0xF0|(cp>>18) as u8); buf.push(0x80|((cp>>12)&0x3F) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
}

fn pj(s: &str) -> JsonValue { JP::new(s.as_bytes()).parse() }

fn jg<'a>(v: &'a JsonValue, k: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(f) = v { for (key, val) in f { if key == k { return Some(val); } } }
    None
}
fn js(v: &JsonValue, k: &str) -> Option<String> {
    jg(v, k).and_then(|x| if let JsonValue::Str(s) = x { Some(s.clone()) } else { None })
}
fn jn(v: &JsonValue, k: &str) -> Option<f64> {
    jg(v, k).and_then(|x| if let JsonValue::Num(n) = x { Some(*n) } else { None })
}
fn ja<'a>(v: &'a JsonValue, k: &str) -> Option<&'a Vec<JsonValue>> {
    jg(v, k).and_then(|x| if let JsonValue::Array(a) = x { Some(a) } else { None })
}
fn jos(v: &JsonValue, k: &str) -> Option<String> {
    match jg(v, k) { Some(JsonValue::Str(s)) => Some(s.clone()), _ => None }
}

// ==================== Base64 ====================

fn b64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut o = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i+1 < data.len() { data[i+1] as u32 } else { 0 };
        let b2 = if i+2 < data.len() { data[i+2] as u32 } else { 0 };
        let n = (b0<<16)|(b1<<8)|b2;
        o.push(T[(n>>18) as usize] as char);
        o.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() { o.push(T[((n>>6)&63) as usize] as char); } else { o.push('='); }
        if i+2 < data.len() { o.push(T[(n&63) as usize] as char); } else { o.push('='); }
        i += 3;
    }
    o
}

// ==================== URL encoding ====================

fn fenc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'*' => o.push(b as char),
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn penc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'~' => o.push(b as char),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ==================== HTTP ====================

struct Resp { status: u16, headers: Vec<(String,String)>, body: Vec<u8> }

fn purl(url: &str) -> (String, u16, String) {
    let r = url.strip_prefix("http://").unwrap_or(url);
    let sl = r.find('/').unwrap_or(r.len());
    let hp = &r[..sl];
    let path = if sl < r.len() { &r[sl..] } else { "/" };
    let (h, p) = match hp.rfind(':') {
        Some(i) => (hp[..i].to_string(), hp[i+1..].parse::<u16>().unwrap_or(80)),
        None => (hp.to_string(), 80),
    };
    (h, p, path.to_string())
}

fn rline(r: &mut BufReader<TcpStream>) -> String {
    let mut l = String::new();
    r.read_line(&mut l).unwrap();
    if l.ends_with('\n') { l.pop(); }
    if l.ends_with('\r') { l.pop(); }
    l
}

fn http(method: &str, host: &str, port: u16, path: &str, hdrs: &[(String,String)], body: Option<&[u8]>) -> Resp {
    let mut s = TcpStream::connect((host, port)).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host);
    for (k, v) in hdrs { req.push_str(&format!("{}: {}\r\n", k, v)); }
    if let Some(b) = body { req.push_str(&format!("Content-Length: {}\r\n", b.len())); }
    req.push_str("Connection: close\r\n\r\n");
    s.write_all(req.as_bytes()).unwrap();
    if let Some(b) = body { s.write_all(b).unwrap(); }
    s.flush().unwrap();

    let mut r = BufReader::new(s);
    let sl = rline(&mut r);
    let status: u16 = sl.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    loop {
        let l = rline(&mut r);
        if l.is_empty() { break; }
        if let Some(c) = l.find(':') {
            headers.push((l[..c].trim().to_lowercase(), l[c+1..].trim().to_string()));
        }
    }

    let mut chunked = false;
    let mut clen: Option<usize> = None;
    for (k, v) in &headers {
        if k == "transfer-encoding" && v.to_lowercase().contains("chunked") { chunked = true; }
        if k == "content-length" { clen = v.trim().parse().ok(); }
    }

    let body_bytes = if chunked {
        let mut bd = Vec::new();
        loop {
            let szl = rline(&mut r);
            let hx = szl.split(';').next().unwrap_or("").trim();
            if hx.is_empty() { break; }
            let sz = usize::from_str_radix(hx, 16).unwrap();
            if sz == 0 {
                loop { let t = rline(&mut r); if t.is_empty() { break; } }
                break;
            }
            let mut ch = vec![0u8; sz];
            r.read_exact(&mut ch).unwrap();
            bd.extend_from_slice(&ch);
            rline(&mut r);
        }
        bd
    } else if let Some(len) = clen {
        let mut bd = vec![0u8; len];
        r.read_exact(&mut bd).unwrap();
        bd
    } else {
        let mut bd = Vec::new();
        r.read_to_end(&mut bd).unwrap();
        bd
    };

    Resp { status, headers, body: body_bytes }
}

fn gh(r: &Resp, n: &str) -> String {
    for (k, v) in &r.headers { if k == n { return v.clone(); } }
    String::new()
}

// ==================== Amount ====================

fn pamt(s: &str) -> i64 {
    let b = s.as_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == b'-' { neg = true; i += 1; }
    let mut ip: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() { ip = ip*10 + (b[i]-b'0') as i64; i += 1; }
    let mut fp: i64 = 0;
    if i < b.len() && b[i] == b'.' {
        i += 1;
        let mut d = 0;
        while i < b.len() && b[i].is_ascii_digit() { fp = fp*10 + (b[i]-b'0') as i64; d += 1; i += 1; }
        if d == 1 { fp *= 10; }
    }
    let t = ip*100 + fp;
    if neg { -t } else { t }
}

fn fmtc(c: i64) -> String {
    if c < 0 {
        let a = (c as i128).wrapping_neg() as u64;
        format!("-{}.{:02}", a/100, a%100)
    } else {
        format!("{}.{:02}", c/100, c%100)
    }
}

// ==================== Token ====================

fn get_tok(host: &str, port: u16, pp: &str, cid: &str, csec: &str, scope: &str) -> String {
    let tp = format!("{}/oauth/token", pp);
    let cred = format!("{}:{}", fenc(cid), fenc(csec));
    let auth = format!("Basic {}", b64(cred.as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", fenc(scope));
    let hdrs = vec![
        ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
        ("Authorization".to_string(), auth),
    ];
    let resp = http("POST", host, port, &tp, &hdrs, Some(body.as_bytes()));
    if resp.status != 200 {
        let bs = String::from_utf8_lossy(&resp.body).to_string();
        println!("ERROR {} {}", resp.status, bs);
        std::process::exit(0);
    }
    let bs = String::from_utf8(resp.body).unwrap();
    js(&pj(&bs), "access_token").unwrap()
}

// ==================== Main ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cs = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cj = pj(&cs);
    let cid = js(&cj, "client_id").unwrap();
    let csec = js(&cj, "client_secret").unwrap();
    let scope = js(&cj, "scope").unwrap();
    let psz = jn(&cj, "page_size").unwrap() as i64;

    let (host, port, pp) = purl(base_url);

    let mut tok = get_tok(&host, port, &pp, &cid, &csec, &scope);

    let mut orders: Vec<JsonValue> = Vec::new();
    let mut cursor: Option<String> = None;
    let mut pages: u64 = 0;
    let mut retries: u64 = 0;
    let mut reauth: u64 = 0;
    let mut tok_used = false;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}?limit={}&cursor={}", pp, psz, penc(c))
        } else {
            format!("{}?limit={}", pp, psz)
        };

        loop {
            let ah = format!("Bearer {}", tok);
            let hdrs = vec![("Authorization".to_string(), ah)];
            let resp = http("GET", &host, port, &path, &hdrs, None);

            match resp.status {
                200 => {
                    pages += 1;
                    let bs = String::from_utf8(resp.body).unwrap();
                    let j = pj(&bs);
                    if let Some(data) = ja(&j, "data") {
                        for item in data { orders.push(item.clone()); }
                    }
                    cursor = jos(&j, "next_cursor");
                    tok_used = true;
                    break;
                }
                429 => {
                    retries += 1;
                    let ra: u64 = gh(&resp, "retry-after").trim().parse().unwrap_or(1);
                    sleep(Duration::from_secs(ra));
                }
                503 => {
                    retries += 1;
                }
                401 => {
                    if !tok_used {
                        let bs = String::from_utf8_lossy(&resp.body).to_string();
                        println!("ERROR {} {}", resp.status, bs);
                        return;
                    }
                    tok = get_tok(&host, port, &pp, &cid, &csec, &scope);
                    reauth += 1;
                    tok_used = false;
                }
                _ => {
                    let bs = String::from_utf8_lossy(&resp.body).to_string();
                    println!("ERROR {} {}", resp.status, bs);
                    return;
                }
            }
        }
        if cursor.is_none() { break; }
    }

    let mut totals: HashMap<(String,String), i64> = HashMap::new();
    let mut scounts: HashMap<String, u64> = HashMap::new();

    for o in &orders {
        let st = js(o, "status").unwrap_or_default();
        *scounts.entry(st.clone()).or_insert(0) += 1;
        if st != "cancelled" {
            let nm = jg(o, "customer").and_then(|c| js(c, "name")).unwrap_or_default();
            let cur = js(o, "currency").unwrap_or_default();
            let amt = pamt(&js(o, "amount").unwrap_or_else(|| "0".to_string()));
            *totals.entry((nm, cur)).or_insert(0) += amt;
        }
    }

    let mut tl: Vec<(String,String,i64)> = totals.into_iter().map(|((n,c),v)| (n,c,v)).collect();
    tl.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    for (n,c,v) in &tl { println!("total {} {} {}", c, fmtc(*v), n); }

    let mut sl: Vec<(String,u64)> = scounts.into_iter().collect();
    sl.sort_by(|a,b| a.0.cmp(&b.0));
    for (s,c) in &sl { println!("status {} {}", s, c); }

    println!("orders {} pages {} retries {} reauth {}", orders.len(), pages, retries, reauth);
}

use std::io::{Read, Write, BufRead, BufReader};
use std::net::TcpStream;
use std::collections::HashMap;
use std::thread::sleep;
use std::time::Duration;
use std::env;
use std::fs;

// ==================== JSON Parser ====================

#[derive(Clone)]
enum JsonValue {
    Object(Vec<(String, JsonValue)>),
    Array(Vec<JsonValue>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

struct JP<'a> { d: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(d: &'a [u8]) -> Self { JP { d, p: 0 } }
    fn ws(&mut self) { while self.p < self.d.len() && matches!(self.d[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn pk(&self) -> Option<u8> { if self.p < self.d.len() { Some(self.d[self.p]) } else { None } }

    fn parse(&mut self) -> JsonValue {
        self.ws();
        match self.pk() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => JsonValue::Str(self.string()),
            Some(b't') => { self.p += 4; JsonValue::Bool(true) }
            Some(b'f') => { self.p += 5; JsonValue::Bool(false) }
            Some(b'n') => { self.p += 4; JsonValue::Null }
            _ => self.num(),
        }
    }

    fn obj(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut f = Vec::new();
        if self.pk() == Some(b'}') { self.p += 1; return JsonValue::Object(f); }
        loop {
            self.ws(); let k = self.string(); self.ws(); self.p += 1; self.ws();
            let v = self.parse(); f.push((k, v)); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Object(f)
    }

    fn arr(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut a = Vec::new();
        if self.pk() == Some(b']') { self.p += 1; return JsonValue::Array(a); }
        loop {
            self.ws(); a.push(self.parse()); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Array(a)
    }

    fn string(&mut self) -> String {
        self.p += 1;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = self.d[self.p];
            if c == b'"' { self.p += 1; break; }
            if c == b'\\' {
                self.p += 1;
                let c2 = self.d[self.p];
                match c2 {
                    b'"' => { buf.push(b'"'); self.p += 1; }
                    b'\\' => { buf.push(b'\\'); self.p += 1; }
                    b'/' => { buf.push(b'/'); self.p += 1; }
                    b'b' => { buf.push(8); self.p += 1; }
                    b'f' => { buf.push(12); self.p += 1; }
                    b'n' => { buf.push(b'\n'); self.p += 1; }
                    b'r' => { buf.push(b'\r'); self.p += 1; }
                    b't' => { buf.push(b'\t'); self.p += 1; }
                    b'u' => {
                        self.p += 1;
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            utf8(&mut buf, code);
                        } else {
                            utf8(&mut buf, cp);
                        }
                    }
                    _ => { buf.push(c2); self.p += 1; }
                }
            } else { buf.push(c); self.p += 1; }
        }
        String::from_utf8(buf).unwrap()
    }

    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.d[self.p];
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => 0,
            };
            self.p += 1;
        }
        v
    }

    fn num(&mut self) -> JsonValue {
        let s = self.p;
        if self.d[self.p] == b'-' { self.p += 1; }
        while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.d.len() && self.d[self.p] == b'.' {
            self.p += 1;
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        if self.p < self.d.len() && (self.d[self.p] == b'e' || self.d[self.p] == b'E') {
            self.p += 1;
            if self.d[self.p] == b'+' || self.d[self.p] == b'-' { self.p += 1; }
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        JsonValue::Num(std::str::from_utf8(&self.d[s..self.p]).unwrap().parse::<f64>().unwrap())
    }
}

fn utf8(buf: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 { buf.push(cp as u8); }
    else if cp < 0x800 { buf.push(0xC0|(cp>>6) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else if cp < 0x10000 { buf.push(0xE0|(cp>>12) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else { buf.push(0xF0|(cp>>18) as u8); buf.push(0x80|((cp>>12)&0x3F) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
}

fn pj(s: &str) -> JsonValue { JP::new(s.as_bytes()).parse() }

fn jg<'a>(v: &'a JsonValue, k: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(f) = v { for (key, val) in f { if key == k { return Some(val); } } }
    None
}
fn js(v: &JsonValue, k: &str) -> Option<String> {
    jg(v, k).and_then(|x| if let JsonValue::Str(s) = x { Some(s.clone()) } else { None })
}
fn jn(v: &JsonValue, k: &str) -> Option<f64> {
    jg(v, k).and_then(|x| if let JsonValue::Num(n) = x { Some(*n) } else { None })
}
fn ja<'a>(v: &'a JsonValue, k: &str) -> Option<&'a Vec<JsonValue>> {
    jg(v, k).and_then(|x| if let JsonValue::Array(a) = x { Some(a) } else { None })
}
fn jos(v: &JsonValue, k: &str) -> Option<String> {
    match jg(v, k) { Some(JsonValue::Str(s)) => Some(s.clone()), _ => None }
}

// ==================== Base64 ====================

fn b64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut o = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i+1 < data.len() { data[i+1] as u32 } else { 0 };
        let b2 = if i+2 < data.len() { data[i+2] as u32 } else { 0 };
        let n = (b0<<16)|(b1<<8)|b2;
        o.push(T[(n>>18) as usize] as char);
        o.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() { o.push(T[((n>>6)&63) as usize] as char); } else { o.push('='); }
        if i+2 < data.len() { o.push(T[(n&63) as usize] as char); } else { o.push('='); }
        i += 3;
    }
    o
}

// ==================== URL encoding ====================

fn fenc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'*' => o.push(b as char),
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn penc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'~' => o.push(b as char),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ==================== HTTP ====================

struct Resp { status: u16, headers: Vec<(String,String)>, body: Vec<u8> }

fn purl(url: &str) -> (String, u16, String) {
    let r = url.strip_prefix("http://").unwrap_or(url);
    let sl = r.find('/').unwrap_or(r.len());
    let hp = &r[..sl];
    let path = if sl < r.len() { &r[sl..] } else { "/" };
    let (h, p) = match hp.rfind(':') {
        Some(i) => (hp[..i].to_string(), hp[i+1..].parse::<u16>().unwrap_or(80)),
        None => (hp.to_string(), 80),
    };
    (h, p, path.to_string())
}

fn rline(r: &mut BufReader<TcpStream>) -> String {
    let mut l = String::new();
    r.read_line(&mut l).unwrap();
    if l.ends_with('\n') { l.pop(); }
    if l.ends_with('\r') { l.pop(); }
    l
}

fn http(method: &str, host: &str, port: u16, path: &str, hdrs: &[(String,String)], body: Option<&[u8]>) -> Resp {
    let mut s = TcpStream::connect((host, port)).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host);
    for (k, v) in hdrs { req.push_str(&format!("{}: {}\r\n", k, v)); }
    if let Some(b) = body { req.push_str(&format!("Content-Length: {}\r\n", b.len())); }
    req.push_str("Connection: close\r\n\r\n");
    s.write_all(req.as_bytes()).unwrap();
    if let Some(b) = body { s.write_all(b).unwrap(); }
    s.flush().unwrap();

    let mut r = BufReader::new(s);
    let sl = rline(&mut r);
    let status: u16 = sl.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    loop {
        let l = rline(&mut r);
        if l.is_empty() { break; }
        if let Some(c) = l.find(':') {
            headers.push((l[..c].trim().to_lowercase(), l[c+1..].trim().to_string()));
        }
    }

    let mut chunked = false;
    let mut clen: Option<usize> = None;
    for (k, v) in &headers {
        if k == "transfer-encoding" && v.to_lowercase().contains("chunked") { chunked = true; }
        if k == "content-length" { clen = v.trim().parse().ok(); }
    }

    let body_bytes = if chunked {
        let mut bd = Vec::new();
        loop {
            let szl = rline(&mut r);
            let hx = szl.split(';').next().unwrap_or("").trim();
            if hx.is_empty() { break; }
            let sz = usize::from_str_radix(hx, 16).unwrap();
            if sz == 0 {
                loop { let t = rline(&mut r); if t.is_empty() { break; } }
                break;
            }
            let mut ch = vec![0u8; sz];
            r.read_exact(&mut ch).unwrap();
            bd.extend_from_slice(&ch);
            rline(&mut r);
        }
        bd
    } else if let Some(len) = clen {
        let mut bd = vec![0u8; len];
        r.read_exact(&mut bd).unwrap();
        bd
    } else {
        let mut bd = Vec::new();
        r.read_to_end(&mut bd).unwrap();
        bd
    };

    Resp { status, headers, body: body_bytes }
}

fn gh(r: &Resp, n: &str) -> String {
    for (k, v) in &r.headers { if k == n { return v.clone(); } }
    String::new()
}

// ==================== Amount ====================

fn pamt(s: &str) -> i64 {
    let b = s.as_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == b'-' { neg = true; i += 1; }
    let mut ip: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() { ip = ip*10 + (b[i]-b'0') as i64; i += 1; }
    let mut fp: i64 = 0;
    if i < b.len() && b[i] == b'.' {
        i += 1;
        let mut d = 0;
        while i < b.len() && b[i].is_ascii_digit() { fp = fp*10 + (b[i]-b'0') as i64; d += 1; i += 1; }
        if d == 1 { fp *= 10; }
    }
    let t = ip*100 + fp;
    if neg { -t } else { t }
}

fn fmtc(c: i64) -> String {
    if c < 0 {
        let a = (c as i128).wrapping_neg() as u64;
        format!("-{}.{:02}", a/100, a%100)
    } else {
        format!("{}.{:02}", c/100, c%100)
    }
}

// ==================== Token ====================

fn get_tok(host: &str, port: u16, pp: &str, cid: &str, csec: &str, scope: &str) -> String {
    let tp = format!("{}/oauth/token", pp);
    let cred = format!("{}:{}", fenc(cid), fenc(csec));
    let auth = format!("Basic {}", b64(cred.as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", fenc(scope));
    let hdrs = vec![
        ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
        ("Authorization".to_string(), auth),
    ];
    let resp = http("POST", host, port, &tp, &hdrs, Some(body.as_bytes()));
    if resp.status != 200 {
        let bs = String::from_utf8_lossy(&resp.body).to_string();
        println!("ERROR {} {}", resp.status, bs);
        std::process::exit(0);
    }
    let bs = String::from_utf8(resp.body).unwrap();
    js(&pj(&bs), "access_token").unwrap()
}

// ==================== Main ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cs = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cj = pj(&cs);
    let cid = js(&cj, "client_id").unwrap();
    let csec = js(&cj, "client_secret").unwrap();
    let scope = js(&cj, "scope").unwrap();
    let psz = jn(&cj, "page_size").unwrap() as i64;

    let (host, port, pp) = purl(base_url);

    let mut tok = get_tok(&host, port, &pp, &cid, &csec, &scope);

    let mut orders: Vec<JsonValue> = Vec::new();
    let mut cursor: Option<String> = None;
    let mut pages: u64 = 0;
    let mut retries: u64 = 0;
    let mut reauth: u64 = 0;
    let mut tok_used = false;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}?limit={}&cursor={}", pp, psz, penc(c))
        } else {
            format!("{}?limit={}", pp, psz)
        };

        loop {
            let ah = format!("Bearer {}", tok);
            let hdrs = vec![("Authorization".to_string(), ah)];
            let resp = http("GET", &host, port, &path, &hdrs, None);

            match resp.status {
                200 => {
                    pages += 1;
                    let bs = String::from_utf8(resp.body).unwrap();
                    let j = pj(&bs);
                    if let Some(data) = ja(&j, "data") {
                        for item in data { orders.push(item.clone()); }
                    }
                    cursor = jos(&j, "next_cursor");
                    tok_used = true;
                    break;
                }
                429 => {
                    retries += 1;
                    let ra: u64 = gh(&resp, "retry-after").trim().parse().unwrap_or(1);
                    sleep(Duration::from_secs(ra));
                }
                503 => {
                    retries += 1;
                }
                401 => {
                    if !tok_used {
                        let bs = String::from_utf8_lossy(&resp.body).to_string();
                        println!("ERROR {} {}", resp.status, bs);
                        return;
                    }
                    tok = get_tok(&host, port, &pp, &cid, &csec, &scope);
                    reauth += 1;
                    tok_used = false;
                }
                _ => {
                    let bs = String::from_utf8_lossy(&resp.body).to_string();
                    println!("ERROR {} {}", resp.status, bs);
                    return;
                }
            }
        }
        if cursor.is_none() { break; }
    }

    let mut totals: HashMap<(String,String), i64> = HashMap::new();
    let mut scounts: HashMap<String, u64> = HashMap::new();

    for o in &orders {
        let st = js(o, "status").unwrap_or_default();
        *scounts.entry(st.clone()).or_insert(0) += 1;
        if st != "cancelled" {
            let nm = jg(o, "customer").and_then(|c| js(c, "name")).unwrap_or_default();
            let cur = js(o, "currency").unwrap_or_default();
            let amt = pamt(&js(o, "amount").unwrap_or_else(|| "0".to_string()));
            *totals.entry((nm, cur)).or_insert(0) += amt;
        }
    }

    let mut tl: Vec<(String,String,i64)> = totals.into_iter().map(|((n,c),v)| (n,c,v)).collect();
    tl.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    for (n,c,v) in &tl { println!("total {} {} {}", c, fmtc(*v), n); }

    let mut sl: Vec<(String,u64)> = scounts.into_iter().collect();
    sl.sort_by(|a,b| a.0.cmp(&b.0));
    for (s,c) in &sl { println!("status {} {}", s, c); }

    println!("orders {} pages {} retries {} reauth {}", orders.len(), pages, retries, reauth);
}

#!/usr/bin/env python3
import sys
import json
import http.client
from urllib.parse import urlparse


def escape_string(s):
    result = []
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        else:
            result.append(ch)
    return ''.join(result)


def parse_sse(data):
    text = data.decode('utf-8')
    events = []
    event_type = None
    data_lines = []

    lines = []
    i = 0
    current = []
    while i < len(text):
        if text[i] == '\r':
            lines.append(''.join(current))
            current = []
            if i + 1 < len(text) and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
        elif text[i] == '\n':
            lines.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(text[i])
            i += 1
    if current:
        lines.append(''.join(current))

    for line in lines:
        if line == '':
            if event_type is not None or data_lines:
                events.append((event_type, '\n'.join(data_lines)))
            event_type = None
            data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('event:'):
            val = line[6:]
            if val.startswith(' '):
                val = val[1:]
            event_type = val
        elif line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            data_lines.append(val)

    return events


def make_request(base_url, api_key, body):
    parsed = urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or 80

    conn = http.client.HTTPConnection(host, port)
    path = parsed.path + '/v1/messages'
    body_bytes = json.dumps(body).encode('utf-8')

    headers = {
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
    }

    conn.request('POST', path, body=body_bytes, headers=headers)
    response = conn.getresponse()
    status = response.status
    resp_body = response.read()
    conn.close()

    return status, resp_body


def parse_response(events):
    blocks = {}
    stop_reason = None
    input_tokens = 0
    output_tokens = 0
    cache_read_tokens = 0

    for event_type, data_str in events:
        if not data_str:
            continue
        try:
            data = json.loads(data_str)
        except json.JSONDecodeError:
            continue

        if event_type == 'message_start':
            msg = data.get('message', {})
            usage = msg.get('usage', {})
            input_tokens += usage.get('input_tokens', 0)
            cache_read_tokens += usage.get('cache_read_input_tokens', 0)
        elif event_type == 'content_block_start':
            index = data['index']
            cb = data['content_block']
            blocks[index] = {
                'type': cb['type'],
                'thinking': '',
                'signature': '',
                'text': '',
                'id': cb.get('id', ''),
                'name': cb.get('name', ''),
                'input_json': '',
            }
        elif event_type == 'content_block_delta':
            index = data['index']
            delta = data['delta']
            if index not in blocks:
                continue
            dtype = delta.get('type', '')
            if dtype == 'thinking_delta':
                blocks[index]['thinking'] += delta.get('thinking', '')
            elif dtype == 'signature_delta':
                blocks[index]['signature'] += delta.get('signature', '')
            elif dtype == 'text_delta':
                blocks[index]['text'] += delta.get('text', '')
            elif dtype == 'input_json_delta':
                blocks[index]['input_json'] += delta.get('partial_json', '')
        elif event_type == 'message_delta':
            delta = data.get('delta', {})
            if 'stop_reason' in delta:
                stop_reason = delta['stop_reason']
            usage = data.get('usage', {})
            output_tokens += usage.get('output_tokens', 0)

    ordered = [blocks[i] for i in sorted(blocks.keys())]
    return ordered, stop_reason, input_tokens, output_tokens, cache_read_tokens


def execute_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        if unit == 'code_points':
            return str(len(text)), False
        elif unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        elif unit == 'utf16_units':
            count = sum(2 if ord(c) > 0xFFFF else 1 for c in text)
            return str(count), False
        else:
            return f'unsupported unit: {unit}', True
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return text[::-1], False
    else:
        return f'unknown tool: {name}', True


def print_blocks(blocks):
    for block in blocks:
        if block['type'] == 'thinking':
            print(f'thinking {escape_string(block["thinking"])}')
            print(f'signature {escape_string(block["signature"])}')
        elif block['type'] == 'text':
            print(f'text {escape_string(block["text"])}')
        elif block['type'] == 'tool_use':
            print(f'tool_use {escape_string(block["id"])} {escape_string(block["name"])} {escape_string(block["input_json"])}')


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f'{data_dir}/request.json', 'r') as f:
        req = json.load(f)

    api_key = req['api_key']
    model = req['model']
    max_tokens = req['max_tokens']
    thinking_budget = req['thinking_budget']
    system = req['system']
    prompt = req['prompt']
    tools = req['tools']

    # Request 1
    body1 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [{'role': 'user', 'content': prompt}],
    }

    print('request 1')

    status1, resp1 = make_request(base_url, api_key, body1)

    if status1 != 200:
        try:
            err = json.loads(resp1)
            print(f'ERROR {status1} {err["error"]["type"]}: {err["error"]["message"]}')
        except Exception:
            print(f'ERROR {status1}')
        sys.exit(0)

    events1 = parse_sse(resp1)
    blocks1, stop1, inp1, out1, cr1 = parse_response(events1)
    print_blocks(blocks1)
    print(f'stop_reason {stop1}')

    # Execute tools
    tool_results = []
    for block in blocks1:
        if block['type'] == 'tool_use':
            input_obj = json.loads(block['input_json']) if block['input_json'] else {}
            result, is_error = execute_tool(block['name'], input_obj)
            tool_results.append({'id': block['id'], 'result': result, 'is_error': is_error})

    for tr in tool_results:
        if tr['is_error']:
            print(f'error {escape_string(tr["id"])} {escape_string(tr["result"])}')
        else:
            print(f'result {escape_string(tr["id"])} {escape_string(tr["result"])}')

    # Build request 2
    assistant_content = []
    for block in blocks1:
        if block['type'] == 'thinking':
            assistant_content.append({
                'type': 'thinking',
                'thinking': block['thinking'],
                'signature': block['signature'],
            })
        elif block['type'] == 'text':
            assistant_content.append({
                'type': 'text',
                'text': block['text'],
            })
        elif block['type'] == 'tool_use':
            input_obj = json.loads(block['input_json']) if block['input_json'] else {}
            assistant_content.append({
                'type': 'tool_use',
                'id': block['id'],
                'name': block['name'],
                'input': input_obj,
            })

    tool_result_content = []
    for tr in tool_results:
        blk = {'type': 'tool_result', 'tool_use_id': tr['id'], 'content': tr['result']}
        if tr['is_error']:
            blk['is_error'] = True
        tool_result_content.append(blk)

    body2 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [
            {'role': 'user', 'content': prompt},
            {'role': 'assistant', 'content': assistant_content},
            {'role': 'user', 'content': tool_result_content},
        ],
    }

    print('request 2')

    status2, resp2 = make_request(base_url, api_key, body2)

    if status2 != 200:
        try:
            err = json.loads(resp2)
            print(f'ERROR {status2} {err["error"]["type"]}: {err["error"]["message"]}')
        except Exception:
            print(f'ERROR {status2}')
        sys.exit(0)

    events2 = parse_sse(resp2)
    blocks2, stop2, inp2, out2, cr2 = parse_response(events2)
    print_blocks(blocks2)
    print(f'stop_reason {stop2}')

    print(f'usage input={inp1 + inp2} output={out1 + out2} cache_read={cr1 + cr2}')


main()

import Foundation

// MARK: - URL Parsing

struct ParsedURL {
    var host: String
    var port: Int
    var path: String
}

func parseURL(_ url: String) -> ParsedURL {
    // Expect http://host:port/path
    var rest = url
    if rest.hasPrefix("http://") {
        rest = String(rest.dropFirst(7))
    }
    // Split host:port from path
    var hostPort = ""
    var path = "/"
    if let slashIdx = rest.firstIndex(of: "/") {
        hostPort = String(rest[rest.startIndex..<slashIdx])
        path = String(rest[slashIdx...])
    } else {
        hostPort = rest
    }
    var host = hostPort
    var port = 80
    if let colonIdx = hostPort.lastIndex(of: ":") {
        host = String(hostPort[hostPort.startIndex..<colonIdx])
        port = Int(hostPort[hostPort.index(after: colonIdx)...]) ?? 80
    }
    return ParsedURL(host: host, port: port, path: path)
}

// MARK: - Raw HTTP Client

func findHeaderEnd(_ data: [UInt8]) -> Int? {
    if data.count < 4 { return nil }
    for i in 0...(data.count - 4) {
        if data[i] == 13 && data[i+1] == 10 && data[i+2] == 13 && data[i+3] == 10 {
            return i + 4
        }
    }
    return nil
}

func decodeChunked(_ data: [UInt8]) -> [UInt8] {
    var result = [UInt8]()
    var pos = 0
    while pos < data.count {
        // Read chunk size line
        var lineStart = pos
        while pos < data.count && data[pos] != 0x0D {
            pos += 1
        }
        let line = String(bytes: data[lineStart..<pos], encoding: .ascii) ?? ""
        // Skip \r\n
        if pos + 1 < data.count { pos += 2 } else { pos = data.count }

        // Parse hex size (before any ';')
        let sizeStr = line.components(separatedBy: ";")[0].trimmingCharacters(in: .whitespaces)
        let size = Int(sizeStr, radix: 16) ?? 0

        if size == 0 { break }

        // Read chunk data
        if pos + size <= data.count {
            result.append(contentsOf: data[pos..<(pos + size)])
        }
        pos += size

        // Skip \r\n after chunk data
        if pos + 1 < data.count { pos += 2 } else { pos = data.count }
    }
    return result
}

struct HTTPResponse {
    var status: Int
    var headers: [(String, String)]
    var body: String
}

func performRequest(host: String, port: Int, method: String, path: String, headers: [(String, String)], body: String?) -> HTTPResponse {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0 { fatalError("socket failed") }

    // Resolve host
    var hints = addrinfo(ai_flags: 0, ai_family: AF_INET, ai_socktype: SOCK_STREAM, ai_protocol: IPPROTO_TCP, ai_addrlen: 0, ai_canonname: nil, ai_addr: nil, ai_next: nil)
    var res: UnsafeMutablePointer<addrinfo>?
    let err = getaddrinfo(host, String(port), &hints, &res)
    if err != 0 || res == nil { fatalError("getaddrinfo failed for \(host):\(port)") }

    let connectResult = connect(fd, res!.pointee.ai_addr, res!.pointee.ai_addrlen)
    freeaddrinfo(res)
    if connectResult < 0 { fatalError("connect failed to \(host):\(port)") }

    // Build request
    var request = "\(method) \(path) HTTP/1.1\r\n"
    request += "Host: \(host):\(port)\r\n"
    for (name, value) in headers {
        request += "\(name): \(value)\r\n"
    }
    if let b = body {
        let bodyBytes = Array(b.utf8)
        request += "Content-Length: \(bodyBytes.count)\r\n"
    }
    request += "\r\n"
    if let b = body {
        request += b
    }

    // Send
    let requestBytes = Array(request.utf8)
    var sent = 0
    while sent < requestBytes.count {
        let n = requestBytes.withUnsafeBufferPointer { buf in
            Foundation.send(fd, buf.baseAddress!.advanced(by: sent), requestBytes.count - sent, 0)
        }
        if n <= 0 { fatalError("send failed") }
        sent += n
    }

    // Receive all (Connection: close means server closes after response)
    var data = [UInt8]()
    let bufSize = 65536
    var buf = [UInt8](repeating: 0, count: bufSize)
    while true {
        let n = recv(fd, &buf, bufSize, 0)
        if n <= 0 { break }
        data.append(contentsOf: buf[0..<n])
    }
    close(fd)

    // Parse response
    guard let headerEnd = findHeaderEnd(data) else {
        fatalError("No header end found")
    }

    let headerData = Array(data[0..<headerEnd])
    let headerStr = String(bytes: headerData, encoding: .utf8) ?? ""
    let lines = headerStr.components(separatedBy: "\r\n")

    // Status line: HTTP/1.1 200 OK
    let statusParts = lines[0].components(separatedBy: " ")
    let status = Int(statusParts.count >= 2 ? statusParts[1] : "0") ?? 0

    // Headers
    var respHeaders: [(String, String)] = []
    var i = 1
    while i < lines.count && !lines[i].isEmpty {
        if let colonIdx = lines[i].firstIndex(of: ":") {
            let name = String(lines[i][lines[i].startIndex..<colonIdx])
            let value = String(lines[i][lines[i].index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
            respHeaders.append((name, value))
        }
        i += 1
    }

    // Body
    let bodyBytes = Array(data[headerEnd...])

    let isChunked = respHeaders.contains { $0.0.lowercased() == "transfer-encoding" && $0.1.lowercased().contains("chunked") }

    let actualBodyBytes: [UInt8]
    if isChunked {
        actualBodyBytes = decodeChunked(bodyBytes)
    } else {
        actualBodyBytes = bodyBytes
    }

    let bodyStr = String(bytes: actualBodyBytes, encoding: .utf8) ?? ""

    return HTTPResponse(status: status, headers: respHeaders, body: bodyStr)
}

// MARK: - Encoding Helpers

func oauthFormEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) || // A-Z
           (byte >= 0x61 && byte <= 0x7A) || // a-z
           (byte >= 0x30 && byte <= 0x39) || // 0-9
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x2A { // -._*
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 0x20 {
            result.append("+")
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

func percentEncodeQuery(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) || // A-Z
           (byte >= 0x61 && byte <= 0x7A) || // a-z
           (byte >= 0x30 && byte <= 0x39) || // 0-9
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x7E { // -._~
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

// MARK: - Amount Parsing (exact cents, no floating point)

func parseAmount(_ s: String) -> Int64 {
    var str = s
    var negative = false
    if str.hasPrefix("-") {
        negative = true
        str = String(str.dropFirst())
    }

    var intPart = ""
    var fracPart = ""

    if let dotIdx = str.firstIndex(of: ".") {
        intPart = String(str[str.startIndex..<dotIdx])
        fracPart = String(str[str.index(after: dotIdx)...])
    } else {
        intPart = str
    }

    // Pad or truncate fracPart to 2 digits
    while fracPart.count < 2 { fracPart += "0" }
    if fracPart.count > 2 { fracPart = String(fracPart.prefix(2)) }

    let intVal = Int64(intPart) ?? 0
    let fracVal = Int64(fracPart) ?? 0
    var cents = intVal * 100 + fracVal
    if negative { cents = -cents }
    return cents
}

// MARK: - Format cents to string

func formatCents(_ cents: Int64) -> String {
    let negative = cents < 0
    let absCents = negative ? -cents : cents
    let intPart = absCents / 100
    let fracPart = absCents % 100
    let sign = negative ? "-" : ""
    return String(format: "%@%lld.%02lld", sign, intPart, fracPart)
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 3 else {
    exit(0)
}

let dataDir = args[1]
let baseUrl = args[2]

// Read client.json
let clientPath = dataDir + "/client.json"
guard let clientData = FileManager.default.contents(atPath: clientPath),
      let clientStr = String(data: clientData, encoding: .utf8),
      let clientJson = try? JSONSerialization.jsonObject(with: clientData) as? [String: Any] else {
    fatalError("Cannot read client.json")
}

let clientId = clientJson["client_id"] as? String ?? ""
let clientSecret = clientJson["client_secret"] as? String ?? ""
let scope = clientJson["scope"] as? String ?? ""
let pageSize = clientJson["page_size"] as? Int ?? 10

// Parse base URL
let parsed = parseURL(baseUrl)

// MARK: Step 1 - Get token

func getToken() -> String? {
    let encodedId = oauthFormEncode(clientId)
    let encodedSecret = oauthFormEncode(clientSecret)
    let credentials = "\(encodedId):\(encodedSecret)"
    let credData = Data(credentials.utf8)
    let b64 = credData.base64EncodedString()

    let tokenPath = parsed.path + "/oauth/token"
    let formBody = "grant_type=client_credentials&scope=\(percentEncodeQuery(scope))"

    let headers: [(String, String)] = [
        ("Content-Type", "application/x-www-form-urlencoded"),
        ("Authorization", "Basic \(b64)")
    ]

    let resp = performRequest(host: parsed.host, port: parsed.port, method: "POST", path: tokenPath, headers: headers, body: formBody)

    if resp.status != 200 {
        print("ERROR \(resp.status) \(resp.body)")
        exit(0)
    }

    guard let json = try? JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as? [String: Any],
          let token = json["access_token"] as? String else {
        print("ERROR \(resp.status) \(resp.body)")
        exit(0)
    }

    return token
}

// MARK: Step 2 - Fetch pages

var accessToken = getToken()!
var tokenIsFresh = true // first request with this token

var allOrders: [[String: Any]] = []
var pages = 0
var retries = 0
var reauths = 0

var cursor: String? = nil
var firstPage = true

while true {
    // Build path
    var path = parsed.path + "/orders?limit=\(pageSize)"
    if let c = cursor {
        path += "&cursor=\(percentEncodeQuery(c))"
    }

    let headers: [(String, String)] = [
        ("Authorization", "Bearer \(accessToken)")
    ]

    let resp = performRequest(host: parsed.host, port: parsed.port, method: "GET", path: path, headers: headers, body: nil)

    if resp.status == 429 {
        retries += 1
        let retryAfter = resp.headers.first { $0.0.lowercased() == "retry-after" }?.1 ?? "0"
        let seconds = Double(retryAfter) ?? 0
        Thread.sleep(forTimeInterval: max(seconds, 0))
        continue
    }

    if resp.status == 503 {
        retries += 1
        Thread.sleep(forTimeInterval: 0.5)
        continue
    }

    if resp.status == 401 {
        if tokenIsFresh {
            // First request with newly obtained token got 401 - fatal
            print("ERROR \(resp.status) \(resp.body)")
            exit(0)
        }
        // Token expired, re-auth
        accessToken = getToken()!
        tokenIsFresh = true
        reauths += 1
        continue
    }

    if resp.status != 200 {
        print("ERROR \(resp.status) \(resp.body)")
        exit(0)
    }

    // Success
    pages += 1
    tokenIsFresh = false

    guard let json = try? JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as? [String: Any] else {
        print("ERROR \(resp.status) \(resp.body)")
        exit(0)
    }

    if let data = json["data"] as? [[String: Any]] {
        allOrders.append(contentsOf: data)
    }

    // Check next_cursor
    let nextCursor = json["next_cursor"]
    if nextCursor is NSNull || nextCursor == nil {
        break
    } else if let c = nextCursor as? String {
        cursor = c
    } else {
        break
    }

    _ = firstPage
    firstPage = false
}

// MARK: Aggregate

var totals: [(name: String, currency: String, cents: Int64)] = []
var statusCounts: [String: Int] = [:]

for order in allOrders {
    // Status
    let status = order["status"] as? String ?? ""
    statusCounts[status, default: 0] += 1

    // Non-cancelled totals
    if status != "cancelled" {
        let customer = order["customer"] as? [String: Any]
        let name = customer?["name"] as? String ?? ""
        let currency = order["currency"] as? String ?? ""
        let amountStr = order["amount"] as? String ?? "0"
        let cents = parseAmount(amountStr)

        // Find existing entry
        var found = false
        for i in 0..<totals.count {
            if totals[i].name == name && totals[i].currency == currency {
                totals[i].cents += cents
                found = true
                break
            }
        }
        if !found {
            totals.append((name: name, currency: currency, cents: cents))
        }
    }
}

// Sort totals by name (UTF-8 byte order) then currency
totals.sort { a, b in
    let cmp = a.name.utf8.lexicographicallyPrecedes(b.name.utf8)
    if a.name.utf8.elementsEqual(b.name.utf8) {
        return a.currency < b.currency
    }
    return cmp
}

// MARK: Output

for t in totals {
    print("total \(t.currency) \(formatCents(t.cents)) \(t.name)")
}

let sortedStatuses = statusCounts.keys.sorted()
for s in sortedStatuses {
    print("status \(s) \(statusCounts[s]!)")
}

print("orders \(allOrders.count) pages \(pages) retries \(retries) reauth \(reauths)")

exit(0)

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface RequestConfig {
  api_key: string;
  model: string;
  max_tokens: number;
  thinking_budget: number;
  system: string;
  prompt: string;
  tools: any[];
}

interface AccumulatedBlock {
  type: string;
  thinking: string;
  signature: string;
  text: string;
  id: string;
  name: string;
  partial_json: string;
}

interface StreamResult {
  blocks: AccumulatedBlock[];
  stopReason: string;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
}

function escapeString(s: string): string {
  let result = '';
  for (const ch of s) {
    if (ch === '\\') result += '\\\\';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\r') result += '\\r';
    else if (ch === '\t') result += '\\t';
    else result += ch;
  }
  return result;
}

function parseSSE(body: string): Array<{ event: string; data: string }> {
  const events: Array<{ event: string; data: string }> = [];
  const lines = body.split(/\r?\n/);

  let currentEvent = '';
  let dataLines: string[] = [];
  let hasContent = false;

  for (const line of lines) {
    if (line === '') {
      if (hasContent) {
        events.push({ event: currentEvent, data: dataLines.join('\n') });
      }
      currentEvent = '';
      dataLines = [];
      hasContent = false;
    } else if (line.startsWith(':')) {
      // comment — ignore
    } else if (line.startsWith('event:')) {
      let value = line.slice(6);
      if (value.startsWith(' ')) value = value.slice(1);
      currentEvent = value;
      hasContent = true;
    } else if (line.startsWith('data:')) {
      let value = line.slice(5);
      if (value.startsWith(' ')) value = value.slice(1);
      dataLines.push(value);
      hasContent = true;
    }
  }

  if (hasContent) {
    events.push({ event: currentEvent, data: dataLines.join('\n') });
  }

  return events;
}

function processStream(body: string): StreamResult {
  const events = parseSSE(body);
  const blocks = new Map<number, AccumulatedBlock>();
  let stopReason = '';
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheReadTokens = 0;

  for (const evt of events) {
    if (evt.event === 'ping' || evt.event === '' || !evt.data) continue;

    let data: any;
    try {
      data = JSON.parse(evt.data);
    } catch {
      continue;
    }

    switch (evt.event) {
      case 'message_start':
        if (data.message?.usage) {
          inputTokens += data.message.usage.input_tokens || 0;
          cacheReadTokens += data.message.usage.cache_read_input_tokens || 0;
        }
        break;
      case 'content_block_start': {
        const idx = data.index as number;
        const cb = data.content_block;
        blocks.set(idx, {
          type: cb.type,
          thinking: '',
          signature: '',
          text: '',
          id: cb.id || '',
          name: cb.name || '',
          partial_json: '',
        });
        break;
      }
      case 'content_block_delta': {
        const idx = data.index as number;
        const delta = data.delta;
        const b = blocks.get(idx);
        if (b) {
          if (delta.type === 'thinking_delta') b.thinking += delta.thinking || '';
          else if (delta.type === 'signature_delta') b.signature += delta.signature || '';
          else if (delta.type === 'text_delta') b.text += delta.text || '';
          else if (delta.type === 'input_json_delta') b.partial_json += delta.partial_json || '';
        }
        break;
      }
      case 'content_block_stop':
        break;
      case 'message_delta':
        if (data.delta?.stop_reason) stopReason = data.delta.stop_reason;
        if (data.usage?.output_tokens != null) outputTokens += data.usage.output_tokens;
        break;
      case 'message_stop':
        break;
    }
  }

  const sortedBlocks = [...blocks.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(e => e[1]);

  return { blocks: sortedBlocks, stopReason, inputTokens, outputTokens, cacheReadTokens };
}

function executeTool(name: string, input: any): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = String(input.text ?? '');
    const unit = String(input.unit ?? '');
    if (unit === 'code_points') {
      return { result: String([...text].length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = String(input.text ?? '');
    return { result: [...text].reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

function makeRequest(
  apiKey: string,
  baseUrl: string,
  body: object
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(`${baseUrl}/v1/messages`);
    const bodyStr = JSON.stringify(body);
    const contentLength = Buffer.byteLength(bodyStr, 'utf-8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port ? parseInt(url.port, 10) : undefined,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Type': 'application/json',
        'Content-Length': String(contentLength),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode || 0,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
      res.on('error', reject);
    });

    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

function printBlocks(blocks: AccumulatedBlock[]): void {
  for (const block of blocks) {
    if (block.type === 'thinking') {
      console.log(`thinking ${escapeString(block.thinking)}`);
      console.log(`signature ${escapeString(block.signature)}`);
    } else if (block.type === 'text') {
      console.log(`text ${escapeString(block.text)}`);
    } else if (block.type === 'tool_use') {
      console.log(`tool_use ${block.id} ${block.name} ${escapeString(block.partial_json)}`);
    }
  }
}

async function main(): Promise<void> {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const config: RequestConfig = JSON.parse(
    fs.readFileSync(path.join(dataDir, 'request.json'), 'utf-8')
  );

  // --- Request 1 ---
  console.log('request 1');

  const req1Body = {
    model: config.model,
    max_tokens: config.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: config.thinking_budget },
    system: config.system,
    tools: config.tools,
    messages: [{ role: 'user', content: config.prompt }],
  };

  const res1 = await makeRequest(config.api_key, baseUrl, req1Body);

  if (res1.status !== 200) {
    const err = JSON.parse(res1.body);
    console.log(`ERROR ${res1.status} ${err.error.type}: ${err.error.message}`);
    process.exit(0);
  }

  const reply1 = processStream(res1.body);
  printBlocks(reply1.blocks);
  console.log(`stop_reason ${reply1.stopReason}`);

  // --- Execute tools ---
  const toolResults: Array<{ id: string; result: string; isError: boolean }> = [];
  for (const block of reply1.blocks) {
    if (block.type === 'tool_use') {
      const input = block.partial_json ? JSON.parse(block.partial_json) : {};
      const execResult = executeTool(block.name, input);
      toolResults.push({ id: block.id, result: execResult.result, isError: execResult.isError });
      const prefix = execResult.isError ? 'error' : 'result';
      console.log(`${prefix} ${block.id} ${escapeString(execResult.result)}`);
    }
  }

  // --- Request 2 ---
  console.log('request 2');

  const assistantContent: any[] = [];
  for (const block of reply1.blocks) {
    if (block.type === 'thinking') {
      assistantContent.push({
        type: 'thinking',
        thinking: block.thinking,
        signature: block.signature,
      });
    } else if (block.type === 'text') {
      assistantContent.push({ type: 'text', text: block.text });
    } else if (block.type === 'tool_use') {
      const input = block.partial_json ? JSON.parse(block.partial_json) : {};
      assistantContent.push({ type: 'tool_use', id: block.id, name: block.name, input });
    }
  }

  const toolResultContent: any[] = toolResults.map((r) => {
    const block: any = { type: 'tool_result', tool_use_id: r.id, content: r.result };
    if (r.isError) block.is_error = true;
    return block;
  });

  const req2Body = {
    model: config.model,
    max_tokens: config.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: config.thinking_budget },
    system: config.system,
    tools: config.tools,
    messages: [
      { role: 'user', content: config.prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResultContent },
    ],
  };

  const res2 = await makeRequest(config.api_key, baseUrl, req2Body);

  if (res2.status !== 200) {
    const err = JSON.parse(res2.body);
    console.log(`ERROR ${res2.status} ${err.error.type}: ${err.error.message}`);
    process.exit(0);
  }

  const reply2 = processStream(res2.body);
  printBlocks(reply2.blocks);
  console.log(`stop_reason ${reply2.stopReason}`);

  // --- Usage ---
  const totalInput = reply1.inputTokens + reply2.inputTokens;
  const totalOutput = reply1.outputTokens + reply2.outputTokens;
  const totalCacheRead = reply1.cacheReadTokens + reply2.cacheReadTokens;
  console.log(`usage input=${totalInput} output=${totalOutput} cache_read=${totalCacheRead}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // ─── Output escaping ───────────────────────────────────────────────
    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    // ─── JSON Parser ───────────────────────────────────────────────────
    static Object parseJson(String s) {
        int[] pos = {0};
        Object v = parseVal(s, pos);
        return v;
    }

    static void skipWs(String s, int[] p) {
        while (p[0] < s.length() && (s.charAt(p[0]) == ' ' || s.charAt(p[0]) == '\t'
                || s.charAt(p[0]) == '\n' || s.charAt(p[0]) == '\r')) p[0]++;
    }

    static Object parseVal(String s, int[] p) {
        skipWs(s, p);
        if (p[0] >= s.length()) return null;
        char c = s.charAt(p[0]);
        if (c == '{') return parseObj(s, p);
        if (c == '[') return parseArr(s, p);
        if (c == '"') return parseStr(s, p);
        if (c == 't') { p[0] += 4; return Boolean.TRUE; }
        if (c == 'f') { p[0] += 5; return Boolean.FALSE; }
        if (c == 'n') { p[0] += 4; return null; }
        return parseNum(s, p);
    }

    static Map<String, Object> parseObj(String s, int[] p) {
        Map<String, Object> m = new LinkedHashMap<>();
        p[0]++; // {
        skipWs(s, p);
        if (s.charAt(p[0]) == '}') { p[0]++; return m; }
        while (true) {
            skipWs(s, p);
            String key = parseStr(s, p);
            skipWs(s, p);
            p[0]++; // :
            Object val = parseVal(s, p);
            m.put(key, val);
            skipWs(s, p);
            if (s.charAt(p[0]) == ',') { p[0]++; continue; }
            p[0]++; // }
            break;
        }
        return m;
    }

    static List<Object> parseArr(String s, int[] p) {
        List<Object> list = new ArrayList<>();
        p[0]++; // [
        skipWs(s, p);
        if (s.charAt(p[0]) == ']') { p[0]++; return list; }
        while (true) {
            Object val = parseVal(s, p);
            list.add(val);
            skipWs(s, p);
            if (s.charAt(p[0]) == ',') { p[0]++; continue; }
            p[0]++; // ]
            break;
        }
        return list;
    }

    static String parseStr(String s, int[] p) {
        p[0]++; // opening "
        StringBuilder sb = new StringBuilder();
        while (p[0] < s.length()) {
            char c = s.charAt(p[0]);
            if (c == '"') { p[0]++; return sb.toString(); }
            if (c == '\\') {
                p[0]++;
                char e = s.charAt(p[0]);
                p[0]++;
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u': {
                        int cp = Integer.parseInt(s.substring(p[0], p[0] + 4), 16);
                        p[0] += 4;
                        if (cp >= 0xD800 && cp <= 0xDBFF && p[0] + 5 < s.length()
                                && s.charAt(p[0]) == '\\' && s.charAt(p[0] + 1) == 'u') {
                            p[0] += 2;
                            int lo = Integer.parseInt(s.substring(p[0], p[0] + 4), 16);
                            p[0] += 4;
                            sb.appendCodePoint(0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00));
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    }
                    default: sb.append(e);
                }
            } else {
                sb.append(c);
                p[0]++;
            }
        }
        return sb.toString();
    }

    static Object parseNum(String s, int[] p) {
        int start = p[0];
        while (p[0] < s.length() && "+-0123456789.eE".indexOf(s.charAt(p[0])) >= 0) p[0]++;
        String num = s.substring(start, p[0]);
        if (num.contains(".") || num.contains("e") || num.contains("E"))
            return Double.parseDouble(num);
        return Long.parseLong(num);
    }

    // ─── JSON Serializer ───────────────────────────────────────────────
    static String toJson(Object v) {
        if (v == null) return "null";
        if (v instanceof String) return jsonEsc((String) v);
        if (v instanceof Boolean) return v.toString();
        if (v instanceof Long) return v.toString();
        if (v instanceof Integer) return v.toString();
        if (v instanceof Double) {
            double d = (Double) v;
            if (d == Math.floor(d) && !Double.isInfinite(d)) return Long.toString((long) d);
            return v.toString();
        }
        if (v instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> m = (Map<String, Object>) v;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append(jsonEsc(e.getKey())).append(':').append(toJson(e.getValue()));
            }
            sb.append('}');
            return sb.toString();
        }
        if (v instanceof List) {
            @SuppressWarnings("unchecked")
            List<Object> l = (List<Object>) v;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object o : l) {
                if (!first) sb.append(',');
                first = false;
                sb.append(toJson(o));
            }
            sb.append(']');
            return sb.toString();
        }
        return v.toString();
    }

    static String jsonEsc(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    // ─── HTTP ──────────────────────────────────────────────────────────
    static String readHttpLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int n = in.read();
                if (n == '\n' || n == -1) break;
                sb.append('\r');
                sb.append((char) n);
            } else if (c == '\n') {
                break;
            } else {
                sb.append((char) c);
            }
        }
        if (sb.length() == 0 && c == -1) return null;
        return sb.toString();
    }

    static byte[] readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        while (true) {
            String line = readHttpLine(in);
            if (line == null) break;
            int semi = line.indexOf(';');
            if (semi >= 0) line = line.substring(0, semi);
            line = line.trim();
            if (line.isEmpty()) continue;
            int size;
            try { size = Integer.parseInt(line, 16); } catch (NumberFormatException e) { break; }
            if (size == 0) {
                // read trailer lines until empty line
                while (true) {
                    String t = readHttpLine(in);
                    if (t == null || t.isEmpty()) break;
                }
                break;
            }
            byte[] buf = new byte[size];
            int off = 0;
            while (off < size) {
                int r = in.read(buf, off, size - off);
                if (r < 0) break;
                off += r;
            }
            out.write(buf, 0, off);
            // trailing CRLF after chunk data
            readHttpLine(in);
        }
        return out.toByteArray();
    }

    static String[] httpPost(String host, int port, String path, String apiKey, String body) throws IOException {
        Socket sock = new Socket(host, port);
        sock.setSoTimeout(120000);
        OutputStream out = sock.getOutputStream();
        InputStream in = sock.getInputStream();

        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);
        StringBuilder req = new StringBuilder();
        req.append("POST ").append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host).append(':').append(port).append("\r\n");
        req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
        req.append("x-api-key: ").append(apiKey).append("\r\n");
        req.append("anthropic-version: 2023-06-01\r\n");
        req.append("content-type: application/json\r\n");
        req.append("\r\n");

        out.write(req.toString().getBytes(StandardCharsets.UTF_8));
        out.write(bodyBytes);
        out.flush();

        String statusLine = readHttpLine(in);
        int statusCode = Integer.parseInt(statusLine.split(" ")[1]);

        Map<String, String> headers = new HashMap<>();
        String hl;
        while ((hl = readHttpLine(in)) != null && !hl.isEmpty()) {
            int ci = hl.indexOf(':');
            if (ci >= 0) {
                headers.put(hl.substring(0, ci).trim().toLowerCase(), hl.substring(ci + 1).trim());
            }
        }

        byte[] respBody;
        if (statusCode == 200) {
            respBody = readChunked(in);
        } else {
            String cl = headers.get("content-length");
            int len = cl != null ? Integer.parseInt(cl) : 0;
            respBody = new byte[len];
            int off = 0;
            while (off < len) {
                int r = in.read(respBody, off, len - off);
                if (r < 0) break;
                off += r;
            }
        }
        sock.close();
        return new String[]{String.valueOf(statusCode), new String(respBody, StandardCharsets.UTF_8)};
    }

    // ─── SSE Parser ────────────────────────────────────────────────────
    static class SSEEvent {
        String event;
        String data;
        SSEEvent(String e, String d) { event = e; data = d; }
    }

    static List<SSEEvent> parseSSE(String body) {
        List<SSEEvent> events = new ArrayList<>();
        String evName = null;
        StringBuilder dataBuf = new StringBuilder();
        boolean hasData = false;
        int pos = 0;
        while (pos <= body.length()) {
            int nl = body.indexOf('\n', pos);
            String line;
            if (nl < 0) {
                line = body.substring(pos);
                pos = body.length() + 1;
            } else {
                line = body.substring(pos, nl);
                pos = nl + 1;
            }
            if (line.endsWith("\r")) line = line.substring(0, line.length() - 1);

            if (line.isEmpty()) {
                if (hasData) {
                    events.add(new SSEEvent(evName, dataBuf.toString()));
                }
                evName = null;
                dataBuf = new StringBuilder();
                hasData = false;
            } else if (line.charAt(0) == ':') {
                // comment
            } else if (line.startsWith("event:")) {
                String v = line.substring(6);
                if (v.startsWith(" ")) v = v.substring(1);
                evName = v;
            } else if (line.startsWith("data:")) {
                String v = line.substring(5);
                if (v.startsWith(" ")) v = v.substring(1);
                if (hasData) dataBuf.append('\n');
                dataBuf.append(v);
                hasData = true;
            }
        }
        return events;
    }

    // ─── Content Block ─────────────────────────────────────────────────
    static class Block {
        String type;
        StringBuilder thinking = new StringBuilder();
        StringBuilder signature = new StringBuilder();
        StringBuilder text = new StringBuilder();
        String id, name;
        StringBuilder rawInput = new StringBuilder();
    }

    // ─── Tool Execution ────────────────────────────────────────────────
    static String[] execTool(String name, Map<String, Object> input) {
        if (name.equals("measure")) {
            String text = (String) input.get("text");
            String unit = (String) input.get("unit");
            if (unit == null) return new String[]{null, "unsupported unit: null"};
            switch (unit) {
                case "code_points":
                    return new String[]{String.valueOf(text.codePointCount(0, text.length())), null};
                case "utf8_bytes":
                    return new String[]{String.valueOf(text.getBytes(StandardCharsets.UTF_8).length), null};
                case "utf16_units":
                    return new String[]{String.valueOf(text.length()), null};
                default:
                    return new String[]{null, "unsupported unit: " + unit};
            }
        } else if (name.equals("reverse")) {
            String text = (String) input.get("text");
            StringBuilder sb = new StringBuilder();
            int[] cps = text.codePoints().toArray();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return new String[]{sb.toString(), null};
        } else {
            return new String[]{null, "unknown tool: " + name};
        }
    }

    // ─── Main ──────────────────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read request.json
        String reqJsonStr = new String(readFile(dataDir + "/request.json"), StandardCharsets.UTF_8);
        Map<String, Object> cfg = (Map<String, Object>) parseJson(reqJsonStr);

        String apiKey = (String) cfg.get("api_key");
        String model = (String) cfg.get("model");
        long maxTokens = ((Number) cfg.get("max_tokens")).longValue();
        long thinkingBudget = ((Number) cfg.get("thinking_budget")).longValue();
        String system = (String) cfg.get("system");
        String prompt = (String) cfg.get("prompt");
        Object tools = cfg.get("tools");

        // Parse URL
        URL url = new URL(baseUrl + "/v1/messages");
        String host = url.getHost();
        int port = url.getPort();
        if (port < 0) port = 80;
        String path = url.getPath();

        int totalInput = 0, totalOutput = 0, totalCacheRead = 0;

        // ── Request 1 ──
        List<Object> messages1 = new ArrayList<>();
        Map<String, Object> um1 = new LinkedHashMap<>();
        um1.put("role", "user");
        um1.put("content", prompt);
        messages1.add(um1);

        Map<String, Object> body1 = new LinkedHashMap<>();
        body1.put("model", model);
        body1.put("max_tokens", maxTokens);
        body1.put("stream", Boolean.TRUE);
        Map<String, Object> thinkingCfg = new LinkedHashMap<>();
        thinkingCfg.put("type", "enabled");
        thinkingCfg.put("budget_tokens", thinkingBudget);
        body1.put("thinking", thinkingCfg);
        body1.put("system", system);
        body1.put("tools", tools);
        body1.put("messages", messages1);

        String[] resp1 = httpPost(host, port, path, apiKey, toJson(body1));
        int status1 = Integer.parseInt(resp1[0]);
        String body1Str = resp1[1];

        if (status1 != 200) {
            // print what we have (nothing yet for request 1 blocks)
            System.out.println("request 1");
            Map<String, Object> errObj = (Map<String, Object>) parseJson(body1Str);
            Map<String, Object> err = (Map<String, Object>) errObj.get("error");
            System.out.println("ERROR " + status1 + " " + err.get("type") + ": " + err.get("message"));
            return;
        }

        List<SSEEvent> sse1 = parseSSE(body1Str);
        List<Block> blocks1 = processSSE(sse1);
        String stopReason1 = null;
        for (SSEEvent ev : sse1) {
            if (!"message_delta".equals(ev.event)) continue;
            Map<String, Object> d = (Map<String, Object>) parseJson(ev.data);
            Map<String, Object> delta = (Map<String, Object>) d.get("delta");
            if (delta != null) stopReason1 = (String) delta.get("stop_reason");
            Map<String, Object> usage = (Map<String, Object>) d.get("usage");
            if (usage != null) totalOutput += ((Number) usage.get("output_tokens")).intValue();
        }
        for (SSEEvent ev : sse1) {
            if (!"message_start".equals(ev.event)) continue;
            Map<String, Object> d = (Map<String, Object>) parseJson(ev.data);
            Map<String, Object> msg = (Map<String, Object>) d.get("message");
            if (msg != null) {
                Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
                if (usage != null) {
                    Object it = usage.get("input_tokens");
                    if (it != null) totalInput += ((Number) it).intValue();
                    Object crt = usage.get("cache_read_input_tokens");
                    if (crt != null) totalCacheRead += ((Number) crt).intValue();
                }
            }
        }

        // Print request 1
        System.out.println("request 1");
        for (Block b : blocks1) {
            if ("thinking".equals(b.type)) {
                System.out.println("thinking " + esc(b.thinking.toString()));
                System.out.println("signature " + esc(b.signature.toString()));
            } else if ("text".equals(b.type)) {
                System.out.println("text " + esc(b.text.toString()));
            } else if ("tool_use".equals(b.type)) {
                System.out.println("tool_use " + esc(b.id) + " " + esc(b.name) + " " + esc(b.rawInput.toString()));
            }
        }
        System.out.println("stop_reason " + stopReason1);

        // Execute tools
        List<String[]> toolResults = new ArrayList<>(); // [tool_use_id, result, isError]
        for (Block b : blocks1) {
            if (!"tool_use".equals(b.type)) continue;
            Map<String, Object> input = (Map<String, Object>) parseJson(b.rawInput.toString());
            String[] res = execTool(b.name, input);
            if (res[1] != null) {
                toolResults.add(new String[]{b.id, res[1], "1"});
            } else {
                toolResults.add(new String[]{b.id, res[0], "0"});
            }
        }
        for (String[] tr : toolResults) {
            if ("1".equals(tr[2])) {
                System.out.println("error " + esc(tr[0]) + " " + esc(tr[1]));
            } else {
                System.out.println("result " + esc(tr[0]) + " " + esc(tr[1]));
            }
        }

        // ── Request 2 ──
        List<Object> messages2 = new ArrayList<>();
        // user message (same as request 1)
        Map<String, Object> um2 = new LinkedHashMap<>();
        um2.put("role", "user");
        um2.put("content", prompt);
        messages2.add(um2);

        // assistant message
        List<Object> assistantContent = new ArrayList<>();
        for (Block b : blocks1) {
