import sys
import struct
import zlib
from decimal import Decimal


def read_varint(data, offset):
    result = 0
    for i in range(9):
        if i == 8:
            result = (result << 8) | data[offset]
            return result, offset + 1
        byte = data[offset]
        result = (result << 7) | (byte & 0x7F)
        offset += 1
        if not (byte & 0x80):
            return result, offset
    raise ValueError("Varint too long")


def to_signed_64(val):
    if val >= (1 << 63):
        val -= (1 << 64)
    return val


def decode_int(data, offset, nbytes):
    val = int.from_bytes(data[offset:offset + nbytes], 'big', signed=True)
    return val, offset + nbytes


def read_page(db_data, page_num, page_size):
    offset = (page_num - 1) * page_size
    return db_data[offset:offset + page_size]


def read_overflow(db_data, overflow_page, page_size, usable_size, remaining):
    data = b''
    while remaining > 0 and overflow_page != 0:
        page_data = read_page(db_data, overflow_page, page_size)
        next_page = struct.unpack('>I', page_data[0:4])[0]
        chunk = min(usable_size - 4, remaining)
        data += page_data[4:4 + chunk]
        remaining -= chunk
        overflow_page = next_page
    return data


def parse_cell_leaf(db_data, page_data, cell_off, page_size, usable_size):
    overflow_page = struct.unpack('>I', page_data[cell_off:cell_off + 4])[0]
    cell_off += 4
    payload_len, cell_off = read_varint(page_data, cell_off)
    rowid, cell_off = read_varint(page_data, cell_off)
    rowid = to_signed_64(rowid)

    max_local = usable_size - 35
    local_len = min(payload_len, max_local)
    local_payload = page_data[cell_off:cell_off + local_len]

    if payload_len > local_len:
        overflow_data = read_overflow(db_data, overflow_page, page_size, usable_size, payload_len - local_len)
        payload = local_payload + overflow_data
    else:
        payload = local_payload

    return rowid, payload


def walk_btree(db_data, page_num, page_size, usable_size):
    rows = []
    stack = [page_num]
    while stack:
        pn = stack.pop()
        if pn == 0:
            continue
        page_data = read_page(db_data, pn, page_size)
        hdr_off = 100 if pn == 1 else 0
        page_type = page_data[hdr_off]
