#[derive(Clone, Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<JsonValue>),
    Obj(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get_str(&self, key: &str) -> Option<&str> {
        if let JsonValue::Obj(fields) = self {
            for (k, v) in fields {
                if k == key {
                    if let JsonValue::Str(s) = v { return Some(s.as_str()); }
                }
            }
        }
        None
    }
    fn get_num_str(&self, key: &str) -> Option<&str> {
        if let JsonValue::Obj(fields) = self {
            for (k, v) in fields {
                if k == key {
                    if let JsonValue::Num(s) = v { return Some(s.as_str()); }
                }
            }
        }
        None
    }
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Obj(fields) = self {
            for (k, v) in fields {
                if k == key { return Some(v); }
            }
        }
        None
    }
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        if self.pos >= self.input.len() { return Err("eof".into()); }
        match self.input[self.pos] {
            b'"' => self.parse_string().map(JsonValue::Str),
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b't' => { if self.input[self.pos..].starts_with(b"true") { self.pos += 4; Ok(JsonValue::Bool(true)) } else { Err("bad".into()) } }
            b'f' => { if self.input[self.pos..].starts_with(b"false") { self.pos += 5; Ok(JsonValue::Bool(false)) } else { Err("bad".into()) } }
            b'n' => { if self.input[self.pos..].starts_with(b"null") { self.pos += 4; Ok(JsonValue::Null) } else { Err("bad".into()) } }
            _ => self.parse_number(),
        }
    }
    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.input.len() { return Err("unterminated string".into()); }
            let c = self.input[self.pos];
            if c == b'"' { self.pos += 1; return Ok(result); }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() { return Err("unterminated escape".into()); }
                match self.input[self.pos] {
                    b'"' => { result.push('"'); self.pos += 1; }
                    b'\\' => { result.push('\\'); self.pos += 1; }
                    b'/' => { result.push('/'); self.pos += 1; }
                    b'b' => { result.push('\u{0008}'); self.pos += 1; }
                    b'f' => { result.push('\u{000C}'); self.pos += 1; }
                    b'n' => { result.push('\n'); self.pos += 1; }
                    b'r' => { result.push('\r'); self.pos += 1; }
                    b't' => { result.push('\t'); self.pos += 1; }
                    b'u' => {
                        self.pos += 1;
                        let code = self.parse_hex4()?;
                        if code >= 0xD800 && code <= 0xDBFF {
                            if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                self.pos += 2;
                                let low = self.parse_hex4()?;
                                if low >= 0xDC00 && low <= 0xDFFF {
                                    let cp = 0x10000 + ((code as u32 - 0xD800) << 10) + (low as u32 - 0xDC00);
                                    result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                } else {
                                    result.push('\u{FFFD}');
                                    result.push(char::from_u32(low as u32).unwrap_or('\u{FFFD}'));
                                }
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else if code >= 0xDC00 && code <= 0xDFFF {
                            result.push('\u{FFFD}');
                        } else {
                            result.push(char::from_u32(code as u32).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => return Err("bad escape".into()),
                }
            } else {
                let start = self.pos;
                self.pos += 1;
                if c >= 0x80 {
                    let extra = if c >= 0xF0 { 3 } else if c >= 0xE0 { 2 } else if c >= 0xC0 { 1 } else { 0 };
                    self.pos += extra;
                }
                let s = str::from_utf8(&self.input[start..self.pos]).map_err(|e| e.to_string())?;
                result.push_str(s);
            }
        }
    }
    fn parse_hex4(&mut self) -> Result<u16, String> {
        if self.pos + 4 > self.input.len() { return Err("incomplete \\u".into()); }
        let hex = str::from_utf8(&self.input[self.pos..self.pos+4]).map_err(|e| e.to_string())?;
        self.pos += 4;
        u16::from_str_radix(hex, 16).map_err(|e| e.to_string())
    }
    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        self.skip_ws();
        let mut fields = Vec::new();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' { self.pos += 1; return Ok(JsonValue::Obj(fields)); }
        loop {
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b'"' { return Err("expected key".into()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' { return Err("expected :".into()); }
            self.pos += 1;
            let value = self.parse_value()?;
            fields.push((key, value));
            self.skip_ws();
            if self.pos >= self.input.len() { return Err("unterminated obj".into()); }
            if self.input[self.pos] == b',' { self.pos += 1; }
            else if self.input[self.pos] == b'}' { self.pos += 1; return Ok(JsonValue::Obj(fields)); }
            else { return Err("expected , or }".into()); }
        }
    }
    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        self.skip_ws();
        let mut items = Vec::new();
        if self.pos < self.input.len() && self.input[self.pos] == b']' { self.pos += 1; return Ok(JsonValue::Arr(items)); }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            if self.pos >= self.input.len() { return Err("unterminated arr".into()); }
            if self.input[self.pos] == b',' { self.pos += 1; }
            else if self.input[self.pos] == b']' { self.pos += 1; return Ok(JsonValue::Arr(items)); }
            else { return Err("expected , or ]".into()); }
        }
    }
    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = str::from_utf8(&self.input[start..self.pos]).map_err(|e| e.to_string())?;
        Ok(JsonValue::Num(s.to_string()))
    }
}

fn json_parse(s: &str) -> Result<JsonValue, String> {
    let mut p = JsonParser::new(s);
    p.parse_value()
}

fn json_serialize(val: &JsonValue) -> String {
    match val {
        JsonValue::Null => "null".into(),
        JsonValue::Bool(b) => if *b { "true".into() } else { "false".into() },
        JsonValue::Num(s) => s.clone(),
        JsonValue::Str(s) => json_escape_str(s),
        JsonValue::Arr(items) => {
            let parts: Vec<String> = items.iter().map(|i| json_serialize(i)).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Obj(fields) => {
            let parts: Vec<String> = fields.iter().map(|(k, v)| format!("{}:{}", json_escape_str(k), json_serialize(v))).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn json_escape_str(s: &str) -> String {
    let mut r = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

// ============ HTTP ============

struct HttpResponse {
    status: u16,
    body: Vec<u8>,
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { url };
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let host_port = &rest[..slash_pos];
    let path = &rest[slash_pos..];
    let (host, port) = if let Some(cp) = host_port.rfind(':') {
        (&host_port[..cp], host_port[cp+1..].parse::<u16>().unwrap_or(80))
    } else {
        (host_port, 80u16)
    };
    (host.to_string(), port, path.to_string())
}

fn http_request(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> HttpResponse {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        path, host, port, body.len(), api_key, body
    );
    stream.write_all(req.as_bytes()).expect("write failed");
    stream.flush().expect("flush failed");

    let mut buf = Vec::new();
    let mut tmp = [0u8; 65536];
    loop {
        let n = stream.read(&mut tmp).expect("read failed");
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
        if buf.windows(4).any(|w| w == b"\r\n\r\n") { break; }
    }

    let hdr_end = buf.windows(4).position(|w| w == b"\r\n\r\n").unwrap_or(0) + 4;
    let hdr_str = str::from_utf8(&buf[..hdr_end]).unwrap_or("");
    let status_line = hdr_str.split("\r\n").next().unwrap_or("");
    let status: u16 = status_line.split_whitespace().nth(1).unwrap_or("0").parse().unwrap_or(0);

    let mut is_chunked = false;
    let mut content_length: usize = 0;
    for line in hdr_str.split("\r\n").skip(1) {
        if line.is_empty() { break; }
        if let Some(cp) = line.find(':') {
            let name = line[..cp].trim().to_lowercase();
            let val = line[cp+1..].trim().to_string();
            if name == "transfer-encoding" && val.to_lowercase().contains("chunked") { is_chunked = true; }
            if name == "content-length" { content_length = val.parse().unwrap_or(0); }
        }
    }

    let mut body_buf = buf[hdr_end..].to_vec();

    if is_chunked {
        loop {
            let n = stream.read(&mut tmp).expect("read failed");
            if n == 0 { break; }
            body_buf.extend_from_slice(&tmp[..n]);
        }
        let decoded = decode_chunked(&body_buf);
        HttpResponse { status, body: decoded }
    } else {
        while body_buf.len() < content_length {
            let n = stream.read(&mut tmp).expect("read failed");
            if n == 0 { break; }
            body_buf.extend_from_slice(&tmp[..n]);
        }
        body_buf.truncate(content_length);
        HttpResponse { status, body: body_buf }
    }
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        // find end of chunk-size line
        let line_end = find_crlf(data, pos);
        if line_end == usize::MAX { break; }
        let line = match str::from_utf8(&data[pos..line_end]) { Ok(s) => s, Err(_) => break };
        let size_str = line.split(';').next().unwrap_or("").trim();
        let chunk_size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        pos = line_end + 2;
        if chunk_size == 0 { break; }
        let end = std::cmp::min(pos + chunk_size, data.len());
        result.extend_from_slice(&data[pos..end]);
        pos = pos + chunk_size;
        // skip trailing CRLF
        if pos + 1 < data.len() && data[pos] == b'\r' && data[pos+1] == b'\n' {
            pos += 2;
        } else if pos < data.len() && data[pos] == b'\n' {
            pos += 1;
        }
    }
    result
}

fn find_crlf(data: &[u8], start: usize) -> usize {
    let mut i = start;
    while i + 1 < data.len() {
        if data[i] == b'\r' && data[i+1] == b'\n' { return i; }
        i += 1;
    }
    usize::MAX
}

// ============ SSE ============

struct SseEvent {
    event_type: String,
    data: String,
}

fn parse_sse(data: &[u8]) -> Vec<SseEvent> {
    let text = match str::from_utf8(data) { Ok(s) => s, Err(_) => return vec![] };
    let mut events = Vec::new();
    let mut event_type = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let bytes = text.as_bytes();
    let mut line_start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            let mut end = i;
            if end > line_start && bytes[end - 1] == b'\r' { end -= 1; }
            let line = &text[line_start..end];
            process_sse_line(line, &mut event_type, &mut data_lines, &mut events);
            line_start = i + 1;
        }
        i += 1;
    }
    if line_start < bytes.len() {
        let line = &text[line_start..];
        process_sse_line(line, &mut event_type, &mut data_lines, &mut events);
    }
    // flush remaining
    if !data_lines.is_empty() || !event_type.is_empty() {
        events.push(SseEvent { event_type, data: data_lines.join("\n") });
    }
    events
}

fn process_sse_line(line: &str, event_type: &mut String, data_lines: &mut Vec<String>, events: &mut Vec<SseEvent>) {
    if line.is_empty() {
        if !data_lines.is_empty() || !event_type.is_empty() {
            events.push(SseEvent { event_type: event_type.clone(), data: data_lines.join("\n") });
        }
        event_type.clear();
        data_lines.clear();
    } else if line.starts_with(':') {
        // comment
    } else if line.starts_with("event:") {
        let val = &line[6..];
        *event_type = if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() };
    } else if line.starts_with("data:") {
        let val = &line[5..];
        data_lines.push(if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() });
    }
}

// ============ Content Blocks ============

struct ContentBlock {
    block_type: String,
    thinking: String,
    signature: String,
    text: String,
    tool_id: String,
    tool_name: String,
    partial_json: String,
}

fn process_stream(events: &[SseEvent]) -> (Vec<ContentBlock>, String, u64, u64, u64) {
    let mut blocks: Vec<Option<ContentBlock>> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens: u64 = 0;
    let mut output_tokens: u64 = 0;
    let mut cache_read: u64 = 0;

    for ev in events {
        let data = match json_parse(&ev.data) { Ok(v) => v, Err(_) => continue };
        match ev.event_type.as_str() {
            "message_start" => {
                if let Some(msg) = data.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        if let Some(v) = usage.get_num_str("input_tokens") { input_tokens += v.parse().unwrap_or(0); }
                        if let Some(v) = usage.get_num_str("cache_read_input_tokens") { cache_read += v.parse().unwrap_or(0); }
                    }
                }
            }
            "content_block_start" => {
                let idx = data.get_num_str("index").unwrap_or("0").parse::<usize>().unwrap_or(0);
                let cb = data.get("content_block").cloned().unwrap_or(JsonValue::Null);
                let bt = cb.get_str("type").unwrap_or("").to_string();
                while blocks.len() <= idx { blocks.push(None); }
                blocks[idx] = Some(ContentBlock {
                    block_type: bt,
                    thinking: String::new(),
                    signature: String::new(),
                    text: String::new(),
                    tool_id: cb.get_str("id").unwrap_or("").to_string(),
                    tool_name: cb.get_str("name").unwrap_or("").to_string(),
                    partial_json: String::new(),
                });
            }
            "content_block_delta" => {
                let idx = data.get_num_str("index").unwrap_or("0").parse::<usize>().unwrap_or(0);
                let delta = data.get("delta").cloned().unwrap_or(JsonValue::Null);
                let dt = delta.get_str("type").unwrap_or("");
                if idx < blocks.len() {
                    if let Some(Some(b)) = blocks.get_mut(idx) {
                        match dt {
                            "thinking_delta" => { if let Some(t) = delta.get_str("thinking") { b.thinking.push_str(t); } }
                            "signature_delta" => { if let Some(s) = delta.get_str("signature") { b.signature.push_str(s); } }
                            "text_delta" => { if let Some(t) = delta.get_str("text") { b.text.push_str(t); } }
                            "input_json_delta" => { if let Some(p) = delta.get_str("partial_json") { b.partial_json.push_str(p); } }
                            _ => {}
                        }
                    }
                }
            }
            "message_delta" => {
                if let Some(d) = data.get("delta") {
                    if let Some(sr) = d.get_str("stop_reason") { stop_reason = sr.to_string(); }
                }
                if let Some(usage) = data.get("usage") {
                    if let Some(v) = usage.get_num_str("output_tokens") { output_tokens += v.parse().unwrap_or(0); }
                }
            }
            _ => {}
        }
    }

    let result: Vec<ContentBlock> = blocks.into_iter().filter_map(|b| b).collect();
    (result, stop_reason, input_tokens, output_tokens, cache_read)
}

// ============ Tools ============

fn execute_tool(name: &str, input_json: &str) -> (String, bool) {
    let input = match json_parse(input_json) {
        Ok(v) => v,
        Err(_) => return (format!("unknown tool: {}", name), true),
    };
    match name {
        "measure" => {
            let text = input.get_str("text").unwrap_or("");
            let unit = input.get_str("unit").unwrap_or("");
            match unit {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.as_bytes().len().to_string(), false),
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get_str("text").unwrap_or("");
            let reversed: String = text.chars().rev().collect();
            (reversed, false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ============ Output ============

fn escape_output(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

// ============ Request Building ============

fn build_request1(model: &str, max_tokens: &str, thinking_budget: &str, system: &str, tools: &JsonValue, prompt: &str) -> String {
    let fields = vec![
        ("model".to_string(), JsonValue::Str(model.to_string())),
        ("max_tokens".to_string(), JsonValue::Num(max_tokens.to_string())),
        ("stream".to_string(), JsonValue::Bool(true)),
        ("thinking".to_string(), JsonValue::Obj(vec![
            ("type".to_string(), JsonValue::Str("enabled".to_string())),
            ("budget_tokens".to_string(), JsonValue::Num(thinking_budget.to_string())),
        ])),
        ("system".to_string(), JsonValue::Str(system.to_string())),
        ("tools".to_string(), tools.clone()),
        ("messages".to_string(), JsonValue::Arr(vec![
            JsonValue::Obj(vec![
                ("role".to_string(), JsonValue::Str("user".to_string())),
                ("content".to_string(), JsonValue::Str(prompt.to_string())),
            ]),
        ])),
    ];
    json_serialize(&JsonValue::Obj(fields))
}

fn build_request2(model: &str, max_tokens: &str, thinking_budget: &str, system: &str, tools: &JsonValue, prompt: &str, blocks: &[ContentBlock], tool_results: &[(String, String, bool)]) -> String {
    let mut assistant_blocks: Vec<JsonValue> = Vec::new();
    for b in blocks {
        match b.block_type.as_str() {
            "thinking" => assistant_blocks.push(JsonValue::Obj(vec![
                ("type".to_string(), JsonValue::Str("thinking".to_string())),
                ("thinking".to_string(), JsonValue::Str(b.thinking.clone())),
                ("signature".to_string(), JsonValue::Str(b.signature.clone())),
            ])),
            "text" => assistant_blocks.push(JsonValue::Obj(vec![
                ("type".to_string(), JsonValue::Str("text".to_string())),
                ("text".to_string(), JsonValue::Str(b.text.clone())),
            ])),
            "tool_use" => {
                let pj = if b.partial_json.is_empty() { "{}" } else { &b.partial_json };
                let iv = json_parse(pj).unwrap_or(JsonValue::Obj(vec![]));
                assistant_blocks.push(JsonValue::Obj(vec![
                    ("type".to_string(), JsonValue::Str("tool_use".to_string())),
                    ("id".to_string(), JsonValue::Str(b.tool_id.clone())),
                    ("name".to_string(), JsonValue::Str(b.tool_name.clone())),
                    ("input".to_string(), iv),
                ]));
            }
            _ => {}
        }
    }

    let mut result_blocks: Vec<JsonValue> = Vec::new();
    for (id, result, is_error) in tool_results {
        let mut f = vec![
            ("type".to_string(), JsonValue::Str("tool_result".to_string())),
            ("tool_use_id".to_string(), JsonValue::Str(id.clone())),
            ("content".to_string(), JsonValue::Str(result.clone())),
        ];
        if *is_error { f.push(("is_error".to_string(), JsonValue::Bool(true))); }
        result_blocks.push(JsonValue::Obj(f));
    }

    let fields = vec![
        ("model".to_string(), JsonValue::Str(model.to_string())),
        ("max_tokens".to_string(), JsonValue::Num(max_tokens.to_string())),
        ("stream".to_string(), JsonValue::Bool(true)),
        ("thinking".to_string(), JsonValue::Obj(vec![
            ("type".to_string(), JsonValue::Str("enabled".to_string())),
            ("budget_tokens".to_string(), JsonValue::Num(thinking_budget.to_string())),
        ])),
        ("system".to_string(), JsonValue::Str(system.to_string())),
        ("tools".to_string(), tools.clone()),
        ("messages".to_string(), JsonValue::Arr(vec![
            JsonValue::Obj(vec![
                ("role".to_string(), JsonValue::Str("user".to_string())),
                ("content".to_string(), JsonValue::Str(prompt.to_string())),
            ]),
            JsonValue::Obj(vec![
                ("role".to_string(), JsonValue::Str("assistant".to_string())),
                ("content".to_string(), JsonValue::Arr(assistant_blocks)),
            ]),
            JsonValue::Obj(vec![
                ("role".to_string(), JsonValue::Str("user".to_string())),
                ("content".to_string(), JsonValue::Arr(result_blocks)),
            ]),
        ])),
    ];
    json_serialize(&JsonValue::Obj(fields))
}

// ============ Main ============

fn print_blocks(out: &mut Vec<String>, blocks: &[ContentBlock], stop_reason: &str) {
    for b in blocks {
        match b.block_type.as_str() {
            "thinking" => {
                out.push(format!("thinking {}", escape_output(&b.thinking)));
                out.push(format!("signature {}", escape_output(&b.signature)));
            }
            "text" => {
                out.push(format!("text {}", escape_output(&b.text)));
            }
            "tool_use" => {
                out.push(format!("tool_use {} {} {}", b.tool_id, b.tool_name, escape_output(&b.partial_json)));
            }
            _ => {}
        }
    }
    out.push(format!("stop_reason {}", stop_reason));
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let req_str = fs::read_to_string(format!("{}/request.json", data_dir)).unwrap();
    let req = json_parse(&req_str).unwrap();

    let api_key = req.get_str("api_key").unwrap_or("").to_string();
    let model = req.get_str("model").unwrap_or("").to_string();
    let max_tokens = req.get_num_str("max_tokens").unwrap_or("0").to_string();
    let thinking_budget = req.get_num_str("thinking_budget").unwrap_or("0").to_string();
    let system = req.get_str("system").unwrap_or("").to_string();
    let prompt = req.get_str("prompt").unwrap_or("").to_string();
    let tools = req.get("tools").cloned().unwrap_or(JsonValue::Arr(vec![]));

    let (host, port, path) = parse_url(base_url);
    let endpoint = format!("{}/v1/messages", path);

    let mut out: Vec<String> = Vec::new();
    let mut total_input: u64 = 0;
    let mut total_output: u64 = 0;
    let mut total_cache_read: u64 = 0;

    // Request 1
    out.push("request 1".to_string());
    let body1 = build_request1(&model, &max_tokens, &thinking_budget, &system, &tools, &prompt);
    let resp1 = http_request(&host, port, &endpoint, &api_key, &body1);

    if resp1.status != 200 {
        let err_str = String::from_utf8_lossy(&resp1.body).to_string();
        let err_json = json_parse(&err_str).unwrap_or(JsonValue::Null);
        let et = err_json.get("error").and_then(|e| e.get_str("type")).unwrap_or("unknown");
        let em = err_json.get("error").and_then(|e| e.get_str("message")).unwrap_or("unknown");
        for l in &out { println!("{}", l); }
        println!("ERROR {} {}: {}", resp1.status, et, em);
        return;
    }

    let events1 = parse_sse(&resp1.body);
    let (blocks1, stop1, i1, o1, c1) = process_stream(&events1);
    total_input += i1;
    total_output += o1;
    total_cache_read += c1;
    print_blocks(&mut out, &blocks1, &stop1);

    // Execute tools
    let tool_blocks: Vec<&ContentBlock> = blocks1.iter().filter(|b| b.block_type == "tool_use").collect();
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();
    for b in &tool_blocks {
        let pj = if b.partial_json.is_empty() { "{}" } else { &b.partial_json };
        let (result, is_err) = execute_tool(&b.tool_name, pj);
        tool_results.push((b.tool_id.clone(), result.clone(), is_err));
        if is_err {
            out.push(format!("error {} {}", b.tool_id, escape_output(&result)));
        } else {
            out.push(format!("result {} {}", b.tool_id, escape_output(&result)));
        }
    }

    // Request 2
    out.push("request 2".to_string());
    let body2 = build_request2(&model, &max_tokens, &thinking_budget, &system, &tools, &prompt, &blocks1, &tool_results);
    let resp2 = http_request(&host, port, &endpoint, &api_key, &body2);

    if resp2.status != 200 {
        let err_str = String::from_utf8_lossy(&resp2.body).to_string();
        let err_json = json_parse(&err_str).unwrap_or(JsonValue::Null);
        let et = err_json.get("error").and_then(|e| e.get_str("type")).unwrap_or("unknown");
        let em = err_json.get("error").and_then(|e| e.get_str("message")).unwrap_or("unknown");
        for l in &out { println!("{}", l); }
        println!("ERROR {} {}: {}", resp2.status, et, em);
        return;
    }

    let events2 = parse_sse(&resp2.body);
    let (blocks2, stop2, i2, o2, c2) = process_stream(&events2);
    total_input += i2;
    total_output += o2;
    total_cache_read += c2;
    print_blocks(&mut out, &blocks2, &stop2);

    out.push(format!("usage input={} output={} cache_read={}", total_input, total_output, total_cache_read));

    for l in &out {
        println!("{}", l);
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.math.BigInteger;

public class Main {

    // === JSON Value Types ===

    abstract static class JVal {
        abstract void write(StringBuilder sb);
    }

    static class JStr extends JVal {
        String raw;
        String val;
        JStr(String raw, String val) { this.raw = raw; this.val = val; }
        JStr(String val) { this.raw = null; this.val = val; }
        void write(StringBuilder sb) {
            sb.append('"');
            if (raw != null) sb.append(raw);
            else escapeStr(sb, val);
            sb.append('"');
        }
    }

    static class JNum extends JVal {
        String raw;
        JNum(String raw) { this.raw = raw; }
        void write(StringBuilder sb) { sb.append(raw); }
    }

    static class JBool extends JVal {
        boolean val;
        JBool(boolean val) { this.val = val; }
        void write(StringBuilder sb) { sb.append(val ? "true" : "false"); }
    }

    static class JNull extends JVal {
        void write(StringBuilder sb) { sb.append("null"); }
    }

    static class JObj extends JVal {
        List<String> keys = new ArrayList<>();
        List<JVal> vals = new ArrayList<>();
        void put(String k, JVal v) { keys.add(k); vals.add(v); }
        JVal get(String k) {
            for (int i = 0; i < keys.size(); i++) if (keys.get(i).equals(k)) return vals.get(i);
            return null;
        }
        void write(StringBuilder sb) {
            sb.append('{');
            for (int i = 0; i < keys.size(); i++) {
                if (i > 0) sb.append(',');
                sb.append('"'); escapeStr(sb, keys.get(i)); sb.append('"'); sb.append(':');
                vals.get(i).write(sb);
            }
            sb.append('}');
        }
    }

    static class JArr extends JVal {
        List<JVal> elems = new ArrayList<>();
        void add(JVal v) { elems.add(v); }
        void write(StringBuilder sb) {
            sb.append('[');
            for (int i = 0; i < elems.size(); i++) {
                if (i > 0) sb.append(',');
                elems.get(i).write(sb);
            }
            sb.append(']');
        }
    }

    // === JSON String Escaping ===

    static void escapeStr(StringBuilder sb, String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
    }

    // === JSON Parser ===

    static class JsonParser {
        String s;
        int pos;

        JsonParser(String s) { this.s = s; this.pos = 0; }

        JVal parse() {
            skipWs();
            JVal v = parseVal();
            skipWs();
            return v;
        }

        void skipWs() {
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        JVal parseVal() {
            char c = s.charAt(pos);
            if (c == '{') return parseObj();
            if (c == '[') return parseArr();
            if (c == '"') return parseStr();
            if (c == 't') { pos += 4; return new JBool(true); }
            if (c == 'f') { pos += 5; return new JBool(false); }
            if (c == 'n') { pos += 4; return new JNull(); }
            return parseNum();
        }

        JObj parseObj() {
            pos++;
            JObj obj = new JObj();
            skipWs();
            if (pos < s.length() && s.charAt(pos) == '}') { pos++; return obj; }
            while (true) {
                skipWs();
                JStr key = parseStr();
                skipWs();
                pos++; // skip ':'
                skipWs();
                JVal val = parseVal();
                obj.put(key.val, val);
                skipWs();
                if (pos < s.length() && s.charAt(pos) == ',') { pos++; continue; }
                if (pos < s.length() && s.charAt(pos) == '}') { pos++; break; }
                break;
            }
            return obj;
        }

        JArr parseArr() {
            pos++;
            JArr arr = new JArr();
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ']') { pos++; return arr; }
            while (true) {
                skipWs();
                JVal v = parseVal();
                arr.add(v);
                skipWs();
                if (pos < s.length() && s.charAt(pos) == ',') { pos++; continue; }
                if (pos < s.length() && s.charAt(pos) == ']') { pos++; break; }
                break;
            }
            return arr;
        }

        JStr parseStr() {
            pos++; // skip opening "
            int start = pos;
            StringBuilder decoded = new StringBuilder();
            while (pos < s.length() && s.charAt(pos) != '"') {
                if (s.charAt(pos) == '\\') {
                    pos++;
                    char esc = s.charAt(pos);
                    switch (esc) {
                        case '"': decoded.append('"'); pos++; break;
                        case '\\': decoded.append('\\'); pos++; break;
                        case '/': decoded.append('/'); pos++; break;
                        case 'b': decoded.append('\b'); pos++; break;
                        case 'f': decoded.append('\f'); pos++; break;
                        case 'n': decoded.append('\n'); pos++; break;
                        case 'r': decoded.append('\r'); pos++; break;
                        case 't': decoded.append('\t'); pos++; break;
                        case 'u':
                            pos++; // skip 'u'
                            int cp = Integer.parseInt(s.substring(pos, pos + 4), 16);
                            pos += 4;
                            if (cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < s.length()
                                    && s.charAt(pos) == '\\' && s.charAt(pos + 1) == 'u') {
                                pos += 2;
                                int cp2 = Integer.parseInt(s.substring(pos, pos + 4), 16);
                                pos += 4;
                                if (cp2 >= 0xDC00 && cp2 <= 0xDFFF) {
                                    int codePoint = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                    decoded.appendCodePoint(codePoint);
                                } else {
                                    decoded.append((char) cp);
                                    decoded.append((char) cp2);
                                }
                            } else {
                                decoded.append((char) cp);
                            }
                            break;
                        default:
                            decoded.append(esc);
                            pos++;
                    }
                } else {
                    decoded.append(s.charAt(pos));
                    pos++;
                }
            }
            String raw = s.substring(start, pos);
            pos++; // skip closing "
            return new JStr(raw, decoded.toString());
        }

        JNum parseNum() {
            int start = pos;
            if (pos < s.length() && s.charAt(pos) == '-') pos++;
            while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            if (pos < s.length() && s.charAt(pos) == '.') {
                pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            return new JNum(s.substring(start, pos));
        }
    }

    // === CSV Parser ===

    static List<String[]> parseCsv(String content) {
        if (content.startsWith("\uFEFF")) content = content.substring(1);
        List<String[]> records = new ArrayList<>();
        int i = 0;
        int len = content.length();
        while (i < len) {
            List<String> fields = new ArrayList<>();
            while (true) {
                if (i < len && content.charAt(i) == '"') {
                    i++;
                    StringBuilder field = new StringBuilder();
                    while (i < len) {
                        if (content.charAt(i) == '"') {
                            if (i + 1 < len && content.charAt(i + 1) == '"') {
                                field.append('"');
                                i += 2;
                            } else {
                                i++;
                                break;
                            }
                        } else {
                            field.append(content.charAt(i));
                            i++;
                        }
                    }
                    fields.add(field.toString());
                } else {
                    StringBuilder field = new StringBuilder();
                    while (i < len && content.charAt(i) != ',' && content.charAt(i) != '\r' && content.charAt(i) != '\n') {
                        field.append(content.charAt(i));
                        i++;
                    }
                    fields.add(field.toString());
                }
                if (i < len && content.charAt(i) == ',') {
                    i++;
                } else {
                    if (i < len && content.charAt(i) == '\r') i++;
                    if (i < len && content.charAt(i) == '\n') i++;
                    break;
                }
            }
            if (!fields.isEmpty() && !(fields.size() == 1 && fields.get(0).isEmpty())) {
                records.add(fields.toArray(new String[0]));
            }
        }
        return records;
    }

    // === HTTP ===

    static class HttpResponse {
        int status;
        String body;
        HttpResponse(int status, String body) { this.status = status; this.body = body; }
    }

    static HttpResponse doPost(String urlStr, String apiKey, String body) throws IOException {
        URL url = new URL(urlStr);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Authorization", "Bearer " + apiKey);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setDoOutput(true);
        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);
        conn.setFixedLengthStreamingMode(bodyBytes.length);
        try (OutputStream os = conn.getOutputStream()) {
            os.write(bodyBytes);
            os.flush();
        }
        int status = conn.getResponseCode();
        InputStream is = (status >= 200 && status < 300) ? conn.getInputStream() : conn.getErrorStream();
        String respBody = "";
        if (is != null) {
            respBody = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            is.close();
        }
        conn.disconnect();
        return new HttpResponse(status, respBody);
    }

    // === Tool Execution ===

    static String executeTool(String name, String argsStr, Map<String, String[]> inventory, Map<String, BigInteger> rates) {
        JObj args = (JObj) new JsonParser(argsStr).parse();

        if (name.equals("inventory_lookup")) {
            String sku = ((JStr) args.get("sku")).val;
            String[] row = inventory.get(sku);
            if (row == null) {
                StringBuilder sb = new StringBuilder();
                sb.append("{\"error\":");
                sb.append('"'); escapeStr(sb, "unknown sku: " + sku); sb.append('"');
                sb.append('}');
                return sb.toString();
            }
            StringBuilder sb = new StringBuilder();
            sb.append("{\"sku\":");
            sb.append('"'); escapeStr(sb, row[0]); sb.append('"');
            sb.append(",\"name\":");
            sb.append('"'); escapeStr(sb, row[1]); sb.append('"');
            sb.append(",\"price_cents\":");
            sb.append(row[2]);
            sb.append(",\"currency\":");
            sb.append('"'); escapeStr(sb, row[3]); sb.append('"');
            sb.append(",\"stock\":");
            sb.append(row[4]);
            sb.append('}');
            return sb.toString();
        } else if (name.equals("convert_currency")) {
            BigInteger amountCents = new BigInteger(((JNum) args.get("amount_cents")).raw);
            String from = ((JStr) args.get("from")).val;
            String to = ((JStr) args.get("to")).val;
            BigInteger rateFrom = rates.get(from);
            BigInteger rateTo = rates.get(to);
            BigInteger numerator = BigInteger.valueOf(2).multiply(amountCents).multiply(rateTo).add(rateFrom);
            BigInteger denominator = BigInteger.valueOf(2).multiply(rateFrom);
            BigInteger converted = numerator.divide(denominator);
            StringBuilder sb = new StringBuilder();
            sb.append("{\"amount_cents\":");
            sb.append(converted.toString());
            sb.append(",\"currency\":");
            sb.append('"'); escapeStr(sb, to); sb.append('"');
            sb.append('}');
            return sb.toString();
        } else {
            StringBuilder sb = new StringBuilder();
            sb.append("{\"error\":");
            sb.append('"'); escapeStr(sb, "unknown tool: " + name); sb.append('"');
            sb.append('}');
            return sb.toString();
        }
    }

    // === Main ===

    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read task.json
        String taskContent = new String(Files.readAllBytes(Paths.get(dataDir, "task.json")), StandardCharsets.UTF_8);
        JObj task = (JObj) new JsonParser(taskContent).parse();
        String apiKey = ((JStr) task.get("api_key")).val;
        String model = ((JStr) task.get("model")).val;
        String system = ((JStr) task.get("system")).val;
        String user = ((JStr) task.get("user")).val;
        JVal tools = task.get("tools");

        // Read rates.json
        String ratesContent = new String(Files.readAllBytes(Paths.get(dataDir, "rates.json")), StandardCharsets.UTF_8);
        JObj ratesObj = (JObj) new JsonParser(ratesContent).parse();
        JObj ratesMap = (JObj) ratesObj.get("rates");
        Map<String, BigInteger> rates = new HashMap<>();
        for (int i = 0; i < ratesMap.keys.size(); i++) {
            rates.put(ratesMap.keys.get(i), new BigInteger(((JNum) ratesMap.vals.get(i)).raw));
        }

        // Read inventory.csv
        String csvContent = new String(Files.readAllBytes(Paths.get(dataDir, "inventory.csv")), StandardCharsets.UTF_8);
        List<String[]> csvRecords = parseCsv(csvContent);
        Map<String, String[]> inventory = new HashMap<>();
        for (int i = 1; i < csvRecords.size(); i++) {
            String[] row = csvRecords.get(i);
            inventory.put(row[0], row);
        }

        // Build initial conversation
        List<JVal> conversation = new ArrayList<>();
        {
            JObj msg = new JObj();
            msg.put("role", new JStr("system"));
            msg.put("content", new JStr(system));
            conversation.add(msg);
        }
        {
            JObj msg = new JObj();
            msg.put("role", new JStr("user"));
            msg.put("content", new JStr(user));
            conversation.add(msg);
        }

        // Loop
        int totalPrompt = 0, totalCompletion = 0, totalTotal = 0, numRequests = 0;
        String endpoint = baseUrl + "/chat/completions";

        while (true) {
            // Build request
            JObj req = new JObj();
            req.put("model", new JStr(model));
            JArr msgsArr = new JArr();
            for (JVal m : conversation) msgsArr.add(m);
            req.put("messages", msgsArr);
            req.put("tools", tools);
            req.put("tool_choice", new JStr("auto"));

            StringBuilder sb = new StringBuilder();
            req.write(sb);
            String reqBody = sb.toString();

            HttpResponse resp = doPost(endpoint, apiKey, reqBody);
            numRequests++;

            if (resp.status != 200) {
                try {
                    JObj errObj = (JObj) new JsonParser(resp.body).parse();
                    JObj err = (JObj) errObj.get("error");
                    String errMsg = ((JStr) err.get("message")).val;
                    System.out.println("ERROR " + resp.status + " " + errMsg);
                } catch (Exception e) {
                    System.out.println("ERROR " + resp.status + " " + resp.body);
                }
                System.exit(0);
            }

            JObj respObj = (JObj) new JsonParser(resp.body).parse();

            // Accumulate usage
            JVal usageVal = respObj.get("usage");
            if (usageVal instanceof JObj) {
                JObj usage = (JObj) usageVal;
                totalPrompt += Integer.parseInt(((JNum) usage.get("prompt_tokens")).raw);
                totalCompletion += Integer.parseInt(((JNum) usage.get("completion_tokens")).raw);
                totalTotal += Integer.parseInt(((JNum) usage.get("total_tokens")).raw);
            }

            JArr choices = (JArr) respObj.get("choices");
            JObj choice = (JObj) choices.elems.get(0);
            String finishReason = ((JStr) choice.get("finish_reason")).val;
            JObj message = (JObj) choice.get("message");

            if (finishReason.equals("stop")) {
                JVal contentVal = message.get("content");
                if (contentVal instanceof JStr) {
                    System.out.println("FINAL " + ((JStr) contentVal).val);
                }
                break;
            }

            if (finishReason.equals("tool_calls")) {
                // Print SAY if content is a string
                JVal contentVal = message.get("content");
                if (contentVal instanceof JStr) {
                    System.out.println("SAY " + ((JStr) contentVal).val);
                }

                JArr toolCalls = (JArr) message.get("tool_calls");

                // Print CALL lines
                for (JVal tc : toolCalls.elems) {
                    JObj tcObj = (JObj) tc;
                    String id = ((JStr) tcObj.get("id")).val;
                    JObj func = (JObj) tcObj.get("function");
                    String name = ((JStr) func.get("name")).val;
                    System.out.println("CALL " + id + " " + name);
                }

                // Execute tools, print RESULT lines, collect results
                List<String> results = new ArrayList<>();
                for (JVal tc : toolCalls.elems) {
                    JObj tcObj = (JObj) tc;
                    String id = ((JStr) tcObj.get("id")).val;
                    JObj func = (JObj) tcObj.get("function");
                    String name = ((JStr) func.get("name")).val;
                    String argsStr = ((JStr) func.get("arguments")).val;

                    String result = executeTool(name, argsStr, inventory, rates);
                    results.add(result);
                    System.out.println("RESULT " + id + " " + result);
                }

                // Append assistant message to conversation
                conversation.add(message);

                // Append tool result messages
                for (int i = 0; i < toolCalls.elems.size(); i++) {
                    JObj tcObj = (JObj) toolCalls.elems.get(i);
                    String id = ((JStr) tcObj.get("id")).val;

                    JObj toolMsg = new JObj();
                    toolMsg.put("role", new JStr("tool"));
                    toolMsg.put("tool_call_id", new JStr(id));
                    toolMsg.put("content", new JStr(results.get(i)));
                    conversation.add(toolMsg);
                }
            }
        }

        System.out.println("USAGE prompt=" + totalPrompt + " completion=" + totalCompletion
                + " total=" + totalTotal + " requests=" + numRequests);
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.CRC32;
import java.math.BigDecimal;

public class Main {
    static byte[] data;
    static int pageSize, reservedBytes, usableSize;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        data = Files.readAllBytes(Path.of(dir, "db.sqlite"));

        pageSize = ((data[16] & 0xFF) << 8) | (data[17] & 0xFF);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = data[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<Row> schemaRows = readTable(1);

        List<TableInfo> tables = new ArrayList<>();
        for (Row r : schemaRows) {
            if (r.cols.size() >= 5) {
                Object type = r.cols.get(0);
                Object name = r.cols.get(1);
                Object rootpage = r.cols.get(3);
                Object sql = r.cols.get(4);
                if (type instanceof String && name instanceof String
                        && rootpage instanceof Long && sql instanceof String) {
                    String typeStr = (String) type;
                    String nameStr = (String) name;
                    if (typeStr.equals("table") && !nameStr.startsWith("sqlite_")) {
                        tables.add(new TableInfo(nameStr, (Long) rootpage, (String) sql));
                    }
                }
            }
        }

        tables.sort((a, b) -> {
            byte[] an = a.name.getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.name.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < tables.size(); t++) {
            if (t > 0) sb.append("\n");
            TableInfo ti = tables.get(t);
            List<ColInfo> cols = parseColumns(ti.sql);
            List<Row> rows = readTable((int) ti.rootpage);

            sb.append("TABLE ").append(ti.name).append(" rows=").append(rows.size()).append("\n");
            List<String> colNames = new ArrayList<>();
            for (ColInfo ci : cols) colNames.add(ci.name);
            sb.append("COLUMNS ").append(String.join(", ", colNames)).append("\n");

            rows.sort((a, b) -> Long.compare(a.rowid, b.rowid));

            for (Row row : rows) {
                sb.append(row.rowid).append(": ");
                List<String> vals = new ArrayList<>();
                for (int c = 0; c < cols.size(); c++) {
                    if (cols.get(c).isRowidAlias) {
                        vals.add(String.valueOf(row.rowid));
                    } else if (c < row.cols.size()) {
                        vals.add(formatVal(row.cols.get(c)));
                    } else {
                        vals.add("NULL");
                    }
                }
                sb.append(String.join(", ", vals)).append("\n");
            }
        }

        System.out.print(sb.toString());
    }

    static class Row {
        long rowid;
        List<Object> cols;
    }

    static class TableInfo {
        String name;
        long rootpage;
        String sql;
        TableInfo(String name, long rootpage, String sql) {
            this.name = name;
            this.rootpage = rootpage;
            this.sql = sql;
        }
    }

    static class ColInfo {
        String name;
        boolean isRowidAlias;
    }

    static List<Row> readTable(int rootPage) {
        List<Row> rows = new ArrayList<>();
        walkBTree(rootPage, rows);
        return rows;
    }

    static void walkBTree(int page, List<Row> rows) {
        int base = (page - 1) * pageSize;
        int hdrOff = (page == 1) ? 100 : 0;
        int pageType = data[base + hdrOff] & 0xFF;

        if (pageType == 0x0D) {
            int numCells = ((data[base + hdrOff + 3] & 0xFF) << 8) | (data[base + hdrOff + 4] & 0xFF);
            int cellPtrStart = base + hdrOff + 8;
            int maxLocal = (usableSize - 35) * 32 / 255 - 23;
            if (maxLocal < 0) maxLocal = 0;

            for (int i = 0; i < numCells; i++) {
                int cellOff = ((data[cellPtrStart + i * 2] & 0xFF) << 8)
                        | (data[cellPtrStart + i * 2 + 1] & 0xFF);
                int pos = base + cellOff;

                long[] vr = readVarint(data, pos);
                long payloadSize = vr[0];
                pos = (int) vr[1];

                vr = readVarint(data, pos);
                long rowid = vr[0];
                pos = (int) vr[1];

                int localSize = (int) Math.min(payloadSize, (long) maxLocal);
                byte[] payload = new byte[(int) payloadSize];
                System.arraycopy(data, pos, payload, 0, localSize);
                pos += localSize;

                if (payloadSize > maxLocal) {
                    int overflowPage = ((data[pos] & 0xFF) << 24) | ((data[pos + 1] & 0xFF) << 16)
                            | ((data[pos + 2] & 0xFF) << 8) | (data[pos + 3] & 0xFF);
                    int written = localSize;
                    int remaining = (int) payloadSize - localSize;
                    while (overflowPage != 0 && remaining > 0) {
                        int opBase = (overflowPage - 1) * pageSize;
                        int nextOp = ((data[opBase] & 0xFF) << 24) | ((data[opBase + 1] & 0xFF) << 16)
                                | ((data[opBase + 2] & 0xFF) << 8) | (data[opBase + 3] & 0xFF);
                        int avail = usableSize - 4;
                        int toRead = Math.min(remaining, avail);
                        System.arraycopy(data, opBase + 4, payload, written, toRead);
                        written += toRead;
                        remaining -= toRead;
                        overflowPage = nextOp;
                    }
                }

                Row row = new Row();
                row.rowid = rowid;
                row.cols = decodeRecord(payload);
                rows.add(row);
            }
        } else if (pageType == 0x05) {
            int numCells = ((data[base + hdrOff + 3] & 0xFF) << 8) | (data[base + hdrOff + 4] & 0xFF);
            int cellPtrStart = base + hdrOff + 12;

            for (int i = 0; i < numCells; i++) {
                int cellOff = ((data[cellPtrStart + i * 2] & 0xFF) << 8)
                        | (data[cellPtrStart + i * 2 + 1] & 0xFF);
                int pos = base + cellOff;
                long[] vr = readVarint(data, pos);
                int childPage = (int) vr[0];
                walkBTree(childPage, rows);
            }

            int rightMost = ((data[base + hdrOff + 8] & 0xFF) << 24)
                    | ((data[base + hdrOff + 9] & 0xFF) << 16)
                    | ((data[base + hdrOff + 10] & 0xFF) << 8)
                    | (data[base + hdrOff + 11] & 0xFF);
            walkBTree(rightMost, rows);
        }
    }

    static long[] readVarint(byte[] buf, int pos) {
        long val = 0;
        for (int i = 0; i < 9; i++) {
            int b = buf[pos + i] & 0xFF;
            if (i < 8) {
                val = (val << 7) | (b & 0x7F);
                if ((b & 0x80) == 0) return new long[]{val, pos + i + 1};
            } else {
                val = (val << 8) | b;
                return new long[]{val, pos + 9};
            }
        }
        return new long[]{val, pos + 9};
    }

    static List<Object> decodeRecord(byte[] payload) {
        List<Object> cols = new ArrayList<>();
        if (payload.length == 0) return cols;

        int pos = 0;
        long[] vr = readVarint(payload, pos);
        long headerSize = vr[0];
        pos = (int) vr[1];

        List<Long> serialTypes = new ArrayList<>();
        while (pos < headerSize) {
            vr = readVarint(payload, pos);
            serialTypes.add(vr[0]);
            pos = (int) vr[1];
        }

        int dataPos = (int) headerSize;
        for (long st : serialTypes) {
            if (st == 0) {
                cols.add(null);
            } else if (st >= 1 && st <= 6) {
                int numBytes = (int) st;
                long val = 0;
                for (int i = 0; i < numBytes; i++) {
                    val = (val << 8) | (payload[dataPos + i] & 0xFF);
                }
                if ((payload[dataPos] & 0x80) != 0) {
                    val -= (1L << (numBytes * 8));
                }
                cols.add(val);
                dataPos += numBytes;
            } else if (st == 7) {
                long bits = 0;
                for (int i = 0; i < 8; i++) {
                    bits = (bits << 8) | (payload[dataPos + i] & 0xFF);
                }
                cols.add(Double.longBitsToDouble(bits));
                dataPos += 8;
            } else if (st == 8) {
                cols.add(0L);
            } else if (st == 9) {
                cols.add(1L);
            } else if (st >= 12 && st % 2 == 0) {
                int len = (int) ((st - 12) / 2);
                byte[] b = Arrays.copyOfRange(payload, dataPos, dataPos + len);
                cols.add(b);
                dataPos += len;
            } else if (st >= 13 && st % 2 == 1) {
                int len = (int) ((st - 13) / 2);
                byte[] b = Arrays.copyOfRange(payload, dataPos, dataPos + len);
                cols.add(new String(b, StandardCharsets.UTF_8));
                dataPos += len;
            }
        }
        return cols;
    }

    static String formatVal(Object val) {
        if (val == null) return "NULL";
        if (val instanceof Long) return String.valueOf((Long) val);
        if (val instanceof Double) return formatReal((Double) val);
        if (val instanceof byte[]) return formatBlob((byte[]) val);
        if (val instanceof String) return formatText((String) val);
        return "NULL";
    }

    static String formatReal(double d) {
        BigDecimal bd = new BigDecimal(d);
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        while (s.endsWith("0") && !s.endsWith(".0")) {
            s = s.substring(0, s.length() - 1);
        }
        return s;
    }

    static String formatText(String text) {
        byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
        if (bytes.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(bytes);
            return "<TEXT len=" + bytes.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        int i = 0;
        while (i < bytes.length) {
            int b = bytes[i] & 0xFF;
            if (b == 0x5C) { sb.append("\\\\"); i++; }
            else if (b == 0x22) { sb.append("\\\""); i++; }
            else if (b == 0x0A) { sb.append("\\n"); i++; }
            else if (b == 0x0D) { sb.append("\\r"); i++; }
            else if (b == 0x09) { sb.append("\\t"); i++; }
            else if (b < 0x20 || b == 0x7F) {
                sb.append(String.format("\\x%02X", b));
                i++;
            } else {
                int start = i;
                while (i < bytes.length) {
                    int c = bytes[i] & 0xFF;
                    if (c == 0x5C || c == 0x22 || c == 0x0A || c == 0x0D || c == 0x09
                            || c < 0x20 || c == 0x7F) break;
                    i++;
                }
                sb.append(new String(bytes, start, i - start, StandardCharsets.UTF_8));
            }
        }
        sb.append('"');
        return sb.toString();
    }

    static String formatBlob(byte[] bytes) {
        if (bytes.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(bytes);
            return "<BLOB len=" + bytes.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder();
        sb.append("X'");
        for (byte b : bytes) {
            sb.append(String.format("%02X", b & 0xFF));
        }
        sb.append("'");
        return sb.toString();
    }

    static List<ColInfo> parseColumns(String sql) {
        List<ColInfo> cols = new ArrayList<>();
        int pos = skipCreateTable(sql, 0);
        if (pos >= sql.length() || sql.charAt(pos) != '(') return cols;
        int openParen = pos;
        int closeParen = findMatchingParen(sql, openParen);
        String defs = sql.substring(openParen + 1, closeParen);

        List<String> defList = splitByCommas(defs);

        for (String def : defList) {
            String trimmed = def.trim();
            if (trimmed.isEmpty()) continue;

            ColInfo ci = new ColInfo();
            int p = 0;
            if (trimmed.charAt(0) == '"') {
                int qEnd = trimmed.indexOf('"', 1);
                ci.name = trimmed.substring(1, qEnd);
                p = qEnd + 1;
            } else {
                int i = 0;
                while (i < trimmed.length() && isIdentChar(trimmed.charAt(i))) i++;
                ci.name = trimmed.substring(0, i);
                p = i;
            }

            String rest = trimmed.substring(p).trim();
            ci.isRowidAlias = false;
            if (containsPrimaryKey(rest) && !rest.isEmpty()) {
                int i = 0;
                while (i < rest.length() && isIdentChar(rest.charAt(i))) i++;
                String firstWord = rest.substring(0, i);
                if (firstWord.equalsIgnoreCase("INTEGER")) {
                    if (i >= rest.length() || (!isIdentChar(rest.charAt(i)) && rest.charAt(i) != '(')) {
                        ci.isRowidAlias = true;
                    }
                }
            }
            cols.add(ci);
        }
        return cols;
    }

    static int skipCreateTable(String sql, int pos) {
        pos = skipWs(sql, pos);
        pos = skipWord(sql, pos, "CREATE");
        pos = skipWs(sql, pos);
        pos = skipWord(sql, pos, "TABLE");
        pos = skipWs(sql, pos);
        if (pos < sql.length() && sql.charAt(pos) == '"') {
            pos++;
            while (pos < sql.length() && sql.charAt(pos) != '"') pos++;
            pos++;
        } else {
            while (pos < sql.length() && !Character.isWhitespace(sql.charAt(pos))
                    && sql.charAt(pos) != '(') pos++;
        }
        pos = skipWs(sql, pos);
        return pos;
    }

    static int skipWs(String s, int pos) {
        while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++;
        return pos;
    }

    static int skipWord(String s, int pos, String word) {
        if (pos + word.length() <= s.length()
                && s.substring(pos, pos + word.length()).equalsIgnoreCase(word)) {
            return pos + word.length();
        }
        return pos;
    }

    static int findMatchingParen(String s, int open) {
        int depth = 0;
        for (int i = open; i < s.length(); i++) {
            if (s.charAt(i) == '(') depth++;
            else if (s.charAt(i) == ')') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static List<String> splitByCommas(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i));
                start = i + 1;
            }
        }
        parts.add(s.substring(start));
        return parts;
    }

    static boolean containsPrimaryKey(String s) {
        String upper = s.toUpperCase();
        int idx = 0;
        while ((idx = upper.indexOf("PRIMARY", idx)) >= 0) {
            int after = idx + 7;
            while (after < upper.length() && Character.isWhitespace(upper.charAt(after))) after++;
            if (after + 3 <= upper.length() && upper.substring(after, after + 3).equals("KEY")) {
                int afterKey = after + 3;
                if (afterKey >= upper.length() || !isIdentChar(upper.charAt(afterKey))) {
                    return true;
                }
            }
            idx++;
        }
        return false;
    }

    static boolean isIdentChar(char c) {
        return Character.isLetterOrDigit(c) || c == '_';
    }
}

