/* ============ Dynamic string buffer ============ */
typedef struct { char *d; size_t len, cap; } sb;
static void sb_init(sb *b){b->d=NULL;b->len=0;b->cap=0;}
static void sb_ens(sb *b,size_t e){if(b->len+e+1>b->cap){b->cap=(b->len+e+1)*2;if(b->cap<256)b->cap=256;b->d=realloc(b->d,b->cap);}}
static void sb_ap(sb *b,const char *s,size_t n){sb_ens(b,n);memcpy(b->d+b->len,s,n);b->len+=n;b->d[b->len]=0;}
static void sb_as(sb *b,const char *s){sb_ap(b,s,strlen(s));}
static void sb_ac(sb *b,char c){sb_ap(b,&c,1);}
static void sb_pf(sb *b,const char *fmt,...){char t[1024];va_list ap;va_start(ap,fmt);int n=vsnprintf(t,sizeof t,fmt,ap);va_end(ap);if(n>0)sb_ap(b,t,(size_t)n);}
static char *sb_dup(sb *b){if(!b->d)return strdup("");return strndup(b->d,b->len);}

/* ============ JSON value ============ */
typedef enum{JV_NULL,JV_TRUE,JV_FALSE,JV_NUM,JV_STR,JV_ARR,JV_OBJ}jtype;
typedef struct jval{
    jtype type;
    char *num;
    char *str;
    struct{struct jval **items;int cnt,cap;}arr;
    struct{char **keys;struct jval **vals;int cnt,cap;}obj;
}jval;

static jval *jnew(jtype t){jval *v=calloc(1,sizeof(jval));v->type=t;return v;}
static void jarr_push(jval *a,jval *item){if(a->arr.cnt==a->arr.cap){a->arr.cap=a->arr.cap?a->arr.cap*2:8;a->arr.items=realloc(a->arr.items,a->arr.cap*sizeof(void*));}a->arr.items[a->arr.cnt++]=item;}
static void jobj_push(jval *o,const char *k,jval *v){if(o->obj.cnt==o->obj.cap){o->obj.cap=o->obj.cap?o->obj.cap*2:8;o->obj.keys=realloc(o->obj.keys,o->obj.cap*sizeof(char*));o->obj.vals=realloc(o->obj.vals,o->obj.cap*sizeof(void*));}o->obj.keys[o->obj.cnt]=strdup(k);o->obj.vals[o->obj.cnt]=v;o->obj.cnt++;}
static jval *jobj_get(jval *o,const char *k){if(!o||o->type!=JV_OBJ)return NULL;for(int i=0;i<o->obj.cnt;i++)if(!strcmp(o->obj.keys[i],k))return o->obj.vals[i];return NULL;}
static jval *jarr_get(jval *a,int i){if(!a||a->type!=JV_ARR||i<0||i>=a->arr.cnt)return NULL;return a->arr.items[i];}

/* ============ JSON parser ============ */
typedef struct{const char *d;size_t pos,len;}jp;
static void jp_skip(jp *p){while(p->pos<p->len&&(p->d[p->pos]==' '||p->d[p->pos]=='\t'||p->d[p->pos]=='\n'||p->d[p->pos]=='\r'))p->pos++;}
static jval *jp_val(jp *p);
static char *jp_str_raw(jp *p){
    if(p->pos>=p->len||p->d[p->pos]!='"')return NULL;
    p->pos++;
    sb b;sb_init(&b);
    while(p->pos<p->len&&p->d[p->pos]!='"'){
        if(p->d[p->pos]=='\\'){
            p->pos++;
            if(p->pos>=p->len)break;
            char c=p->d[p->pos++];
            switch(c){
                case '"':sb_ac(&b,'"');break;
                case '\\':sb_ac(&b,'\\');break;
                case '/':sb_ac(&b,'/');break;
                case 'b':sb_ac(&b,'\b');break;
                case 'f':sb_ac(&b,'\f');break;
                case 'n':sb_ac(&b,'\n');break;
                case 'r':sb_ac(&b,'\r');break;
                case 't':sb_ac(&b,'\t');break;
                case 'u':{
                    if(p->pos+4>p->len)break;
                    unsigned cp=0;
                    for(int i=0;i<4;i++){char h=p->d[p->pos++];cp=cp*16+(isdigit(h)?h-'0':(tolower(h)-'a'+10));}
                    if(cp>=0xD800&&cp<=0xDBFF&&p->pos+6<=p->len&&p->d[p->pos]=='\\'&&p->d[p->pos+1]=='u'){
                        p->pos+=2;unsigned lo=0;
                        for(int i=0;i<4;i++){char h=p->d[p->pos++];lo=lo*16+(isdigit(h)?h-'0':(tolower(h)-'a'+10));}
                        if(lo>=0xDC00&&lo<=0xDFFF)cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                        else{sb_ac(&b,'?');cp=lo;}
                    }
                    if(cp<0x80)sb_ac(&b,(char)cp);
                    else if(cp<0x800){sb_ac(&b,(char)(0xC0|(cp>>6)));sb_ac(&b,(char)(0x80|(cp&0x3F)));}
                    else if(cp<0x10000){sb_ac(&b,(char)(0xE0|(cp>>12)));sb_ac(&b,(char)(0x80|((cp>>6)&0x3F)));sb_ac(&b,(char)(0x80|(cp&0x3F)));}
                    else{sb_ac(&b,(char)(0xF0|(cp>>18)));sb_ac(&b,(char)(0x80|((cp>>12)&0x3F)));sb_ac(&b,(char)(0x80|((cp>>6)&0x3F)));sb_ac(&b,(char)(0x80|(cp&0x3F)));}
                    break;
                }
                default:sb_ac(&b,c);break;
            }
        }else{
            sb_ac(&b,p->d[p->pos++]);
        }
    }
    if(p->pos<p->len)p->pos++;
    return sb_dup(&b);
}
static jval *jp_val(jp *p){
    jp_skip(p);
    if(p->pos>=p->len)return jnew(JV_NULL);
    char c=p->d[p->pos];
    if(c=='"'){jval *v=jnew(JV_STR);v->str=jp_str_raw(p);return v;}
    if(c=='['){p->pos++;jval *v=jnew(JV_ARR);jp_skip(p);if(p->pos<p->len&&p->d[p->pos]==']'){p->pos++;return v;}while(1){jarr_push(v,jp_val(p));jp_skip(p);if(p->pos<p->len&&p->d[p->pos]==','){p->pos++;continue;}if(p->pos<p->len&&p->d[p->pos]==']'){p->pos++;break;}break;}return v;}
    if(c=='{'){p->pos++;jval *v=jnew(JV_OBJ);jp_skip(p);if(p->pos<p->len&&p->d[p->pos]=='}'){p->pos++;return v;}while(1){jp_skip(p);char *k=jp_str_raw(p);jp_skip(p);if(p->pos<p->len&&p->d[p->pos]==':')p->pos++;jobj_push(v,k?k:"",jp_val(p));free(k);jp_skip(p);if(p->pos<p->len&&p->d[p->pos]==','){p->pos++;continue;}if(p->pos<p->len&&p->d[p->pos]=='}'){p->pos++;break;}break;}return v;}
    if(c=='t'){if(p->pos+4<=p->len&&!memcmp(p->d+p->pos,"true",4)){p->pos+=4;return jnew(JV_TRUE);}p->pos++;return jnew(JV_NULL);}
    if(c=='f'){if(p->pos+5<=p->len&&!memcmp(p->d+p->pos,"false",5)){p->pos+=5;return jnew(JV_FALSE);}p->pos++;return jnew(JV_NULL);}
    if(c=='n'){if(p->pos+4<=p->len&&!memcmp(p->d+p->pos,"null",4)){p->pos+=4;return jnew(JV_NULL);}p->pos++;return jnew(JV_NULL);}
    size_t start=p->pos;
    if(p->pos<p->len&&p->d[p->pos]=='-')p->pos++;
    while(p->pos<p->len&&isdigit(p->d[p->pos]))p->pos++;
    if(p->pos<p->len&&p->d[p->pos]=='.'){p->pos++;while(p->pos<p->len&&isdigit(p->d[p->pos]))p->pos++;}
    if(p->pos<p->len&&(p->d[p->pos]=='e'||p->d[p->pos]=='E')){p->pos++;if(p->pos<p->len&&(p->d[p->pos]=='+'||p->d[p->pos]=='-'))p->pos++;while(p->pos<p->len&&isdigit(p->d[p->pos]))p->pos++;}
    jval *v=jnew(JV_NUM);v->num=strndup(p->d+start,p->pos-start);return v;
}
static jval *json_parse(const char *s,size_t len){jp p={s,0,len};return jp_val(&p);}

/* ============ JSON serializer ============ */
static void js_str(sb *b,const char *s){
    sb_ac(b,'"');
    for(const char *p=s;p&&*p;p++){
        unsigned char c=(unsigned char)*p;
        if(c=='"')sb_as(b,"\\\"");
        else if(c=='\\')sb_as(b,"\\\\");
        else if(c=='\n')sb_as(b,"\\n");
        else if(c=='\r')sb_as(b,"\\r");
        else if(c=='\t')sb_as(b,"\\t");
        else if(c=='\b')sb_as(b,"\\b");
        else if(c=='\f')sb_as(b,"\\f");
        else if(c<0x20)sb_pf(b,"\\u%04x",c);
        else sb_ac(b,(char)c);
    }
    sb_ac(b,'"');
}
static void js_val(sb *b,jval *v){
    if(!v){sb_as(b,"null");return;}
    switch(v->type){
        case JV_NULL:sb_as(b,"null");break;
        case JV_TRUE:sb_as(b,"true");break;
        case JV_FALSE:sb_as(b,"false");break;
        case JV_NUM:sb_as(b,v->num?v->num:"0");break;
        case JV_STR:js_str(b,v->str?v->str:"");break;
        case JV_ARR:sb_ac(b,'[');for(int i=0;i<v->arr.cnt;i++){if(i)sb_ac(b,',');js_val(b,v->arr.items[i]);}sb_ac(b,']');break;
        case JV_OBJ:sb_ac(b,'{');for(int i=0;i<v->obj.cnt;i++){if(i)sb_ac(b,',');js_str(b,v->obj.keys[i]);sb_ac(b,':');js_val(b,v->obj.vals[i]);}sb_ac(b,'}');break;
    }
}

/* ============ UTF-8 utilities ============ */
static int utf8_decode(const char *s,uint32_t *cp){
    unsigned char c=(unsigned char)*s;
    if(c<0x80){*cp=c;return 1;}
    else if((c&0xE0)==0xC0){*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    else if((c&0xF0)==0xE0){*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    else{*cp=((c&0x07)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;}
}
static int utf8_encode(uint32_t cp,char *out){
    if(cp<0x80){out[0]=(char)cp;return 1;}
    else if(cp<0x800){out[0]=(char)(0xC0|(cp>>6));out[1]=(char)(0x80|(cp&0x3F));return 2;}
    else if(cp<0x10000){out[0]=(char)(0xE0|(cp>>12));out[1]=(char)(0x80|((cp>>6)&0x3F));out[2]=(char)(0x80|(cp&0x3F));return 3;}
    else{out[0]=(char)(0xF0|(cp>>18));out[1]=(char)(0x80|((cp>>12)&0x3F));out[2]=(char)(0x80|((cp>>6)&0x3F));out[3]=(char)(0x80|(cp&0x3F));return 4;}
}
static int utf8_count(const char *s){int n=0;while(*s){uint32_t cp;s+=utf8_decode(s,&cp);n++;}return n;}
static int utf16_count(const char *s){int n=0;while(*s){uint32_t cp;s+=utf8_decode(s,&cp);n+=(cp>0xFFFF)?2:1;}return n;}
static char *utf8_reverse(const char *s){
    int total=0;const char *p=s;while(*p){uint32_t cp;p+=utf8_decode(p,&cp);total++;}
    uint32_t *cps=malloc((total+1)*sizeof(uint32_t));
    p=s;for(int i=0;i<total;i++){cps[i]=0;p+=utf8_decode(p,&cps[i]);}
    sb b;sb_init(&b);
    for(int i=total-1;i>=0;i--){char tmp[4];int n=utf8_encode(cps[i],tmp);sb_ap(&b,tmp,n);}
    free(cps);
    return sb_dup(&b);
}

/* ============ HTTP client ============ */
static int parse_url(const char *url,char *host,int *port,char *path){
    const char *p=url;
    if(!strncmp(p,"http://",7))p+=7;
    else if(!strncmp(p,"https://",8))p+=8;
    const char *colon=strchr(p,':');
    const char *slash=strchr(p,'/');
    if(colon&&(!slash||colon<slash)){
        size_t hlen=(size_t)(colon-p);
        memcpy(host,p,hlen);host[hlen]=0;
        *port=atoi(colon+1);
        if(slash)strcpy(path,slash);else strcpy(path,"/");
    }else{
        size_t hlen=slash?(size_t)(slash-p):strlen(p);
        memcpy(host,p,hlen);host[hlen]=0;
        *port=80;
        if(slash)strcpy(path,slash);else strcpy(path,"/");
    }
    return 0;
}

static char *http_post(const char *host,int port,const char *path,const char *api_key,const char *body,size_t body_len,int *status){
    struct addrinfo hints={0},*res;
    char portstr[16];snprintf(portstr,sizeof portstr,"%d",port);
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    if(getaddrinfo(host,portstr,&hints,&res)){*status=0;return NULL;}
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);*status=0;return NULL;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);*status=0;return NULL;}
    freeaddrinfo(res);

    sb req;sb_init(&req);
    sb_pf(&req,"POST %s HTTP/1.1\r\n",path);
    sb_pf(&req,"Host: %s:%d\r\n",host,port);
    sb_pf(&req,"Content-Length: %zu\r\n",body_len);
    sb_as(&req,"x-api-key: ");sb_as(&req,api_key);sb_as(&req,"\r\n");
    sb_as(&req,"anthropic-version: 2023-06-01\r\n");
    sb_as(&req,"content-type: application/json\r\n");
    sb_as(&req,"\r\n");
    sb_ap(&req,body,body_len);
    write(fd,req.d,req.len);
    free(req.d);

    sb resp;sb_init(&resp);
    char buf[65536];
    ssize_t n;
    while((n=read(fd,buf,sizeof buf))>0)sb_ap(&resp,buf,(size_t)n);
    close(fd);
    if(resp.d)resp.d[resp.len]=0;

    *status=0;
    if(resp.len>=12&&!memcmp(resp.d,"HTTP/1.1 ",9)){
        *status=atoi(resp.d+9);
    }else if(resp.len>=12&&!memcmp(resp.d,"HTTP/1.0 ",9)){
        *status=atoi(resp.d+9);
    }
    return sb_dup(&resp);
}

/* ============ Chunked decoder ============ */
static char *decode_chunked(const char *body,size_t blen,size_t *out_len){
    sb out;sb_init(&out);
    size_t pos=0;
    while(pos<blen){
        size_t sz=0;
        while(pos<blen&&isxdigit((unsigned char)body[pos])){
            char c=body[pos];
            sz=sz*16+(isdigit(c)?c-'0':(tolower(c)-'a'+10));
            pos++;
        }
        while(pos<blen&&body[pos]!='\n')pos++;
        if(pos<blen)pos++;
        if(sz==0)break;
        if(pos+sz<=blen){sb_ap(&out,body+pos,sz);pos+=sz;}
        else{sb_ap(&out,body+pos,blen-pos);pos=blen;break;}
        if(pos<blen&&body[pos]=='\r')pos++;
        if(pos<blen&&body[pos]=='\n')pos++;
    }
    *out_len=out.len;
    return sb_dup(&out);
}

/* ============ SSE parser ============ */
typedef struct{char *event;char *data;}sse_event;
typedef struct{sse_event *items;int cnt,cap;}sse_list;
static void sse_add(sse_list *l,const char *ev,const char *data){
    if(l->cnt==l->cap){l->cap=l->cap?l->cap*2:16;l->items=realloc(l->items,l->cap*sizeof(sse_event));}
    l->items[l->cnt].event=strdup(ev?ev:"");
    l->items[l->cnt].data=strdup(data?data:"");
    l->cnt++;
}
static sse_list *parse_sse(const char *body,size_t blen){
    sse_list *l=calloc(1,sizeof(sse_list));
    char *cur_ev=NULL;
    sb cur_data;sb_init(&cur_data);
    int has_data=0;
    size_t pos=0;
    while(pos<=blen){
        size_t lstart=pos;
        while(pos<blen&&body[pos]!='\n')pos++;
        size_t lend=pos;
        if(pos<blen)pos++;
        if(lend>lstart&&body[lend-1]=='\r')lend--;
        size_t linelen=lend-lstart;
        const char *line=body+lstart;

        if(linelen==0){
            if(has_data){
                sse_add(l,cur_ev,cur_data.d?cur_data.d:"");
            }
            free(cur_ev);cur_ev=NULL;
            free(cur_data.d);sb_init(&cur_data);
            has_data=0;
            continue;
        }
        if(line[0]==':')continue;
        const char *colon=memchr(line,':',linelen);
        if(!colon)continue;
        size_t fname_len=(size_t)(colon-line);
        const char *fval=colon+1;
        size_t fval_len=linelen-fname_len-1;
        if(fval_len>0&&fval[0]==' '){fval++;fval_len--;}

        if(fname_len==5&&!memcmp(line,"event",5)){
            free(cur_ev);cur_ev=malloc(fval_len+1);memcpy(cur_ev,fval,fval_len);cur_ev[fval_len]=0;
        }else if(fname_len==4&&!memcmp(line,"data",4)){
            if(has_data)sb_ac(&cur_data,'\n');
            sb_ap(&cur_data,fval,fval_len);
            has_data=1;
        }
    }
    if(has_data){
        sse_add(l,cur_ev,cur_data.d?cur_data.d:"");
    }
    free(cur_ev);free(cur_data.d);
    return l;
}

/* ============ Content blocks ============ */
typedef struct{
    char *type;
    char *thinking;
    char *signature;
    char *text;
    char *id;
    char *name;
    char *input_raw;
    char *tool_result;
    int tool_is_error;
}cblock;

typedef struct{
    cblock *blocks;int cnt,cap;
    char *stop_reason;
}reply;

static void reply_init(reply *r){memset(r,0,sizeof(*r));}
static cblock *reply_get_block(reply *r,int idx){
    while(r->cnt<=idx){
        if(r->cnt==r->cap){r->cap=r->cap?r->cap*2:8;r->blocks=realloc(r->blocks,r->cap*sizeof(cblock));memset(&r->blocks[r->cnt],0,(r->cap-r->cnt)*sizeof(cblock));}
        r->cnt++;
    }
    return &r->blocks[idx];
}

/* ============ Output escaping ============ */
static void print_escaped(sb *out,const char *s){
    for(const char *p=s;p&&*p;p++){
        char c=*p;
        if(c=='\\')sb_as(out,"\\\\");
        else if(c=='\n')sb_as(out,"\\n");
        else if(c=='\r')sb_as(out,"\\r");
        else if(c=='\t')sb_as(out,"\\t");
        else sb_ac(out,c);
    }
}

/* ============ Tools ============ */
static char *tool_measure(const char *text,const char *unit,int *err){
    *err=0;
    if(!strcmp(unit,"code_points")){
        char buf[32];snprintf(buf,sizeof buf,"%d",utf8_count(text));return strdup(buf);
    }else if(!strcmp(unit,"utf8_bytes")){
        char buf[32];snprintf(buf,sizeof buf,"%zu",strlen(text));return strdup(buf);
    }else if(!strcmp(unit,"utf16_units")){
        char buf[32];snprintf(buf,sizeof buf,"%d",utf16_count(text));return strdup(buf);
    }else{
        *err=1;
        sb b;sb_init(&b);sb_as(&b,"unsupported unit: ");sb_as(&b,unit);return sb_dup(&b);
    }
}
static char *tool_reverse(const char *text){return utf8_reverse(text);}

/* ============ Process SSE events into a reply ============ */
static void process_events(sse_list *events,reply *r,long long *total_input,long long *total_output,long long *total_cache){
    for(int i=0;i<events->cnt;i++){
        const char *ev=events->items[i].event;
        const char *data=events->items[i].data;
        if(!ev||!data||!*data)continue;
        jval *jv=json_parse(data,strlen(data));
        if(!jv)continue;
        if(!strcmp(ev,"message_start")){
            jval *msg=jobj_get(jv,"message");
            jval *usage=jobj_get(msg,"usage");
            jval *it=jobj_get(usage,"input_tokens");
            jval *cr=jobj_get(usage,"cache_read_input_tokens");
            if(it&&it->type==JV_NUM)*total_input+=atoll(it->num);
            if(cr&&cr->type==JV_NUM)*total_cache+=atoll(cr->num);
        }else if(!strcmp(ev,"content_block_start")){
            jval *jidx=jobj_get(jv,"index");
            int idx=jidx&&jidx->type==JV_NUM?atoi(jidx->num):0;
            jval *cb=jobj_get(jv,"content_block");
            cblock *blk=reply_get_block(r,idx);
            jval *jtype=jobj_get(cb,"type");
            blk->type=strdup(jtype&&jtype->type==JV_STR?jtype->str:"");
            if(!strcmp(blk->type,"thinking")){blk->thinking=strdup("");blk->signature=strdup("");}
            else if(!strcmp(blk->type,"text")){blk->text=strdup("");}
            else if(!strcmp(blk->type,"tool_use")){
                jval *jid=jobj_get(cb,"id");jval *jname=jobj_get(cb,"name");
                blk->id=strdup(jid&&jid->type==JV_STR?jid->str:"");
                blk->name=strdup(jname&&jname->type==JV_STR?jname->str:"");
                blk->input_raw=strdup("");
            }
        }else if(!strcmp(ev,"content_block_delta")){
            jval *jidx=jobj_get(jv,"index");
            int idx=jidx&&jidx->type==JV_NUM?atoi(jidx->num):0;
            jval *delta=jobj_get(jv,"delta");
            jval *dtype=jobj_get(delta,"type");
            if(!dtype||dtype->type!=JV_STR)continue;
            cblock *blk=reply_get_block(r,idx);
            if(!strcmp(dtype->str,"thinking_delta")){
                jval *t=jobj_get(delta,"thinking");
                if(t&&t->type==JV_STR){
                    size_t ol=strlen(blk->thinking?blk->thinking:"");
                    size_t nl=ol+strlen(t->str);
                    blk->thinking=realloc(blk->thinking,nl+1);
                    memcpy(blk->thinking+ol,t->str,strlen(t->str)+1);
                }
            }else if(!strcmp(dtype->str,"signature_delta")){
                jval *t=jobj_get(delta,"signature");
                if(t&&t->type==JV_STR){
                    size_t ol=strlen(blk->signature?blk->signature:"");
                    size_t nl=ol+strlen(t->str);
                    blk->signature=realloc(blk->signature,nl+1);
                    memcpy(blk->signature+ol,t->str,strlen(t->str)+1);
                }
            }else if(!strcmp(dtype->str,"text_delta")){
                jval *t=jobj_get(delta,"text");
                if(t&&t->type==JV_STR){
                    size_t ol=strlen(blk->text?blk->text:"");
                    size_t nl=ol+strlen(t->str);
                    blk->text=realloc(blk->text,nl+1);
                    memcpy(blk->text+ol,t->str,strlen(t->str)+1);
                }
            }else if(!strcmp(dtype->str,"input_json_delta")){
                jval *t=jobj_get(delta,"partial_json");
                if(t&&t->type==JV_STR){
                    size_t ol=strlen(blk->input_raw?blk->input_raw:"");
                    size_t nl=ol+strlen(t->str);
                    blk->input_raw=realloc(blk->input_raw,nl+1);
                    memcpy(blk->input_raw+ol,t->str,strlen(t->str)+1);
                }
            }
        }else if(!strcmp(ev,"message_delta")){
            jval *delta=jobj_get(jv,"delta");
            jval *sr=jobj_get(delta,"stop_reason");
            if(sr&&sr->type==JV_STR)r->stop_reason=strdup(sr->str);
            jval *usage=jobj_get(jv,"usage");
            jval *ot=jobj_get(usage,"output_tokens");
            if(ot&&ot->type==JV_NUM)*total_output+=atoll(ot->num);
        }
    }
}

/* ============ Print reply blocks ============ */
static void print_reply(sb *output,reply *r,const char *label){
    sb_as(output,label);
    sb_ac(output,'\n');
    for(int i=0;i<r->cnt;i++){
        cblock *b=&r->blocks[i];
        if(!b->type)continue;
        if(!strcmp(b->type,"thinking")){
            sb_as(output,"thinking ");print_escaped(output,b->thinking);sb_ac(output,'\n');
            sb_as(output,"signature ");print_escaped(output,b->signature);sb_ac(output,'\n');
        }else if(!strcmp(b->type,"text")){
            sb_as(output,"text ");print_escaped(output,b->text);sb_ac(output,'\n');
        }else if(!strcmp(b->type,"tool_use")){
            sb_as(output,"tool_use ");
            print_escaped(output,b->id);sb_ac(output,' ');
            print_escaped(output,b->name);sb_ac(output,' ');
            print_escaped(output,b->input_raw);sb_ac(output,'\n');
        }
    }
    sb_as(output,"stop_reason ");print_escaped(output,r->stop_reason?r->stop_reason:"");sb_ac(output,'\n');
}

/* ============ Main ============ */
static char *read_file(const char *path,size_t *len){
    FILE *f=fopen(path,"rb");
    if(!f)return NULL;
    fseek(f,0,SEEK_END);*len=ftell(f);fseek(f,0,SEEK_SET);
    char *buf=malloc(*len+1);
    fread(buf,1,*len,f);buf[*len]=0;fclose(f);
    return buf;
}

static void build_request_body(sb *body,const char *model,const char *max_tokens,
    const char *thinking_budget,jval *j_system,jval *j_tools,
    const char *prompt,int is_request2,reply *r1)
{
    sb_as(body,"{\"model\":");js_str(body,model);
    sb_as(body,",\"max_tokens\":");sb_as(body,max_tokens);
    sb_as(body,",\"stream\":true");
    sb_as(body,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");sb_as(body,thinking_budget);sb_as(body,"}");
    sb_as(body,",\"system\":");
    if(j_system)js_val(body,j_system);else sb_as(body,"null");
    sb_as(body,",\"tools\":");js_val(body,j_tools);
    sb_as(body,",\"messages\":[");
    /* message 1: user with prompt */
    sb_as(body,"{\"role\":\"user\",\"content\":");js_str(body,prompt);sb_as(body,"}");
    if(is_request2){
        /* message 2: assistant with content blocks */
        sb_as(body,",{\"role\":\"assistant\",\"content\":[");
        for(int i=0;i<r1->cnt;i++){
            cblock *b=&r1->blocks[i];
            if(!b->type)continue;
            if(i>0)sb_ac(body,',');
            if(!strcmp(b->type,"thinking")){
                sb_as(body,"{\"type\":\"thinking\",\"thinking\":");js_str(body,b->thinking?b->thinking:"");
                sb_as(body,",\"signature\":");js_str(body,b->signature?b->signature:"");
                sb_as(body,"}");
            }else if(!strcmp(b->type,"text")){
                sb_as(body,"{\"type\":\"text\",\"text\":");js_str(body,b->text?b->text:"");
                sb_as(body,"}");
            }else if(!strcmp(b->type,"tool_use")){
                sb_as(body,"{\"type\":\"tool_use\",\"id\":");js_str(body,b->id?b->id:"");
                sb_as(body,",\"name\":");js_str(body,b->name?b->name:"");
                sb_as(body,",\"input\":");
                jval *inp=json_parse(b->input_raw?b->input_raw:"{}",b->input_raw?strlen(b->input_raw):2);
                js_val(body,inp);
                sb_as(body,"}");
            }
        }
        sb_as(body,"]}");
        /* message 3: user with tool results */
        sb_as(body,",{\"role\":\"user\",\"content\":[");
        int first=1;
        for(int i=0;i<r1->cnt;i++){
            cblock *b=&r1->blocks[i];
            if(!b->type||strcmp(b->type,"tool_use"))continue;
            if(!first)sb_ac(body,',');first=0;
            sb_as(body,"{\"type\":\"tool_result\",\"tool_use_id\":");js_str(body,b->id?b->id:"");
            sb_as(body,",\"content\":");js_str(body,b->tool_result?b->tool_result:"");
            if(b->tool_is_error)sb_as(body,",\"is_error\":true");
            sb_as(body,"}");
        }
        sb_as(body,"]}]");
    }else{
        sb_as(body,"]");
    }
}

int main(int argc,char *argv[]){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    char dpath[4096];snprintf(dpath,sizeof dpath,"%s/request.json",argv[1]);
    size_t flen;char *fdata=read_file(dpath,&flen);
    if(!fdata){fprintf(stderr,"cannot read %s\n",dpath);return 1;}
    jval *cfg=json_parse(fdata,flen);
    if(!cfg){fprintf(stderr,"cannot parse request.json\n");return 1;}

    jval *j_api_key=jobj_get(cfg,"api_key");
    jval *j_model=jobj_get(cfg,"model");
    jval *j_max_tokens=jobj_get(cfg,"max_tokens");
    jval *j_thinking_budget=jobj_get(cfg,"thinking_budget");
    jval *j_system=jobj_get(cfg,"system");
    jval *j_prompt=jobj_get(cfg,"prompt");
    jval *j_tools=jobj_get(cfg,"tools");

    const char *api_key=j_api_key&&j_api_key->type==JV_STR?j_api_key->str:"";
    const char *model=j_model&&j_model->type==JV_STR?j_model->str:"";
    const char *max_tokens=j_max_tokens&&j_max_tokens->type==JV_NUM?j_max_tokens->num:"8000";
    const char *thinking_budget=j_thinking_budget&&j_thinking_budget->type==JV_NUM?j_thinking_budget->num:"1024";
    const char *prompt=j_prompt&&j_prompt->type==JV_STR?j_prompt->str:"";

    /* parse base_url */
    char host[256]={0},path[256]={0};int port=80;
    parse_url(argv[2],host,&port,path);
    char endpoint[512];snprintf(endpoint,sizeof endpoint,"%s/v1/messages",path);

    /* output buffer */
    sb output;sb_init(&output);

    long long total_input=0,total_output=0,total_cache=0;

    /* ---- Request 1 ---- */
    sb body1;sb_init(&body1);
    build_request_body(&body1,model,max_tokens,thinking_budget,j_system,j_tools,prompt,0,NULL);

    int status1=0;
    char *resp1=http_post(host,port,endpoint,api_key,body1.d,body1.len,&status1);
    if(!resp1){sb_pf(&output,"ERROR 0 connect: connection failed\n");fputs(output.d,stdout);return 0;}

    /* find header/body boundary */
    char *hdr_end=strstr(resp1,"\r\n\r\n");
    char *body_start;
    if(hdr_end)body_start=hdr_end+4;
    else{hdr_end=strstr(resp1,"\n\n");if(hdr_end)body_start=hdr_end+2;else body_start=resp1+strlen(resp1);}
    size_t body1_len=strlen(body_start);

    if(status1!=200){
        jval *err=json_parse(body_start,body1_len);
        jval *err_obj=jobj_get(err,"error");
        jval *etype=jobj_get(err_obj,"type");
        jval *emsg=jobj_get(err_obj,"message");
        sb_pf(&output,"ERROR %d %s: %s\n",status1,
            etype&&etype->type==JV_STR?etype->str:"unknown",
            emsg&&emsg->type==JV_STR?emsg->str:"");
        fputs(output.d,stdout);
        return 0;
    }

    size_t decoded1_len;
    char *decoded1=decode_chunked(body_start,body1_len,&decoded1_len);
    sse_list *events1=parse_sse(decoded1,decoded1_len);

    reply r1;reply_init(&r1);
    process_events(events1,&r1,&total_input,&total_output,&total_cache);

    /* print request 1 */
    print_reply(&output,&r1,"request 1");

    /* execute tools */
    for(int i=0;i<r1.cnt;i++){
        cblock *b=&r1.blocks[i];
        if(!b->type||strcmp(b->type,"tool_use"))continue;
        jval *inp=json_parse(b->input_raw?b->input_raw:"{}",b->input_raw?strlen(b->input_raw):2);
        jval *jtext=jobj_get(inp,"text");
        const char *text=jtext&&jtext->type==JV_STR?jtext->str:"";
        int is_err=0;
        char *result=NULL;
        if(!strcmp(b->name,"measure")){
            jval *junit=jobj_get(inp,"unit");
            const char *unit=junit&&junit->type==JV_STR?junit->str:"";
            result=tool_measure(text,unit,&is_err);
        }else if(!strcmp(b->name,"reverse")){
            result=tool_reverse(text);
        }else{
            is_err=1;
            sb eb;sb_init(&eb);sb_as(&eb,"unknown tool: ");sb_as(&eb,b->name);result=sb_dup(&eb);
        }
        b->tool_result=result;
        b->tool_is_error=is_err;
        if(is_err){
            sb_as(&output,"error ");print_escaped(&output,b->id);sb_ac(&output,' ');print_escaped(&output,result);sb_ac(&output,'\n');
        }else{
            sb_as(&output,"result ");print_escaped(&output,b->id);sb_ac(&output,' ');print_escaped(&output,result);sb_ac(&output,'\n');
        }
    }

    /* ---- Request 2 ---- */
    sb body2;sb_init(&body2);
    build_request_body(&body2,model,max_tokens,thinking_budget,j_system,j_tools,prompt,1,&r1);

    int status2=0;
    char *resp2=http_post(host,port,endpoint,api_key,body2.d,body2.len,&status2);
    if(!resp2){sb_pf(&output,"ERROR 0 connect: connection failed\n");fputs(output.d,stdout);return 0;}

    char *hdr_end2=strstr(resp2,"\r\n\r\n");
    char *body_start2;
    if(hdr_end2)body_start2=hdr_end2+4;
    else{hdr_end2=strstr(resp2,"\n\n");if(hdr_end2)body_start2=hdr_end2+2;else body_start2=resp2+strlen(resp2);}
    size_t body2_len=strlen(body_start2);

    if(status2!=200){
        jval *err=json_parse(body_start2,body2_len);
        jval *err_obj=jobj_get(err,"error");
        jval *etype=jobj_get(err_obj,"type");
        jval *emsg=jobj_get(err_obj,"message");
        sb_pf(&output,"ERROR %d %s: %s\n",status2,
            etype&&etype->type==JV_STR?etype->str:"unknown",
            emsg&&emsg->type==JV_STR?emsg->str:"");
        fputs(output.d,stdout);
        return 0;
    }

    size_t decoded2_len;
    char *decoded2=decode_chunked(body_start2,body2_len,&decoded2_len);
    sse_list *events2=parse_sse(decoded2,decoded2_len);

    reply r2;reply_init(&r2);
    process_events(events2,&r2,&total_input,&total_output,&total_cache);

    /* print request 2 */
    print_reply(&output,&r2,"request 2");

    sb_pf(&output,"usage input=%lld output=%lld cache_read=%lld\n",total_input,total_output,total_cache);

    fputs(output.d,stdout);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

// --- CSV Parsing (RFC 4180) ---
function parseCSV(content: string): string[][] {
  if (content.charCodeAt(0) === 0xFEFF) content = content.substring(1);
  const rows: string[][] = [];
  let i = 0;
  const len = content.length;

  while (i < len) {
    const row: string[] = [];
    let endOfRecord = false;

    while (!endOfRecord) {
      let field: string;
      if (i < len && content[i] === '"') {
        i++;
        let val = '';
        while (i < len) {
          if (content[i] === '"') {
            if (i + 1 < len && content[i + 1] === '"') {
              val += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            val += content[i];
            i++;
          }
        }
        field = val;
      } else {
        let val = '';
        while (i < len && content[i] !== ',' && content[i] !== '\r' && content[i] !== '\n') {
          val += content[i];
          i++;
        }
        field = val;
      }
      row.push(field);

      if (i < len && content[i] === ',') {
        i++;
      } else {
        if (i < len && content[i] === '\r') {
          i++;
          if (i < len && content[i] === '\n') i++;
        } else if (i < len && content[i] === '\n') {
          i++;
        }
        endOfRecord = true;
      }
    }

    if (row.length > 0 && !(row.length === 1 && row[0] === '')) {
      rows.push(row);
    }
  }
  return rows;
}

// --- JSON string escaping for tool results ---
function escStr(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x22) r += '\\"';
    else if (c === 0x5C) r += '\\\\';
    else if (c === 0x08) r += '\\b';
    else if (c === 0x0C) r += '\\f';
    else if (c === 0x0A) r += '\\n';
    else if (c === 0x0D) r += '\\r';
    else if (c === 0x09) r += '\\t';
    else if (c < 0x20) r += '\\u00' + c.toString(16).padStart(2, '0');
    else r += s[i];
  }
  return r + '"';
}

function serializeResult(obj: Record<string, string | number>): string {
  const keys = Object.keys(obj);
  let r = '{';
  for (let i = 0; i < keys.length; i++) {
    if (i > 0) r += ',';
    r += escStr(keys[i]) + ':';
    const v = obj[keys[i]];
    if (typeof v === 'string') r += escStr(v);
    else r += String(v);
  }
  return r + '}';
}

// --- Tool execution ---
function executeTool(
  name: string,
  argsStr: string,
  inventory: Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>,
  rates: Record<string, number>
): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const item = inventory.get(sku);
    if (item) {
      return serializeResult({
        sku: item.sku,
        name: item.name,
        price_cents: item.price_cents,
        currency: item.currency,
        stock: item.stock,
      });
    } else {
      return serializeResult({ error: `unknown sku: ${sku}` });
    }
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates[from]);
    const rateTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    // HALF_UP: (2*amount*rateTo + rateFrom) / (2*rateFrom)
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = Number(numerator / denominator);
    return serializeResult({ amount_cents: converted, currency: to });
  } else {
    return serializeResult({ error: `unknown tool: ${name}` });
  }
}

// --- HTTP POST ---
function httpPost(
  url: string,
  headers: Record<string, string>,
  body: string
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const req = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port ? parseInt(parsed.port, 10) : 80,
        path: parsed.pathname + parsed.search,
        method: 'POST',
        headers: {
          ...headers,
          'Content-Length': String(Buffer.byteLength(body, 'utf-8')),
          'Host': parsed.host,
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (chunk: Buffer) => chunks.push(chunk));
        res.on('end', () => {
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString('utf-8'),
          });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// --- Extract raw JSON text of choices[0].message from response body ---
function extractRawMessage(responseBody: string): string | null {
  // Find "choices" at top level
  let pos = findKeyValueStart(responseBody, 0, 'choices', 1);
  if (pos < 0) return null;
  if (responseBody[pos] !== '[') return null;
  pos++; // skip '['
  pos = skipWS(responseBody, pos);
  if (responseBody[pos] !== '{') return null;
  // Now find "message" key inside this first object
  return findKeyInObject(responseBody, pos, 'message');
}

function skipWS(s: string, i: number): number {
  while (i < s.length && (s[i] === ' ' || s[i] === '\t' || s[i] === '\n' || s[i] === '\r')) i++;
  return i;
}

function findKeyValueStart(json: string, start: number, key: string, targetDepth: number): number {
  let depth = 0;
  let pos = start;
  let inStr = false;
  let esc = false;
  while (pos < json.length) {
    if (esc) { esc = false; pos++; continue; }
    if (inStr) {
      if (json[pos] === '\\') esc = true;
      else if (json[pos] === '"') inStr = false;
      pos++;
      continue;
    }
    if (json[pos] === '{' || json[pos] === '[') { depth++; pos++; continue; }
    if (json[pos] === '}' || json[pos] === ']') { depth--; pos++; continue; }
    if (json[pos] === '"') {
      const s = pos;
      pos++;
      while (pos < json.length) {
        if (json[pos] === '\\') { pos += 2; continue; }
        if (json[pos] === '"') break;
        pos++;
      }
      const k = json.substring(s + 1, pos);
      pos++; // skip closing "
      if (depth === targetDepth && k === key) {
        pos = skipWS(json, pos);
        if (json[pos] === ':') pos++;
        pos = skipWS(json, pos);
        return pos;
      }
      continue;
    }
    pos++;
  }
  return -1;
}

function findKeyInObject(json: string, objStart: number, key: string): string | null {
  let depth = 0;
  let pos = objStart;
  let inStr = false;
  let esc = false;
  while (pos < json.length) {
    if (esc) { esc = false; pos++; continue; }
    if (inStr) {
      if (json[pos] === '\\') esc = true;
      else if (json[pos] === '"') inStr = false;
      pos++;
      continue;
    }
    if (json[pos] === '{' || json[pos] === '[') { depth++; pos++; continue; }
    if (json[pos] === '}' || json[pos] === ']') {
      depth--;
      if (depth === 0) break;
      pos++;
      continue;
    }
    if (json[pos] === '"') {
      const s = pos;
      pos++;
      while (pos < json.length) {
        if (json[pos] === '\\') { pos += 2; continue; }
        if (json[pos] === '"') break;
        pos++;
      }
      const k = json.substring(s + 1, pos);
      pos++;
      if (depth === 1 && k === key) {
        pos = skipWS(json, pos);
        if (json[pos] === ':') pos++;
        pos = skipWS(json, pos);
        return extractValue(json, pos);
      }
      continue;
    }
    pos++;
  }
  return null;
}

function extractValue(json: string, pos: number): string {
  if (pos >= json.length) return '';
  const ch = json[pos];
  if (ch === '{' || ch === '[') {
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = pos; i < json.length; i++) {
      if (esc) { esc = false; continue; }
      if (inStr) {
        if (json[i] === '\\') esc = true;
        else if (json[i] === '"') inStr = false;
        continue;
      }
      if (json[i] === '"') { inStr = true; continue; }
      if (json[i] === '{' || json[i] === '[') depth++;
      if (json[i] === '}' || json[i] === ']') {
        depth--;
        if (depth === 0) return json.substring(pos, i + 1);
      }
    }
    return '';
  }
  if (ch === '"') {
    let i = pos + 1;
    while (i < json.length) {
      if (json[i] === '\\') { i += 2; continue; }
      if (json[i] === '"') return json.substring(pos, i + 1);
      i++;
    }
    return '';
  }
  let i = pos;
  while (i < json.length && json[i] !== ',' && json[i] !== '}' && json[i] !== ']' && json[i] !== ' ' && json[i] !== '\t' && json[i] !== '\n' && json[i] !== '\r') i++;
  return json.substring(pos, i);
}

// --- Build request body preserving raw assistant messages ---
function buildRequestBody(model: string, messages: any[], tools: any[]): string {
  let body = '{"model":' + JSON.stringify(model) + ',"messages":[';
  for (let i = 0; i < messages.length; i++) {
    if (i > 0) body += ',';
    if (messages[i].__raw) {
      body += messages[i].__raw;
    } else {
      body += JSON.stringify(messages[i]);
    }
  }
  body += '],"tools":' + JSON.stringify(tools) + ',"tool_choice":"auto"}';
  return body;
}

// --- Main ---
async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const taskJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8'));
  const csvContent = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const ratesJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8'));

  // Parse inventory
  const csvRows = parseCSV(csvContent);
  const inventory = new Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>();
  for (let i = 1; i < csvRows.length; i++) {
    const r = csvRows[i];
    if (r.length < 5) continue;
    inventory.set(r[0], {
      sku: r[0],
      name: r[1],
      price_cents: parseInt(r[2], 10),
      currency: r[3],
      stock: parseInt(r[4], 10),
    });
  }

  const { api_key, model, system, user, tools } = taskJson;

  const conversation: any[] = [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTokens = 0;
  let requestCount = 0;
  const output: string[] = [];
  let hadError = false;

  while (true) {
    const body = buildRequestBody(model, conversation, tools);

    const resp = await httpPost(`${baseUrl}/chat/completions`, {
      'Authorization': `Bearer ${api_key}`,
      'Content-Type': 'application/json',
    }, body);

    requestCount++;

    if (resp.status !== 200) {
      let errMsg = '';
      try {
        const errJson = JSON.parse(resp.body);
        errMsg = errJson?.error?.message ?? '';
      } catch {}
      output.push(`ERROR ${resp.status} ${errMsg}`);
      hadError = true;
      break;
    }

    const respJson = JSON.parse(resp.body);

    if (respJson.usage) {
      totalPrompt += respJson.usage.prompt_tokens ?? 0;
      totalCompletion += respJson.usage.completion_tokens ?? 0;
      totalTokens += respJson.usage.total_tokens ?? 0;
    }

    const choice = respJson.choices[0];
    const msg = choice.message;
    const finish = choice.finish_reason;

    if (finish === 'stop') {
      output.push(`FINAL ${msg.content}`);
      break;
    }

    // finish_reason === 'tool_calls'
    if (typeof msg.content === 'string') {
      output.push(`SAY ${msg.content}`);
    }

    const toolCalls: any[] = msg.tool_calls ?? [];

    for (const tc of toolCalls) {
      output.push(`CALL ${tc.id} ${tc.function.name}`);
    }

    const toolResults: string[] = [];
    for (const tc of toolCalls) {
      const result = executeTool(tc.function.name, tc.function.arguments, inventory, ratesJson.rates);
      toolResults.push(result);
      output.push(`RESULT ${tc.id} ${result}`);
    }

    // Append assistant message with raw text preserved
    const rawMsg = extractRawMessage(resp.body);
    if (rawMsg) {
      conversation.push({ __raw: rawMsg });
    } else {
      conversation.push({
        role: msg.role,
        content: msg.content ?? null,
        tool_calls: msg.tool_calls,
      });
    }

    // Append tool result messages
    for (let i = 0; i < toolCalls.length; i++) {
      conversation.push({
        role: 'tool',
        tool_call_id: toolCalls[i].id,
        content: toolResults[i],
      });
    }
  }

  if (!hadError) {
    output.push(`USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalTokens} requests=${requestCount}`);
  }

  process.stdout.write(output.join('\n') + '\n');
}

main().catch((e) => {
  process.stderr.write(String(e) + '\n');
  process.exit(1);
});

import * as fs from 'fs';

const dir = process.argv[2];
const filePath = dir + '/db.sqlite';
const fileBuf = fs.readFileSync(filePath);

const pageSizeRaw = fileBuf.readUInt16BE(16);
const pageSize = pageSizeRaw === 1 ? 65536 : pageSizeRaw;
const reservedBytes = fileBuf[20];
const usableSize = pageSize - reservedBytes;

function readPage(pageNum: number): Buffer {
    const offset = (pageNum - 1) * pageSize;
    return fileBuf.subarray(offset, offset + pageSize);
}

function readVarint(buf: Buffer, offset: number): { value: number; bytesRead: number } {
    let value = 0;
    for (let i = 0; i < 9; i++) {
        const byte = buf[offset + i];
        if (i === 8) {
            value = value * 256 + byte;
            return { value, bytesRead: 9 };
        }
        value = value * 128 + (byte & 0x7F);
        if ((byte & 0x80) === 0) {
            return { value, bytesRead: i + 1 };
        }
    }
    throw new Error('Invalid varint');
}

function readVarintBigInt(buf: Buffer, offset: number): { value: bigint; bytesRead: number } {
    let value = 0n;
    for (let i = 0; i < 9; i++) {
        const byte = buf[offset + i];
        if (i === 8) {
            value = value * 256n + BigInt(byte);
            return { value, bytesRead: 9 };
        }
        value = value * 128n + BigInt(byte & 0x7F);
        if ((byte & 0x80) === 0) {
            return { value, bytesRead: i + 1 };
        }
    }
    throw new Error('Invalid varint');
}

function toSigned64(value: bigint): bigint {
    if (value >= 0x8000000000000000n) {
        return value - 0x10000000000000000n;
    }
    return value;
}

interface PageInfo {
    type: number;
    cellCount: number;
    cellPointers: number[];
    rightmostPointer?: number;
}

function parsePageHeader(page: Buffer, pageNum: number): PageInfo {
    const hdr = pageNum === 1 ? 100 : 0;
    const type = page[hdr];
    const cellCount = page.readUInt16BE(hdr + 2);
    const isInterior = type === 2 || type === 5;
    const hdrSize = isInterior ? 12 : 8;
    const cellPointers: number[] = [];
    for (let i = 0; i < cellCount; i++) {
        cellPointers.push(page.readUInt16BE(hdr + hdrSize + i * 2));
    }
    let rightmostPointer: number | undefined;
    if (isInterior) {
        rightmostPointer = page.readUInt32BE(hdr + 8);
    }
    return { type, cellCount, cellPointers, rightmostPointer };
}

function readFullPayload(page: Buffer, cellOffset: number, payloadSize: number, isInterior: boolean): Buffer {
    const U = usableSize - (isInterior ? 65 : 35);
    let localSize: number;

    if (payloadSize <= U) {
        localSize = payloadSize;
        return Buffer.from(page.subarray(cellOffset, cellOffset + localSize));
    }

    const M = Math.floor((usableSize - 12) * 32 / 255) - 23;
    let K = M + ((payloadSize - M) % (usableSize - 4));
    if (K > U) K = U;
    localSize = K;

    const local = Buffer.from(page.subarray(cellOffset, cellOffset + localSize));
    const overflowPageNum = page.readUInt32BE(cellOffset + localSize);
    const overflowSize = payloadSize - localSize;
    const overflow = Buffer.alloc(overflowSize);
    let currentOffset = 0;
    let nextPage = overflowPageNum;

    while (nextPage !== 0 && currentOffset < overflowSize) {
        const pageData = readPage(nextPage);
        const nextOverflow = pageData.readUInt32BE(0);
        const dataLen = Math.min(usableSize - 4, overflowSize - currentOffset);
        pageData.copy(overflow, currentOffset, 4, 4 + dataLen);
        currentOffset += dataLen;
        nextPage = nextOverflow;
    }

    return Buffer.concat([local, overflow]);
}

interface TableRow {
    rowid: bigint;
    payload: Buffer;
}

function walkBTree(pageNum: number): TableRow[] {
    const rows: TableRow[] = [];
    const page = readPage(pageNum);
    const info = parsePageHeader(page, pageNum);

    if (info.type === 5) {
        for (let i = 0; i < info.cellCount; i++) {
            const cellOff = info.cellPointers[i];
            const childPage = page.readUInt32BE(cellOff);
            rows.push(...walkBTree(childPage));
        }
        if (info.rightmostPointer !== undefined) {
            rows.push(...walkBTree(info.rightmostPointer));
        }
    } else if (info.type === 10) {
        for (let i = 0; i < info.cellCount; i++) {
            const cellOff = info.cellPointers[i];
            const { value: payloadSize, bytesRead: b1 } = readVarint(page, cellOff);
            const { value: rowidRaw, bytesRead: b2 } = readVarintBigInt(page, cellOff + b1);
            const rowid = toSigned64(rowidRaw);
            const dataOffset = cellOff + b1 + b2;
            const payload = readFullPayload(page, dataOffset, payloadSize, false);
            rows.push({ rowid, payload });
        }
    }

    return rows;
}

type Value =
    | { type: 'null' }
    | { type: 'integer', value: bigint }
    | { type: 'real', value: number }
    | { type: 'text', value: Buffer }
    | { type: 'blob', value: Buffer };

function parseRecord(payload: Buffer): Value[] {
    if (payload.length === 0) return [];

    const { value: headerSize, bytesRead } = readVarint(payload, 0);
    const serialTypes: number[] = [];
    let offset = bytesRead;

    while (offset < headerSize) {
        const { value: st, bytesRead: b } = readVarint(payload, offset);
        serialTypes.push(st);
        offset += b;
    }

    const values: Value[] = [];
    let bodyOffset = headerSize;

    for (const st of serialTypes) {
        if (st === 0) {
            values.push({ type: 'null' });
        } else if (st === 1) {
            const v = payload.readInt8(bodyOffset);
            values.push({ type: 'integer', value: BigInt(v) });
            bodyOffset += 1;
        } else if (st === 2) {
            const v = payload.readInt16BE(bodyOffset);
            values.push({ type: 'integer', value: BigInt(v) });
            bodyOffset += 2;
        } else if (st === 3) {
            let v = (payload[bodyOffset] << 16) | (payload[bodyOffset + 1] << 8) | payload[bodyOffset + 2];
            if (v & 0x800000) v -= 0x1000000;
            values.push({ type: 'integer', value: BigInt(v) });
            bodyOffset += 3;
        } else if (st === 4) {
            const v = payload.readInt32BE(bodyOffset);
            values.push({ type: 'integer', value: BigInt(v) });
            bodyOffset += 4;
        } else if (st === 5) {
            let v = 0n;
            for (let i = 0; i < 6; i++) v = (v << 8n) | BigInt(payload[bodyOffset + i]);
            if (v & 0x800000000000n) v -= 0x1000000000000n;
            values.push({ type: 'integer', value: v });
            bodyOffset += 6;
        } else if (st === 6) {
            let v = 0n;
            for (let i = 0; i < 8; i++) v = (v << 8n) | BigInt(payload[bodyOffset + i]);
            if (v & 0x8000000000000000n) v -= 0x10000000000000000n;
            values.push({ type: 'integer', value: v });
            bodyOffset += 8;
        } else if (st === 7) {
            const v = payload.readDoubleBE(bodyOffset);
            values.push({ type: 'real', value: v });
            bodyOffset += 8;
        } else if (st === 8) {
            values.push({ type: 'integer', value: 0n });
        } else if (st === 9) {
            values.push({ type: 'integer', value: 1n });
        } else if (st >= 12 && st % 2 === 0) {
            const len = (st - 12) / 2;
            values.push({ type: 'blob', value: Buffer.from(payload.subarray(bodyOffset, bodyOffset + len)) });
            bodyOffset += len;
        } else if (st >= 13 && st % 2 === 1) {
            const len = (st - 13) / 2;
            values.push({ type: 'text', value: Buffer.from(payload.subarray(bodyOffset, bodyOffset + len)) });
            bodyOffset += len;
        } else {
            values.push({ type: 'null' });
        }
    }

    return values;
}

function crc32(data: Buffer): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >>> 1) ^ 0xEDB88320;
            } else {
                crc >>>= 1;
            }
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(value: number): string {
    if (Object.is(value, -0)) return '0.0';
    let str = value.toFixed(8);
    // Strip trailing zeros but keep at least one digit after decimal
    str = str.replace(/0+$/, '');
    if (str.endsWith('.')) str += '0';
    return str;
}

function formatText(buf: Buffer): string {
    const str = buf.toString('utf-8');
    let result = '"';
    for (const ch of str) {
        const cp = ch.codePointAt(0)!;
        if (cp === 0x5C) result += '\\\\';
        else if (cp === 0x22) result += '\\"';
        else if (cp === 0x0A) result += '\\n';
        else if (cp === 0x0D) result += '\\r';
        else if (cp === 0x09) result += '\\t';
        else if (cp < 0x20 || cp === 0x7F) {
            result += '\\x' + cp.toString(16).toUpperCase().padStart(2, '0');
        } else {
            result += ch;
        }
    }
    result += '"';
    return result;
}

function formatBlob(buf: Buffer): string {
    let hex = '';
    for (let i = 0; i < buf.length; i++) {
        hex += buf[i].toString(16).toUpperCase().padStart(2, '0');
    }
    return "X'" + hex + "'";
}

function formatValue(val: Value): string {
    if (val.type === 'null') return 'NULL';
    if (val.type === 'integer') return val.value.toString();
    if (val.type === 'real') return formatReal(val.value);
    if (val.type === 'text') {
        if (val.value.length <= 100) return formatText(val.value);
        const crc = crc32(val.value);
        return `<TEXT len=${val.value.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
    }
    if (val.type === 'blob') {
        if (val.value.length <= 100) return formatBlob(val.value);
        const crc = crc32(val.value);
        return `<BLOB len=${val.value.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
    }
    return 'NULL';
}

function parseCreateTable(sql: string): { colNames: string[]; rowidAliases: boolean[] } {
    let i = 0;
    // Skip whitespace
    while (i < sql.length && /\s/.test(sql[i])) i++;
    // Skip "CREATE"
    while (i < sql.length && /[a-zA-Z]/.test(sql[i])) i++;
    // Skip whitespace
    while (i < sql.length && /\s/.test(sql[i])) i++;
    // Skip "TABLE"
    while (i < sql.length && /[a-zA-Z]/.test(sql[i])) i++;
    // Skip whitespace
    while (i < sql.length && /\s/.test(sql[i])) i++;

    // Skip table name (may be double-quoted)
    if (i < sql.length && sql[i] === '"') {
        i++;
        while (i < sql.length && sql[i] !== '"') i++;
        i++;
    } else {
        while (i < sql.length && !/\s/.test(sql[i]) && sql[i] !== '(') i++;
    }

    // Skip whitespace
    while (i < sql.length && /\s/.test(sql[i])) i++;

    // Now should be at '('
    if (i >= sql.length || sql[i] !== '(') {
        return { colNames: [], rowidAliases: [] };
    }
    i++; // skip '('

    // Find matching ')'
    let depth = 1;
    const start = i;
    while (i < sql.length && depth > 0) {
        if (sql[i] === '(') depth++;
        else if (sql[i] === ')') depth--;
        if (depth > 0) i++;
    }
    const defsStr = sql.substring(start, i);

    // Split by commas at depth 0
    const defs: string[] = [];
    depth = 0;
    let current = '';
    for (let j = 0; j < defsStr.length; j++) {
        const ch = defsStr[j];
        if (ch === '(') depth++;
        else if (ch === ')') depth--;
        else if (ch === ',' && depth === 0) {
            defs.push(current);
            current = '';
            continue;
        }
        current += ch;
    }
    if (current.trim().length > 0) defs.push(current);

    const colNames: string[] = [];
    const rowidAliases: boolean[] = [];

    for (const def of defs) {
        let k = 0;
        while (k < def.length && /\s/.test(def[k])) k++;

        let colName: string;
        if (k < def.length && def[k] === '"') {
            k++;
            const nameStart = k;
            while (k < def.length && def[k] !== '"') k++;
            colName = def.substring(nameStart, k);
            k++; // skip closing quote
        } else {
            const nameStart = k;
            while (k < def.length && !/\s/.test(def[k]) && def[k] !== '(') k++;
            colName = def.substring(nameStart, k);
        }

        colNames.push(colName);

        // Check for INTEGER PRIMARY KEY
        const rest = def.substring(k);
        const restUpper = rest.toUpperCase();

        // Extract type name: first token after column name
        let tk = 0;
        while (tk < rest.length && /\s/.test(rest[tk])) tk++;
        const typeStart = tk;
        while (tk < rest.length && !/\s/.test(rest[tk]) && rest[tk] !== '(' && rest[tk] !== ')') tk++;
        const typeName = rest.substring(typeStart, tk);
        const followedByParen = tk < rest.length && rest[tk] === '(';

        let isAlias = false;
        if (!followedByParen && typeName.toUpperCase() === 'INTEGER') {
            // Check for PRIMARY KEY in the rest
            const words = restUpper.split(/[^A-Z0-9_]+/).filter(w => w.length > 0);
            if (words.includes('PRIMARY') && words.includes('KEY')) {
                isAlias = true;
            }
        }

        rowidAliases.push(isAlias);
    }

    return { colNames, rowidAliases };
}

// Read schema from page 1
const schemaRows = walkBTree(1);

interface TableInfo {
    name: string;
    rootpage: number;
    sql: string;
}

const tables: TableInfo[] = [];

for (const row of schemaRows) {
    const values = parseRecord(row.payload);
    if (values.length < 5) continue;

    const typeVal = values[0];
    if (typeVal.type !== 'text') continue;
    const typeStr = typeVal.value.toString('utf-8');
    if (typeStr !== 'table') continue;

    const nameVal = values[1];
    if (nameVal.type !== 'text') continue;
    const nameStr = nameVal.value.toString('utf-8');
    if (nameStr.startsWith('sqlite_')) continue;

    const rootVal = values[3];
    if (rootVal.type !== 'integer') continue;
    const rootpage = Number(rootVal.value);

    const sqlVal = values[4];
    if (sqlVal.type !== 'text') continue;
    const sqlStr = sqlVal.value.toString('utf-8');

    tables.push({ name: nameStr, rootpage, sql: sqlStr });
}

// Sort by name (byte-wise ascending, which equals code-point order for UTF-8)
tables.sort((a, b) => {
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    return 0;
});

const outputLines: string[] = [];

for (let t = 0; t < tables.length; t++) {
    const table = tables[t];
    const { colNames, rowidAliases } = parseCreateTable(table.sql);
    const rows = walkBTree(table.rootpage);
    rows.sort((a, b) => {
        if (a.rowid < b.rowid) return -1;
        if (a.rowid > b.rowid) return 1;
        return 0;
    });

    outputLines.push(`TABLE ${table.name} rows=${rows.length}`);
    outputLines.push(`COLUMNS ${colNames.join(', ')}`);

    for (const row of rows) {
        const values = parseRecord(row.payload);
        const formatted: string[] = [];

        for (let c = 0; c < colNames.length; c++) {
            if (rowidAliases[c]) {
                formatted.push(row.rowid.toString());
            } else {
                if (c < values.length) {
                    formatted.push(formatValue(values[c]));
                } else {
                    formatted.push('NULL');
                }
            }
        }

        outputLines.push(`${row.rowid}: ${formatted.join(', ')}`);
    }

    if (t < tables.length - 1) {
        outputLines.push('');
    }
}

process.stdout.write(outputLines.join('\n') + '\n');

use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Int(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).expect("failed to read database file");

    let page_size_raw = u16::from_be_bytes([data[16], data[17]]) as usize;
    let page_size = if page_size_raw == 1 { 65536 } else { page_size_raw };
    let reserved = data[20] as usize;

    // Read schema from page 1
    let schema_rows = read_btree(&data, 1, page_size, reserved);

    // Collect user tables
    let mut tables: Vec<(String, i64, String)> = Vec::new();
    for (_rowid, values) in &schema_rows {
        if values.len() >= 5 {
            let rtype = get_text(&values[0]);
            let name = get_text(&values[1]);
            let rootpage = get_int(&values[3]);
            let sql = get_text(&values[4]);
            if rtype == "table" && !name.starts_with("sqlite_") {
                tables.push((name, rootpage, sql));
            }
        }
    }

    tables.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut output = String::new();
    let mut first = true;

    for (name, rootpage, sql) in &tables {
        if !first {
            output.push('\n');
        }
        first = false;

        let (columns, rowid_alias) = parse_create_table(sql);
        let rows = read_btree(&data, *rootpage as usize, page_size, reserved);

        output.push_str(&format!("TABLE {} rows={}\n", name, rows.len()));
        output.push_str(&format!("COLUMNS {}\n", columns.join(", ")));

        for (rowid, values) in &rows {
            output.push_str(&format!("{}: ", rowid));
            let mut parts: Vec<String> = Vec::new();
            for i in 0..columns.len() {
                if Some(i) == rowid_alias {
                    parts.push(format!("{}", rowid));
                } else if i < values.len() {
                    parts.push(format_value(&values[i]));
                } else {
                    parts.push("NULL".to_string());
                }
            }
            output.push_str(&parts.join(", "));
            output.push('\n');
        }
    }

    print!("{}", output);
}

fn get_text(v: &Value) -> String {
    match v {
        Value::Text(b) => String::from_utf8_lossy(b).to_string(),
        Value::Blob(b) => String::from_utf8_lossy(b).to_string(),
        Value::Int(i) => i.to_string(),
        Value::Real(f) => f.to_string(),
        Value::Null => String::new(),
    }
}

fn get_int(v: &Value) -> i64 {
    match v {
        Value::Int(i) => *i,
        Value::Text(b) => String::from_utf8_lossy(b).parse().unwrap_or(0),
        _ => 0,
    }
}

fn read_varint(data: &[u8], pos: usize) -> (i64, usize) {
    let mut result: u64 = 0;
    let mut i = 0;
    loop {
        if i == 8 {
            result = (result << 8) | (data[pos + i] as u64);
            i += 1;
            break;
        }
        let byte = data[pos + i];
        if byte & 0x80 == 0 {
            result = (result << 7) | (byte as u64);
            i += 1;
            break;
        } else {
            result = (result << 7) | (byte & 0x7F) as u64;
            i += 1;
        }
    }
    (result as i64, i)
}

fn read_btree(data: &[u8], page_num: usize, page_size: usize, reserved: usize) -> Vec<(i64, Vec<Value>)> {
    let mut results = Vec::new();
    read_btree_rec(data, page_num, page_size, reserved, &mut results);
    results.sort_by_key(|(r, _)| *r);
    results
}

fn read_btree_rec(data: &[u8], page_num: usize, page_size: usize, reserved: usize, results: &mut Vec<(i64, Vec<Value>)>) {
    if page_num == 0 {
        return;
    }
    let page_off = (page_num - 1) * page_size;
    let hdr_off = if page_num == 1 { 100 } else { 0 };
    let page_type = data[page_off + hdr_off];

    let cell_count = u16::from_be_bytes([
        data[page_off + hdr_off + 3],
        data[page_off + hdr_off + 4],
    ]) as usize;

    if page_type == 0x0D {
        // Leaf table b-tree
        let cell_ptr_start = page_off + hdr_off + 8;
        for i in 0..cell_count {
            let cp = u16::from_be_bytes([
                data[cell_ptr_start + i * 2],
                data[cell_ptr_start + i * 2 + 1],
            ]) as usize;
            let cell_off = page_off + cp;
            let mut pos = cell_off;
            let (payload_size, n1) = read_varint(data, pos);
            pos += n1;
            let (rowid, n2) = read_varint(data, pos);
            pos += n2;
            let payload = read_payload(data, pos, payload_size as usize, page_size, reserved);
            let values = parse_record(&payload);
            results.push((rowid, values));
        }
    } else if page_type == 0x05 {
        // Interior table b-tree
        let cell_ptr_start = page_off + hdr_off + 12;
        for i in 0..cell_count {
            let cp = u16::from_be_bytes([
                data[cell_ptr_start + i * 2],
                data[cell_ptr_start + i * 2 + 1],
            ]) as usize;
            let cell_off = page_off + cp;
            let child = u32::from_be_bytes([
                data[cell_off],
                data[cell_off + 1],
                data[cell_off + 2],
                data[cell_off + 3],
            ]) as usize;
            read_btree_rec(data, child, page_size, reserved, results);
        }
        // Right-most pointer
        let right = u32::from_be_bytes([
            data[page_off + hdr_off + 8],
            data[page_off + hdr_off + 9],
            data[page_off + hdr_off + 10],
            data[page_off + hdr_off + 11],
        ]) as usize;
        read_btree_rec(data, right, page_size, reserved, results);
    }
}

fn read_payload(data: &[u8], start: usize, payload_size: usize, page_size: usize, reserved: usize) -> Vec<u8> {
    let usable = page_size - reserved;
    let max_local = usable - 35;
    let min_local = ((usable - 12) * 32 / 255) - 23;

    if payload_size <= max_local {
        return data[start..start + payload_size].to_vec();
    }

    let k = min_local + (payload_size - min_local) % (usable - 4);
    let local_bytes = if k <= max_local { k } else { min_local };

    let mut result = data[start..start + local_bytes].to_vec();

    let overflow_page = u32::from_be_bytes([
        data[start + local_bytes],
        data[start + local_bytes + 1],
        data[start + local_bytes + 2],
        data[start + local_bytes + 3],
    ]) as usize;

    let mut remaining = payload_size - local_bytes;
    let mut current = overflow_page;

    while remaining > 0 && current != 0 {
        let poff = (current - 1) * page_size;
        let next = u32::from_be_bytes([
            data[poff],
            data[poff + 1],
            data[poff + 2],
            data[poff + 3],
        ]) as usize;
        let n = std::cmp::min(remaining, usable - 4);
        result.extend_from_slice(&data[poff + 4..poff + 4 + n]);
        remaining -= n;
        current = next;
    }

    result
}

fn parse_record(payload: &[u8]) -> Vec<Value> {
    if payload.is_empty() {
        return vec![];
    }

    let mut pos = 0;
    let (header_size, n) = read_varint(payload, pos);
    pos += n;
    let header_end = header_size as usize;

    let mut serial_types: Vec<i64> = Vec::new();
    while pos < header_end {
        let (st, n) = read_varint(payload, pos);
        pos += n;
        serial_types.push(st);
    }

    let mut values = Vec::new();
    for &st in &serial_types {
        match st {
            0 => values.push(Value::Null),
            1 => {
                values.push(Value::Int(payload[pos] as i8 as i64));
                pos += 1;
            }
            2 => {
                values.push(Value::Int(i16::from_be_bytes([payload[pos], payload[pos + 1]]) as i64));
                pos += 2;
            }
            3 => {
                let mut v: i32 = 0;
                for i in 0..3 {
                    v = (v << 8) | (payload[pos + i] as i32);
                }
                v = (v << 8) >> 8;
                values.push(Value::Int(v as i64));
                pos += 3;
            }
            4 => {
                values.push(Value::Int(i32::from_be_bytes([
                    payload[pos], payload[pos + 1], payload[pos + 2], payload[pos + 3],
                ]) as i64));
                pos += 4;
            }
            5 => {
                let mut v: i64 = 0;
                for i in 0..6 {
                    v = (v << 8) | (payload[pos + i] as i64);
                }
                v = (v << 16) >> 16;
                values.push(Value::Int(v));
                pos += 6;
            }
            6 => {
                values.push(Value::Int(i64::from_be_bytes([
                    payload[pos], payload[pos + 1], payload[pos + 2], payload[pos + 3],
                    payload[pos + 4], payload[pos + 5], payload[pos + 6], payload[pos + 7],
                ])));
                pos += 8;
            }
            7 => {
                values.push(Value::Real(f64::from_bits(u64::from_be_bytes([
                    payload[pos], payload[pos + 1], payload[pos + 2], payload[pos + 3],
                    payload[pos + 4], payload[pos + 5], payload[pos + 6], payload[pos + 7],
                ]))));
                pos += 8;
            }
            8 => values.push(Value::Int(0)),
            9 => values.push(Value::Int(1)),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                values.push(Value::Blob(payload[pos..pos + len].to_vec()));
                pos += len;
            }
            n if n >= 13 => {
                let len = ((n - 13) / 2) as usize;
                values.push(Value::Text(payload[pos..pos + len].to_vec()));
                pos += len;
            }
            _ => values.push(Value::Null),
        }
    }

    values
}

fn parse_create_table(sql: &str) -> (Vec<String>, Option<usize>) {
    let sql_lower = sql.to_lowercase();
    let create_pos = sql_lower.find("create table").unwrap_or(0);
    let mut pos = create_pos + 12;
    let bytes = sql.as_bytes();

    // Skip whitespace
    while pos < bytes.len() && (bytes[pos] as char).is_whitespace() {
        pos += 1;
    }

    // Skip table name (possibly double-quoted)
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        pos += 1;
    } else {
        while pos < bytes.len() && !(bytes[pos] as char).is_whitespace() && bytes[pos] != b'(' {
            pos += 1;
        }
    }

    // Skip whitespace
    while pos < bytes.len() && (bytes[pos] as char).is_whitespace() {
        pos += 1;
    }

    // Expect '('
    if pos < bytes.len() && bytes[pos] == b'(' {
        pos += 1;
    }

    let defs_start = pos;

    // Find matching ')'
    let mut depth = 1;
    let mut in_quotes = false;
    while pos < bytes.len() && depth > 0 {
        if !in_quotes {
            if bytes[pos] == b'"' {
                in_quotes = true;
            } else if bytes[pos] == b'(' {
                depth += 1;
            } else if bytes[pos] == b')' {
                depth -= 1;
            }
        } else {
            if bytes[pos] == b'"' {
                in_quotes = false;
            }
        }
        if depth > 0 {
            pos += 1;
        }
    }

    let defs_str = &sql[defs_start..pos];

    // Split by commas at depth 0, not inside quotes
    let mut columns: Vec<String> = Vec::new();
    let mut rowid_alias: Option<usize> = None;

    let mut current = String::new();
    let mut depth = 0;
    let mut in_quotes = false;

    for &ch in defs_str.as_bytes() {
        if ch == b'"' {
            in_quotes = !in_quotes;
            current.push(ch as char);
        } else if !in_quotes && ch == b'(' {
            depth += 1;
            current.push(ch as char);
        } else if !in_quotes && ch == b')' {
            depth -= 1;
            current.push(ch as char);
        } else if !in_quotes && ch == b',' && depth == 0 {
            process_col_def(&current, &mut columns, &mut rowid_alias);
            current.clear();
        } else {
            current.push(ch as char);
        }
    }
    if !current.trim().is_empty() {
        process_col_def(&current, &mut columns, &mut rowid_alias);
    }

    (columns, rowid_alias)
}

fn process_col_def(def: &str, columns: &mut Vec<String>, rowid_alias: &mut Option<usize>) {
    let def = def.trim();
    if def.is_empty() {
        return;
    }

    let bytes = def.as_bytes();
    let mut pos = 0;

    let col_name;
    if bytes[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
        pos += 1;
    } else {
        let start = pos;
        while pos < bytes.len()
            && !(bytes[pos] as char).is_whitespace()
            && bytes[pos] != b'('
            && bytes[pos] != b')'
        {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
    }

    let col_idx = columns.len();
    columns.push(col_name);

    // Check for INTEGER PRIMARY KEY
    let rest = def[pos..].trim_start();
    if !rest.is_empty() {
        let rb = rest.as_bytes();
        let mut type_end = 0;
        while type_end < rb.len() && ((rb[type_end] as char).is_alphanumeric() || rb[type_end] == b'_') {
            type_end += 1;
        }
        let type_word = &rest[..type_end];

        if type_word.eq_ignore_ascii_case("INTEGER") {
            // Ensure it's a complete word (next char is not alnum or _)
            let after_type = &rest[type_end..];
            let is_complete = after_type.is_empty()
                || !((after_type.as_bytes()[0] as char).is_alphanumeric()
                    || after_type.as_bytes()[0] == b'_');

            if is_complete {
                let def_upper = def.to_uppercase();
                if def_upper.contains("PRIMARY KEY") {
                    *rowid_alias = Some(col_idx);
                }
            }
        }
    }
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Int(i) => i.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(b) => {
            if b.len() <= 100 {
                format_text(b)
            } else {
                format!("<TEXT len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
        Value::Blob(b) => {
            if b.len() <= 100 {
                format_blob(b)
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn format_real(val: f64) -> String {
    if val == 0.0 {
        if val.is_sign_negative() {
            return "-0.0".to_string();
        }
        return "0.0".to_string();
    }
    let s = format!("{:.8}", val);
    let dot_pos = s.find('.').unwrap();
    let mut end = s.len();
    while end > dot_pos + 2 && s.as_bytes()[end - 1] == b'0' {
        end -= 1;
    }
    s[..end].to_string()
}

fn format_text(bytes: &[u8]) -> String {
    let mut result: Vec<u8> = Vec::new();
    result.push(b'"');
    for &b in bytes {
        match b {
            b'\\' => result.extend_from_slice(b"\\\\"),
            b'"' => result.extend_from_slice(b"\\\""),
            b'\n' => result.extend_from_slice(b"\\n"),
            b'\r' => result.extend_from_slice(b"\\r"),
            b'\t' => result.extend_from_slice(b"\\t"),
            0x7F => result.extend_from_slice(b"\\x7F"),
            b if b < 0x20 => {
                result.extend_from_slice(format!("\\x{:02X}", b).as_bytes());
            }
            _ => result.push(b),
        }
    }
    result.push(b'"');
    String::from_utf8(result).unwrap()
}

fn format_blob(bytes: &[u8]) -> String {
    let mut result = String::from("X'");
    for &b in bytes {
        result.push_str(&format!("{:02X}", b));
    }
    result.push('\'');
    result
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

import Foundation

// --- Escaping ---
func esc(_ s: String) -> String {
    var r = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(c)
        }
    }
    return r
}

// --- Socket / HTTP ---
func connectTCP(host: String, port: UInt16) -> Int32 {
    var hints = addrinfo(ai_flags: 0, ai_family: AF_INET, ai_socktype: SOCK_STREAM,
                         ai_protocol: IPPROTO_TCP, ai_addrlen: 0, ai_canonname: nil,
                         ai_addr: nil, ai_next: nil)
    var res: UnsafeMutablePointer<addrinfo>?
    guard getaddrinfo(host, String(port), &hints, &res) == 0, let info = res else {
        fatalError("DNS failed")
    }
    defer { freeaddrinfo(res) }
    let fd = socket(info.pointee.ai_family, info.pointee.ai_socktype, info.pointee.ai_protocol)
    guard fd >= 0 else { fatalError("socket() failed") }
    guard connect(fd, info.pointee.ai_addr, info.pointee.ai_addrlen) == 0 else {
        close(fd); fatalError("connect failed")
    }
    return fd
}

func sendAll(_ fd: Int32, _ bytes: [UInt8]) {
    var off = 0
    while off < bytes.count {
        let n = send(fd, bytes + off, bytes.count - off, 0)
        if n <= 0 { fatalError("send failed") }
        off += n
    }
}

func recvAll(_ fd: Int32) -> [UInt8] {
    var out: [UInt8] = []
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(fd, &buf, buf.count, 0)
        if n <= 0 { break }
        out.append(contentsOf: buf[0..<n])
    }
    return out
}

// --- Chunked transfer decoding ---
func decodeChunked(_ data: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var pos = 0
    while pos < data.count {
        var e = pos
        while e < data.count && data[e] != 10 { e += 1 }
        if e >= data.count { break }
        var te = e
        if te > pos && data[te - 1] == 13 { te -= 1 }
        let line = String(bytes: data[pos..<te], encoding: .ascii) ?? ""
        pos = e + 1
        let hex = line.components(separatedBy: ";")[0].trimmingCharacters(in: .whitespaces)
        let sz = Int(hex, radix: 16) ?? 0
        if sz == 0 { break }
        if pos + sz > data.count { break }
        result.append(contentsOf: data[pos..<pos+sz])
        pos += sz
        if pos < data.count && data[pos] == 13 { pos += 1 }
        if pos < data.count && data[pos] == 10 { pos += 1 }
    }
    return result
}

// --- HTTP request/response ---
struct HTTPResponse {
    let status: Int
    let headers: [String: String]
    let body: [UInt8]
}

func doRequest(host: String, port: UInt16, path: String,
               headers: [(String, String)], body: Data) -> HTTPResponse {
    let fd = connectTCP(host: host, port: port)
    defer { close(fd) }

    var req = "POST \(path) HTTP/1.1\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    req += "\r\n"

    var bytes = Array(req.utf8)
    bytes.append(contentsOf: [UInt8](body))
    sendAll(fd, bytes)

    let raw = recvAll(fd)

    // Find header/body boundary
    var headerEnd = -1
    for i in 0..<(raw.count - 3) {
        if raw[i] == 13 && raw[i+1] == 10 && raw[i+2] == 13 && raw[i+3] == 10 {
            headerEnd = i + 4; break
        }
    }
    if headerEnd < 0 {
        for i in 0..<(raw.count - 1) {
            if raw[i] == 10 && raw[i+1] == 10 {
                headerEnd = i + 2; break
            }
        }
    }
    guard headerEnd > 0 else { fatalError("No header boundary") }

    let headerStr = String(bytes: raw[0..<headerEnd], encoding: .utf8) ?? ""
    let lines = headerStr.components(separatedBy: "\r\n").filter { !$0.isEmpty }

    let statusLine = lines.first ?? ""
    let parts = statusLine.components(separatedBy: " ")
    let status = Int(parts.count >= 2 ? parts[1] : "") ?? 0

    var hdrs: [String: String] = [:]
    for line in lines.dropFirst() {
        if let colon = line.firstIndex(of: ":") {
            let key = String(line[line.startIndex..<colon]).lowercased()
            let val = String(line[line.index(after: colon)...]).trimmingCharacters(in: .whitespaces)
            hdrs[key] = val
        }
    }

    var bodyBytes = Array(raw[headerEnd...])
    if hdrs["transfer-encoding"]?.lowercased().contains("chunked") == true {
        bodyBytes = decodeChunked(bodyBytes)
    }

    return HTTPResponse(status: status, headers: hdrs, body: bodyBytes)
}

// --- SSE parsing ---
struct SSEEvent { let event: String; let data: String }

func parseSSE(_ data: [UInt8]) -> [SSEEvent] {
    var events: [SSEEvent] = []
    var evType = ""
    var dataLines: [String] = []
    var pos = 0
    while pos < data.count {
        var e = pos
        while e < data.count && data[e] != 10 { e += 1 }
        var te = e
        if te > pos && data[te - 1] == 13 { te -= 1 }
        let line = String(bytes: data[pos..<te], encoding: .utf8) ?? ""
        pos = e + 1

        if line.isEmpty {
            if !evType.isEmpty || !dataLines.isEmpty {
                events.append(SSEEvent(event: evType, data: dataLines.joined(separator: "\n")))
            }
            evType = ""; dataLines = []
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            evType = v
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            dataLines.append(v)
        }
    }
    if !evType.isEmpty || !dataLines.isEmpty {
        events.append(SSEEvent(event: evType, data: dataLines.joined(separator: "\n")))
    }
    return events
}

// --- Content block model ---
struct Block {
    var type = ""
    var thinking = ""
    var signature = ""
    var text = ""
    var id = ""
    var name = ""
    var partialJson = ""
}

struct ReplyResult {
    var blocks: [(Int, Block)] = []
    var stopReason = ""
    var inputTokens = 0
    var outputTokens = 0
    var cacheReadTokens = 0
}

func processEvents(_ events: [SSEEvent]) -> ReplyResult {
    var r = ReplyResult()
    var blocks: [Int: Block] = [:]

    for ev in events {
        guard let jData = ev.data.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: jData) as? [String: Any] else { continue }

        switch ev.event {
        case "message_start":
            if let msg = json["message"] as? [String: Any],
               let usage = msg["usage"] as? [String: Any] {
                r.inputTokens = usage["input_tokens"] as? Int ?? 0
                r.cacheReadTokens = usage["cache_read_input_tokens"] as? Int ?? 0
            }
        case "content_block_start":
            let idx = json["index"] as? Int ?? 0
            if let cb = json["content_block"] as? [String: Any] {
                var b = Block()
                b.type = cb["type"] as? String ?? ""
                if b.type == "tool_use" {
                    b.id = cb["id"] as? String ?? ""
                    b.name = cb["name"] as? String ?? ""
                }
                blocks[idx] = b
            }
        case "content_block_delta":
            let idx = json["index"] as? Int ?? 0
            if var b = blocks[idx], let delta = json["delta"] as? [String: Any] {
                let dt = delta["type"] as? String ?? ""
                switch dt {
                case "thinking_delta": b.thinking += delta["thinking"] as? String ?? ""
                case "signature_delta": b.signature += delta["signature"] as? String ?? ""
                case "text_delta": b.text += delta["text"] as? String ?? ""
                case "input_json_delta": b.partialJson += delta["partial_json"] as? String ?? ""
                default: break
                }
                blocks[idx] = b
            }
        case "content_block_stop":
            let idx = json["index"] as? Int ?? 0
            if let b = blocks[idx] {
                r.blocks.append((idx, b))
            }
        case "message_delta":
            if let delta = json["delta"] as? [String: Any] {
                r.stopReason = delta["stop_reason"] as? String ?? ""
            }
            if let usage = json["usage"] as? [String: Any] {
                r.outputTokens = usage["output_tokens"] as? Int ?? 0
            }
        default: break
        }
    }

    r.blocks.sort { $0.0 < $1.0 }
    return r
}

// --- Tool execution ---
func runTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points": return (String(text.unicodeScalars.count), false)
        case "utf8_bytes": return (String(text.utf8.count), false)
        case "utf16_units": return (String(text.utf16.count), false)
        default: return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        return (String(text.unicodeScalars.reversed()), false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

