/* ===== Dynamic String Buffer ===== */
typedef struct { char *d; int len, cap; } SB;
static void sb_init(SB *s){ s->d=NULL; s->len=0; s->cap=0; }
static void sb_ensure(SB *s, int n){
    if(s->len+n>s->cap){ s->cap=s->cap?s->cap*2:256; while(s->cap<s->len+n)s->cap*=2; s->d=realloc(s->d,s->cap); }
}
static void sb_putc(SB *s, char c){ sb_ensure(s,1); s->d[s->len++]=c; }
static void sb_puts(SB *s, const char *t){ int n=strlen(t); sb_ensure(s,n); memcpy(s->d+s->len,t,n); s->len+=n; }
static void sb_putn(SB *s, const char *t, int n){ sb_ensure(s,n); memcpy(s->d+s->len,t,n); s->len+=n; }
static void sb_puti(SB *s, long long v){ char buf[32]; int n=snprintf(buf,sizeof buf,"%lld",v); sb_putn(s,buf,n); }
static void sb_free(SB *s){ free(s->d); }

/* ===== JSON Value ===== */
typedef enum { JV_NULL, JV_BOOL, JV_NUM, JV_STR, JV_ARR, JV_OBJ } JVType;
typedef struct JV {
    JVType type;
    union {
        int bval;
        char *nval;
        char *sval;
        struct { struct JV **items; int count, cap; } arr;
        struct { char **keys; struct JV **vals; int count, cap; } obj;
    };
} JV;

static JV *jv_new(JVType t){ JV *v=calloc(1,sizeof(JV)); v->type=t; return v; }
static void jv_arr_push(JV *a, JV *item){
    if(a->arr.count>=a->arr.cap){ a->arr.cap=a->arr.cap?a->arr.cap*2:4; a->arr.items=realloc(a->arr.items,a->arr.cap*sizeof(JV*)); }
    a->arr.items[a->arr.count++]=item;
}
static void jv_obj_push(JV *o, const char *k, JV *v){
    if(o->obj.count>=o->obj.cap){ o->obj.cap=o->obj.cap?o->obj.cap*2:4; o->obj.keys=realloc(o->obj.keys,o->obj.cap*sizeof(char*)); o->obj.vals=realloc(o->obj.vals,o->obj.cap*sizeof(JV*)); }
    o->obj.keys[o->obj.count]=strdup(k); o->obj.vals[o->obj.count]=v; o->obj.count++;
}
static JV *jv_obj_get(JV *o, const char *k){
    if(!o||o->type!=JV_OBJ)return NULL;
    for(int i=0;i<o->obj.count;i++) if(strcmp(o->obj.keys[i],k)==0) return o->obj.vals[i];
    return NULL;
}
static const char *jv_str(JV *v){ return (v&&v->type==JV_STR)?v->sval:NULL; }
static long long jv_int(JV *v){ return (v&&v->type==JV_NUM)?strtoll(v->nval,NULL,10):0; }

/* ===== JSON Parser ===== */
typedef struct { const char *p, *end; } JC;
static void jskip(JC *c){ while(c->p<c->end&&(*c->p==' '||*c->p=='\t'||*c->p=='\n'||*c->p=='\r'))c->p++; }
static JV *jparse(JC *c);

static char *jparse_str(JC *c){
    if(*c->p!='"')return NULL;
    c->p++;
    SB sb; sb_init(&sb);
    while(c->p<c->end&&*c->p!='"'){
        if(*c->p=='\\'){
            c->p++;
            if(c->p>=c->end)break;
            switch(*c->p){
                case '"': sb_putc(&sb,'"'); c->p++; break;
                case '\\': sb_putc(&sb,'\\'); c->p++; break;
                case '/': sb_putc(&sb,'/'); c->p++; break;
                case 'b': sb_putc(&sb,'\b'); c->p++; break;
                case 'f': sb_putc(&sb,'\f'); c->p++; break;
                case 'n': sb_putc(&sb,'\n'); c->p++; break;
                case 'r': sb_putc(&sb,'\r'); c->p++; break;
                case 't': sb_putc(&sb,'\t'); c->p++; break;
                case 'u': {
                    c->p++;
                    if(c->p+4>c->end)goto done;
                    unsigned cp=0;
                    for(int i=0;i<4;i++){ char ch=c->p[i]; int d; if(ch>='0'&&ch<='9')d=ch-'0'; else if(ch>='a'&&ch<='f')d=ch-'a'+10; else if(ch>='A'&&ch<='F')d=ch-'A'+10; else d=0; cp=cp*16+d; }
                    c->p+=4;
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(c->p+6<=c->end&&c->p[0]=='\\'&&c->p[1]=='u'){
                            c->p+=2;
                            unsigned lo=0;
                            for(int i=0;i<4;i++){ char ch=c->p[i]; int d; if(ch>='0'&&ch<='9')d=ch-'0'; else if(ch>='a'&&ch<='f')d=ch-'a'+10; else if(ch>='A'&&ch<='F')d=ch-'A'+10; else d=0; lo=lo*16+d; }
                            c->p+=4;
                            if(lo>=0xDC00&&lo<=0xDFFF){
                                cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            } else {
                                /* lone high surrogate, encode as replacement */
                                cp=0xFFFD;
                            }
                        } else { cp=0xFFFD; }
                    }
                    /* encode UTF-8 */
                    if(cp<0x80){ sb_putc(&sb,(char)cp); }
                    else if(cp<0x800){ sb_putc(&sb,(char)(0xC0|(cp>>6))); sb_putc(&sb,(char)(0x80|(cp&0x3F))); }
                    else if(cp<0x10000){ sb_putc(&sb,(char)(0xE0|(cp>>12))); sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F))); sb_putc(&sb,(char)(0x80|(cp&0x3F))); }
                    else { sb_putc(&sb,(char)(0xF0|(cp>>18))); sb_putc(&sb,(char)(0x80|((cp>>12)&0x3F))); sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F))); sb_putc(&sb,(char)(0x80|(cp&0x3F))); }
                    break;
                }
                default: sb_putc(&sb,*c->p); c->p++; break;
            }
        } else {
            sb_putc(&sb,*c->p); c->p++;
        }
    }
done:
    if(c->p<c->end&&*c->p=='"')c->p++;
    sb_putc(&sb,0);
    return sb.d;
}

static JV *jparse(JC *c){
    jskip(c);
    if(c->p>=c->end)return jv_new(JV_NULL);
    char ch=*c->p;
    if(ch=='"'){ JV *v=jv_new(JV_STR); v->sval=jparse_str(c); return v; }
    if(ch=='{'){
        c->p++; JV *o=jv_new(JV_OBJ);
        jskip(c);
        if(c->p<c->end&&*c->p=='}'){c->p++;return o;}
        while(1){
            jskip(c);
            char *k=jparse_str(c);
            jskip(c);
            if(c->p<c->end&&*c->p==':')c->p++;
            JV *v=jparse(c);
            jv_obj_push(o,k,v); free(k);
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p=='}'){c->p++;break;}
            break;
        }
        return o;
    }
    if(ch=='['){
        c->p++; JV *a=jv_new(JV_ARR);
        jskip(c);
        if(c->p<c->end&&*c->p==']'){c->p++;return a;}
        while(1){
            JV *v=jparse(c);
            jv_arr_push(a,v);
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p==']'){c->p++;break;}
            break;
        }
        return a;
    }
    if(ch=='t'){ c->p+=4; JV *v=jv_new(JV_BOOL); v->bval=1; return v; }
    if(ch=='f'){ c->p+=5; JV *v=jv_new(JV_BOOL); v->bval=0; return v; }
    if(ch=='n'){ c->p+=4; return jv_new(JV_NULL); }
    /* number */
    const char *ns=c->p;
    while(c->p<c->end&&(isdigit(*c->p)||*c->p=='-'||*c->p=='+'||*c->p=='.'||*c->p=='e'||*c->p=='E'))c->p++;
    JV *v=jv_new(JV_NUM);
    int nlen=c->p-ns;
    v->nval=malloc(nlen+1); memcpy(v->nval,ns,nlen); v->nval[nlen]=0;
    return v;
}

static JV *json_parse(const char *text){ JC c={text,text+strlen(text)}; return jparse(&c); }

/* ===== JSON String Encoder ===== */
static void enc_json_str(SB *sb, const char *s){
    sb_putc(sb,'"');
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        unsigned char c=*p;
        if(c=='"') sb_puts(sb,"\\\"");
        else if(c=='\\') sb_puts(sb,"\\\\");
        else if(c=='\b') sb_puts(sb,"\\b");
        else if(c=='\f') sb_puts(sb,"\\f");
        else if(c=='\n') sb_puts(sb,"\\n");
        else if(c=='\r') sb_puts(sb,"\\r");
        else if(c=='\t') sb_puts(sb,"\\t");
        else if(c<0x20){ char buf[8]; snprintf(buf,sizeof buf,"\\u%04x",c); sb_puts(sb,buf); }
        else sb_putc(sb,(char)c);
    }
    sb_putc(sb,'"');
}

/* ===== HTTP Client ===== */
typedef struct { int status; char *body; } HttpResp;

static int parse_url(const char *url, char *host, int hsz, int *port, char *path, int psz){
    const char *p=url;
    if(strncmp(p,"http://",7)==0) p+=7;
    else if(strncmp(p,"https://",8)==0) p+=8;
    const char *slash=strchr(p,'/');
    const char *colon=NULL;
    const char *hstart=p;
    const char *hend=slash?slash:p+strlen(p);
    for(const char *q=hstart;q<hend;q++) if(*q==':'){colon=q;break;}
    if(colon){
        int hl=colon-hstart; if(hl>=hsz)hl=hsz-1;
        memcpy(host,hstart,hl); host[hl]=0;
        *port=atoi(colon+1);
    } else {
        int hl=hend-hstart; if(hl>=hsz)hl=hsz-1;
        memcpy(host,hstart,hl); host[hl]=0;
        *port=80;
    }
    if(slash){ int pl=strlen(slash); if(pl>=psz)pl=psz-1; memcpy(path,slash,pl); path[pl]=0; }
    else { path[0]='/'; path[1]=0; }
    return 0;
}

static HttpResp http_post(const char *base_url, const char *api_key, const char *body, int body_len){
    char host[256]={0}, path[512]={0};
    int port=80;
    parse_url(base_url,host,sizeof host,&port,path,sizeof path);
    /* append /chat/completions to path */
    int plen=strlen(path);
    snprintf(path+plen,sizeof(path)-plen,"/chat/completions");

    struct addrinfo hints={0}, *res=NULL;
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    char portstr[16]; snprintf(portstr,sizeof portstr,"%d",port);
    if(getaddrinfo(host,portstr,&hints,&res)!=0){ HttpResp r={0,NULL}; return r; }

    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){ freeaddrinfo(res); HttpResp r={0,NULL}; return r; }
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){ close(fd); freeaddrinfo(res); HttpResp r={0,NULL}; return r; }
    freeaddrinfo(res);

    SB req; sb_init(&req);
    sb_puts(&req,"POST ");
    sb_puts(&req,path);
    sb_puts(&req," HTTP/1.1\r\n");
    sb_puts(&req,"Host: "); sb_puts(&req,host);
    if(port!=80){ sb_putc(&req,':'); sb_puti(&req,port); }
    sb_puts(&req,"\r\n");
    sb_puts(&req,"Authorization: Bearer "); sb_puts(&req,api_key);
    sb_puts(&req,"\r\n");
    sb_puts(&req,"Content-Type: application/json\r\n");
    sb_puts(&req,"Content-Length: "); sb_puti(&req,body_len);
    sb_puts(&req,"\r\n\r\n");
    sb_putn(&req,body,body_len);

    /* send */
    int sent=0;
    while(sent<req.len){
        int w=write(fd,req.d+sent,req.len-sent);
        if(w<=0)break;
        sent+=w;
    }
    sb_free(&req);

    /* read response */
    SB resp; sb_init(&resp);
    char buf[65536];
    while(1){
        int n=read(fd,buf,sizeof buf);
        if(n<=0)break;
        sb_putn(&resp,buf,n);
    }
    close(fd);

    HttpResp hr={0,NULL};
    if(resp.len==0){ sb_free(&resp); return hr; }

    /* parse status */
    const char *rp=resp.d;
    const char *rend=resp.d+resp.len;
    if(strncmp(rp,"HTTP/",5)==0){
        const char *sp=strchr(rp,' ');
        if(sp) hr.status=atoi(sp+1);
    }

    /* find body (after \r\n\r\n) */
    const char *sep=NULL;
    for(const char *q=rp;q+3<rend;q++){
        if(q[0]=='\r'&&q[1]=='\n'&&q[2]=='\r'&&q[3]=='\n'){ sep=q+4; break; }
    }
    if(!sep){
        /* try \n\n */
        for(const char *q=rp;q+1<rend;q++){
            if(q[0]=='\n'&&q[1]=='\n'){ sep=q+2; break; }
        }
    }
    if(sep){
        int blen=rend-sep;
        hr.body=malloc(blen+1);
        memcpy(hr.body,sep,blen);
        hr.body[blen]=0;
    } else {
        hr.body=strdup("");
    }
    sb_free(&resp);
    return hr;
}

/* ===== CSV Parser ===== */
typedef struct { char *sku; char *name; long long price_cents; char *currency; long long stock; } InvRow;
static InvRow *inv_rows=NULL; static int inv_count=0;

static char *read_file(const char *path, int *len){
    FILE *f=fopen(path,"rb");
    if(!f)return NULL;
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(sz+1);
    fread(buf,1,sz,f); fclose(f);
    buf[sz]=0; *len=sz; return buf;
}

static void parse_csv(const char *data, int dlen){
    const char *p=data, *end=data+dlen;
    /* skip BOM */
    if(dlen>=3&&(unsigned char)p[0]==0xEF&&(unsigned char)p[1]==0xBB&&(unsigned char)p[2]==0xBF) p+=3;
    /* skip header line */
    while(p<end&&*p!='\n')p++;
    if(p<end)p++; /* skip \n */

    inv_rows=NULL; inv_count=0; int cap=0;
    while(p<end){
        /* parse one record */
        char *fields[5]={0}; int nf=0;
        while(nf<5){
            /* parse one field */
            SB fsb; sb_init(&fsb);
            if(p<end&&*p=='"'){
                p++; /* skip opening quote */
                while(p<end){
                    if(*p=='"'){
                        if(p+1<end&&p[1]=='"'){ sb_putc(&fsb,'"'); p+=2; }
                        else { p++; break; }
                    } else {
                        sb_putc(&fsb,*p); p++;
                    }
                }
            } else {
                while(p<end&&*p!=','&&*p!='\r'&&*p!='\n'){
                    sb_putc(&fsb,*p); p++;
                }
            }
            sb_putc(&fsb,0);
            fields[nf++]=fsb.d;
            if(p<end&&*p==','){ p++; continue; }
            break;
        }
        /* skip to end of line */
        while(p<end&&*p!='\n')p++;
        if(p<end)p++;

        if(nf<5){ for(int i=0;i<nf;i++)free(fields[i]); continue; }
        if(inv_count>=cap){ cap=cap?cap*2:64; inv_rows=realloc(inv_rows,cap*sizeof(InvRow)); }
        inv_rows[inv_count].sku=fields[0];
        inv_rows[inv_count].name=fields[1];
        inv_rows[inv_count].price_cents=strtoll(fields[2],NULL,10);
        inv_rows[inv_count].currency=fields[3];
        inv_rows[inv_count].stock=strtoll(fields[4],NULL,10);
        inv_count++;
    }
}

/* ===== Rates ===== */
typedef struct { char *currency; long long rate; } RateEntry;
static RateEntry *rates_arr=NULL; static int rates_count=0; static long long rates_scale=1000000;

static long long get_rate(const char *cur){
    for(int i=0;i<rates_count;i++) if(strcmp(rates_arr[i].currency,cur)==0) return rates_arr[i].rate;
    return 0;
}

/* ===== Tool Execution ===== */
static char *exec_tool(const char *name, JV *args){
    SB out; sb_init(&out);
    if(strcmp(name,"inventory_lookup")==0){
        const char *sku=jv_str(jv_obj_get(args,"sku"));
        if(!sku)sku="";
        InvRow *found=NULL;
        for(int i=0;i<inv_count;i++){
            if(strcmp(inv_rows[i].sku,sku)==0){found=&inv_rows[i];break;}
        }
        if(!found){
            sb_puts(&out,"{\"error\":\"unknown sku: ");
            enc_json_str_inner:
            sb_puts(&out,sku);
            sb_puts(&out,"\"}");
            sb_putc(&out,0);
            return out.d;
        }
        sb_puts(&out,"{\"sku\":"); enc_json_str(&out,found->sku);
        sb_puts(&out,",\"name\":"); enc_json_str(&out,found->name);
        sb_puts(&out,",\"price_cents\":"); sb_puti(&out,found->price_cents);
        sb_puts(&out,",\"currency\":"); enc_json_str(&out,found->currency);
        sb_puts(&out,",\"stock\":"); sb_puti(&out,found->stock);
        sb_putc(&out,'}');
        sb_putc(&out,0);
        return out.d;
    } else if(strcmp(name,"convert_currency")==0){
        long long amount=jv_int(jv_obj_get(args,"amount_cents"));
        const char *from=jv_str(jv_obj_get(args,"from"));
        const char *to=jv_str(jv_obj_get(args,"to"));
        if(!from)from=""; if(!to)to="";
        long long rf=get_rate(from), rt=get_rate(to);
        if(rf==0)rf=1;
        long long converted=(2*amount*rt+rf)/(2*rf);
        sb_puts(&out,"{\"amount_cents\":"); sb_puti(&out,converted);
        sb_puts(&out,",\"currency\":"); enc_json_str(&out,to);
        sb_putc(&out,'}');
        sb_putc(&out,0);
        return out.d;
    } else {
        sb_puts(&out,"{\"error\":\"unknown tool: ");
        sb_puts(&out,name);
        sb_puts(&out,"\"}");
        sb_putc(&out,0);
        return out.d;
    }
}

