import * as fs from 'fs';
import * as path from 'path';

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];
const KEYPAD = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir)
    .filter(f => f.endsWith('.wav'))
    .sort((a, b) => Buffer.from(a).compare(Buffer.from(b)));

  const outputs: string[] = [];

  for (const name of files) {
    const filePath = path.join(dir, name);
    const buf = fs.readFileSync(filePath);

    // Parse RIFF header
    if (buf.length < 12 || buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') {
      outputs.push(`${name}: unsupported`);
      continue;
    }

    let offset = 12;
    let fmtBody: Buffer | null = null;
    let dataBody: Buffer | null = null;
    let dataSize = 0;

    while (offset + 8 <= buf.length) {
      const chunkId = buf.toString('ascii', offset, offset + 4);
      const chunkSize = buf.readUInt32LE(offset + 4);
      const bodyStart = offset + 8;

      if (chunkId === 'fmt ') {
        fmtBody = buf.slice(bodyStart, bodyStart + chunkSize);
      } else if (chunkId === 'data') {
        dataSize = chunkSize;
        dataBody = buf.slice(bodyStart, Math.min(bodyStart + chunkSize, buf.length));
      }

      offset = bodyStart + chunkSize + (chunkSize % 2);
    }

    if (!fmtBody || !dataBody) {
      outputs.push(`${name}: unsupported`);
      continue;
    }

    // Parse fmt chunk
    const formatTag = fmtBody.readUInt16LE(0);
    const channels = fmtBody.readUInt16LE(2);
    const sampleRate = fmtBody.readUInt32LE(4);
    const bitsPerSample = fmtBody.readUInt16LE(14);

    let effectiveFormat = formatTag;
    if (formatTag === 0xFFFE) {
      if (fmtBody.length > 24) {
        effectiveFormat = fmtBody.readUInt16LE(24);
      } else {
        effectiveFormat = -1;
      }
    }

    if (effectiveFormat !== 1 || bitsPerSample !== 16) {
      outputs.push(`${name}: unsupported`);
      continue;
    }

    if ((channels !== 1 && channels !== 2) || (sampleRate !== 8000 && sampleRate !== 16000)) {
      outputs.push(`${name}: unsupported`);
      continue;
    }

    // Extract left channel samples
    const bytesPerFrame = 2 * channels;
    const numFrames = Math.floor(dataSize / bytesPerFrame);
    const samples: number[] = new Array(numFrames);
    for (let i = 0; i < numFrames; i++) {
      samples[i] = dataBody.readInt16LE(i * bytesPerFrame);
    }

    // Detection
    const N = sampleRate / 50;
    const numBlocks = Math.floor(numFrames / N);

    const labels: (string | null)[] = new Array(numBlocks);

    for (let b = 0; b < numBlocks; b++) {
      const start = b * N;
      const x: number[] = new Array(N);
      for (let n = 0; n < N; n++) {
        x[n] = samples[start + n];
      }

      // Energy
      let E = 0;
      for (let n = 0; n < N; n++) {
        E += x[n] * x[n];
      }

      if (E < 1000000 * N) {
        labels[b] = null;
        continue;
      }

      // Goertzel power computation
      const computeR = (f: number): number => {
        const c = 2 * Math.cos(2 * Math.PI * f / sampleRate);
        let s1 = 0, s2 = 0;
        for (let n = 0; n < N; n++) {
          const s = x[n] + c * s1 - s2;
