static uint16_t read_u16(const unsigned char *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32(const unsigned char *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | (p[3] << 24));
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    const char *dirpath = argv[1];
    DIR *dir = opendir(dirpath);
    if (!dir) return 1;

    char **files = NULL;
    int nfiles = 0;
    struct dirent *ent;

    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        int len = (int)strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            files = realloc(files, (nfiles + 1) * sizeof(char *));
            files[nfiles] = strdup(name);
            nfiles++;
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(char *), cmp_str);

    const double low_freqs[4] = {697, 770, 852, 941};
    const double high_freqs[4] = {1209, 1336, 1477, 1633};
    const char keypad[4][4] = {
        {'1','2','3','A'},
        {'4','5','6','B'},
        {'7','8','9','C'},
        {'*','0','#','D'}
    };

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        char filepath[4096];
        snprintf(filepath, sizeof(filepath), "%s/%s", dirpath, files[fi]);

        FILE *fp = fopen(filepath, "rb");
        if (!fp) {
            printf("%s: unsupported\n", files[fi]);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        unsigned char *buf = malloc(fsize > 0 ? fsize : 1);
        size_t rd = fread(buf, 1, fsize, fp);
        fclose(fp);
        (void)rd;

        /* Check RIFF/WAVE header */
        if (fsize < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        /* Parse chunks */
        unsigned char *fmt_body = NULL;
        uint32_t fmt_size = 0;
        unsigned char *data_body = NULL;
        uint32_t data_size = 0;

        long pos = 12;
        while (pos + 8 <= fsize) {
            uint32_t chunk_size = read_u32(buf + pos + 4);
            if (pos + 8 + (long)chunk_size > fsize) break;

            if (memcmp(buf + pos, "fmt ", 4) == 0) {
                fmt_body = buf + pos + 8;
                fmt_size = chunk_size;
            } else if (memcmp(buf + pos, "data", 4) == 0) {
                data_body = buf + pos + 8;
                data_size = chunk_size;
            }

            pos += 8 + (long)chunk_size;
            if (chunk_size & 1) pos++;
        }

        if (!fmt_body || !data_body) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        uint16_t format_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t sample_rate = read_u32(fmt_body + 4);
        uint16_t bits_per_sample = read_u16(fmt_body + 14);

        uint16_t effective_format = format_tag;
        if (format_tag == 0xFFFE && fmt_size > 24) {
            effective_format = read_u16(fmt_body + 24);
        }

        if (effective_format != 1 || bits_per_sample != 16 ||
            (channels != 1 && channels != 2) ||
            (sample_rate != 8000 && sample_rate != 16000)) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        /* Extract left channel samples */
        int nframes = (int)(data_size / (2 * channels));
        int N = (int)(sample_rate / 50);
        int nblocks = nframes / N;

        int16_t *left = malloc((size_t)nframes * sizeof(int16_t));
        for (int i = 0; i < nframes; i++) {
            left[i] = (int16_t)read_u16(data_body + (size_t)i * 2 * channels);
        }

        /* Detect digits per block */
        char *labels = calloc(nblocks, 1);

        for (int b = 0; b < nblocks; b++) {
            int16_t *x = left + (size_t)b * N;

            double E = 0.0;
            for (int n = 0; n < N; n++) {
                double v = (double)x[n];
                E += v * v;
            }

            if (E < 1000000.0 * (double)N) {
                labels[b] = 0;
                continue;
            }

            double r_low[4], r_high[4];

            for (int k = 0; k < 4; k++) {
                double c = 2.0 * cos(2.0 * M_PI * low_freqs[k] / (double)sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[k] = 2.0 * P / ((double)N * E);
            }

            for (int k = 0; k < 4; k++) {
                double c = 2.0 * cos(2.0 * M_PI * high_freqs[k] / (double)sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[k] = 2.0 * P / ((double)N * E);
            }

            int fl = 0, fh = 0;
            for (int k = 1; k < 4; k++) {
                if (r_low[k] > r_low[fl]) fl = k;
                if (r_high[k] > r_high[fh]) fh = k;
            }

            if (r_low[fl] >= 0.1 && r_high[fh] >= 0.1 && r_low[fl] + r_high[fh] >= 0.6) {
                labels[b] = keypad[fl][fh];
            } else {
                labels[b] = 0;
            }
        }

        /* Bridging: use original labels for decision */
        char *bridged = malloc(nblocks);
        memcpy(bridged, labels, nblocks);

        for (int b = 0; b < nblocks; b++) {
            if (labels[b] != 0) continue;
            if (b == 0 || b == nblocks - 1) continue;
            if (labels[b - 1] != 0 && labels[b - 1] == labels[b + 1]) {
                bridged[b] = labels[b - 1];
            }
        }

        /* Output */
        printf("%s: %u Hz, %u ch, %d blocks\n", files[fi],
               (unsigned)sample_rate, (unsigned)channels, nblocks);

        char digits_str[65536];
        int dpos = 0;
        digits_str[0] = '\0';

        int b = 0;
        while (b < nblocks) {
            if (bridged[b] == 0) { b++; continue; }
            int start = b;
            char digit = bridged[b];
            while (b < nblocks && bridged[b] == digit) b++;
            int len = b - start;
            if (len >= 2) {
                int start_ms = 20 * start;
                int end_ms = 20 * b;
                printf("%c %d %d\n", digit, start_ms, end_ms);
                digits_str[dpos++] = digit;
                digits_str[dpos] = '\0';
            }
        }

        printf("digits: %s\n", digits_str);

        free(left);
        free(labels);
        free(bridged);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);

    return 0;
}

