        let off = i * bytesPerFrame
        let raw = UInt16(audio[aBase + off]) | (UInt16(audio[aBase + off + 1]) << 8)
        samples[i] = Int(Int16(bitPattern: raw))
    }

    let N = sampleRate / 50
    let numBlocks = numFrames / N

    let lowFreqs: [Double] = [697, 770, 852, 941]
    let highFreqs: [Double] = [1209, 1336, 1477, 1633]

    let digitMap: [[String]] = [
        ["1", "2", "3", "A"],
        ["4", "5", "6", "B"],
        ["7", "8", "9", "C"],
        ["*", "0", "#", "D"]
    ]

    var blockLabels: [String?] = []

    for block in 0..<numBlocks {
        let start = block * N

        var E: Double = 0
        for n in 0..<N {
            let x = Double(samples[start + n])
            E += x * x
        }

        if E < 1000000.0 * Double(N) {
            blockLabels.append(nil)
            continue
        }

