            let c = 2.0 * cos(2.0 * Double.pi * freq / Double(sampleRate))
            var s1: Double = 0
            var s2: Double = 0
            for n in 0..<N {
                let x = Double(samples[start + n])
                let s = x + c * s1 - s2
                s2 = s1
                s1 = s
            }
            return s1 * s1 + s2 * s2 - c * s1 * s2
        }

