            let r = 2.0 * P / (Double(N) * E)
            if r > maxLowR {
                maxLowR = r
                maxLowIdx = i
            }
        }

        for i in 0..<4 {
            let P = goertzelPower(freq: highFreqs[i])
            let r = 2.0 * P / (Double(N) * E)
            if r > maxHighR {
                maxHighR = r
                maxHighIdx = i
            }
        }

        if maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6 {
            blockLabels.append(digitMap[maxLowIdx][maxHighIdx])
        } else {
            blockLabels.append(nil)
        }
    }

    // Bridging: use original step-3 labels for neighbor checks
    let step3Labels = blockLabels
    var finalLabels = blockLabels

    for i in 0..<numBlocks {
        if finalLabels[i] == nil && i > 0 && i < numBlocks - 1 {
            if let left = step3Labels[i - 1], let right = step3Labels[i + 1], left == right {
                finalLabels[i] = left
            }
        }
    }

