            if j - i >= 2 {
                events.append((digit: digit, start: 20 * i, end: 20 * j))
            }
            i = j
        } else {
            i += 1
        }
    }

    var result = "\(name): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks\n"
    for event in events {
        result += "\(event.digit) \(event.start) \(event.end)\n"
    }
    let allDigits = events.map { $0.digit }.joined()
    result += "digits: \(allDigits)\n"

    return result
}

