use std::env;
use std::fs;
use std::path::Path;

fn goertzel_power(block: &[i16], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = (x as f64) + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    let entries = fs::read_dir(Path::new(dir)).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
