        let num_blocks = samples.len() / n;
        let rate_f = sample_rate as f64;

        let mut labels: Vec<Option<char>> = vec![None; num_blocks];

        for bi in 0..num_blocks {
            let block = &samples[bi * n..(bi + 1) * n];
            let e: f64 = block.iter().map(|&x| (x as f64) * (x as f64)).sum();

            if e < 1000000.0 * n as f64 {
                continue;
            }

            let mut r_low = [0.0f64; 4];
            let mut r_high = [0.0f64; 4];

            for fi in 0..4 {
                r_low[fi] = goertzel_power(block, low_freqs[fi], rate_f, n, e);
                r_high[fi] = goertzel_power(block, high_freqs[fi], rate_f, n, e);
            }

            let mut best_low = 0;
            let mut best_high = 0;
            for fi in 1..4 {
                if r_low[fi] > r_low[best_low] {
                    best_low = fi;
                }
                if r_high[fi] > r_high[best_high] {
                    best_high = fi;
                }
            }

            if r_low[best_low] >= 0.1
                && r_high[best_high] >= 0.1
                && (r_low[best_low] + r_high[best_high]) >= 0.6
            {
                labels[bi] = Some(digits[best_low][best_high]);
            }
        }

        // Bridging
        let mut bridged: Vec<Option<char>> = labels.clone();
        if num_blocks >= 3 {
            for bi in 1..num_blocks - 1 {
                if labels[bi].is_none() {
                    if let (Some(d1), Some(d2)) = (labels[bi - 1], labels[bi + 1]) {
                        if d1 == d2 {
                            bridged[bi] = Some(d1);
                        }
                    }
                }
            }
        }

        // Events
        let mut events: Vec<(char, usize, usize)> = Vec::new();
        let mut bi = 0;
        while bi < num_blocks {
            if let Some(d) = bridged[bi] {
                let start = bi;
                while bi < num_blocks && bridged[bi] == Some(d) {
                    bi += 1;
                }
                let end = bi;
                if end - start >= 2 {
                    events.push((d, start * 20, end * 20));
                }
            } else {
                bi += 1;
            }
        }

        println!(
            "{}: {} Hz, {} ch, {} blocks",
            name, sample_rate, channels, num_blocks
        );
        for (d, start, end) in &events {
            println!("{} {} {}", d, start, end);
        }
        let digits_str: String = events.iter().map(|(d, _, _)| *d).collect();
        println!("digits: {}", digits_str);
    }
}

#!/usr/bin/env python3
import sys
import socket
import os
import base64
import hashlib
import struct
import re


def parse_ws_url(url):
    match = re.match(r'ws://([^:/]+):(\d+)(/.*)', url)
    if not match:
        raise ValueError(f"Invalid URL: {url}")
    host = match.group(1)
    port = int(match.group(2))
    path = match.group(3)
    return host, port, path


class WSConnection:
    def __init__(self, sock):
        self.sock = sock
        self.buffer = b''

    def read_exact(self, n):
        while len(self.buffer) < n:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buffer += data
        result = self.buffer[:n]
        self.buffer = self.buffer[n:]
        return result

    def read_frame(self):
        header = self.read_exact(2)
        fin = (header[0] >> 7) & 1
        opcode = header[0] & 0x0F
        masked = (header[1] >> 7) & 1
        length = header[1] & 0x7F

        if length == 126:
            length = struct.unpack('!H', self.read_exact(2))[0]
        elif length == 127:
            length = struct.unpack('!Q', self.read_exact(8))[0]

        mask_key = None
        if masked:
            mask_key = self.read_exact(4)

        payload = self.read_exact(length) if length > 0 else b''

        if mask_key:
            payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))

        return fin, opcode, payload

    def send_frame(self, opcode, payload):
        frame = bytearray()
        frame.append(0x80 | opcode)

        mask_key = os.urandom(4)
        while mask_key == b'\x00\x00\x00\x00':
            mask_key = os.urandom(4)

        length = len(payload)
        if length <= 125:
            frame.append(0x80 | length)
        elif length <= 65535:
            frame.append(0x80 | 126)
            frame.extend(struct.pack('!H', length))
        else:
            frame.append(0x80 | 127)
            frame.extend(struct.pack('!Q', length))

        frame.extend(mask_key)
        masked_payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))
        frame.extend(masked_payload)

        self.sock.sendall(bytes(frame))

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


def do_handshake(conn, host, port, path):
    key = base64.b64encode(os.urandom(16)).decode('ascii')

    request = (
        f"GET {path} HTTP/1.1\r\n"
        f"Host: {host}:{port}\r\n"
        f"Upgrade: websocket\r\n"
        f"Connection: Upgrade\r\n"
        f"Sec-WebSocket-Version: 13\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        f"\r\n"
    )

    conn.sock.sendall(request.encode('ascii'))

    header_data = b''
    while b'\r\n\r\n' not in header_data:
        data = conn.sock.recv(65536)
        if not data:
            raise ConnectionError("Connection closed during handshake")
        header_data += data

    sep = header_data.index(b'\r\n\r\n')
    headers_raw = header_data[:sep + 4]
    conn.buffer = header_data[sep + 4:]

    lines = headers_raw.split(b'\r\n')
    status_line = lines[0].decode('ascii')
    parts = status_line.split(' ', 2)
    status_code = int(parts[1])
    reason = parts[2] if len(parts) > 2 else ''

    headers = {}
    for line in lines[1:]:
        if b':' in line:
            name, value = line.split(b':', 1)
            headers[name.strip().lower().decode('ascii')] = value.strip().decode('ascii')

    return status_code, reason, headers, key


def handle_close(conn, payload, state):
    if len(payload) >= 2:
        code = struct.unpack('!H', payload[:2])[0]
        reason_bytes = payload[2:]
        reason_str = reason_bytes.decode('utf-8', errors='replace')
    else:
        code = 1005
        reason_str = ''

    if reason_str:
        print(f"closed {code} {reason_str}")
    else:
        print(f"closed {code}")

    if not state['sent_close']:
        close_payload = struct.pack('!H', code)
        conn.send_frame(8, close_payload)
        state['sent_close'] = True


def read_message(conn, state):
    """Read a complete message. Returns (opcode, payload) or None if closed/error."""
    while True:
        try:
            fin, opcode, payload = conn.read_frame()
        except ConnectionError:
            return None

        if opcode == 9:
            conn.send_frame(10, payload)
            continue

        if opcode == 10:
            continue

        if opcode == 8:
            handle_close(conn, payload, state)
            return None

        if opcode in (1, 2):
            msg_opcode = opcode
            msg_payload = payload

            while not fin:
                try:
                    fin2, opcode2, payload2 = conn.read_frame()
                except ConnectionError:
                    return None

                if opcode2 == 9:
                    conn.send_frame(10, payload2)
                    continue
                if opcode2 == 10:
                    continue
                if opcode2 == 8:
                    handle_close(conn, payload2, state)
                    return None

                msg_payload += payload2
                fin = fin2

            return (msg_opcode, msg_payload)

        continue


def process_session(url):
    try:
        host, port, path = parse_ws_url(url)
    except ValueError:
        return

    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((host, port))
    except (OSError, ConnectionError):
        return

    conn = WSConnection(sock)
    state = {'sent_close': False}

    try:
        status_code, reason, headers, key = do_handshake(conn, host, port, path)
    except (ConnectionError, Exception):
        conn.close()
        return

    if status_code != 101:
        print(f"handshake failed: {status_code} {reason}")
        conn.close()
        return

    expected_accept = base64.b64encode(
        hashlib.sha1((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode('ascii')).digest()
    ).decode('ascii')

    actual_accept = headers.get('sec-websocket-accept', None)
    if actual_accept != expected_accept:
        print("handshake failed: bad Sec-WebSocket-Accept")
        conn.close()
        return

    while True:
        msg = read_message(conn, state)
        if msg is None:
            break

        msg_opcode, msg_payload = msg

        if msg_opcode == 1:
            text = msg_payload.decode('utf-8')

            if text == 'BYE':
                close_payload = struct.pack('!H', 1000)
                conn.send_frame(8, close_payload)
                state['sent_close'] = True

                while True:
                    msg2 = read_message(conn, state)
                    if msg2 is None:
                        break
                break

            elif text.startswith('ADD '):
                parts = text.split(' ', 2)
                a = int(parts[1])
                b = int(parts[2])
                result = str(a + b)
                conn.send_frame(1, result.encode('utf-8'))
                print(f"{text} -> {result}")

            elif text.startswith('REV '):
                text_content = text[4:]
                reversed_text = text_content[::-1]
                conn.send_frame(1, reversed_text.encode('utf-8'))
                print(f"{text} -> {reversed_text}")

            elif text == 'SHA1':
                msg2 = read_message(conn, state)
                if msg2 is None:
                    break
                _, bin_payload = msg2
                hex_digest = hashlib.sha1(bin_payload).hexdigest()
                conn.send_frame(1, hex_digest.encode('utf-8'))
                print(f"SHA1 {len(bin_payload)} -> {hex_digest}")

        elif msg_opcode == 2:
            pass

    conn.close()


def main():
    urls = sys.argv[1:]
    for i, url in enumerate(urls, 1):
        print(f"session {i}")
        process_session(url)


if __name__ == '__main__':
    try:
        main()
    except Exception:
        pass
    sys.exit(0)

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> wavFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wavFiles.add(f);
            }
        }
        wavFiles.sort((a, b) -> {
            byte[] an = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getName().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        boolean first = true;
        for (File file : wavFiles) {
            if (!first) System.out.println();
            first = false;
            processFile(file);
        }
    }

    static void processFile(File file) throws Exception {
        String name = file.getName();
        byte[] data = Files.readAllBytes(file.toPath());

        if (data.length < 12) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F'
                || data[8] != 'W' || data[9] != 'A' || data[10] != 'V' || data[11] != 'E') {
            System.out.println(name + ": unsupported");
            return;
        }

        int pos = 12;
        byte[] fmtBody = null;
        byte[] dataBody = null;

        while (pos + 8 <= data.length) {
            String chunkId = new String(data, pos, 4, StandardCharsets.US_ASCII);
            int chunkSize = readInt32LE(data, pos + 4);
            pos += 8;

            if (chunkId.equals("fmt ")) {
                fmtBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            } else if (chunkId.equals("data")) {
                dataBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            }

            pos += chunkSize;
            if (chunkSize % 2 != 0) pos++;
        }

        if (fmtBody == null || dataBody == null) {
            System.out.println(name + ": unsupported");
            return;
        }

        int formatTag = readInt16LE(fmtBody, 0);
        int channels = readInt16LE(fmtBody, 2);
        int sampleRate = readInt32LE(fmtBody, 4);
        int bitsPerSample = readInt16LE(fmtBody, 10);

        int effectiveFormat = formatTag;
        if (formatTag == 0xFFFE) {
            if (fmtBody.length >= 26) {
                effectiveFormat = readInt16LE(fmtBody, 24);
            } else {
                System.out.println(name + ": unsupported");
                return;
            }
        }

        if (effectiveFormat != 1 || bitsPerSample != 16) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (channels < 1 || channels > 2) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (sampleRate != 8000 && sampleRate != 16000) {
            System.out.println(name + ": unsupported");
            return;
        }

        int frameSize = 2 * channels;
        int numFrames = dataBody.length / frameSize;
        short[] samples = new short[numFrames];
        for (int i = 0; i < numFrames; i++) {
            int offset = i * frameSize;
            samples[i] = (short) ((dataBody[offset] & 0xFF) | ((dataBody[offset + 1] & 0xFF) << 8));
        }

        int N = sampleRate / 50;
        int numBlocks = numFrames / N;

        double[] lowFreqs = {697, 770, 852, 941};
        double[] highFreqs = {1209, 1336, 1477, 1633};

        char[] digitMap = {
            '1', '2', '3', 'A',
            '4', '5', '6', 'B',
            '7', '8', '9', 'C',
            '*', '0', '#', 'D'
        };

        char[] blockLabels = new char[numBlocks];
        for (int b = 0; b < numBlocks; b++) {
            int start = b * N;
            double E = 0;
            for (int n = 0; n < N; n++) {
                double x = samples[start + n];
                E += x * x;
            }

            if (E < 1000000.0 * N) {
                blockLabels[b] = 0;
                continue;
            }

            double maxLowR = -1, maxHighR = -1;
            int maxLowIdx = -1, maxHighIdx = -1;

            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, start, N, lowFreqs[fi], sampleRate, E);
                if (r > maxLowR) {
                    maxLowR = r;
                    maxLowIdx = fi;
                }
            }
            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, start, N, highFreqs[fi], sampleRate, E);
                if (r > maxHighR) {
                    maxHighR = r;
                    maxHighIdx = fi;
                }
            }

            if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
                blockLabels[b] = digitMap[maxLowIdx * 4 + maxHighIdx];
            } else {
                blockLabels[b] = 0;
            }
        }

        char[] bridged = Arrays.copyOf(blockLabels, numBlocks);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (blockLabels[i] == 0 && blockLabels[i - 1] != 0 && blockLabels[i + 1] != 0
                    && blockLabels[i - 1] == blockLabels[i + 1]) {
                bridged[i] = blockLabels[i - 1];
            }
        }

        List<int[]> events = new ArrayList<>();
        List<Character> eventDigits = new ArrayList<>();

        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == 0) {
                i++;
                continue;
            }
            char d = bridged[i];
            int startBlock = i;
            while (i < numBlocks && bridged[i] == d) i++;
            int endBlock = i - 1;
            if (endBlock - startBlock + 1 >= 2) {
                events.add(new int[]{startBlock, endBlock});
                eventDigits.add(d);
            }
        }

        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        StringBuilder digits = new StringBuilder();
        for (int j = 0; j < events.size(); j++) {
            int[] ev = events.get(j);
            System.out.println(eventDigits.get(j) + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
            digits.append(eventDigits.get(j));
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int start, int N, double freq, double rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readInt32LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8)
                | ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }

    static int readInt16LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }
}

