            }
        }

        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        StringBuilder digits = new StringBuilder();
        for (int j = 0; j < events.size(); j++) {
            int[] ev = events.get(j);
            System.out.println(eventDigits.get(j) + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
            digits.append(eventDigits.get(j));
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int start, int N, double freq, double rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }
}

import * as net from 'net';
import * as crypto from 'crypto';

class BufferedSocket {
  private buffer: Buffer = Buffer.alloc(0);
  private socket: net.Socket;
  private waiting: (() => void)[] = [];
  private closed: boolean = false;

  constructor(socket: net.Socket) {
    this.socket = socket;
    socket.on('data', (chunk: Buffer) => {
      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.wake();
    });
    socket.on('close', () => {
      this.closed = true;
      this.wake();
    });
    socket.on('error', () => {
      this.closed = true;
      this.wake();
    });
  }

  private wake(): void {
    while (this.waiting.length > 0) {
      const w = this.waiting.shift()!;
      w();
    }
  }

  private async waitForData(): Promise<void> {
    if (this.closed) return;
    await new Promise<void>(resolve => this.waiting.push(resolve));
  }

  async readBytes(n: number): Promise<Buffer | null> {
    while (this.buffer.length < n) {
      if (this.closed) return null;
      await this.waitForData();
    }
    const result = Buffer.from(this.buffer.subarray(0, n));
    this.buffer = this.buffer.subarray(n);
    return result;
  }

  async readUntilDoubleCRLF(): Promise<string | null> {
    const delim = Buffer.from([0x0D, 0x0A, 0x0D, 0x0A]);
    while (true) {
      const idx = this.buffer.indexOf(delim);
      if (idx !== -1) {
        const header = this.buffer.subarray(0, idx).toString('latin1');
        this.buffer = this.buffer.subarray(idx + 4);
        return header;
      }
      if (this.closed) return null;
      await this.waitForData();
    }
  }
}

function writeFrame(socket: net.Socket, opcode: number, payload: Buffer): void {
  const parts: Buffer[] = [];
  parts.push(Buffer.from([0x80 | opcode]));

  const len = payload.length;
  if (len <= 125) {
    parts.push(Buffer.from([0x80 | len]));
  } else if (len <= 65535) {
    parts.push(Buffer.from([0x80 | 126]));
    const ext = Buffer.alloc(2);
    ext.writeUInt16BE(len);
    parts.push(ext);
  } else {
    parts.push(Buffer.from([0x80 | 127]));
    const ext = Buffer.alloc(8);
    ext.writeBigUInt64BE(BigInt(len));
    parts.push(ext);
  }

  let maskKey: Buffer;
  do {
    maskKey = crypto.randomBytes(4);
  } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);
  parts.push(maskKey);

  const masked = Buffer.alloc(len);
  for (let i = 0; i < len; i++) {
    masked[i] = payload[i] ^ maskKey[i % 4];
  }
  parts.push(masked);

  socket.write(Buffer.concat(parts));
}

async function readFrame(bs: BufferedSocket): Promise<{ fin: boolean; opcode: number; payload: Buffer } | null> {
  const h = await bs.readBytes(2);
  if (!h) return null;

  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let payloadLen = h[1] & 0x7F;

  if (payloadLen === 126) {
    const ext = await bs.readBytes(2);
    if (!ext) return null;
    payloadLen = ext.readUInt16BE(0);
  } else if (payloadLen === 127) {
    const ext = await bs.readBytes(8);
    if (!ext) return null;
    payloadLen = Number(ext.readBigUInt64BE(0));
  }

  let maskKey: Buffer | null = null;
  if (masked) {
    maskKey = await bs.readBytes(4);
    if (!maskKey) return null;
  }

  let payload: Buffer;
  if (payloadLen > 0) {
    payload = await bs.readBytes(payloadLen);
    if (!payload) return null;
    if (maskKey) {
      for (let i = 0; i < payload.length; i++) {
        payload[i] ^= maskKey[i % 4];
      }
    }
  } else {
    payload = Buffer.alloc(0);
  }

  return { fin, opcode, payload };
}

function connect(host: string, port: number): Promise<net.Socket> {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection(port, host, () => {
      resolve(socket);
    });
    socket.on('error', reject);
  });
}

async function handleSession(url: string): Promise<void> {
  const parsed = new URL(url);
  const host = parsed.hostname;
  const port = parseInt(parsed.port) || 80;
  const path = parsed.pathname + parsed.search;

  let socket: net.Socket;
  try {
    socket = await connect(host, port);
  } catch {
    return;
  }

  const bs = new BufferedSocket(socket);

  const key = crypto.randomBytes(16).toString('base64');
  const request = `GET ${path} HTTP/1.1\r\nHost: ${host}:${port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${key}\r\n\r\n`;

  socket.write(request);

  const headerStr = await bs.readUntilDoubleCRLF();
  if (headerStr === null) {
    socket.destroy();
    return;
  }

  const lines = headerStr.split('\r\n');
  const statusLine = lines[0];
  const match = statusLine.match(/^HTTP\/\d\.\d (\d+) (.*)$/);

  if (!match) {
    socket.destroy();
    return;
  }

  const statusCode = parseInt(match[1]);
  const reason = match[2];

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reason}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');

  let acceptHeader: string | null = null;
  for (let i = 1; i < lines.length; i++) {
    const colonIdx = lines[i].indexOf(':');
    if (colonIdx === -1) continue;
    const name = lines[i].substring(0, colonIdx).trim().toLowerCase();
    const value = lines[i].substring(colonIdx + 1).trim();
    if (name === 'sec-websocket-accept') {
      acceptHeader = value;
    }
  }

  if (acceptHeader !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  await processFrames(bs, socket);
  socket.destroy();
}

async function processFrames(bs: BufferedSocket, socket: net.Socket): Promise<void> {
  let fragments: Buffer[] = [];
  let currentOpcode: number | null = null;
  let sentClose = false;
  let sha1Pending = false;

  function handleClose(payload: Buffer): void {
    let code: number;
    let reason: string;

    if (payload.length >= 2) {
      code = payload.readUInt16BE(0);
      reason = payload.subarray(2).toString('utf8');
    } else {
      code = 1005;
      reason = '';
    }

    if (!sentClose) {
      const closePayload = Buffer.alloc(2);
      closePayload.writeUInt16BE(code);
      writeFrame(socket, 8, closePayload);
      sentClose = true;
    }

    if (reason.length > 0) {
      console.log(`closed ${code} ${reason}`);
    } else {
      console.log(`closed ${code}`);
    }
  }

  async function handleCompleteMessage(opcode: number, payload: Buffer): Promise<void> {
    if (opcode === 1) {
      const text = payload.toString('utf8');

      if (text === 'BYE') {
        const closePayload = Buffer.from([0x03, 0xE8]);
        writeFrame(socket, 8, closePayload);
        sentClose = true;
        return;
      }

      if (text === 'SHA1') {
        sha1Pending = true;
        return;
      }

      if (text.startsWith('ADD ')) {
        const parts = text.substring(4).split(' ');
        const a = BigInt(parts[0]);
        const b = BigInt(parts[1]);
        const sum = a + b;
        const reply = sum.toString();
        writeFrame(socket, 1, Buffer.from(reply, 'utf8'));
        console.log(`${text} -> ${reply}`);
      } else if (text.startsWith('REV ')) {
        const text2 = text.substring(4);
        const reversed = Array.from(text2).reverse().join('');
        writeFrame(socket, 1, Buffer.from(reversed, 'utf8'));
        console.log(`REV ${text2} -> ${reversed}`);
      }
    } else if (opcode === 2) {
      if (sha1Pending) {
        sha1Pending = false;
        const hash = crypto.createHash('sha1').update(payload).digest('hex');
        writeFrame(socket, 1, Buffer.from(hash, 'utf8'));
        console.log(`SHA1 ${payload.length} -> ${hash}`);
      }
    }
  }

  while (true) {
    const frame = await readFrame(bs);
    if (!frame) break;

    switch (frame.opcode) {
      case 0:
        fragments.push(frame.payload);
        if (frame.fin) {
          const fullPayload = Buffer.concat(fragments);
          await handleCompleteMessage(currentOpcode!, fullPayload);
          fragments = [];
          currentOpcode = null;
        }
        break;

      case 1:
      case 2:
        if (frame.fin) {
          await handleCompleteMessage(frame.opcode, frame.payload);
        } else {
          fragments = [frame.payload];
          currentOpcode = frame.opcode;
        }
        break;

      case 8:
        handleClose(frame.payload);
        return;

      case 9:
        writeFrame(socket, 10, frame.payload);
        break;

      case 10:
        break;
    }
  }
}

async function main(): Promise<void> {
  const urls = process.argv.slice(2);
  for (let i = 0; i < urls.length; i++) {
    console.log(`session ${i + 1}`);
    await handleSession(urls[i]);
  }
}

main().then(() => process.exit(0));

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom RNG = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            try {
                handleSession(args[i]);
            } catch (Exception e) {
                // connection error, move on
            }
        }
        System.out.flush();
    }

    static void handleSession(String url) throws Exception {
        String rest = url.substring(5); // remove "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx == -1) {
            hostPort = rest;
            path = "/";
        } else {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        }

        String host;
        int port;
        int colonIdx = hostPort.lastIndexOf(':');
        if (colonIdx == -1) {
            host = hostPort;
            port = 80;
        } else {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        }

        Socket socket = new Socket();
        try {
            socket.connect(new InetSocketAddress(host, port), 30000);
            socket.setTcpNoDelay(true);
            InputStream in = new BufferedInputStream(socket.getInputStream());
            OutputStream out = socket.getOutputStream();

            // Generate Sec-WebSocket-Key
            byte[] keyBytes = new byte[16];
            RNG.nextBytes(keyBytes);
            String key = Base64.getEncoder().encodeToString(keyBytes);

            // Send handshake
            StringBuilder req = new StringBuilder();
            req.append("GET ").append(path).append(" HTTP/1.1\r\n");
            req.append("Host: ").append(host).append(":").append(port).append("\r\n");
            req.append("Upgrade: websocket\r\n");
            req.append("Connection: Upgrade\r\n");
            req.append("Sec-WebSocket-Version: 13\r\n");
            req.append("Sec-WebSocket-Key: ").append(key).append("\r\n");
            req.append("\r\n");
            out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
            out.flush();

            // Read response headers byte-by-byte until \r\n\r\n
            ByteArrayOutputStream headerBuf = new ByteArrayOutputStream();
            int state = 0;
            while (true) {
                int b = in.read();
                if (b == -1) return;
                headerBuf.write(b);
                if (b == '\r') {
                    state = (state == 2) ? 3 : 1;
                } else if (b == '\n') {
                    if (state == 1) state = 2;
                    else if (state == 3) break;
                    else state = 0;
                } else {
                    state = 0;
                }
            }

            String headerBlock = new String(headerBuf.toByteArray(), StandardCharsets.US_ASCII);
            String[] lines = headerBlock.split("\r\n");
            String statusLine = lines[0];
            String[] statusParts = statusLine.split(" ", 3);
            int statusCode = Integer.parseInt(statusParts[1]);
            String reasonPhrase = statusParts.length > 2 ? statusParts[2] : "";

            if (statusCode != 101) {
                System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
                return;
            }

            // Check Sec-WebSocket-Accept
            String accept = null;
            for (int i = 1; i < lines.length; i++) {
                int colon = lines[i].indexOf(':');
                if (colon == -1) continue;
                String name = lines[i].substring(0, colon).trim().toLowerCase();
                String value = lines[i].substring(colon + 1).trim();
                if (name.equals("sec-websocket-accept")) {
                    accept = value;
                }
            }

            String expectedAccept = computeAccept(key);
            if (accept == null || !accept.equals(expectedAccept)) {
                System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                return;
            }

            // Process WebSocket frames
            processFrames(in, out);
        } finally {
            try { socket.close(); } catch (IOException e) {}
        }
    }

    static void processFrames(InputStream in, OutputStream out) throws Exception {
        boolean sentClose = false;
        boolean pendingSHA1 = false;
        int msgOpcode = -1;
        ByteArrayOutputStream msgBuf = new ByteArrayOutputStream();

        while (true) {
            // Read frame header
            int b0 = readByte(in);
            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;

            int b1 = readByte(in);
            boolean masked = (b1 & 0x80) != 0;
            long len = b1 & 0x7F;

            if (len == 126) {
                int b2 = readByte(in);
                int b3 = readByte(in);
                len = ((b2 & 0xFF) << 8) | (b3 & 0xFF);
            } else if (len == 127) {
                len = 0;
                for (int i = 0; i < 8; i++) {
                    len = (len << 8) | (readByte(in) & 0xFF);
                }
            }

            byte[] maskKey = null;
            if (masked) {
                maskKey = readNBytes(in, 4);
            }

            byte[] payload = readNBytes(in, (int) len);

            if (masked && maskKey != null) {
                for (int i = 0; i < payload.length; i++) {
                    payload[i] ^= maskKey[i & 3];
                }
            }

            // Handle frame by opcode
            if (opcode == 8) { // Close
                int code = 1005;
                String reason = "";
                if (payload.length >= 2) {
                    code = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
                    reason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
                }
                if (reason.isEmpty()) {
                    System.out.println("closed " + code);
                } else {
                    System.out.println("closed " + code + " " + reason);
                }
                if (!sentClose) {
                    byte[] cp = new byte[]{(byte) (code >> 8), (byte) (code & 0xFF)};
                    try { sendFrame(out, 8, cp); } catch (IOException e) {}
                }
                return;
            }

            if (opcode == 9) { // Ping
                try { sendFrame(out, 10, payload); } catch (IOException e) {}
                continue;
            }

            if (opcode == 10) { // Pong
                continue;
            }

            // Data frame (0=continuation, 1=text, 2=binary)
            if (opcode != 0) {
                msgOpcode = opcode;
                msgBuf.reset();
            }
            msgBuf.write(payload);

            if (fin) {
                byte[] fullPayload = msgBuf.toByteArray();

                if (pendingSHA1) {
                    pendingSHA1 = false;
                    String hex = sha1Hex(fullPayload);
                    System.out.println("SHA1 " + fullPayload.length + " -> " + hex);
                    try { sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                } else if (msgOpcode == 1) {
                    String cmd = new String(fullPayload, StandardCharsets.UTF_8);
                    if (cmd.equals("BYE")) {
                        byte[] cp = new byte[]{0x03, (byte) 0xE8};
                        try { sendFrame(out, 8, cp); } catch (IOException e) {}
                        sentClose = true;
                    } else if (cmd.startsWith("ADD ")) {
                        String params = cmd.substring(4);
                        int sp = params.indexOf(' ');
                        long a = Long.parseLong(params.substring(0, sp));
                        long b = Long.parseLong(params.substring(sp + 1));
                        long sum = a + b;
                        String reply = Long.toString(sum);
                        System.out.println(cmd + " -> " + reply);
                        try { sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                    } else if (cmd.startsWith("REV ")) {
                        String text = cmd.substring(4);
                        String reversed = reverseCodePoints(text);
                        System.out.println(cmd + " -> " + reversed);
                        try { sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                    } else if (cmd.equals("SHA1")) {
                        pendingSHA1 = true;
                    }
                }
            }
        }
    }

    static int readByte(InputStream in) throws IOException {
        int b = in.read();
        if (b == -1) throw new EOFException();
        return b;
    }

    static byte[] readNBytes(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = in.read(buf, off, n - off);
            if (r == -1) throw new EOFException();
            off += r;
        }
        return buf;
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        // FIN=1, RSV=0, opcode
        buf.write(0x80 | opcode);

        int len = payload.length;
        if (len <= 125) {
            buf.write(0x80 | len);
        } else if (len <= 65535) {
            buf.write(0x80 | 126);
            buf.write((len >> 8) & 0xFF);
            buf.write(len & 0xFF);
        } else {
            buf.write(0x80 | 127);
            long l = len;
            for (int i = 7; i >= 0; i--) {
                buf.write((int) ((l >>> (i * 8)) & 0xFF));
            }
        }

        // Masking key: 4 random bytes, not all zero
        byte[] mk = new byte[4];
        do {
            RNG.nextBytes(mk);
        } while (mk[0] == 0 && mk[1] == 0 && mk[2] == 0 && mk[3] == 0);
        buf.write(mk);

        // Masked payload
        for (int i = 0; i < payload.length; i++) {
            buf.write(payload[i] ^ mk[i & 3]);
        }

        out.write(buf.toByteArray());
        out.flush();
    }

    static String computeAccept(String key) throws Exception {
        String combined = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        byte[] digest = sha1.digest(combined.getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(digest);
    }

    static String sha1Hex(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder(40);
        for (byte b : digest) {
            sb.append(Character.forDigit((b >> 4) & 0xF, 16));
            sb.append(Character.forDigit(b & 0xF, 16));
        }
        return sb.toString();
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        for (int i = 0, j = cps.length - 1; i < j; i++, j--) {
            int tmp = cps[i];
            cps[i] = cps[j];
            cps[j] = tmp;
        }
        return new String(cps, 0, cps.length);
    }
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::collections::HashMap;
use std::time::Duration;

#[derive(Clone, Debug)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(fields) = self {
            for (k, v) in fields {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self { Some(s) } else { None }
    }
    fn as_i64(&self) -> Option<i64> {
        if let Json::Num(n) = self { Some(*n as i64) } else { None }
    }
    fn as_array(&self) -> Option<&Vec<Json>> {
        if let Json::Arr(a) = self { Some(a) } else { None }
    }
}

struct JsonParser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self {
        JsonParser { data: s.as_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.data.len() {
            match self.data[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        if self.pos < self.data.len() { Some(self.data[self.pos]) } else { None }
    }
    fn expect(&mut self, b: u8) {
        if self.pos >= self.data.len() || self.data[self.pos] != b {
            panic!("Expected '{}' at pos {}", b as char, self.pos);
        }
        self.pos += 1;
    }
    fn parse(&mut self) -> Json {
        self.skip_ws();
        let val = self.parse_value();
        self.skip_ws();
        val
    }
    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string(),
            Some(b't') => { self.expect_lit(b"true"); Json::Bool(true) }
            Some(b'f') => { self.expect_lit(b"false"); Json::Bool(false) }
            Some(b'n') => { self.expect_lit(b"null"); Json::Null }
            _ => self.parse_number(),
        }
    }
    fn expect_lit(&mut self, lit: &[u8]) {
        for &b in lit { self.expect(b); }
    }
    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut fields = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Json::Obj(fields); }
        loop {
            self.skip_ws();
            let key = self.parse_string_value();
            self.skip_ws();
            self.expect(b':');
            self.skip_ws();
            let val = self.parse_value();
            fields.push((key, val));
            self.skip_ws();
            if self.peek() == Some(b',') { self.pos += 1; } else { break; }
        }
        self.expect(b'}');
        Json::Obj(fields)
    }
    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Json::Arr(items); }
        loop {
            self.skip_ws();
            let val = self.parse_value();
            items.push(val);
            self.skip_ws();
            if self.peek() == Some(b',') { self.pos += 1; } else { break; }
        }
        self.expect(b']');
        Json::Arr(items)
    }
    fn parse_string_value(&mut self) -> String {
        self.expect(b'"');
        let mut result = String::new();
        loop {
            let b = self.data[self.pos];
            self.pos += 1;
            match b {
                b'"' => break,
                b'\\' => {
                    let esc = self.data[self.pos];
                    self.pos += 1;
                    match esc {
                        b'"' => result.push('"'),
                        b'\\' => result.push('\\'),
                        b'/' => result.push('/'),
                        b'b' => result.push('\u{08}'),
                        b'f' => result.push('\u{0C}'),
                        b'n' => result.push('\n'),
                        b'r' => result.push('\r'),
                        b't' => result.push('\t'),
                        b'u' => {
                            let cp = self.parse_hex4();
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                self.expect(b'\\');
                                self.expect(b'u');
                                let cp2 = self.parse_hex4();
                                let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                result.push(char::from_u32(combined).unwrap_or('\u{FFFD}'));
                            } else {
                                result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => { result.push('\\'); result.push(esc as char); }
                    }
                }
                _ => {
                    if b < 0x80 {
                        result.push(b as char);
                    } else {
                        let extra = if b >= 0xF0 { 3usize } else if b >= 0xE0 { 2 } else { 1 };
                        let mut bytes = vec![b];
                        for _ in 0..extra {
                            bytes.push(self.data[self.pos]);
                            self.pos += 1;
                        }
                        result.push_str(&String::from_utf8_lossy(&bytes));
                    }
                }
            }
        }
        result
    }
    fn parse_string(&mut self) -> Json {
        Json::Str(self.parse_string_value())
    }
    fn parse_hex4(&mut self) -> u32 {
        let mut val: u32 = 0;
        for _ in 0..4 {
            let b = self.data[self.pos];
            self.pos += 1;
            let d = match b {
                b'0'..=b'9' => (b - b'0') as u32,
                b'a'..=b'f' => (b - b'a' + 10) as u32,
                b'A'..=b'F' => (b - b'A' + 10) as u32,
                _ => panic!("bad hex"),
            };
            val = val * 16 + d;
        }
        val
    }
    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.data.len() && self.data[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.data.len() && (self.data[self.pos] == b'e' || self.data[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.data.len() && (self.data[self.pos] == b'+' || self.data[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap();
        Json::Num(s.parse::<f64>().unwrap())
    }
}

fn json_to_string(j: &Json) -> String {
    let mut out = String::new();
    write_json(j, &mut out);
    out
}

fn write_json(j: &Json, out: &mut String) {
    match j {
        Json::Null => out.push_str("null"),
        Json::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Json::Num(n) => {
            if *n == n.floor() && n.abs() < 9.007199254740992e15 {
                out.push_str(&format!("{}", *n as i64));
            } else {
                out.push_str(&format!("{}", n));
            }
        }
        Json::Str(s) => write_json_str(s, out),
        Json::Arr(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push(','); }
                write_json(item, out);
            }
            out.push(']');
        }
        Json::Obj(fields) => {
            out.push('{');
            for (i, (k, v)) in fields.iter().enumerate() {
                if i > 0 { out.push(','); }
                write_json_str(k, out);
                out.push(':');
                write_json(v, out);
            }
            out.push('}');
        }
    }
}

fn write_json_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => out.push(c),
        }
    }
    out.push('"');
}

fn json_str(s: &str) -> String {
    let mut out = String::new();
    write_json_str(s, &mut out);
    out
}

fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let mut pos = 0;
    if data.len() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
        pos = 3;
    }
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut current_record: Vec<String> = Vec::new();
    let mut field_bytes: Vec<u8> = Vec::new();

    while pos < data.len() {
        if data[pos] == b'"' {
            pos += 1;
            loop {
                if pos >= data.len() { break; }
                if data[pos] == b'"' {
                    if pos + 1 < data.len() && data[pos + 1] == b'"' {
                        field_bytes.push(b'"');
                        pos += 2;
                    } else {
                        pos += 1;
                        break;
                    }
                } else {
                    field_bytes.push(data[pos]);
                    pos += 1;
                }
            }
        } else if data[pos] == b',' {
            current_record.push(String::from_utf8_lossy(&field_bytes).into_owned());
            field_bytes.clear();
            pos += 1;
        } else if data[pos] == b'\r' && pos + 1 < data.len() && data[pos + 1] == b'\n' {
            current_record.push(String::from_utf8_lossy(&field_bytes).into_owned());
            field_bytes.clear();
            records.push(std::mem::take(&mut current_record));
            pos += 2;
        } else if data[pos] == b'\n' {
            current_record.push(String::from_utf8_lossy(&field_bytes).into_owned());
            field_bytes.clear();
            records.push(std::mem::take(&mut current_record));
            pos += 1;
        } else {
            field_bytes.push(data[pos]);
            pos += 1;
        }
    }
    if !field_bytes.is_empty() || !current_record.is_empty() {
        current_record.push(String::from_utf8_lossy(&field_bytes).into_owned());
        records.push(current_record);
    }
    records
}

fn find_bytes(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > haystack.len() { return None; }
    for i in 0..=(haystack.len() - needle.len()) {
        if &haystack[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

fn http_post(url: &str, body: &str, api_key: &str) -> (u16, String) {
    let without_scheme = if url.starts_with("http://") {
        &url[7..]
    } else {
        url
    };
    let (host_port, path) = match without_scheme.find('/') {
        Some(i) => (&without_scheme[..i], &without_scheme[i..]),
        None => (without_scheme, "/"),
    };
    let (host, port) = match host_port.rfind(':') {
        Some(i) => (&host_port[..i], host_port[i + 1..].parse::<u16>().unwrap()),
        None => (host_port, 80u16),
    };
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    stream.set_read_timeout(Some(Duration::from_secs(60))).ok();

    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nAuthorization: Bearer {}\r\n\r\n{}",
        path, host_port, body.len(), api_key, body
    );
    stream.write_all(req.as_bytes()).expect("write failed");
    stream.flush().expect("flush failed");

    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("read failed");

    let header_end = find_bytes(&response, b"\r\n\r\n").unwrap_or(response.len());
    let header_bytes = &response[..header_end];
    let body_bytes = if header_end + 4 <= response.len() {
        &response[header_end + 4..]
    } else {
        &[]
    };

    let status_line_end = find_bytes(header_bytes, b"\r\n").unwrap_or(header_bytes.len());
    let status_line = String::from_utf8_lossy(&header_bytes[..status_line_end]).into_owned();
    let status_code: u16 = status_line.split_whitespace().nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);

    let body_str = String::from_utf8_lossy(body_bytes).into_owned();
    (status_code, body_str)
}

fn execute_tool(
    name: &str,
    args: &Json,
    inventory: &HashMap<String, (String, i64, String, i64)>,
    rates: &HashMap<String, i64>,
) -> String {
    match name {
        "inventory_lookup" => {
            let sku = args.get("sku").and_then(|v| v.as_str()).unwrap_or("");
            match inventory.get(sku) {
                Some((inv_name, price_cents, currency, stock)) => {
                    format!(
                        "{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                        json_str(sku),
                        json_str(inv_name),
                        price_cents,
                        json_str(currency),
                        stock
                    )
                }
                None => {
                    format!("{{\"error\":{}}}", json_str(&format!("unknown sku: {}", sku)))
                }
            }
        }
        "convert_currency" => {
            let amount_cents = args.get("amount_cents").and_then(|v| v.as_i64()).unwrap_or(0);
            let from = args.get("from").and_then(|v| v.as_str()).unwrap_or("");
            let to = args.get("to").and_then(|v| v.as_str()).unwrap_or("");
            let rate_from = *rates.get(from).unwrap_or(&1000000);
            let rate_to = *rates.get(to).unwrap_or(&1000000);
            let numerator: i128 = 2 * amount_cents as i128 * rate_to as i128 + rate_from as i128;
            let denominator: i128 = 2 * rate_from as i128;
            let converted = (numerator / denominator) as i64;
            format!("{{\"amount_cents\":{},\"currency\":{}}}", converted, json_str(to))
        }
        _ => {
            format!("{{\"error\":{}}}", json_str(&format!("unknown tool: {}", name)))
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let task_data = fs::read_to_string(format!("{}/task.json", data_dir)).expect("read task.json");
    let task = JsonParser::new(&task_data).parse();

    let api_key = task.get("api_key").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let model = task.get("model").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let system = task.get("system").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let user_msg = task.get("user").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let tools = task.get("tools").cloned().unwrap_or(Json::Arr(vec![]));

    let inv_data = fs::read(format!("{}/inventory.csv", data_dir)).expect("read inventory.csv");
    let csv_records = parse_csv(&inv_data);
    let mut inventory: HashMap<String, (String, i64, String, i64)> = HashMap::new();
    for record in csv_records.iter().skip(1) {
        if record.len() >= 5 {
            let sku = record[0].clone();
            let name = record[1].clone();
            let price_cents: i64 = record[2].parse().unwrap_or(0);
            let currency = record[3].clone();
            let stock: i64 = record[4].parse().unwrap_or(0);
            inventory.insert(sku, (name, price_cents, currency, stock));
        }
    }

    let rates_data = fs::read_to_string(format!("{}/rates.json", data_dir)).expect("read rates.json");
    let rates_json = JsonParser::new(&rates_data).parse();
    let rates_map: HashMap<String, i64> = rates_json
        .get("rates")
        .and_then(|r| if let Json::Obj(fields) = r { Some(fields) } else { None })
        .map(|fields| {
            fields.iter().map(|(k, v)| (k.clone(), v.as_i64().unwrap_or(0))).collect()
        })
        .unwrap_or_default();

    let mut messages: Vec<Json> = vec![
        Json::Obj(vec![
            ("role".to_string(), Json::Str("system".to_string())),
            ("content".to_string(), Json::Str(system)),
        ]),
        Json::Obj(vec![
            ("role".to_string(), Json::Str("user".to_string())),
            ("content".to_string(), Json::Str(user_msg)),
        ]),
    ];

    let mut output_lines: Vec<String> = Vec::new();
    let mut total_prompt: i64 = 0;
    let mut total_completion: i64 = 0;
    let mut total_total: i64 = 0;
    let mut num_requests: i64 = 0;

    loop {
        let request_body = Json::Obj(vec![
            ("model".to_string(), Json::Str(model.clone())),
            ("messages".to_string(), Json::Arr(messages.clone())),
            ("tools".to_string(), tools.clone()),
            ("tool_choice".to_string(), Json::Str("auto".to_string())),
        ]);
        let body_str = json_to_string(&request_body);
        num_requests += 1;

        let url = format!("{}/chat/completions", base_url);
        let (status, resp_body) = http_post(&url, &body_str, &api_key);

        if status != 200 {
            let err_msg = {
                if resp_body.is_empty() {
                    String::new()
                } else {
                    let mut p = JsonParser::new(&resp_body);
                    let err_json = p.parse();
                    err_json
                        .get("error")
                        .and_then(|e| e.get("message"))
                        .and_then(|m| m.as_str())
                        .unwrap_or("")
                        .to_string()
                }
            };
            for line in &output_lines {
                println!("{}", line);
            }
            println!("ERROR {} {}", status, err_msg);
            std::process::exit(0);
        }

        let resp = JsonParser::new(&resp_body).parse();

        if let Some(usage) = resp.get("usage") {
            total_prompt += usage.get("prompt_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
            total_completion += usage.get("completion_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
            total_total += usage.get("total_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
        }

        let choice = resp
            .get("choices")
            .and_then(|c| c.as_array())
            .and_then(|a| a.first())
            .cloned()
            .unwrap_or(Json::Null);

        let finish_reason = choice
            .get("finish_reason")
            .and_then(|f| f.as_str())
            .unwrap_or("stop")
            .to_string();

        let msg = choice.get("message").cloned().unwrap_or(Json::Null);
        let content = msg.get("content").and_then(|c| c.as_str()).map(|s| s.to_string());

        if finish_reason == "tool_calls" {
            if let Some(ref c) = content {
                output_lines.push(format!("SAY {}", c));
            }

            let tool_calls = msg
                .get("tool_calls")
                .and_then(|tc| tc.as_array())
                .cloned()
                .unwrap_or_default();

            for tc in &tool_calls {
                let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let name = tc
                    .get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                output_lines.push(format!("CALL {} {}", id, name));
            }

            let mut tool_results: Vec<Json> = Vec::new();
            for tc in &tool_calls {
                let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let name = tc
                    .get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let args_str = tc
                    .get("function")
                    .and_then(|f| f.get("arguments"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("{}")
                    .to_string();

                let args = {
                    let mut p = JsonParser::new(&args_str);
                    p.parse()
                };

                let result = execute_tool(&name, &args, &inventory, &rates_map);
                output_lines.push(format!("RESULT {} {}", id, result));

                tool_results.push(Json::Obj(vec![
                    ("role".to_string(), Json::Str("tool".to_string())),
                    ("tool_call_id".to_string(), Json::Str(id)),
                    ("content".to_string(), Json::Str(result)),
                ]));
            }

            let content_json = if let Some(ref c) = content {
                Json::Str(c.clone())
            } else {
                Json::Null
            };

            let tc_json: Vec<Json> = tool_calls
                .iter()
                .map(|tc| {
                    let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    let call_type = tc
                        .get("type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("function")
                        .to_string();
                    let func = tc.get("function").cloned().unwrap_or(Json::Obj(vec![]));
                    let name = func
                        .get("name")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string();
                    let arguments = func
                        .get("arguments")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string();
                    Json::Obj(vec![
                        ("id".to_string(), Json::Str(id)),
                        ("type".to_string(), Json::Str(call_type)),
                        (
                            "function".to_string(),
                            Json::Obj(vec![
                                ("name".to_string(), Json::Str(name)),
                                ("arguments".to_string(), Json::Str(arguments)),
                            ]),
                        ),
                    ])
                })
                .collect();

            let assistant_msg = Json::Obj(vec![
                ("role".to_string(), Json::Str("assistant".to_string())),
                ("content".to_string(), content_json),
                ("tool_calls".to_string(), Json::Arr(tc_json)),
            ]);

            messages.push(assistant_msg);
            messages.extend(tool_results);
        } else {
            let final_content = content.unwrap_or_default();
            output_lines.push(format!("FINAL {}", final_content));
            break;
        }
    }

    for line in &output_lines {
        println!("{}", line);
    }
    println!(
        "USAGE prompt={} completion={} total={} requests={}",
        total_prompt, total_completion, total_total, num_requests
    );
}

