    return data.withUnsafeBytes { ptr -> Bool in
        while offset < total {
            let n = write(fd, ptr.baseAddress!.advanced(by: offset), total - offset)
            if n <= 0 { return false }
            offset += n
        }
        return true
    }
}

// MARK: - Buffered Reader

class BufferedReader {
    var buffer: [UInt8] = []
    let fd: Int32

    init(fd: Int32) {
        self.fd = fd
    }

    func fill() -> Bool {
        var tmp = [UInt8](repeating: 0, count: 65536)
        let n = read(fd, &tmp, tmp.count)
        if n <= 0 { return false }
        buffer.append(contentsOf: tmp[0..<n])
        return true
    }

    func ensure(_ count: Int) -> Bool {
        while buffer.count < count {
            if !fill() { return false }
        }
        return true
    }

    func consume(_ count: Int) {
        buffer.removeFirst(count)
    }

    func findSequence(_ seq: [UInt8]) -> Int? {
        if buffer.count < seq.count { return nil }
        for i in 0...(buffer.count - seq.count) {
            var match = true
            for j in 0..<seq.count {
                if buffer[i + j] != seq[j] { match = false; break }
            }
            if match { return i }
        }
        return nil
    }
}

// MARK: - WebSocket Frame

struct WSFrame {
    let fin: Bool
    let opcode: UInt8
    let payload: [UInt8]
}

func readFrame(_ reader: BufferedReader) -> WSFrame? {
    guard reader.ensure(2) else { return nil }
    let b0 = reader.buffer[0]
    let b1 = reader.buffer[1]

    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let masked = (b1 & 0x80) != 0
    var payloadLen = Int(b1 & 0x7F)
    var headerSize = 2

    if payloadLen == 126 {
        guard reader.ensure(4) else { return nil }
        payloadLen = (Int(reader.buffer[2]) << 8) | Int(reader.buffer[3])
        headerSize = 4
    } else if payloadLen == 127 {
        guard reader.ensure(10) else { return nil }
        payloadLen = 0
        for i in 2..<10 {
            payloadLen = (payloadLen << 8) | Int(reader.buffer[i])
        }
        headerSize = 10
    }

    var maskKey: [UInt8] = []
    if masked {
        guard reader.ensure(headerSize + 4) else { return nil }
        maskKey = Array(reader.buffer[headerSize..<headerSize + 4])
        headerSize += 4
    }

    guard reader.ensure(headerSize + payloadLen) else { return nil }
    var payload = Array(reader.buffer[headerSize..<headerSize + payloadLen])

    if masked {
        for i in 0..<payload.count {
            payload[i] ^= maskKey[i % 4]
        }
    }

    reader.consume(headerSize + payloadLen)
    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

func sendFrame(_ fd: Int32, opcode: UInt8, payload: [UInt8]) -> Bool {
    var frame: [UInt8] = []
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in (0..<8).reversed() {
            frame.append(UInt8((len >> (i * 8)) & 0xFF))
        }
    }

    var maskKey: [UInt8]
    repeat {
        maskKey = randomBytes(4)
    } while maskKey == [0, 0, 0, 0]
    frame.append(contentsOf: maskKey)

    for i in 0..<payload.count {
        frame.append(payload[i] ^ maskKey[i % 4])
    }

    return writeAll(fd, frame)
}

// MARK: - URL Parsing

struct WSURL {
    let host: String
    let port: UInt16
    let path: String
}

func parseWSURL(_ url: String) -> WSURL? {
    guard url.hasPrefix("ws://") else { return nil }
    let rest = String(url.dropFirst(5))

    guard let slashIdx = rest.firstIndex(of: "/") else {
        let parts = rest.split(separator: ":")
        guard parts.count == 2, let p = UInt16(parts[1]) else { return nil }
        return WSURL(host: String(parts[0]), port: p, path: "/")
    }

    let hostPort = String(rest[rest.startIndex..<slashIdx])
    let path = String(rest[slashIdx...])
    let parts = hostPort.split(separator: ":")
    guard parts.count == 2, let p = UInt16(parts[1]) else { return nil }
    return WSURL(host: String(parts[0]), port: p, path: path)
}

// MARK: - Session handling

func handleSession(url: WSURL, sessionNum: Int) {
    print("session \(sessionNum)")

    guard let fd = connectTCP(host: url.host, port: url.port) else { return }
    defer { close(fd) }

    let reader = BufferedReader(fd: fd)

    let keyBytes = randomBytes(16)
    let wsKey = base64Encode(keyBytes)

    var request = "GET \(url.path) HTTP/1.1\r\n"
    request += "Host: \(url.host):\(url.port)\r\n"
    request += "Upgrade: websocket\r\n"
    request += "Connection: Upgrade\r\n"
    request += "Sec-WebSocket-Version: 13\r\n"
    request += "Sec-WebSocket-Key: \(wsKey)\r\n"
    request += "\r\n"

    guard writeAll(fd, Array(request.utf8)) else { return }

    // Read HTTP response header block
    let crlfcrlf: [UInt8] = [13, 10, 13, 10]
    var headerEnd = -1
    while true {
        if let idx = reader.findSequence(crlfcrlf) {
            headerEnd = idx
            break
        }
        if !reader.fill() { return }
    }

    let headerData = Array(reader.buffer[0..<headerEnd])
    reader.consume(headerEnd + 4)

    let headerStr = String(bytes: headerData, encoding: .utf8) ?? ""
    let lines = headerStr.components(separatedBy: "\r\n")

    guard let statusLine = lines.first else { return }
    let statusParts = statusLine.components(separatedBy: " ")
    guard statusParts.count >= 2, let statusCode = Int(statusParts[1]) else { return }

    if statusCode != 101 {
        let reason = statusParts.count >= 3 ? statusParts[2...].joined(separator: " ") : ""
        print("handshake failed: \(statusCode) \(reason)")
        return
    }

    // Validate Sec-WebSocket-Accept
    var acceptValue: String?
    for line in lines.dropFirst() {
        if let colonIdx = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<colonIdx]).lowercased()
            let value = String(line[line.index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
            if name == "sec-websocket-accept" {
                acceptValue = value
            }
        }
    }

    let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    let acceptInput = Array((wsKey + magic).utf8)
    let expectedAccept = base64Encode(sha1Digest(acceptInput))

    if acceptValue != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        return
    }

    // Frame processing state
    var waitingForSHA1 = false
    var hasSentClose = false
    var fragOpcode: UInt8 = 0
    var fragPayload: [UInt8] = []

    func processMessage(opcode: UInt8, payload: [UInt8]) {
        if opcode == 0x01 {
            let text = String(bytes: payload, encoding: .utf8) ?? ""

            if text == "BYE" {
                let closePayload: [UInt8] = [0x03, 0xE8]
                _ = sendFrame(fd, opcode: 0x08, payload: closePayload)
                hasSentClose = true
                return
            }

            if text == "SHA1" {
                waitingForSHA1 = true
                return
            }

            if text.hasPrefix("ADD ") {
                let args = String(text.dropFirst(4))
                let parts = args.split(separator: " ", omittingEmptySubsequences: false)
                if parts.count == 2, let a = Int64(parts[0]), let b = Int64(parts[1]) {
                    let sum = a + b
                    print("\(text) -> \(sum)")
                    _ = sendFrame(fd, opcode: 0x01, payload: Array(String(sum).utf8))
                }
                return
            }

            if text.hasPrefix("REV ") {
                let textToReverse = String(text.dropFirst(4))
                let reversed = String(textToReverse.unicodeScalars.reversed())
                print("REV \(textToReverse) -> \(reversed)")
                _ = sendFrame(fd, opcode: 0x01, payload: Array(reversed.utf8))
                return
            }

        } else if opcode == 0x02 {
            if waitingForSHA1 {
                let digest = sha1Digest(payload)
                let hex = hexString(digest)
                print("SHA1 \(payload.count) -> \(hex)")
                _ = sendFrame(fd, opcode: 0x01, payload: Array(hex.utf8))
                waitingForSHA1 = false
            }
        }
    }

    while true {
        guard let frame = readFrame(reader) else { break }

        switch frame.opcode {
        case 0x09: // Ping
            _ = sendFrame(fd, opcode: 0x0A, payload: frame.payload)

        case 0x0A: // Pong - ignore
            break

        case 0x08: // Close
            var code = 1005
            var reason = ""
            if frame.payload.count >= 2 {
                code = (Int(frame.payload[0]) << 8) | Int(frame.payload[1])
                if frame.payload.count > 2 {
                    reason = String(bytes: frame.payload[2...], encoding: .utf8) ?? ""
                }
            }
            if reason.isEmpty {
                print("closed \(code)")
            } else {
                print("closed \(code) \(reason)")
            }
            if !hasSentClose {
                let closePayload: [UInt8] = [UInt8(code >> 8), UInt8(code & 0xFF)]
                _ = sendFrame(fd, opcode: 0x08, payload: closePayload)
            }
            return

        case 0x01, 0x02: // Text or Binary (start of message)
            if frame.fin {
                processMessage(opcode: frame.opcode, payload: frame.payload)
            } else {
                fragOpcode = frame.opcode
                fragPayload = frame.payload
            }

        case 0x00: // Continuation
            if frame.fin {
                fragPayload.append(contentsOf: frame.payload)
                processMessage(opcode: fragOpcode, payload: fragPayload)
            } else {
                fragPayload.append(contentsOf: frame.payload)
            }

        default:
            break
        }
    }
}

