let args = CommandLine.arguments
guard args.count > 1 else { exit(0) }

for (i, arg) in args[1...].enumerated() {
    guard let url = parseWSURL(arg) else { continue }
    handleSession(url: url, sessionNum: i + 1)
}

exit(0)

