// --- SHA-1 ---
fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let msg_len = data.len() as u64;
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&(msg_len * 8).to_be_bytes());
    for block in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[i * 4], block[i * 4 + 1], block[i * 4 + 2], block[i * 4 + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h[0], h[1], h[2], h[3], h[4]);
        for i in 0..80 {
            let (f, k) = match i {
                0..=19 => ((b & c) | (!b & d), 0x5A827999u32),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1u32),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32),
                _ => (b ^ c ^ d, 0xCA62C1D6u32),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut result = [0u8; 20];
    for i in 0..5 {
        result[i * 4..i * 4 + 4].copy_from_slice(&h[i].to_be_bytes());
    }
    result
}

fn sha1_hex(data: &[u8]) -> String {
    let digest = sha1(data);
    digest.iter().map(|b| format!("{:02x}", b)).collect()
}

// --- Base64 ---
fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

// --- Random ---
fn random_bytes(n: usize) -> Vec<u8> {
    let mut file = std::fs::File::open("/dev/urandom").unwrap();
    let mut buf = vec![0u8; n];
    file.read_exact(&mut buf).unwrap();
    buf
}

fn random_mask_key() -> [u8; 4] {
    loop {
        let bytes = random_bytes(4);
        let key = [bytes[0], bytes[1], bytes[2], bytes[3]];
        if key != [0, 0, 0, 0] {
            return key;
        }
    }
}

// --- Buffered Stream ---
struct BufStream {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
    cap: usize,
}

impl BufStream {
    fn new(stream: TcpStream) -> Self {
        BufStream {
            stream,
            buf: vec![0u8; 65536],
            pos: 0,
            cap: 0,
        }
    }

    fn fill(&mut self) -> std::io::Result<bool> {
        if self.pos >= self.cap {
            self.pos = 0;
            self.cap = self.stream.read(&mut self.buf)?;
        }
        Ok(self.cap > 0)
    }

    fn read_byte(&mut self) -> std::io::Result<u8> {
        if self.pos >= self.cap {
            if !self.fill()? {
                return Err(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF"));
            }
        }
        let b = self.buf[self.pos];
        self.pos += 1;
        Ok(b)
    }

    fn read_exact(&mut self, n: usize) -> std::io::Result<Vec<u8>> {
        let mut result = Vec::with_capacity(n);
        while result.len() < n {
            if self.pos >= self.cap {
                if !self.fill()? {
                    return Err(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF"));
                }
            }
            let avail = self.cap - self.pos;
            let need = n - result.len();
            let take = if avail < need { avail } else { need };
            result.extend_from_slice(&self.buf[self.pos..self.pos + take]);
            self.pos += take;
        }
        Ok(result)
    }

    fn read_line(&mut self) -> std::io::Result<Vec<u8>> {
        let mut line = Vec::new();
        loop {
            let b = self.read_byte()?;
            line.push(b);
            if b == b'\n' {
                break;
            }
        }
        Ok(line)
    }

    fn write_all(&mut self, data: &[u8]) -> std::io::Result<()> {
        self.stream.write_all(data)
    }
}

// --- URL parsing ---
fn parse_ws_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let host_port = &rest[..slash_pos];
    let path = if slash_pos < rest.len() {
        &rest[slash_pos..]
    } else {
        "/"
    };
    let colon_pos = host_port.rfind(':').unwrap();
    let host = host_port[..colon_pos].to_string();
    let port: u16 = host_port[colon_pos + 1..].parse().unwrap();
    (host, port, path.to_string())
}

// --- WebSocket frame I/O ---
fn write_frame(bs: &mut BufStream, opcode: u8, payload: &[u8]) -> std::io::Result<()> {
    let mut buf: Vec<u8> = Vec::new();
    buf.push(0x80 | opcode);
    let mask_key = random_mask_key();
    let len = payload.len();
    if len <= 125 {
        buf.push(0x80 | len as u8);
    } else if len <= 65535 {
        buf.push(0x80 | 126);
        buf.extend_from_slice(&(len as u16).to_be_bytes());
    } else {
        buf.push(0x80 | 127);
        buf.extend_from_slice(&(len as u64).to_be_bytes());
    }
    buf.extend_from_slice(&mask_key);
    for (i, &b) in payload.iter().enumerate() {
        buf.push(b ^ mask_key[i % 4]);
    }
    bs.write_all(&buf)
}

struct Frame {
    fin: bool,
    opcode: u8,
    payload: Vec<u8>,
}

fn read_frame(bs: &mut BufStream) -> std::io::Result<Frame> {
    let b0 = bs.read_byte()?;
    let fin = b0 & 0x80 != 0;
    let opcode = b0 & 0x0F;

    let b1 = bs.read_byte()?;
    let masked = b1 & 0x80 != 0;
    let len7 = (b1 & 0x7F) as u64;

    let payload_len: u64 = match len7 {
        0..=125 => len7,
        126 => {
            let bytes = bs.read_exact(2)?;
            u16::from_be_bytes([bytes[0], bytes[1]]) as u64
        }
        127 => {
            let bytes = bs.read_exact(8)?;
            u64::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7]])
        }
        _ => unreachable!(),
    };

    let mask_key = if masked {
        let k = bs.read_exact(4)?;
        Some([k[0], k[1], k[2], k[3]])
    } else {
        None
    };

    let mut payload = bs.read_exact(payload_len as usize)?;
    if let Some(key) = mask_key {
        for (i, b) in payload.iter_mut().enumerate() {
            *b ^= key[i % 4];
        }
    }

    Ok(Frame { fin, opcode, payload })
}

// --- Session handler ---
fn handle_session(url: &str) {
    let (host, port, path) = parse_ws_url(url);

    let stream = match TcpStream::connect((host.as_str(), port)) {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut bs = BufStream::new(stream);

    // Handshake
    let key_bytes = random_bytes(16);
    let key_b64 = base64_encode(&key_bytes);

    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, key_b64
    );
    if bs.write_all(request.as_bytes()).is_err() {
        return;
    }

    // Read response status line
    let status_line = match bs.read_line() {
        Ok(l) => l,
        Err(_) => return,
    };
    let status_str = String::from_utf8_lossy(&status_line).trim_end().to_string();

    // Parse status code and reason
    let parts: Vec<&str> = status_str.splitn(3, ' ').collect();
    if parts.len() < 2 {
        return;
    }
    let status_code: u16 = match parts[1].parse() {
        Ok(c) => c,
        Err(_) => return,
    };
    let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

    // Read headers
    let mut accept_value: Option<String> = None;
    loop {
        let line = match bs.read_line() {
            Ok(l) => l,
            Err(_) => return,
        };
        if line == b"\r\n" || line == b"\n" {
            break;
        }
        let line_str = String::from_utf8_lossy(&line).to_lowercase();
        if line_str.starts_with("sec-websocket-accept:") {
            let val = String::from_utf8_lossy(&line)["Sec-WebSocket-Accept:".len()..].trim().to_string();
            accept_value = Some(val);
        }
    }

    if status_code != 101 {
        println!("handshake failed: {} {}", status_code, reason_phrase);
        return;
    }

    // Validate Sec-WebSocket-Accept
    let expected_accept = {
        let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        let input = format!("{}{}", key_b64, magic);
        let digest = sha1(input.as_bytes());
        base64_encode(&digest)
    };

    match accept_value {
        Some(val) if val == expected_accept => {}
        _ => {
            println!("handshake failed: bad Sec-WebSocket-Accept");
            return;
        }
    }

    // Frame processing loop
    let mut frag_buf: Vec<u8> = Vec::new();
    let mut frag_opcode: u8 = 0;
    let mut expecting_sha1_payload = false;
    let mut close_sent = false;

    loop {
        let frame = match read_frame(&mut bs) {
            Ok(f) => f,
            Err(_) => break,
        };

        match frame.opcode {
            0x0 | 0x1 | 0x2 => {
                if frame.opcode == 0x0 {
                    frag_buf.extend_from_slice(&frame.payload);
                } else {
                    frag_buf = frame.payload.clone();
                    frag_opcode = frame.opcode;
                }
                if frame.fin {
                    let complete_payload = std::mem::take(&mut frag_buf);
                    if frag_opcode == 0x1 {
                        let text = String::from_utf8_lossy(&complete_payload).to_string();
                        process_text_command(&text, &mut bs, &mut expecting_sha1_payload, &mut close_sent);
                        if close_sent {
                            continue;
                        }
                    } else if frag_opcode == 0x2 {
                        if expecting_sha1_payload {
                            let hex = sha1_hex(&complete_payload);
                            let reply = hex.clone();
                            let _ = write_frame(&mut bs, 0x1, reply.as_bytes());
                            println!("SHA1 {} -> {}", complete_payload.len(), hex);
                            expecting_sha1_payload = false;
                        }
                    }
                }
            }
            0x8 => {
                let payload = &frame.payload;
                if payload.len() >= 2 {
                    let code = u16::from_be_bytes([payload[0], payload[1]]);
                    let reason = if payload.len() > 2 {
                        String::from_utf8_lossy(&payload[2..]).to_string()
                    } else {
                        String::new()
                    };
                    if reason.is_empty() {
                        println!("closed {}", code);
                    } else {
                        println!("closed {} {}", code, reason);
                    }
                    if !close_sent {
                        let close_payload = code.to_be_bytes();
                        let _ = write_frame(&mut bs, 0x8, &close_payload);
                        close_sent = true;
                    }
                } else {
                    println!("closed 1005");
                    if !close_sent {
                        let _ = write_frame(&mut bs, 0x8, &1005u16.to_be_bytes());
                        close_sent = true;
                    }
                }
                break;
            }
            0x9 => {
                let _ = write_frame(&mut bs, 0xA, &frame.payload);
            }
            0xA => {
                // pong - ignore
            }
            _ => {}
        }
    }
}

fn process_text_command(
    text: &str,
    bs: &mut BufStream,
    expecting_sha1: &mut bool,
    close_sent: &mut bool,
) {
    if text == "BYE" {
        let close_payload = 1000u16.to_be_bytes();
        let _ = write_frame(bs, 0x8, &close_payload);
        *close_sent = true;
        return;
    }

    if text == "SHA1" {
        *expecting_sha1 = true;
        return;
    }

    if text.starts_with("ADD ") {
        let rest = &text[4..];
        let parts: Vec<&str> = rest.splitn(2, ' ').collect();
        if parts.len() == 2 {
            let a: i64 = parts[0].parse().unwrap_or(0);
            let b: i64 = parts[1].parse().unwrap_or(0);
            let sum = a + b;
            let reply = sum.to_string();
            let _ = write_frame(bs, 0x1, reply.as_bytes());
            println!("{} -> {}", text, reply);
        }
        return;
    }

    if text.starts_with("REV ") {
        let content = &text[4..];
        let reversed: String = content.chars().rev().collect();
        let _ = write_frame(bs, 0x1, reversed.as_bytes());
        println!("{} -> {}", text, reversed);
        return;
    }
}

